function nav_link(string $page, string $label, string $icon, string $current, ?string $permission = null, ?PDO $db = null): void
{
    if ($permission && !Security::can($db,$permission)) return;
    $currentKind = (string)($_GET['kind'] ?? '');
    $currentCat  = (string)($_GET['cat']  ?? '');

    // Determine active state by matching page + optional kind/cat params
    $pageBase = explode('&', $page)[0];
    $active = '';

    if (strpos($page, '&kind=') !== false) {
        $parts = explode('&kind=', $page);
        $linkBase = $parts[0]; $linkKind = $parts[1] ?? '';
        if ($current === $linkBase && $currentKind === $linkKind) $active = ' active';
    } elseif (strpos($page, '&cat=') !== false) {
        $parts = explode('&cat=', $page);
        $linkBase = $parts[0]; $linkCat = $parts[1] ?? '';
        if ($current === $linkBase && $currentCat === $linkCat) $active = ' active';
    } else {
        // No extra params — active only when page matches AND no conflicting params active
        if ($currentKind !== '' && $pageBase === 'departments') {
            $active = '';
        } elseif ($currentCat !== '' && $pageBase === 'patients') {
            // 'All Patients' link — only active when no cat filter
            $active = ($current === $pageBase && $currentCat === '') ? ' active' : '';
        } else {
            $active = ($current === $page || $current === $pageBase) ? ' active' : '';
        }
    }
    echo '<a class="nav-link' . $active . '" href="/index.php?page=' . e($page) . '" title="' . e($label) . '"><span class="nav-icon">' . get_svg_icon($icon) . '</span><span>' . e($label) . '</span></a>';
}
function nav_group(string $id, string $title, string $icon, array $links, string $currentPage, ?PDO $db = null): void
{
    $visibleLinks = [];
    foreach ($links as $l) {
        if (isset($l['header'])) {
            $visibleLinks[] = $l;
            continue;
        }
        $permission = $l[3] ?? null;
        if (!$permission || Security::can($db, $permission)) {
            $visibleLinks[] = $l;
        }
    }
    if (empty($visibleLinks)) return;

    $currentKind = (string)($_GET['kind'] ?? '');
    $hasActive = false;
    foreach ($visibleLinks as $l) {
        if (!isset($l['header']) && isset($l[0])) {
            $linkPage = (string)$l[0];
            if (strpos($linkPage, '&kind=') !== false) {
                $parts = explode('&kind=', $linkPage);
                if ($parts[0] === $currentPage && ($parts[1] ?? '') === $currentKind) {
                    $hasActive = true;
                    break;
                }
            } else {
                $base = explode('&', $linkPage)[0];
                if ($base === $currentPage) {
                    $hasActive = true;
                    break;
                }
            }
        }
    }
    
    $openClass = $hasActive ? ' open' : '';
    
    echo '<div class="nav-accordion-item' . $openClass . '" id="nav-grp-' . e($id) . '">';
    echo '<button class="nav-accordion-header" type="button" onclick="toggleNavGroup(\'nav-grp-' . e($id) . '\')" title="' . e($title) . '">';
    echo '<span class="nav-accordion-title"><span class="nav-icon">' . get_svg_icon($icon) . '</span><span>' . e($title) . '</span></span>';
    echo '<span class="nav-chevron">❯</span>';
    echo '</button>';
    echo '<div class="nav-accordion-body"><nav class="nav-sub-menu">';
    foreach ($visibleLinks as $l) {
        if (isset($l['header'])) {
            echo '<div class="nav-sub-header">' . e($l['header']) . '</div>';
            continue;
        }
        [$page, $label, $subIcon, $permission] = $l;
        nav_link($page, $label, $subIcon, $currentPage, $permission, $db);
    }
    echo '</nav></div>';
    echo '</div>';
}

function get_system_logo_html(?string $logoUrl = null, int $size = 38, bool $transparent = false): string
{
    $src = '/assets/img/logo.png';
    if (!empty($logoUrl)) {
        $src = (str_starts_with($logoUrl, '/') || str_starts_with($logoUrl, 'http')) ? $logoUrl : '/' . $logoUrl;
    }
    if ($transparent) {
        return '<div class="brand-logo-clean" style="width:' . $size . 'px;height:' . $size . 'px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;background:transparent;">'
             . '<img src="' . e($src) . '" alt="Lutfunnesa Logo" style="height:100%;width:100%;object-fit:contain;filter:drop-shadow(0 4px 12px rgba(0,0,0,0.18));"></div>';
    }
    return '<div class="sidebar-brand-box" style="width:' . $size . 'px;height:' . $size . 'px;border-radius:12px;background:#ffffff;padding:3px;display:inline-flex;align-items:center;justify-content:center;box-shadow:0 4px 14px rgba(0,0,0,0.12);flex-shrink:0;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);">'
         . '<img src="' . e($src) . '" alt="Lutfunnesa Logo" style="height:100%;width:100%;object-fit:contain;border-radius:8px;"></div>';
}

function page_start(PDO $db, array $user, string $page, string $title, string $subtitle): void
{
