    <script>
    function openForgotPasswordModal() {
        const modal = document.getElementById("forgotPasswordModal");
        if (modal) modal.style.display = "flex";
    }
    function closeForgotPasswordModal() {
        const modal = document.getElementById("forgotPasswordModal");
        if (modal) modal.style.display = "none";
        const alertBox = document.getElementById("resetSuccessAlert");
        if (alertBox) alertBox.style.display = "none";
        const form = document.getElementById("resetRequestForm");
        if (form) form.style.display = "block";
    }
    function handleResetSubmit(e) {
        e.preventDefault();
        const btn = document.getElementById("resetSubmitBtn");
        const email = document.getElementById("reset_email_input").value;
        if (btn) {
            btn.innerText = "Processing...";
            btn.disabled = true;
        }
        setTimeout(function() {
            document.getElementById("resetRequestForm").style.display = "none";
            document.getElementById("resetSuccessAlert").style.display = "block";
            if (btn) {
                btn.innerText = "Send Reset Link";
                btn.disabled = false;
            }
        }, 800);
    }
    function togglePwdVisibility() {
        const inp = document.getElementById("password_input");
        const icon = document.getElementById("pwd_eye_icon");
        if (inp.type === "password") {
            inp.type = "text";
            icon.className = "fa-regular fa-eye-slash";
        } else {
            inp.type = "password";
            icon.className = "fa-regular fa-eye";
        }
    }

    function selectRole(roleCode, btn) {
        const credentials = {
            "super_admin": { email: "admin@cognovait.com", password: "admin123" },
            "admin": { email: "admin@cognovait.com", password: "admin123" },
            "clinic": { email: "clinic@cognovait.com", password: "admin123" },
            "cashier": { email: "clinic@cognovait.com", password: "admin123" },
            "lab": { email: "lab@cognovait.com", password: "admin123" },
            "lab_tech": { email: "lab@cognovait.com", password: "admin123" },
            "doctor": { email: "doctor@cognovait.com", password: "admin123" },
            "staff": { email: "staff@cognovait.com", password: "admin123" },
            "pharmacist": { email: "staff@cognovait.com", password: "admin123" }
        };
        const cred = credentials[roleCode];
        if (cred) {
            const emailInp = document.getElementById("email_input");
            const pwdInp = document.getElementById("password_input");
            const sel = document.getElementById("role_code_input");
            if (emailInp) emailInp.value = cred.email;
            if (pwdInp) pwdInp.value = cred.password;
            if (sel) sel.value = roleCode;
            document.querySelectorAll(".quick-chip").forEach(c => c.classList.remove("active"));
            if (btn) btn.classList.add("active");

            const form = document.getElementById("loginForm");
            if (form) form.submit();
        }
    }
    </script>
</body>
</html>';
}
function render_dashboard(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0] ?? 1;

    // Detect Active Sub-Module Tab
    $activeTab = (string)($_GET['tab'] ?? '');
    if (!$activeTab) {
        $page = (string)($_GET['page'] ?? 'dashboard');
        if ($page === 'clinic_dashboard') $activeTab = 'clinic';
        elseif ($page === 'doctor_dashboard') $activeTab = 'doctor';
        elseif ($page === 'pathology_dashboard') $activeTab = 'pathology';
        else $activeTab = 'overview';
    }
    if (!in_array($activeTab, ['overview', 'clinic', 'doctor', 'pathology'], true)) {
        $activeTab = 'overview';
    }

    page_start($db, $user, 'dashboard', 'Operations & Executive Overview', 'Real-time diagnostic center performance, clinical throughput, cash collections and daily analytics.');

    // 1. Sub-Module Navigation Pill Bar (Integrated in-page)
    echo '<div class="dash-submodule-bar">';
    echo '<button type="button" id="dash-btn-overview" class="dash-submodule-tab' . ($activeTab === 'overview' ? ' active' : '') . '" onclick="switchDashTab(\'overview\')">';
    echo '<span class="tab-icon">' . get_svg_icon('dashboard') . '</span>';
    echo '<span>Dashboard</span>';
    echo '<span class="tab-badge">Overview</span>';
    echo '</button>';

    echo '<button type="button" id="dash-btn-clinic" class="dash-submodule-tab' . ($activeTab === 'clinic' ? ' active' : '') . '" onclick="switchDashTab(\'clinic\')">';
