    $pendingResults = $db->query('SELECT lr.*, dt.name AS test_name, p.name AS patient_name, o.order_no FROM lab_results lr JOIN diagnostic_tests dt ON dt.id=lr.test_id JOIN diagnostic_orders o ON o.id=lr.order_id JOIN patients p ON p.id=o.patient_id WHERE lr.status="draft" ORDER BY lr.id DESC LIMIT 5')->fetchAll();
