            echo '<td><span class="code-chip">' . e(strtoupper($pr['result_flag'])) . '</span></td>';
            echo '<td><a href="/index.php?page=pathologist_desk" class="button button-primary small">Review →</a></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">GOVERNANCE LOG</span><h3>Recent System Audit Events</h3></div></div>';
    $logs = $db->query('SELECT a.entity_type,a.action,a.occurred_at,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.id DESC LIMIT 5')->fetchAll();
