    echo '<script>
    function switchDashTab(tabId) {
        document.querySelectorAll(".dash-submodule-content").forEach(function(el) {
            el.style.display = "none";
        });
        document.querySelectorAll(".dash-submodule-tab").forEach(function(el) {
            el.classList.remove("active");
        });
        var targetEl = document.getElementById("dash-tab-" + tabId);
        if (targetEl) targetEl.style.display = "block";
        var targetBtn = document.getElementById("dash-btn-" + tabId);
        if (targetBtn) targetBtn.classList.add("active");
        
        try {
            var url = new URL(window.location);
            url.searchParams.set("tab", tabId);
            window.history.replaceState({}, "", url);
        } catch(e) {}

        window.dispatchEvent(new Event("resize"));
    }

    document.addEventListener("DOMContentLoaded", function() {
        // Flawless geometric centering for doughnut chart center labels via Canvas drawing
        if (typeof Chart !== "undefined") {
            try {
                Chart.register({
                    id: "donutCenterCanvasPlugin",
                    afterDraw: function(chart) {
                        if (chart.config.type !== "doughnut") return;
                        var opts = chart.config.options;
                        var center = opts && opts.plugins && opts.plugins.centerText;
                        if (!center) return;
                        
                        var ctx = chart.ctx;
                        var chartArea = chart.chartArea;
                        if (!chartArea) return;
                        
                        // Calculated exact geometric center of the doughnut ring in chartArea
                        var centerX = (chartArea.left + chartArea.right) / 2;
                        var centerY = (chartArea.top + chartArea.bottom) / 2;
                        
                        ctx.save();
                        ctx.textAlign = "center";
                        ctx.textBaseline = "middle";
                        
                        // Value text
                        ctx.font = "800 21px system-ui, sans-serif";
                        ctx.fillStyle = "#0f2933";
                        ctx.fillText(center.value, centerX, centerY - 9);
                        
                        // Label text
                        ctx.font = "700 11px system-ui, sans-serif";
                        ctx.fillStyle = "#64748b";
                        ctx.fillText(center.label, centerX, centerY + 13);
                        
                        ctx.restore();
                    }
                });
            } catch(e) {}
        }

        // --- Interactive Dynamic Appointment Calendar ---
        (function initAppointmentCalendar() {
            var calPrevBtn = document.getElementById("calPrevBtn");
            var calNextBtn = document.getElementById("calNextBtn");
            var calTodayBtn = document.getElementById("calTodayBtn");
            var calMonthYear = document.getElementById("calMonthYear");
            var calBody = document.getElementById("calBody");
            if (!calBody || !calMonthYear) return;

            var monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
            
            var today = new Date();
            var todayYear = today.getFullYear();
            var todayMonth = today.getMonth();
            var todayDate = today.getDate();

            var viewYear = todayYear;
            var viewMonth = todayMonth;

            var eventsMap = {
                5: [{ time: "09:30 AM", title: "General visit", color: "teal" }, { time: "11:00 AM", title: "Followup", color: "blue" }],
                8: [{ time: "11:00 AM", title: "Blood Routine", color: "amber" }],
                11: [{ time: "10:00 AM", title: "General visit", color: "teal" }],
                14: [{ time: "04:30 PM", title: "Diabetology", color: "green" }, { time: "", title: "+4 more...", color: "teal" }],
                18: [{ time: "02:00 PM", title: "Thyroid Check", color: "amber" }],
                22: [{ time: "10:15 AM", title: "Cardiology", color: "purple" }],
                26: [{ time: "05:00 PM", title: "HbA1c Test", color: "teal" }],
                29: [{ time: "03:30 PM", title: "Endocrinology", color: "blue" }]
            };

            function renderCalendar() {
                calMonthYear.textContent = monthNames[viewMonth] + " " + viewYear;
                calBody.innerHTML = "";

                var firstDayIndex = new Date(viewYear, viewMonth, 1).getDay();
                var daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
                var prevDaysInMonth = new Date(viewYear, viewMonth, 0).getDate();

                var totalCells = (firstDayIndex + daysInMonth > 35) ? 42 : 35;

                var currentDayNum = 1;
                var nextMonthDayNum = 1;
                var tr = document.createElement("tr");

                for (var i = 0; i < totalCells; i++) {
                    var td = document.createElement("td");
                    
                    if (i < firstDayIndex) {
                        var pDay = prevDaysInMonth - firstDayIndex + 1 + i;
                        td.style.background = "#fafafa";
                        td.style.color = "#cbd5e1";
                        td.innerHTML = "<span class=\"calendar-day-num\" style=\"color:#94a3b8;\">" + pDay + "</span>";
                    } else if (currentDayNum <= daysInMonth) {
                        var d = currentDayNum;
                        var isToday = (viewYear === todayYear && viewMonth === todayMonth && d === todayDate);
                        if (isToday) {
                            td.className = "today";
                        }
                        
                        var padMonth = String(viewMonth + 1).padStart(2, "0");
                        var padDay = String(d).padStart(2, "0");
                        var dateStr = viewYear + "-" + padMonth + "-" + padDay;

                        td.style.cursor = "pointer";
                        td.title = "Click to view appointments for " + dateStr;
                        td.onclick = (function(ds) {
                            return function() { window.location.href = "/index.php?page=appointments&date=" + ds; };
                        })(dateStr);

                        var html = "<span class=\"calendar-day-num\">" + d + "</span>";
                        if (eventsMap[d] && (viewMonth % 2 === 1 || viewMonth === todayMonth)) {
                            eventsMap[d].forEach(function(ev) {
                                html += "<span class=\"calendar-event-pill " + ev.color + "\">" + (ev.time ? ev.time + " " : "") + ev.title + "</span>";
                            });
                        }
                        td.innerHTML = html;
                        currentDayNum++;
                    } else {
                        td.style.background = "#fafafa";
                        td.style.color = "#cbd5e1";
                        td.innerHTML = "<span class=\"calendar-day-num\" style=\"color:#94a3b8;\">" + nextMonthDayNum + "</span>";
                        nextMonthDayNum++;
                    }

                    tr.appendChild(td);

                    if ((i + 1) % 7 === 0) {
                        calBody.appendChild(tr);
                        tr = document.createElement("tr");
                    }
                }
            }

            if (calPrevBtn) {
                calPrevBtn.addEventListener("click", function(e) {
                    e.preventDefault();
                    viewMonth--;
                    if (viewMonth < 0) {
                        viewMonth = 11;
                        viewYear--;
                    }
                    renderCalendar();
                });
            }

            if (calNextBtn) {
                calNextBtn.addEventListener("click", function(e) {
                    e.preventDefault();
                    viewMonth++;
                    if (viewMonth > 11) {
                        viewMonth = 0;
                        viewYear++;
                    }
                    renderCalendar();
                });
            }

            if (calTodayBtn) {
                calTodayBtn.addEventListener("click", function(e) {
                    e.preventDefault();
                    viewYear = todayYear;
                    viewMonth = todayMonth;
                    renderCalendar();
                });
            }

            renderCalendar();
        })();

