                        backgroundColor: "rgba(12, 146, 140, 0.12)",
                        fill: true,
                        tension: 0.35,
                        borderWidth: 2.5
                    }, {
                        label: "Specimens Collected",
                        data: [100, 125, 140, 160, 180, 195, 210, 230, 245, 260],
                        borderColor: "#10b981",
                        borderDash: [4, 4],
                        borderWidth: 2
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { position: "top", labels: { boxWidth: 10, font: { size: 10 } } } },
                    scales: {
                        y: { beginAtZero: true, grid: { color: "#f1f5f9" } },
                        x: { grid: { display: false } }
                    }
                }
            });
        }

        var ctxPathDept = document.getElementById("pathologyDeptDonutChart");
        if(ctxPathDept) {
            new Chart(ctxPathDept.getContext("2d"), {
                type: "doughnut",
                data: {
                    labels: ["Biochemistry (42%)", "Hematology (32%)", "Microbiology (12%)", "Histopathology (8%)", "Immunology (6%)"],
                    datasets: [{
                        data: [42, 32, 12, 8, 6],
                        backgroundColor: ["#0c928c", "#0ea5e9", "#10b981", "#f59e0b", "#8b5cf6"],
                        borderWidth: 0
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    cutout: "70%",
                    plugins: {
                        legend: { position: "right", labels: { boxWidth: 10, font: { size: 10 } } },
                        centerText: { value: "42%", label: "Biochem" }
                    }
                }
            });
        }
    });
    </script>';

    page_end();
}

// =========================================================================
// SUB-MODULE 1: LIST OF DOCTORS
// =========================================================================
function render_doctors(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0] ?? 1;

    $q = trim((string)($_GET['q'] ?? ''));
    $specialtyFilter = trim((string)($_GET['specialty'] ?? ''));
    $statusFilter = (string)($_GET['status'] ?? 'all');

    page_start($db, $user, 'doctors', 'Doctors Directory & Clinical Consultants', 'Manage specialist physicians, OPD chamber schedules, credentials and consultation fees.');

    // Query Doctors from DB
    $sql = "SELECT d.*, 
            COALESCE((SELECT COUNT(*) FROM appointments a WHERE a.doctor_id = d.id), 0) AS appt_count
            FROM doctors d WHERE 1=1";
    $params = [];
    if ($q !== '') {
        $sql .= " AND (d.name LIKE ? OR d.code LIKE ? OR d.registration_no LIKE ? OR d.mobile LIKE ?)";
        $wild = '%' . $q . '%';
        array_push($params, $wild, $wild, $wild, $wild);
    }
    if ($specialtyFilter !== '') {
        $sql .= " AND d.specialty LIKE ?";
        $params[] = '%' . $specialtyFilter . '%';
    }
    if ($statusFilter === 'active') {
        $sql .= " AND d.active = 1";
    } elseif ($statusFilter === 'inactive') {
        $sql .= " AND d.active = 0";
    }
    $sql .= " ORDER BY d.id ASC";

    $stmt = $db->prepare($sql);
    $stmt->execute($params);
    $doctorsList = $stmt->fetchAll(PDO::FETCH_ASSOC);

    $totalDocs = count($doctorsList);
    $activeDocs = count(array_filter($doctorsList, fn($d) => !empty($d['active'])));
    $diabDocs = count(array_filter($doctorsList, fn($d) => stripos($d['specialty'] ?? '', 'Diabet') !== false));
    $bmdcCount = count(array_filter($doctorsList, fn($d) => !empty($d['registration_no'])));

    // Top Metric KPIs (Light cards & clickable navigation to relevant views/filters)
    echo '<div class="stats-grid" style="margin-bottom:22px;">';
    echo '<a href="/index.php?page=doctors" class="stat-card card-clickable-nav card-light-teal" style="border-left:4px solid #0c928c;text-decoration:none;"><div class="stat-icon teal">' . get_svg_icon('doctor') . '</div><span>Total Consultants</span><strong>' . $totalDocs . ' Doctors</strong><small style="color:#0c928c;font-weight:700;">● Registered Specialists</small></a>';
    echo '<a href="/index.php?page=doctors&status=active" class="stat-card card-clickable-nav card-light-emerald" style="border-left:4px solid #10b981;text-decoration:none;"><div class="stat-icon green">' . get_svg_icon('check-circle') . '</div><span>Active in Chamber</span><strong>' . $activeDocs . ' Active</strong><small style="color:#10b981;font-weight:700;">Available for OPD Visits</small></a>';
    echo '<a href="/index.php?page=specializations" class="stat-card card-clickable-nav card-light-blue" style="border-left:4px solid #0ea5e9;text-decoration:none;"><div class="stat-icon blue">' . get_svg_icon('stethoscope') . '</div><span>Diabetology & Endocrine</span><strong>' . $diabDocs . ' Specialists</strong><small style="color:#0ea5e9;">Clinical Care Core</small></a>';
    echo '<a href="/index.php?page=security_hardening" class="stat-card card-clickable-nav card-light-amber" style="border-left:4px solid #f59e0b;text-decoration:none;"><div class="stat-icon amber">' . get_svg_icon('shield') . '</div><span>BMDC Verified</span><strong>' . $bmdcCount . ' Verified</strong><small style="color:#f59e0b;">100% Accredited Physicians</small></a>';
    echo '</div>';

    // Action & Filter Bar
    echo '<div class="submod-action-bar">';
    echo '<form method="get" action="/index.php" style="display:flex;gap:10px;flex:1;max-width:700px;align-items:center;">';
    echo '<input type="hidden" name="page" value="doctors">';
    echo '<input name="q" value="' . e($q) . '" placeholder="Search by Doctor Name, BMDC No, Code or Mobile..." style="flex:1;min-height:38px;border:1px solid #cbd5e1;border-radius:8px;padding:8px 14px;font-size:12px;">';
    echo '<select name="specialty" style="min-height:38px;border:1px solid #cbd5e1;border-radius:8px;padding:8px 12px;font-size:12px;background:white;">';
    echo '<option value="">All Specialties</option>';
    $specs = ['Diabetology & Endocrinology', 'Cardiology & Vascular Medicine', 'Clinical Pathology & Laboratory Medicine', 'Radiology & Imaging Specialist', 'Nephrology & Renal Medicine', 'Internal & General Medicine', 'Gastroenterology & Hepatology', 'Obstetrics & Gynecology'];
    foreach ($specs as $sp) {
        $sel = $specialtyFilter === $sp ? ' selected' : '';
        echo '<option value="' . e($sp) . '"' . $sel . '>' . e($sp) . '</option>';
    }
    echo '</select>';
    echo '<button class="button button-outline" style="min-height:38px;">Filter</button>';
    if ($q !== '' || $specialtyFilter !== '') {
        echo '<a href="/index.php?page=doctors" class="button button-outline" style="min-height:38px;">Reset</a>';
    }
    echo '</form>';

    echo '<div style="display:flex;gap:10px;">';
    echo '<button type="button" class="button button-primary" onclick="toggleDoctorForm()"><span class="nav-icon" style="width:14px;height:14px;">' . get_svg_icon('plus') . '</span> + Register New Doctor</button>';
    echo '</div>';
    echo '</div>';

    // Add/Edit Doctor Form Drawer (collapsible)
    echo '<div id="doctorFormDrawer" class="card" style="display:none;margin-bottom:22px;border:1.5px solid #0c928c;background:#f8fdfc;">';
    echo '<div class="card-head"><div><span class="eyebrow" id="docFormEyebrow">REGISTRATION DESK</span><h3 style="margin:0;" id="docFormTitle">Register Specialist Doctor</h3></div><button type="button" class="button button-outline small" onclick="closeDoctorForm()">✕ Close</button></div>';
    echo '<form method="post" action="/index.php?page=doctors" enctype="multipart/form-data" class="field-grid" id="doctorProfileForm">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<input type="hidden" name="id" id="doc_form_id" value="0">';
    echo '<label class="field">Doctor Code (Optional)<input name="code" id="doc_form_code" placeholder="Auto-generated if blank e.g. DOC-009"></label>';
    echo '<label class="field">Full Name with Title *<input name="name" id="doc_form_name" required placeholder="Prof. / Dr. Full Name"></label>';
    echo '<label class="field">Specialty Discipline *<input name="specialty" id="doc_form_specialty" required placeholder="e.g. Diabetology & Endocrinology"></label>';
    echo '<label class="field">BMDC Registration No *<input name="registration_no" id="doc_form_reg" placeholder="e.g. BMDC-A-49210"></label>';
    echo '<label class="field">Contact Mobile *<input name="mobile" id="doc_form_mobile" placeholder="017xxxxxxxx"></label>';
    echo '<label class="field">Status<select name="active" id="doc_form_active"><option value="1">Active (Available for appointments)</option><option value="0">Inactive / On Leave</option></select></label>';
    
    // Doctor Profile Image Upload & URL input
    echo '<div class="field span-2" style="background:#f0fdfa;border:1px dashed #0d9488;border-radius:10px;padding:14px;">';
    echo '<strong style="color:#0f766e;font-size:13px;display:block;margin-bottom:8px;">📷 Doctor Profile Picture</strong>';
    echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:center;">';
    echo '<div><label style="font-size:12px;font-weight:700;color:#134e4a;display:block;margin-bottom:4px;">Upload Image File (JPG, PNG, WebP)</label><input type="file" name="profile_image_file" accept="image/*" style="padding:6px;background:white;border:1px solid #cbd5e1;border-radius:6px;width:100%;"></div>';
    echo '<div><label style="font-size:12px;font-weight:700;color:#134e4a;display:block;margin-bottom:4px;">Or Select Existing / Paste Image URL</label><input type="text" name="profile_image" id="doc_form_img" placeholder="/assets/img/doctors/doc1.jpg" style="padding:8px 12px;font-size:12px;border:1px solid #cbd5e1;border-radius:6px;width:100%;"></div>';
    echo '</div>';
    echo '<div style="margin-top:10px;display:flex;align-items:center;gap:10px;">';
    echo '<span style="font-size:11px;color:#0d9488;font-weight:600;">Default Avatars:</span>';
    for ($di = 1; $di <= 8; $di++) {
        echo '<img src="/assets/img/doctors/doc' . $di . '.jpg" alt="doc' . $di . '" style="width:30px;height:30px;border-radius:50%;object-fit:cover;cursor:pointer;border:2px solid transparent;transition:transform 0.15s;" onmouseover="this.style.transform=\'scale(1.15)\'" onmouseout="this.style.transform=\'scale(1)\'" onclick="document.getElementById(\'doc_form_img\').value=\'/assets/img/doctors/doc' . $di . '.jpg\';document.getElementById(\'doc_form_preview\').src=\'/assets/img/doctors/doc' . $di . '.jpg\';">';
    }
    echo '<div style="margin-left:auto;display:flex;align-items:center;gap:8px;"><span style="font-size:11px;color:#64748b;">Preview:</span><img id="doc_form_preview" src="/assets/img/doctors/doc1.jpg" style="width:34px;height:34px;border-radius:50%;object-fit:cover;border:1.5px solid #0d9488;"></div>';
    echo '</div></div>';

    echo '<div class="span-2 form-actions" style="margin-top:10px;">';
    echo '<button type="submit" class="button button-primary" id="docFormSubmitBtn">Save Doctor Profile</button>';
    echo '<button type="button" class="button button-outline" onclick="closeDoctorForm()">Cancel</button>';
    echo '</div>';
    echo '</form>';
    echo '</div>';

    // Doctors Cards Grid
    echo '<div class="doctor-grid">';
    if (empty($doctorsList)) {
        echo '<div class="empty-state" style="grid-column:1/-1;">No doctors match the selected search filter.</div>';
    } else {
        foreach ($doctorsList as $doc) {
            $isAct = !empty($doc['active']);
            $docId = (int)$doc['id'];
            $imgSrc = !empty($doc['profile_image']) ? $doc['profile_image'] : ('/assets/img/doctors/doc' . (($docId % 8) + 1) . '.jpg');
            echo '<div class="doctor-profile-card">';
            echo '<div>';
            echo '<div class="doctor-card-top">';
            echo '<div class="doctor-card-avatar-real" style="position:relative;cursor:pointer;" title="Click to change picture & edit profile" onclick="editDoctor(' . htmlspecialchars(json_encode($doc), ENT_QUOTES, 'UTF-8') . ')">';
            echo '<img src="' . e($imgSrc) . '" alt="' . e($doc['name']) . '" onerror="this.onerror=null;this.parentElement.innerHTML=\'' . addslashes(get_svg_icon('doctor')) . '\';">';
            echo '<span style="position:absolute;bottom:-2px;right:-2px;background:#0d9488;color:#fff;width:18px;height:18px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;box-shadow:0 1px 4px rgba(0,0,0,0.3);" title="Edit Profile & Picture">✎</span>';
            echo '</div>';
            echo '<div class="doctor-card-meta">';
            echo '<h4>' . e($doc['name']) . '</h4>';
            echo '<span class="doc-specialty">' . e($doc['specialty'] ?: 'General Consultant') . '</span>';
            echo '<span class="doc-bmdc">' . e($doc['registration_no'] ?: 'BMDC Pending') . '</span>';
            echo '</div>';
            echo '</div>';

            echo '<div class="doctor-details-list">';
            echo '<div class="doctor-detail-item"><span>Doctor Code:</span><strong>' . e($doc['code']) . '</strong></div>';
            echo '<div class="doctor-detail-item"><span>Mobile:</span><strong>' . e($doc['mobile'] ?: 'N/A') . '</strong></div>';
            echo '<div class="doctor-detail-item"><span>OPD Chamber:</span><strong>Chamber #204 (Level 2)</strong></div>';
            echo '<div class="doctor-detail-item"><span>Consultation Fee:</span><strong style="color:#059669;">BDT 1,000</strong></div>';
            echo '<div class="doctor-detail-item"><span>Status:</span><span class="active-tag" style="' . ($isAct ? 'background:#dcfce7;color:#15803d;' : 'background:#fee2e2;color:#b91c1c;') . '">' . ($isAct ? '● Active' : '○ Inactive') . '</span></div>';
            echo '</div>';
            echo '</div>';

            echo '<div style="display:flex;gap:8px;margin-top:auto;">';
            echo '<button type="button" class="button button-outline small" style="background:#f0fdfa;border-color:#5eead4;color:#0f766e;font-weight:700;" onclick="editDoctor(' . htmlspecialchars(json_encode($doc), ENT_QUOTES, 'UTF-8') . ')">✏️ Edit</button>';
            echo '<a href="/index.php?page=appointments&doctor_id=' . e($doc['id']) . '" class="button button-primary small" style="flex:1;">Book Appt →</a>';
            echo '<a href="/index.php?page=doctor_dashboard" class="button button-outline small">Desk</a>';
            echo '</div>';
            echo '</div>';
        }
    }
    echo '</div>'; // End Doctor Grid

    echo '<script>
    function toggleDoctorForm() {
        var el = document.getElementById("doctorFormDrawer");
        if(el) {
            var isOpening = (el.style.display === "none" || !el.style.display);
            if(isOpening) {
                resetDocForm();
                el.style.display = "block";
                el.scrollIntoView({ behavior: "smooth" });
            } else {
                el.style.display = "none";
            }
        }
    }
    function closeDoctorForm() {
        var el = document.getElementById("doctorFormDrawer");
        if(el) el.style.display = "none";
    }
    function resetDocForm() {
        document.getElementById("doc_form_id").value = "0";
        document.getElementById("doc_form_code").value = "";
        document.getElementById("doc_form_name").value = "";
        document.getElementById("doc_form_specialty").value = "";
        document.getElementById("doc_form_reg").value = "";
        document.getElementById("doc_form_mobile").value = "";
        document.getElementById("doc_form_img").value = "";
        document.getElementById("doc_form_preview").src = "/assets/img/doctors/doc1.jpg";
        document.getElementById("doc_form_active").value = "1";
        document.getElementById("docFormEyebrow").textContent = "REGISTRATION DESK";
        document.getElementById("docFormTitle").textContent = "Register Specialist Doctor";
        document.getElementById("docFormSubmitBtn").textContent = "Save Doctor Profile";
    }
    function editDoctor(doc) {
        var el = document.getElementById("doctorFormDrawer");
        if(!el) return;
        document.getElementById("doc_form_id").value = doc.id;
        document.getElementById("doc_form_code").value = doc.code || "";
        document.getElementById("doc_form_name").value = doc.name || "";
        document.getElementById("doc_form_specialty").value = doc.specialty || "";
        document.getElementById("doc_form_reg").value = doc.registration_no || "";
        document.getElementById("doc_form_mobile").value = doc.mobile || "";
        var imgSrc = doc.profile_image || ("/assets/img/doctors/doc" + ((doc.id % 8) + 1) + ".jpg");
        document.getElementById("doc_form_img").value = imgSrc;
        document.getElementById("doc_form_preview").src = imgSrc;
        document.getElementById("doc_form_active").value = doc.active ? "1" : "0";
        
        document.getElementById("docFormEyebrow").textContent = "EDIT PROFILE & IMAGE";
        document.getElementById("docFormTitle").textContent = "Edit Doctor: " + doc.name;
        document.getElementById("docFormSubmitBtn").textContent = "Update Doctor Profile";
        
        el.style.display = "block";
        el.scrollIntoView({ behavior: "smooth" });
    }
    </script>';

    page_end();
}

// =========================================================================
// SUB-MODULE 2: SPECIALIZATION
// =========================================================================
function render_specializations(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');

    $q = trim((string)($_GET['q'] ?? ''));

    page_start($db, $user, 'specializations', 'Medical Specializations & Clinical Disciplines', 'Structured taxonomy of medical specialties, departments and clinical care divisions.');

    $specialtiesData = [
        ['code' => 'SPEC-DIA', 'name' => 'Diabetology & Metabolic Disorders', 'category' => 'Clinical Medicine', 'desc' => 'Comprehensive management of Type 1 & 2 Diabetes, Diabetic Foot, HbA1c control and insulin titration.', 'doctors' => 8, 'tests' => 24, 'wing' => 'Level 2, Diabetology Wing'],
        ['code' => 'SPEC-ENDO', 'name' => 'Endocrinology & Hormonal Medicine', 'category' => 'Clinical Medicine', 'desc' => 'Thyroid disorders, Pituitary disorders, PCOD/PCOS, Adrenal health and pediatric hormone issues.', 'doctors' => 6, 'tests' => 18, 'wing' => 'Level 2, Endocrine Suite'],
        ['code' => 'SPEC-CARD', 'name' => 'Cardiology & Cardiovascular Medicine', 'category' => 'Clinical Medicine', 'desc' => 'Hypertension, Ischemic heart disease, Arrhythmias, ECG, Echocardiography & Color Doppler.', 'doctors' => 5, 'tests' => 14, 'wing' => 'Level 1, Cardiac Care Desk'],
        ['code' => 'SPEC-PATH', 'name' => 'Clinical Pathology & Laboratory Medicine', 'category' => 'Diagnostic & LIS', 'desc' => 'Automated Biochemistry, Hematology, Coagulation, Microbiology, Histopathology and PCR Molecular testing.', 'doctors' => 4, 'tests' => 144, 'wing' => 'Level 3, Central Automated Lab'],
        ['code' => 'SPEC-RAD', 'name' => 'Digital Radiology & Medical Imaging', 'category' => 'Diagnostic & LIS', 'desc' => 'Digital X-Ray, High-Resolution 4D Ultrasonography, CT Scan, Mammography and PACS DICOM archive.', 'doctors' => 3, 'tests' => 42, 'wing' => 'Ground Floor, Radiology Wing'],
        ['code' => 'SPEC-NEPH', 'name' => 'Nephrology & Renal Medicine', 'category' => 'Clinical Medicine', 'desc' => 'Chronic Kidney Disease (CKD), Diabetic Nephropathy, Glomerulonephritis and Renal replacement care.', 'doctors' => 3, 'tests' => 16, 'wing' => 'Level 2, Nephro OPD'],
        ['code' => 'SPEC-GAST', 'name' => 'Gastroenterology & Hepatology', 'category' => 'Clinical Medicine', 'desc' => 'Fatty liver disease, Hepatitis B/C, Peptic ulcer, GERD, Endoscopy and Colonoscopy diagnostics.', 'doctors' => 3, 'tests' => 20, 'wing' => 'Level 1, GI Suite'],
        ['code' => 'SPEC-GENM', 'name' => 'Internal & General Medicine', 'category' => 'Clinical Medicine', 'desc' => 'Adult multi-system diseases, Fever of unknown origin, Infection control and chronic care.', 'doctors' => 5, 'tests' => 28, 'wing' => 'Level 1, OPD Chambers'],
        ['code' => 'SPEC-OBGY', 'name' => 'Obstetrics & Gynecology', 'category' => 'Clinical Medicine', 'desc' => 'Gestational diabetes, Antenatal care, High-risk pregnancy, Menstrual health and USG screening.', 'doctors' => 4, 'tests' => 22, 'wing' => 'Level 2, Women\'s Health Desk'],
        ['code' => 'SPEC-PED', 'name' => 'Pediatrics & Child Health', 'category' => 'Clinical Medicine', 'desc' => 'Childhood diabetes, Pediatric growth monitoring, Vaccinations and nutritional assessments.', 'doctors' => 3, 'tests' => 15, 'wing' => 'Level 1, Pediatric Corner'],
        ['code' => 'SPEC-NEUR', 'name' => 'Neurology & Brain Sciences', 'category' => 'Clinical Medicine', 'desc' => 'Diabetic neuropathy, Stroke prevention, Migraine, Epilepsy and peripheral nerve diagnostics.', 'doctors' => 2, 'tests' => 12, 'wing' => 'Level 2, Neuro OPD'],
        ['code' => 'SPEC-ORTH', 'name' => 'Orthopedics & Physical Medicine', 'category' => 'Surgical & Daycare', 'desc' => 'Diabetic joint issues, Osteoporosis, Spine disorders, Arthritis and rehabilitation therapy.', 'doctors' => 2, 'tests' => 16, 'wing' => 'Ground Floor, Ortho Desk'],
    ];

    if ($q !== '') {
        $specialtiesData = array_values(array_filter($specialtiesData, function($s) use ($q) {
            return stripos($s['name'], $q) !== false || stripos($s['code'], $q) !== false || stripos($s['desc'], $q) !== false;
        }));
    }

    // Top Metric KPIs
    // Query Specializations from database
    $dbSpecs = $db->query("SELECT * FROM medical_specializations ORDER BY id ASC")->fetchAll(PDO::FETCH_ASSOC);
    if ($dbSpecs) {
        $specialtiesData = array_map(function($row) use ($db) {
            $docCount = $db->prepare("SELECT COUNT(*) FROM doctors WHERE specialty LIKE ?");
            $docCount->execute(['%' . $row['name'] . '%']);
            $dCnt = (int)$docCount->fetchColumn();
            return [
                'code' => $row['code'],
                'name' => $row['name'],
                'category' => $row['category'] ?: 'Clinical Medicine',
                'desc' => $row['description'] ?: 'Specialized medical diagnosis, outpatient consultations and protocolized treatment care.',
                'doctors' => $dCnt > 0 ? $dCnt : 3,
                'tests' => 20,
                'wing' => $row['wing_location'] ?: 'Clinical Wing'
            ];
        }, $dbSpecs);
    }

    if ($q !== '') {
        $specialtiesData = array_values(array_filter($specialtiesData, function($s) use ($q) {
            return stripos($s['name'], $q) !== false || stripos($s['code'], $q) !== false || stripos($s['desc'], $q) !== false;
        }));
    }

    $totalSpecsCount = count($specialtiesData);
    $clinicalSpecsCount = count(array_filter($specialtiesData, fn($s) => stripos($s['category'], 'Clinical') !== false));
    $diagSpecsCount = count(array_filter($specialtiesData, fn($s) => stripos($s['category'], 'Diagnostic') !== false || stripos($s['category'], 'LIS') !== false));

    // Top Metric KPIs (Clickable and light styled)
    echo '<div class="stats-grid" style="margin-bottom:22px;">';
    echo '<a href="/index.php?page=specializations" class="stat-card card-clickable-nav card-light-teal" style="border-left:4px solid #0c928c;text-decoration:none;"><div class="stat-icon teal">' . get_svg_icon('sliders') . '</div><span>Total Specializations</span><strong>' . $totalSpecsCount . ' Total</strong><small style="color:#0c928c;font-weight:700;">● Active in Directory</small></a>';
    echo '<a href="/index.php?page=specializations" class="stat-card card-clickable-nav card-light-emerald" style="border-left:4px solid #10b981;text-decoration:none;"><div class="stat-icon green">' . get_svg_icon('check-circle') . '</div><span>Clinical Medicine</span><strong>' . $clinicalSpecsCount . ' Disciplines</strong><small style="color:#10b981;font-weight:700;">Physician Chambers</small></a>';
    echo '<a href="/index.php?page=departments" class="stat-card card-clickable-nav card-light-blue" style="border-left:4px solid #0ea5e9;text-decoration:none;"><div class="stat-icon blue">' . get_svg_icon('microscope') . '</div><span>Diagnostics & LIS</span><strong>' . $diagSpecsCount . ' Disciplines</strong><small style="color:#0ea5e9;">Pathology & Radiology</small></a>';
    echo '<a href="/index.php?page=doctors" class="stat-card card-clickable-nav card-light-amber" style="border-left:4px solid #f59e0b;text-decoration:none;"><div class="stat-icon amber">' . get_svg_icon('users') . '</div><span>Avg Doctors / Specialty</span><strong>2.4 Doctors</strong><small style="color:#f59e0b;">Multi-Specialty Coverage</small></a>';
    echo '</div>';

    // Action Bar
    echo '<div class="submod-action-bar">';
    echo '<form method="get" action="/index.php" style="display:flex;gap:10px;flex:1;max-width:550px;">';
    echo '<input type="hidden" name="page" value="specializations">';
    echo '<input name="q" value="' . e($q) . '" placeholder="Search Specialization by name, code or keyword..." style="flex:1;min-height:38px;border:1px solid #cbd5e1;border-radius:8px;padding:8px 14px;font-size:12px;">';
    echo '<button class="button button-outline" style="min-height:38px;">Search</button>';
    if ($q !== '') echo '<a href="/index.php?page=specializations" class="button button-outline" style="min-height:38px;">Reset</a>';
    echo '</form>';
    echo '<button type="button" class="button button-primary" onclick="toggleSpecForm()"><span class="nav-icon" style="width:14px;height:14px;">' . get_svg_icon('plus') . '</span> + Add Specialization</button>';
    echo '</div>';

    // Add Specialization Drawer Form
    echo '<div id="specFormDrawer" class="card" style="display:none;margin-bottom:22px;border:1.5px solid #0c928c;background:#f8fdfc;">';
    echo '<div class="card-head"><div><span class="eyebrow">CLINICAL TAXONOMY</span><h3 style="margin:0;">Add Medical Specialization</h3></div><button type="button" class="button button-outline small" onclick="toggleSpecForm()">✕ Close</button></div>';
    echo '<form method="post" action="/index.php?page=specializations" class="field-grid">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<label class="field">Discipline Code <small>(Optional e.g. SPEC-DERM)</small><input name="code" placeholder="Auto-generated if blank"></label>';
    echo '<label class="field">Specialization Name *<input name="name" required placeholder="e.g. Dermatology & Venereology"></label>';
    echo '<label class="field">Category / Division<select name="category"><option value="Clinical Medicine">Clinical Medicine</option><option value="Diagnostic & LIS">Diagnostic & LIS</option><option value="Surgical & Daycare">Surgical & Daycare</option><option value="Preventive & Health Checkup">Preventive & Health Checkup</option></select></label>';
    echo '<label class="field">Wing / OPD Location<input name="wing_location" placeholder="e.g. Level 2, Suite #208"></label>';
    echo '<label class="field span-2">Clinical Scope & Description<textarea name="desc" rows="2" placeholder="Brief clinical scope, target conditions and OPD procedures..."></textarea></label>';
    echo '<div class="span-2 form-actions" style="margin-top:10px;">';
    echo '<button type="submit" class="button button-primary">Save Specialization</button>';
    echo '<button type="button" class="button button-outline" onclick="toggleSpecForm()">Cancel</button>';
    echo '</div>';
    echo '</form>';
    echo '</div>';

    // Specialty Icon Mapping
    $specIconMap = [
        'SPEC-DIA' => 'activity',
        'SPEC-ENDO' => 'dna',
        'SPEC-CARD' => 'heart',
        'SPEC-PATH' => 'microscope',
        'SPEC-RAD' => 'radiology',
        'SPEC-NEPH' => 'flask',
        'SPEC-GAST' => 'germ',
        'SPEC-GENM' => 'stethoscope',
        'SPEC-OBGY' => 'user',
        'SPEC-PED' => 'users',
        'SPEC-NEUR' => 'zap',
        'SPEC-ORTH' => 'shield'
    ];

    // Specializations Catalog Grid
    echo '<div class="specialty-grid">';
    foreach ($specialtiesData as $item) {
        $iconKey = $specIconMap[$item['code']] ?? 'stethoscope';
        $docTargetUrl = '/index.php?page=doctors&specialty=' . urlencode($item['name']);
        echo '<div class="specialty-card specialty-card-interactive" onclick="window.location.href=\'' . $docTargetUrl . '\'">';
        echo '<div>';
        echo '<div style="display:flex;justify-content:space-between;align-items:flex-start;">';
        echo '<div class="specialty-icon-box">' . get_svg_icon($iconKey) . '</div>';
        echo '<span class="spec-code-tag">' . e($item['code']) . '</span>';
        echo '</div>';
        echo '<h4>' . e($item['name']) . '</h4>';
        echo '<p>' . e($item['desc']) . '</p>';
        echo '<div style="display:flex;flex-direction:column;gap:5px;font-size:11px;border-top:1px dashed #e2e8f0;padding-top:10px;margin-bottom:12px;">';
        echo '<div style="display:flex;justify-content:space-between;"><span>Consultants Assigned:</span><strong>' . e($item['doctors']) . ' Doctors</strong></div>';
        echo '<div style="display:flex;justify-content:space-between;"><span>Diagnostic Protocols:</span><strong>' . e($item['tests']) . ' Tests</strong></div>';
        echo '<div style="display:flex;justify-content:space-between;"><span>Location:</span><strong style="color:#0c928c;">' . e($item['wing']) . '</strong></div>';
        echo '</div>';
        echo '</div>';
        echo '<div style="display:flex;justify-content:space-between;align-items:center;">';
        echo '<span class="pill" style="font-size:10px;background:#e2e8f0;color:#334155;font-weight:600;">' . e($item['category']) . '</span>';
        echo '<a href="' . $docTargetUrl . '" class="text-link" onclick="event.stopPropagation()">View Doctors →</a>';
        echo '</div>';
        echo '</div>';
    }
    echo '</div>';

    echo '<script>
    function toggleSpecForm() {
        var el = document.getElementById("specFormDrawer");
        if(el) {
            el.style.display = el.style.display === "none" ? "block" : "none";
            if(el.style.display === "block") el.scrollIntoView({ behavior: "smooth" });
        }
    }
    </script>';

    page_end();
}

// =========================================================================
// SUB-MODULE 3: DEPARTMENT
// =========================================================================
function render_departments(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0] ?? 1;

    $q = trim((string)($_GET['q'] ?? ''));
    $kindFilter = (string)($_GET['kind'] ?? '');

    // Sub-Module Title dynamically changes based on active kind
    $subTitle = match($kindFilter) {
        'clinical' => 'Clinical Services & In-Patient Divisions',
        'support' => 'Diagnostic LIS, Radiology & Support Wings',
        'administrative' => 'Support, Front Desk & Administrative Wings',
        default => 'Hospital & Clinical Departments'
    };
    $subDesc = match($kindFilter) {
        'clinical' => 'Direct doctor consultations, outpatient specialties, and in-patient clinical divisions.',
        'support' => 'Automated pathology LIS labs, digital PACS radiology imaging, and hospital pharmacy dispensary.',
        'administrative' => 'Patient front desk reception, billing cash counters, and hospital executive management.',
        default => 'Configure medical divisions, diagnostic wings, and administrative cost centers.'
    };

    // Calculate department counts across categories
    $allDeptsStmt = $db->query("SELECT kind, COUNT(*) as cnt FROM departments GROUP BY kind");
    $deptCounts = $allDeptsStmt ? $allDeptsStmt->fetchAll(PDO::FETCH_KEY_PAIR) : [];
    $clinicalCount = (int)($deptCounts['clinical'] ?? 0);
    $supportCount = (int)($deptCounts['support'] ?? 0);
    $adminCount = (int)($deptCounts['administrative'] ?? 0);
    $totalDept = $clinicalCount + $supportCount + $adminCount;

    page_start($db, $user, 'departments', $subTitle, $subDesc);

    // Sub-Navigation Tabs for Dedicated Sub-Modules
    echo '<div style="display:flex;gap:10px;margin-bottom:20px;border-bottom:2px solid #e2e8f0;padding-bottom:12px;flex-wrap:wrap;">';
    echo '<a href="/index.php?page=departments" class="button ' . ($kindFilter === '' ? 'button-primary' : 'button-outline') . '" style="border-radius:10px;font-weight:750;font-size:12.5px;padding:8px 16px;">🏢 All Divisions (' . $totalDept . ')</a>';
    echo '<a href="/index.php?page=departments&kind=clinical" class="button ' . ($kindFilter === 'clinical' ? 'button-primary' : 'button-outline') . '" style="border-radius:10px;font-weight:750;font-size:12.5px;padding:8px 16px;">🩺 Clinical Services (' . $clinicalCount . ')</a>';
    echo '<a href="/index.php?page=departments&kind=support" class="button ' . ($kindFilter === 'support' ? 'button-primary' : 'button-outline') . '" style="border-radius:10px;font-weight:750;font-size:12.5px;padding:8px 16px;">🔬 Diagnostic LIS & Radiology (' . $supportCount . ')</a>';
    echo '<a href="/index.php?page=departments&kind=administrative" class="button ' . ($kindFilter === 'administrative' ? 'button-primary' : 'button-outline') . '" style="border-radius:10px;font-weight:750;font-size:12.5px;padding:8px 16px;">🏛️ Support & Administrative Wings (' . $adminCount . ')</a>';
    echo '</div>';

    // Query Departments
    $sql = "SELECT d.*, b.name AS branch_name FROM departments d LEFT JOIN branches b ON b.id=d.branch_id WHERE 1=1";
    $params = [];
    if ($q !== '') {
        $sql .= " AND (d.name LIKE ? OR d.code LIKE ?)";
        $wild = '%' . $q . '%';
        array_push($params, $wild, $wild);
    }
    if ($kindFilter !== '') {
        $sql .= " AND d.kind = ?";
        $params[] = $kindFilter;
    }
    $sql .= " ORDER BY d.id ASC";

    $stmt = $db->prepare($sql);
    $stmt->execute($params);
    $deptList = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // Top Metric KPIs
    echo '<div class="stats-grid" style="margin-bottom:22px;">';
    echo '<a href="/index.php?page=departments" class="stat-card" style="background:#f0fdfa;border:1px solid #ccfbf1;border-left:4px solid #0c928c;text-decoration:none;cursor:pointer;transition:transform 0.15s,box-shadow 0.15s;border-radius:12px;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 14px rgba(12,146,140,0.15)\'" onmouseout="this.style.transform=\'none\';this.style.boxShadow=\'none\'"><div class="stat-icon teal">' . get_svg_icon('building') . '</div><span>Total Departments ↗</span><strong style="color:#0f766e;">' . $totalDept . ' Units</strong><small style="color:#0c928c;font-weight:700;">● Active Divisions</small></a>';
    echo '<a href="/index.php?page=departments&kind=clinical" class="stat-card" style="background:#f0fdf4;border:1px solid #dcfce7;border-left:4px solid #10b981;text-decoration:none;cursor:pointer;transition:transform 0.15s,box-shadow 0.15s;border-radius:12px;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 14px rgba(16,185,129,0.15)\'" onmouseout="this.style.transform=\'none\';this.style.boxShadow=\'none\'"><div class="stat-icon green">' . get_svg_icon('stethoscope') . '</div><span>Clinical Divisions ↗</span><strong style="color:#15803d;">' . $clinicalCount . ' Units</strong><small style="color:#10b981;font-weight:700;">OPD & In-Patient</small></a>';
    echo '<a href="/index.php?page=departments&kind=support" class="stat-card" style="background:#f0f9ff;border:1px solid #e0f2fe;border-left:4px solid #0ea5e9;text-decoration:none;cursor:pointer;transition:transform 0.15s,box-shadow 0.15s;border-radius:12px;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 14px rgba(14,165,233,0.15)\'" onmouseout="this.style.transform=\'none\';this.style.boxShadow=\'none\'"><div class="stat-icon blue">' . get_svg_icon('pill') . '</div><span>Support & Dispensary ↗</span><strong style="color:#0369a1;">' . $supportCount . ' Units</strong><small style="color:#0ea5e9;font-weight:700;">Pharmacy & LIS Lab</small></a>';
    echo '<a href="/index.php?page=departments&kind=administrative" class="stat-card" style="background:#fffbeb;border:1px solid #fef3c7;border-left:4px solid #f59e0b;text-decoration:none;cursor:pointer;transition:transform 0.15s,box-shadow 0.15s;border-radius:12px;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 14px rgba(245,158,11,0.15)\'" onmouseout="this.style.transform=\'none\';this.style.boxShadow=\'none\'"><div class="stat-icon amber">' . get_svg_icon('sliders') . '</div><span>Administrative ↗</span><strong style="color:#b45309;">' . $adminCount . ' Units</strong><small style="color:#f59e0b;font-weight:700;">Reception & Governance</small></a>';
    echo '</div>';

    // Action Bar
    echo '<div class="submod-action-bar">';
    echo '<form method="get" action="/index.php" style="display:flex;gap:10px;flex:1;max-width:550px;">';
    echo '<input type="hidden" name="page" value="departments">';
    echo '<input name="q" value="' . e($q) . '" placeholder="Search Department by name or code..." style="flex:1;min-height:38px;border:1px solid #cbd5e1;border-radius:8px;padding:8px 14px;font-size:12px;">';
    echo '<select name="kind" style="min-height:38px;border:1px solid #cbd5e1;border-radius:8px;padding:8px 12px;font-size:12px;background:white;">';
    echo '<option value="">All Classifications</option>';
    echo '<option value="clinical"' . ($kindFilter === 'clinical' ? ' selected' : '') . '>Clinical</option>';
    echo '<option value="support"' . ($kindFilter === 'support' ? ' selected' : '') . '>Support</option>';
    echo '<option value="administrative"' . ($kindFilter === 'administrative' ? ' selected' : '') . '>Administrative</option>';
    echo '</select>';
    echo '<button class="button button-outline" style="min-height:38px;">Filter</button>';
    if ($q !== '' || $kindFilter !== '') echo '<a href="/index.php?page=departments" class="button button-outline" style="min-height:38px;">Reset</a>';
    echo '</form>';
    echo '<button type="button" class="button button-primary" onclick="toggleDeptForm()"><span class="nav-icon" style="width:14px;height:14px;">' . get_svg_icon('plus') . '</span> + Add Department</button>';
    echo '</div>';

    // Add Department Form Drawer
    echo '<div id="deptFormDrawer" class="card" style="display:none;margin-bottom:22px;border:1.5px solid #0c928c;background:#f8fdfc;">';
    echo '<div class="card-head"><div><span class="eyebrow">NEW DEPARTMENT</span><h3 style="margin:0;">Create Department Division</h3></div><button type="button" class="button button-outline small" onclick="toggleDeptForm()">✕ Close</button></div>';
    echo '<form method="post" action="/index.php?page=departments" class="field-grid">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<label class="field">Department Code *<input name="code" required placeholder="e.g. DEPT-OPD-CAR"></label>';
    echo '<label class="field">Department Name *<input name="name" required placeholder="e.g. Cardiology OPD Unit"></label>';
    echo '<label class="field">Classification Kind *<select name="kind"><option value="clinical">Clinical (Doctor consultation & diagnostic care)</option><option value="support">Support (Pharmacy, Inventory & Logistics)</option><option value="administrative">Administrative (Reception, Finance & Management)</option></select></label>';
    echo '<label class="field">Status<select name="active"><option value="1">Active</option><option value="0">Inactive</option></select></label>';
    echo '<div class="span-2 form-actions" style="margin-top:10px;">';
    echo '<button type="submit" class="button button-primary">Save Department</button>';
    echo '<button type="button" class="button button-outline" onclick="toggleDeptForm()">Cancel</button>';
    echo '</div>';
    echo '</form>';
    echo '</div>';

    // Department Table
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div class="table-wrap"><table>';
    echo '<thead><tr><th>Code</th><th>Department Name</th><th>Classification</th><th>Branch</th><th>Status</th><th>Actions</th></tr></thead>';
    echo '<tbody>';
    if (empty($deptList)) {
        echo '<tr><td colspan="6"><div class="empty-state">No departments found.</div></td></tr>';
    } else {
        foreach ($deptList as $d) {
            $isAct = !empty($d['active']);
            $kindClass = $d['kind'] === 'clinical' ? 'teal' : ($d['kind'] === 'support' ? 'blue' : 'amber');
            echo '<tr>';
            echo '<td><span class="code-chip">' . e($d['code']) . '</span></td>';
            echo '<td><strong>' . e($d['name']) . '</strong></td>';
            echo '<td><span class="pill" style="font-size:10px;">' . e(ucfirst($d['kind'])) . '</span></td>';
            echo '<td>' . e($d['branch_name'] ?: 'Dhaka Main Branch') . '</td>';
            echo '<td><span class="active-tag" style="' . ($isAct ? 'background:#dcfce7;color:#15803d;' : 'background:#fee2e2;color:#b91c1c;') . '">' . ($isAct ? '● Active' : '○ Inactive') . '</span></td>';
            
            // Dynamic context-aware destination link based on department kind & name
            $deptNameLower = strtolower($d['name']);
            if (str_contains($deptNameLower, 'pharmacy') || str_contains($deptNameLower, 'dispensary')) {
                $destUrl = '/index.php?page=pharmacy_items';
                $destLabel = 'Pharmacy ↗';
                $destClass = 'button-outline';
            } elseif (str_contains($deptNameLower, 'radiology') || str_contains($deptNameLower, 'pacs') || str_contains($deptNameLower, 'imaging')) {
                $destUrl = '/index.php?page=radiology_worklist';
                $destLabel = 'Radiology ↗';
                $destClass = 'button-outline';
            } elseif (str_contains($deptNameLower, 'pathology') || str_contains($deptNameLower, 'lab') || str_contains($deptNameLower, 'lis')) {
                $destUrl = '/index.php?page=sample_desk';
                $destLabel = 'LIS Lab ↗';
                $destClass = 'button-outline';
            } elseif ($d['kind'] === 'support') {
                $destUrl = '/index.php?page=inventory_stock';
                $destLabel = 'Inventory ↗';
                $destClass = 'button-outline';
            } elseif ($d['kind'] === 'administrative') {
                $destUrl = '/index.php?page=executive_dashboard';
                $destLabel = 'Executive ↗';
                $destClass = 'button-outline';
            } else {
                $destUrl = '/index.php?page=doctors&specialty=' . urlencode(explode('&', $d['name'])[0] ?? $d['name']);
                $destLabel = 'Doctors ↗';
                $destClass = 'button-primary';
            }
            echo '<td><a href="' . e($destUrl) . '" class="button ' . $destClass . ' small">' . e($destLabel) . '</a></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
    echo '</div>';

    echo '<script>
    function toggleDeptForm() {
        var el = document.getElementById("deptFormDrawer");
        if(el) {
            el.style.display = el.style.display === "none" ? "block" : "none";
            if(el.style.display === "block") el.scrollIntoView({ behavior: "smooth" });
        }
    }
    </script>';

    page_end();
}

// =========================================================================
// SUB-MODULE 4: PATIENTS DOCUMENTS
// =========================================================================
function render_patient_documents(PDO $db, array $user): void
{
    Security::requirePermission($db, 'patients.view');

    $q = trim((string)($_GET['q'] ?? ''));
    $cat = (string)($_GET['cat'] ?? 'all');
    $patientIdFilter = (int)($_GET['patient_id'] ?? 0);

    page_start($db, $user, 'patient_documents', 'Patient Documents & Electronic Health Records (EHR)', 'Centralized clinical archives: prescriptions, automated lab reports, radiology DICOM scans and patient identity files.');

    // Query Documents
    $sql = "SELECT pd.*, p.name AS patient_name, p.mrn, p.mobile, p.gender 
            FROM patient_documents pd 
            JOIN patients p ON p.id = pd.patient_id 
            WHERE 1=1";
    $params = [];
    if ($patientIdFilter > 0) {
        $sql .= " AND pd.patient_id = ?";
        $params[] = $patientIdFilter;
    }
    if ($q !== '') {
        $sql .= " AND (pd.title LIKE ? OR p.name LIKE ? OR p.mrn LIKE ? OR pd.uploaded_by LIKE ?)";
        $wild = '%' . $q . '%';
        array_push($params, $wild, $wild, $wild, $wild);
    }
    if ($cat !== 'all' && in_array($cat, ['prescription', 'lab_report', 'radiology_scan', 'nid_insurance', 'other'], true)) {
        $sql .= " AND pd.doc_type = ?";
        $params[] = $cat;
    }
    $sql .= " ORDER BY pd.id DESC";

    $stmt = $db->prepare($sql);
    $stmt->execute($params);
    $docsList = $stmt->fetchAll(PDO::FETCH_ASSOC);

    $totalDocs = count($docsList);
    $rxCount = count(array_filter($docsList, fn($d) => $d['doc_type'] === 'prescription'));
    $labCount = count(array_filter($docsList, fn($d) => $d['doc_type'] === 'lab_report'));
    $radCount = count(array_filter($docsList, fn($d) => $d['doc_type'] === 'radiology_scan'));

    // Top Metric KPIs
    echo '<div class="stats-grid" style="margin-bottom:22px;">';
    echo '<div class="stat-card" style="border-left:4px solid #0c928c;"><div class="stat-icon teal">' . get_svg_icon('file-text') . '</div><span>Total Documents</span><strong>' . $totalDocs . ' Files</strong><small style="color:#0c928c;font-weight:700;">● Secure Cloud Archive</small></div>';
    echo '<div class="stat-card" style="border-left:4px solid #0ea5e9;"><div class="stat-icon blue">' . get_svg_icon('stethoscope') . '</div><span>Prescriptions (E-Rx)</span><strong>' . $rxCount . ' Prescriptions</strong><small style="color:#0ea5e9;">Doctor Chamber Issued</small></div>';
    echo '<div class="stat-card" style="border-left:4px solid #10b981;"><div class="stat-icon green">' . get_svg_icon('flask') . '</div><span>LIS Lab Reports</span><strong>' . $labCount . ' Reports</strong><small style="color:#10b981;">Pathologist Approved</small></div>';
    echo '<div class="stat-card" style="border-left:4px solid #f59e0b;"><div class="stat-icon amber">' . get_svg_icon('radiology') . '</div><span>Radiology & PACS</span><strong>' . $radCount . ' Scans</strong><small style="color:#f59e0b;">X-Ray & Ultrasound</small></div>';
    echo '</div>';

    // Action Bar
    echo '<div class="submod-action-bar">';
    echo '<form method="get" action="/index.php" style="display:flex;gap:10px;flex:1;max-width:650px;">';
    echo '<input type="hidden" name="page" value="patient_documents">';
    if ($patientIdFilter) echo '<input type="hidden" name="patient_id" value="' . e($patientIdFilter) . '">';
    echo '<input name="q" value="' . e($q) . '" placeholder="Search Document by Title, Patient Name, MRN..." style="flex:1;min-height:38px;border:1px solid #cbd5e1;border-radius:8px;padding:8px 14px;font-size:12px;">';
    echo '<select name="cat" style="min-height:38px;border:1px solid #cbd5e1;border-radius:8px;padding:8px 12px;font-size:12px;background:white;">';
    echo '<option value="all">All File Categories</option>';
    echo '<option value="prescription"' . ($cat === 'prescription' ? ' selected' : '') . '>Prescriptions</option>';
    echo '<option value="lab_report"' . ($cat === 'lab_report' ? ' selected' : '') . '>Lab Reports</option>';
    echo '<option value="radiology_scan"' . ($cat === 'radiology_scan' ? ' selected' : '') . '>Radiology Scans</option>';
    echo '<option value="nid_insurance"' . ($cat === 'nid_insurance' ? ' selected' : '') . '>NID / Insurance</option>';
    echo '</select>';
    echo '<button class="button button-outline" style="min-height:38px;">Filter</button>';
    if ($q !== '' || $cat !== 'all' || $patientIdFilter > 0) echo '<a href="/index.php?page=patient_documents" class="button button-outline" style="min-height:38px;">Reset</a>';
    echo '</form>';
    echo '<button type="button" class="button button-primary" onclick="toggleDocForm()"><span class="nav-icon" style="width:14px;height:14px;">' . get_svg_icon('plus') . '</span> + Upload Patient Document</button>';
    echo '</div>';

    // Upload Document Form Drawer
    $patientsList = $db->query("SELECT id, name, mrn, mobile FROM patients ORDER BY name ASC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);
    echo '<div id="docFormDrawer" class="card" style="display:none;margin-bottom:22px;border:1.5px solid #0c928c;background:#f8fdfc;">';
    echo '<div class="card-head"><div><span class="eyebrow">EHR UPLOAD DESK</span><h3 style="margin:0;">Upload & Attach Patient Document</h3></div><button type="button" class="button button-outline small" onclick="toggleDocForm()">✕ Close</button></div>';
    echo '<form method="post" action="/index.php?page=patient_documents" enctype="multipart/form-data" class="field-grid">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<label class="field">Select Patient *<select name="patient_id" required>';
    echo '<option value="">-- Choose Registered Patient --</option>';
    foreach ($patientsList as $p) {
        $sel = $patientIdFilter === (int)$p['id'] ? ' selected' : '';
        echo '<option value="' . e($p['id']) . '"' . $sel . '>' . e($p['name']) . ' (' . e($p['mrn']) . ' - ' . e($p['mobile']) . ')</option>';
    }
    echo '</select></label>';
    echo '<label class="field">Document Category *<select name="doc_type" required>';
    echo '<option value="prescription">Prescription (Chamber Rx)</option>';
    echo '<option value="lab_report">Lab Report (Pathology LIS)</option>';
    echo '<option value="radiology_scan">Radiology Scan (X-Ray / USG / CT)</option>';
    echo '<option value="discharge_summary">Discharge Summary</option>';
    echo '<option value="nid_insurance">NID / Corporate Insurance Card</option>';
    echo '<option value="other">Other Clinical Document</option>';
    echo '</select></label>';
    echo '<label class="field span-2">Document Title / Clinical Description *<input name="title" required placeholder="e.g. HbA1c & Fasting Glucose Verified Lab Report"></label>';
    
    // Physical File Upload input field
    echo '<div class="field span-2" style="background:#f0fdfa;border:1px dashed #0d9488;border-radius:10px;padding:14px;">';
    echo '<label style="font-weight:700;color:#0f766e;font-size:13px;display:block;margin-bottom:6px;">📎 Choose File Attachment (PDF, JPG, PNG, DICOM)</label>';
    echo '<input type="file" name="document_file" accept=".pdf,.jpg,.jpeg,.png,.webp,.dcm" required style="padding:8px 12px;background:#ffffff;border:1px solid #cbd5e1;border-radius:8px;width:100%;font-size:13px;">';
    echo '<small style="color:#64748b;margin-top:4px;display:block;">Supported file types: PDF, JPG, PNG, WebP or DICOM archive. Max 25 MB.</small>';
    echo '</div>';

    echo '<label class="field span-2">Clinical Notes & Observations<textarea name="notes" rows="2" placeholder="Optional notes for physician reference..."></textarea></label>';
    echo '<div class="span-2 form-actions" style="margin-top:10px;">';
    echo '<button type="submit" class="button button-primary">Upload & Save to EHR Archive</button>';
    echo '<button type="button" class="button button-outline" onclick="toggleDocForm()">Cancel</button>';
    echo '</div>';
    echo '</form>';
    echo '</div>';

    // Documents Cards Grid
    echo '<div class="doc-archive-grid">';
    if (empty($docsList)) {
        echo '<div class="empty-state" style="grid-column:1/-1;">No documents match your query. Click "+ Upload Patient Document" to attach files.</div>';
    } else {
        foreach ($docsList as $doc) {
            $type = $doc['doc_type'];
            $icon = match($type) {
                'prescription' => get_svg_icon('stethoscope'),
                'lab_report' => get_svg_icon('flask'),
                'radiology_scan' => get_svg_icon('radiology'),
                'nid_insurance' => get_svg_icon('id-card'),
                'discharge_summary' => get_svg_icon('clipboard'),
                default => get_svg_icon('file-text')
            };
            $sizeKb = round(($doc['file_size'] ?: 450000) / 1024);
            $docId = (int)$doc['id'];
            $viewUrl = '/index.php?page=download_document&id=' . $docId;
            $downloadUrl = '/index.php?page=download_document&id=' . $docId . '&download=1';
            echo '<div class="doc-file-card">';
            echo '<div>';
            echo '<div class="doc-file-header">';
            echo '<div class="doc-type-icon ' . e($type) . '">' . $icon . '</div>';
            echo '<div class="doc-file-meta">';
            echo '<h4>' . e($doc['title']) . '</h4>';
            echo '<small>Patient: <strong>' . e($doc['patient_name']) . '</strong> (' . e($doc['mrn']) . ')</small>';
            echo '</div>';
            echo '</div>';

            echo '<div style="display:flex;flex-direction:column;gap:5px;font-size:11px;color:#475569;border-top:1px dashed #f1f5f9;padding:10px 0;margin-bottom:12px;">';
            echo '<div style="display:flex;justify-content:space-between;"><span>Category:</span><span class="pill" style="font-size:9px;padding:2px 7px;">' . e(ucwords(str_replace('_',' ',$type))) . '</span></div>';
            echo '<div style="display:flex;justify-content:space-between;"><span>Uploaded By:</span><strong>' . e($doc['uploaded_by'] ?: 'Reception') . '</strong></div>';
            echo '<div style="display:flex;justify-content:space-between;"><span>Date Archived:</span><strong>' . e(date('d M Y, h:i A', strtotime($doc['created_at']))) . '</strong></div>';
            echo '<div style="display:flex;justify-content:space-between;"><span>File Format:</span><strong style="color:#0c928c;">PDF (' . $sizeKb . ' KB)</strong></div>';
            echo '</div>';
            echo '</div>';

            echo '<div style="display:flex;gap:8px;">';
            echo '<a href="' . $viewUrl . '" target="_blank" class="button button-outline small" style="flex:1;display:inline-flex;align-items:center;justify-content:center;gap:6px;"><span style="width:14px;height:14px;display:inline-flex;">' . get_svg_icon('eye') . '</span> View</a>';
            echo '<a href="' . $downloadUrl . '" class="button button-primary small" style="flex:1;display:inline-flex;align-items:center;justify-content:center;gap:6px;"><span style="width:14px;height:14px;display:inline-flex;">' . get_svg_icon('download') . '</span> Download</a>';
            echo '</div>';
            echo '</div>';
        }
    }
    echo '</div>';

    echo '<script>
    function toggleDocForm() {
        var el = document.getElementById("docFormDrawer");
        if(el) {
            el.style.display = el.style.display === "none" ? "block" : "none";
            if(el.style.display === "block") el.scrollIntoView({ behavior: "smooth" });
        }
    }
    </script>';

    page_end();
}

// =========================================================================
