// =========================================================================
function render_ordering_users(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');

    $q = trim((string)($_GET['q'] ?? ''));

    page_start($db, $user, 'ordering_users', 'Walk-in & Local In-Clinic Customers', 'Manage walk-in counter clients, registered OTC medicine buyers, and direct in-clinic diagnostic test patrons.');

    // Fetch Ordering Users (Joined from patients & patient_portal_accounts with real DB aggregates)
    $sql = "SELECT p.id, p.mrn, p.name, p.mobile, p.email, p.gender, p.category, p.wallet_balance, p.loyalty_points, p.created_at,
            ppa.last_login_at, ppa.id AS portal_id,
            COALESCE((SELECT COUNT(*) FROM diagnostic_orders o WHERE o.patient_id = p.id), 0) AS test_orders_count,
            COALESCE((SELECT SUM(o.payable_amount) FROM diagnostic_orders o WHERE o.patient_id = p.id), 0) AS test_orders_total,
            COALESCE((SELECT COUNT(*) FROM pharmacy_invoices pi WHERE pi.patient_id = p.id OR (pi.patient_mobile IS NOT NULL AND pi.patient_mobile = p.mobile)), 0) AS med_orders_count,
            COALESCE((SELECT SUM(pi.payable_amount) FROM pharmacy_invoices pi WHERE pi.patient_id = p.id OR (pi.patient_mobile IS NOT NULL AND pi.patient_mobile = p.mobile)), 0) AS med_orders_total
            FROM patients p
            LEFT JOIN patient_portal_accounts ppa ON ppa.patient_id = p.id
            WHERE 1=1";
    $params = [];
    if ($q !== '') {
        $sql .= " AND (p.name LIKE ? OR p.mobile LIKE ? OR p.mrn LIKE ? OR p.email LIKE ?)";
        $wild = '%' . $q . '%';
        array_push($params, $wild, $wild, $wild, $wild);
    }
    $sql .= " ORDER BY p.id ASC";

    $stmt = $db->prepare($sql);
    $stmt->execute($params);
    $userRows = $stmt->fetchAll(PDO::FETCH_ASSOC);

    $orderingUsers = [];
    foreach ($userRows as $r) {
        $medOrders = (int)$r['med_orders_count'];
        $medAmount = (float)$r['med_orders_total'];
        $testOrders = (int)$r['test_orders_count'];
        $testAmount = (float)$r['test_orders_total'];

        $orderingUsers[] = array_merge($r, [
            'med_orders' => $medOrders,
            'med_amount' => $medAmount,
            'test_orders' => $testOrders,
            'test_amount' => $testAmount,
            'wallet_balance' => (float)($r['wallet_balance'] ?? 0.00),
            'loyalty_points' => (int)($r['loyalty_points'] ?? 0)
        ]);
    }

    $totalOrdering = count($orderingUsers);
    $totalMedOrders = array_sum(array_column($orderingUsers, 'med_orders'));
    $totalTestOrders = array_sum(array_column($orderingUsers, 'test_orders'));
    $totalGMV = array_sum(array_map(fn($u) => $u['med_amount'] + $u['test_amount'], $orderingUsers));

    // Top Metric KPIs
    echo '<div class="stats-grid" style="margin-bottom:22px;">';
    echo '<a href="/index.php?page=ordering_users" class="stat-card" style="background:#f0fdfa;border:1px solid #ccfbf1;border-left:4px solid #0c928c;text-decoration:none;cursor:pointer;transition:transform 0.15s,box-shadow 0.15s;border-radius:12px;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 14px rgba(12,146,140,0.15)\'" onmouseout="this.style.transform=\'none\';this.style.boxShadow=\'none\'"><div class="stat-icon teal">' . get_svg_icon('users') . '</div><span>Total Walk-in Customers ↗</span><strong style="color:#0f766e;">' . $totalOrdering . ' Registered</strong><small style="color:#0c928c;font-weight:700;">● In-Clinic Database</small></a>';
    echo '<a href="/index.php?page=pharmacy_pos" class="stat-card" style="background:#f0fdf4;border:1px solid #dcfce7;border-left:4px solid #10b981;text-decoration:none;cursor:pointer;transition:transform 0.15s,box-shadow 0.15s;border-radius:12px;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 14px rgba(16,185,129,0.15)\'" onmouseout="this.style.transform=\'none\';this.style.boxShadow=\'none\'"><div class="stat-icon green">' . get_svg_icon('pill') . '</div><span>Medicine Counter Sales ↗</span><strong style="color:#15803d;">' . $totalMedOrders . ' Orders</strong><small style="color:#10b981;">Pharmacy POS Purchases</small></a>';
    echo '<a href="/index.php?page=orders" class="stat-card" style="background:#f0f9ff;border:1px solid #e0f2fe;border-left:4px solid #0ea5e9;text-decoration:none;cursor:pointer;transition:transform 0.15s,box-shadow 0.15s;border-radius:12px;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 14px rgba(14,165,233,0.15)\'" onmouseout="this.style.transform=\'none\';this.style.boxShadow=\'none\'"><div class="stat-icon blue">' . get_svg_icon('flask') . '</div><span>Direct Lab Bookings ↗</span><strong style="color:#0369a1;">' . $totalTestOrders . ' Bookings</strong><small style="color:#0ea5e9;">Diagnostic Counter Tests</small></a>';
    echo '<a href="/index.php?page=billing" class="stat-card" style="background:#fffbeb;border:1px solid #fef3c7;border-left:4px solid #f59e0b;text-decoration:none;cursor:pointer;transition:transform 0.15s,box-shadow 0.15s;border-radius:12px;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 14px rgba(245,158,11,0.15)\'" onmouseout="this.style.transform=\'none\';this.style.boxShadow=\'none\'"><div class="stat-icon amber">' . get_svg_icon('cash') . '</div><span>Total Counter GMV ↗</span><strong style="color:#b45309;">BDT ' . number_format($totalGMV, 2) . '</strong><small style="color:#f59e0b;">Medicine & Diagnostic Revenue</small></a>';
    echo '</div>';

    // Action Bar
    echo '<div class="submod-action-bar">';
    echo '<form method="get" action="/index.php" style="display:flex;gap:10px;flex:1;max-width:550px;">';
    echo '<input type="hidden" name="page" value="ordering_users">';
    echo '<input name="q" value="' . e($q) . '" placeholder="Search Customer by Name, Mobile, ID, Email..." style="flex:1;min-height:38px;border:1px solid #cbd5e1;border-radius:8px;padding:8px 14px;font-size:12px;">';
    echo '<button class="button button-outline" style="min-height:38px;">Search</button>';
    if ($q !== '') echo '<a href="/index.php?page=ordering_users" class="button button-outline" style="min-height:38px;">Reset</a>';
    echo '</form>';
    echo '<button type="button" class="button button-primary" onclick="toggleOrderingUserForm()"><span class="nav-icon" style="width:14px;height:14px;">' . get_svg_icon('plus') . '</span> + Register Walk-in Customer</button>';
    echo '</div>';

    // Add Ordering User Drawer
    echo '<div id="orderingUserFormDrawer" class="card" style="display:none;margin-bottom:22px;border:1.5px solid #0c928c;background:#f8fdfc;">';
    echo '<div class="card-head"><div><span class="eyebrow">NEW WALK-IN CUSTOMER</span><h3 style="margin:0;">Register In-Clinic Walk-in Customer</h3></div><button type="button" class="button button-outline small" onclick="toggleOrderingUserForm()">✕ Close</button></div>';
    echo '<form method="post" action="/index.php?page=ordering_users" class="field-grid">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<label class="field">Customer Full Name *<input name="name" required placeholder="Full Name"></label>';
    echo '<label class="field">Mobile Number (Primary Identifier) *<input name="mobile" required placeholder="017xxxxxxxx"></label>';
    echo '<label class="field">Email Address (Optional)<input type="email" name="email" placeholder="customer@domain.com (Optional)"></label>';
    echo '<label class="field">Gender<select name="gender"><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select></label>';
    echo '<label class="field">Initial Wallet / Store Credit (BDT)<input type="number" step="0.01" name="wallet_balance" value="0.00" placeholder="0.00"></label>';
    echo '<div class="span-2 form-actions" style="margin-top:10px;">';
    echo '<button type="submit" class="button button-primary">Save & Register Local Customer</button>';
    echo '<button type="button" class="button button-outline" onclick="toggleOrderingUserForm()">Cancel</button>';
    echo '</div>';
    echo '</form>';
    echo '</div>';

    // Ordering Users Table
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div class="table-wrap"><table>';
    echo '<thead><tr><th>Customer Profile</th><th>Contact Details</th><th>Counter Type</th><th>Medicine Purchases</th><th>Direct Lab Bookings</th><th>Loyalty / Store Credit</th><th>Quick Actions</th></tr></thead>';
    echo '<tbody>';
    if (empty($orderingUsers)) {
        echo '<tr><td colspan="7"><div class="empty-state">No walk-in customers found.</div></td></tr>';
    } else {
        foreach ($orderingUsers as $u) {
            echo '<tr>';
            echo '<td><strong>' . e($u['name']) . '</strong><br><span class="code-chip">' . e($u['mrn']) . '</span></td>';
            echo '<td><strong>' . e($u['mobile']) . '</strong><br><small class="muted">' . e($u['email'] ?: 'No email registered') . '</small></td>';
            echo '<td><span class="channel-pill local">🏥 In-Clinic Walk-in</span></td>';
            echo '<td><a href="/index.php?page=pharmacy_receipt" style="text-decoration:none;display:inline-block;padding:4px 8px;border-radius:6px;background:#f0fdf4;border:1px solid #bbf7d0;" title="View Customer Medicine Counter Purchases"><strong>' . $u['med_orders'] . ' Orders ↗</strong><br><small style="color:#059669;font-weight:700;">BDT ' . number_format($u['med_amount']) . '</small></a></td>';
            echo '<td><a href="/index.php?page=orders" style="text-decoration:none;display:inline-block;padding:4px 8px;border-radius:6px;background:#f0f9ff;border:1px solid #bae6fd;" title="View Customer Direct Lab Test Bookings"><strong>' . $u['test_orders'] . ' Bookings ↗</strong><br><small style="color:#0284c7;font-weight:700;">BDT ' . number_format($u['test_amount']) . '</small></a></td>';
            echo '<td><strong>BDT ' . number_format($u['wallet_balance']) . '</strong><br><small style="color:#d97706;font-weight:700;">★ ' . $u['loyalty_points'] . ' Pts</small></td>';
            echo '<td>';
            echo '<div style="display:flex;gap:6px;align-items:center;">';
            echo '<button type="button" class="button button-outline small" style="color:#0284c7;border-color:#bae6fd;padding:4px 10px;font-weight:700;" onclick="openEditCustomerModal(' . htmlspecialchars(json_encode($u), ENT_QUOTES, 'UTF-8') . ')" title="View & Edit Customer Details">✏️ Edit</button>';
            echo '<a href="/index.php?page=orders" class="button button-primary small" title="Create Lab Order">+ Direct Lab</a>';
            echo '<a href="/index.php?page=pharmacy_pos&patient_name=' . urlencode($u['name']) . '&patient_uhid=' . urlencode($u['mobile']) . '" class="button button-outline small" title="Dispense Medicine">+ POS Sale</a>';
            echo '</div>';
            echo '</td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
    echo '</div>';

    // Edit Customer Modal Drawer
    echo '<div id="editCustomerModal" style="display:none;position:fixed;inset:0;background:rgba(15,23,42,0.6);z-index:99999;backdrop-filter:blur(4px);align-items:center;justify-content:center;padding:20px;">';
    echo '<div style="background:#ffffff;border-radius:16px;max-width:580px;width:100%;box-shadow:0 20px 40px rgba(0,0,0,0.25);overflow:hidden;border:1px solid #e2e8f0;animation:fadeIn 0.2s ease;">';
    echo '<div style="background:linear-gradient(135deg, #092c36 0%, #0c928c 100%);padding:18px 24px;color:white;display:flex;justify-content:space-between;align-items:center;">';
    echo '<div><h4 style="margin:0;font-size:17px;font-weight:800;letter-spacing:-0.02em;">👤 View & Edit Customer Account</h4><p style="margin:2px 0 0;font-size:12px;color:#c2e4e8;">Update profile details, contact number, email & store credit wallet.</p></div>';
    echo '<button type="button" onclick="closeEditCustomerModal()" style="background:transparent;border:0;color:white;font-size:22px;cursor:pointer;line-height:1;">✕</button>';
    echo '</div>';
    echo '<form method="post" action="/index.php?page=ordering_users" style="padding:24px;">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<input type="hidden" name="action" value="edit_customer">';
    echo '<input type="hidden" name="customer_id" id="edit_cust_id" value="">';
    echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;">';
    echo '<div class="field"><label style="font-weight:700;font-size:12.5px;color:#334155;">Customer Identifier (MRN / LOC)</label><input type="text" id="edit_cust_mrn" readonly style="background:#f8fafc;padding:9px;border:1px solid #cbd5e1;border-radius:8px;font-family:monospace;font-weight:700;color:#0284c7;"></div>';
    echo '<div class="field"><label style="font-weight:700;font-size:12.5px;color:#334155;">Counter Category</label><input type="text" value="Local Walk-in Customer" readonly style="background:#f8fafc;padding:9px;border:1px solid #cbd5e1;border-radius:8px;font-weight:700;color:#059669;"></div>';
    echo '</div>';
    echo '<div style="margin-bottom:14px;"><label style="font-weight:700;font-size:12.5px;color:#334155;display:block;margin-bottom:4px;">Customer Full Name *</label><input type="text" name="name" id="edit_cust_name" required style="width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-size:14px;"></div>';
    echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;">';
    echo '<div class="field"><label style="font-weight:700;font-size:12.5px;color:#334155;">Primary Mobile Number *</label><input type="text" name="mobile" id="edit_cust_mobile" required style="padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-size:13.5px;"></div>';
    echo '<div class="field"><label style="font-weight:700;font-size:12.5px;color:#334155;">Gender</label><select name="gender" id="edit_cust_gender" style="padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-size:13.5px;"><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select></div>';
    echo '</div>';
    echo '<div style="margin-bottom:14px;"><label style="font-weight:700;font-size:12.5px;color:#334155;display:block;margin-bottom:4px;">Email Address (Optional)</label><input type="email" name="email" id="edit_cust_email" placeholder="customer@domain.com (Optional)" style="width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-size:13.5px;"></div>';
    echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:20px;">';
    echo '<div class="field"><label style="font-weight:700;font-size:12.5px;color:#334155;">Wallet Balance (BDT)</label><input type="number" step="0.01" name="wallet_balance" id="edit_cust_wallet" style="padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-size:13.5px;"></div>';
    echo '<div class="field"><label style="font-weight:700;font-size:12.5px;color:#334155;">Loyalty Points</label><input type="number" name="loyalty_points" id="edit_cust_loyalty" style="padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-size:13.5px;"></div>';
    echo '</div>';
    echo '<div style="display:flex;justify-content:flex-end;gap:10px;">';
    echo '<button type="button" class="button button-outline" onclick="closeEditCustomerModal()">Cancel</button>';
    echo '<button type="submit" class="button button-primary" style="background:#0c928c;border-color:#0c928c;padding:10px 22px;font-weight:800;">Save Changes</button>';
    echo '</div>';
    echo '</form></div></div>';

    echo '<script>
    function toggleOrderingUserForm() {
        var el = document.getElementById("orderingUserFormDrawer");
        if(el) {
            el.style.display = el.style.display === "none" ? "block" : "none";
            if(el.style.display === "block") el.scrollIntoView({ behavior: "smooth" });
        }
    }
    function openEditCustomerModal(cust) {
        if(!cust) return;
        document.getElementById("edit_cust_id").value = cust.id || "";
        document.getElementById("edit_cust_mrn").value = cust.mrn || "";
        document.getElementById("edit_cust_name").value = cust.name || "";
        document.getElementById("edit_cust_mobile").value = cust.mobile || "";
        document.getElementById("edit_cust_email").value = cust.email || "";
        document.getElementById("edit_cust_gender").value = cust.gender || "male";
        document.getElementById("edit_cust_wallet").value = cust.wallet_balance !== undefined ? parseFloat(cust.wallet_balance).toFixed(2) : "0.00";
        document.getElementById("edit_cust_loyalty").value = cust.loyalty_points !== undefined ? cust.loyalty_points : "0";
        var modal = document.getElementById("editCustomerModal");
        if(modal) modal.style.display = "flex";
    }
    function closeEditCustomerModal() {
        var modal = document.getElementById("editCustomerModal");
        if(modal) modal.style.display = "none";
    }
    </script>';

    page_end();
}

function render_masters(PDO $db, array $user): void

{
    Security::requirePermission($db,'masters.view');
    $entity = (string)($_GET['entity'] ?? 'branches');
    $spec = Masters::spec($entity);
    $edit = max(0,(int)($_GET['edit'] ?? 0));
    $row = $edit ? Masters::one($db,$entity,$edit) : [];
    $search = mb_substr(trim((string)($_GET['q'] ?? '')),0,80);
    $rows = Masters::scoped($db,$entity,100,$search);
    page_start($db,$user,'masters','Core masters','Configure the shared data used throughout the diagnostic center.');
    echo '<div class="master-layout"><aside class="master-nav"><div class="master-nav-title">MASTER DATA</div>';
    foreach (['Locations & setup'=>['organizations','branches','departments','service_units','rooms','counters','collection_booths','cost_centers'],'Clinical catalog'=>['sample_types','containers','methodologies','measurement_units','report_templates','diagnostic_tests','test_panels'],'Relationships'=>['doctors','referrers','corporate_clients','suppliers'],'Finance setup'=>['banks','payment_methods','discount_types','reason_codes','tax_rules']] as $group=>$entities) {
        echo '<div class="master-group">' . e($group) . '</div>';
        foreach ($entities as $key) echo '<a class="' . ($entity===$key?'selected':'') . '" href="/index.php?page=masters&entity=' . e($key) . '">' . e(Masters::all()[$key]['label']) . '</a>';
    }
    echo '</aside><div class="master-body"><section class="card"><div class="card-head"><div><span class="eyebrow">MASTER DATA</span><h3>' . e($spec['label']) . '</h3><p>Search, review and maintain configuration records.</p></div><span class="pill">' . count($rows) . ' shown</span></div><div class="table-actions"><form method="get" action="/index.php" class="search-form"><input type="hidden" name="page" value="masters"><input type="hidden" name="entity" value="' . e($entity) . '"><input name="q" value="' . e($search) . '" placeholder="Search by name or code..." aria-label="Search"><button class="button button-outline">Search</button></form>';
    if (Security::can($db,'masters.edit')) echo '<a class="button button-primary" href="/index.php?page=masters&entity=' . e($entity) . '&new=1">+ Add new</a>';
    echo '</div><div class="table-wrap"><table><thead><tr><th>ID</th>';
    if (isset($spec['fields']['code'])) echo '<th>Code</th>';
    echo '<th>Name</th><th>Status</th><th></th></tr></thead><tbody>';
    if (!$rows) echo '<tr><td colspan="5"><div class="empty-state">No records found. Add the first entry to get started.</div></td></tr>';
    foreach ($rows as $item) {
        echo '<tr><td class="muted">#' . e($item['id']) . '</td>';
        if (isset($spec['fields']['code'])) echo '<td><span class="code-chip">' . e($item['code']) . '</span></td>';
        echo '<td><strong>' . e($item['name']) . '</strong></td><td><span class="status ' . ((int)$item['active']?'on':'off') . '">' . ((int)$item['active']?'Active':'Inactive') . '</span></td><td><a class="text-link" href="/index.php?page=masters&entity=' . e($entity) . '&edit=' . e($item['id']) . '">Edit →</a></td></tr>';
    }
    echo '</tbody></table></div></section>';
    if ((isset($_GET['new']) || $edit) && Security::can($db,'masters.edit')) {
        echo '<section class="card edit-card"><div class="card-head"><div><span class="eyebrow">CONFIGURATION</span><h3>' . ($edit?'Edit':'Add') . ' ' . e(rtrim($spec['label'],'s')) . '</h3></div><a class="text-link" href="/index.php?page=masters&entity=' . e($entity) . '">Close ×</a></div><form method="post" action="/index.php?page=masters&entity=' . e($entity) . '" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="id" value="' . $edit . '">';
        foreach ($spec['fields'] as $key=>$type) {
            $optional = str_ends_with($type,'?');
            $base = rtrim($type,'?');
            $label = ucwords(str_replace('_',' ',$key));
            $value = $row[$key] ?? ($base==='bool'?1:'');
            echo '<label class="field ' . ($base==='textarea'?'span-2':'') . '">' . e($label) . ($optional?' <small>optional</small>':'');
            if ($base==='bool') echo '<span class="switch-field"><input type="checkbox" name="' . e($key) . '" value="1" ' . ($value?'checked':'') . '> Active</span>';
            elseif ($base==='textarea') echo '<textarea name="' . e($key) . '" rows="3">' . e($value) . '</textarea>';
            elseif (str_starts_with($base,'enum:')) {
                echo '<select name="' . e($key) . '" required><option value="">Select ' . e($label) . '</option>';
                foreach (explode(',',substr($base,5)) as $option) echo '<option value="' . e($option) . '" ' . ($value===$option?'selected':'') . '>' . e(ucwords(str_replace('_',' ',$option))) . '</option>';
                echo '</select>';
            } elseif (str_starts_with($base,'ref:')) {
                $target = substr($base,4);
                echo '<select name="' . e($key) . '" ' . ($optional?'':'required') . '><option value="">Select ' . e($label) . '</option>';
                foreach (Masters::choices($db,$target) as $choice) echo '<option value="' . e($choice['id']) . '" ' . ((string)$value===(string)$choice['id']?'selected':'') . '>' . e(($choice['code'] ?? '') . ' ' . $choice['name']) . '</option>';
                echo '</select>';
            } else {
                $htmlType = match($base) {'email'=>'email','date'=>'date','int','decimal'=>'number',default=>'text'};
                $extra = $base==='decimal'?' step="0.0001" min="0" max="100"':($base==='int'?' min="0"':'');
                echo '<input type="' . $htmlType . '" name="' . e($key) . '" value="' . e($value) . '" ' . ($optional?'':'required') . $extra . '>';
            }
            echo '</label>';
        }
        echo '<div class="form-actions span-2"><button class="button button-primary">Save record</button><a class="button button-outline" href="/index.php?page=masters&entity=' . e($entity) . '">Cancel</a></div></form></section>';
    }
    echo '</div></div>';
    page_end();
}
function render_users(PDO $db, array $user): void
{
    Security::requirePermission($db,'users.manage');
    page_start($db,$user,'users','People & access','Manage team accounts, roles and assigned branches.');
    $branches=Security::branchIds($db);
    $stmt=$db->prepare('SELECT DISTINCT u.id,u.name,u.email,u.active,u.last_login_at,GROUP_CONCAT(DISTINCT r.name ORDER BY r.name SEPARATOR ", ") roles FROM users u JOIN user_branches ub ON ub.user_id=u.id LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id WHERE ub.branch_id IN (' . implode(',',array_fill(0,count($branches),'?')) . ') GROUP BY u.id ORDER BY u.id DESC LIMIT 100');
    $stmt->execute($branches); $users=$stmt->fetchAll();
    $roles=$db->query('SELECT id,name FROM roles WHERE active=1 ORDER BY name')->fetchAll();
    $branchRows=Masters::choices($db,'branches');
    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">TEAM DIRECTORY</span><h3>Active accounts</h3></div><span class="pill">' . count($users) . ' users</span></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>';
    foreach($users as $item) echo '<tr><td><strong>' . e($item['name']) . '</strong><small class="cell-sub">' . e($item['email']) . '</small></td><td>' . e($item['roles']) . '</td><td><span class="status ' . ($item['active']?'on':'off') . '">' . ($item['active']?'Active':'Inactive') . '</span></td><td><a class="text-link" href="/index.php?page=users&edit=' . e($item['id']) . '">Edit</a></td></tr>';
    echo '</tbody></table></div></section>';
    $edit=max(0,(int)($_GET['edit']??0)); $selected=null;
    if($edit) { $stmt=$db->prepare('SELECT u.*,ur.role_id FROM users u JOIN user_roles ur ON ur.user_id=u.id WHERE u.id=?'); $stmt->execute([$edit]); $selected=$stmt->fetch(); if(!$selected || !in_array($edit,array_map('intval',array_column($users,'id')),true)) throw new RuntimeException('User unavailable.'); }
    $selectedBranches=[]; $selectedDepartments=[];
    if($edit) {
        $stmt=$db->prepare('SELECT branch_id FROM user_branches WHERE user_id=?'); $stmt->execute([$edit]); $selectedBranches=array_map('intval',$stmt->fetchAll(PDO::FETCH_COLUMN));
        $stmt=$db->prepare('SELECT department_id FROM user_departments WHERE user_id=?'); $stmt->execute([$edit]); $selectedDepartments=array_map('intval',$stmt->fetchAll(PDO::FETCH_COLUMN));
    }
    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">ACCESS CONTROL</span><h3>' . ($edit?'Edit account':'Invite a team member') . '</h3></div></div><form method="post" action="/index.php?page=users" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="id" value="' . $edit . '"><label class="field">Full name<input name="name" value="' . e($selected['name']??'') . '" required></label><label class="field">Email<input type="email" name="email" value="' . e($selected['email']??'') . '" required></label><label class="field">Role<select name="role_id" required><option value="">Choose role</option>';
    foreach($roles as $role) echo '<option value="' . e($role['id']) . '" ' . ((string)($selected['role_id']??'')===(string)$role['id']?'selected':'') . '>' . e($role['name']) . '</option>';
    echo '</select></label><div class="field"><span>Assigned branches</span><div class="check-list">';
    foreach($branchRows as $branch) echo '<label><input type="checkbox" name="branch_ids[]" value="' . e($branch['id']) . '" ' . (in_array((int)$branch['id'],$selectedBranches,true)?'checked':'') . '> ' . e($branch['name']) . '</label>';
    echo '</div></div><div class="field span-2"><span>Department scope <small>Optional for roles with all-department access</small></span><div class="check-list">';
    foreach(Masters::choices($db,'departments') as $department) echo '<label><input type="checkbox" name="department_ids[]" value="' . e($department['id']) . '" ' . (in_array((int)$department['id'],$selectedDepartments,true)?'checked':'') . '> ' . e($department['name']) . '</label>';
    echo '</div></div><label class="field span-2">' . ($edit?'New password (leave blank to keep)':'Temporary password') . '<input type="password" name="password" minlength="12" autocomplete="new-password" ' . ($edit?'':'required') . ' placeholder="Minimum 12 characters"></label><label class="field span-2"><span class="switch-field"><input type="checkbox" name="active" value="1" ' . (!isset($selected['active']) || $selected['active']?'checked':'') . '> Active account</span></label><div class="form-actions span-2"><button class="button button-primary">Save account</button></div></form></section></div>';
    page_end();
}
function render_approvals(PDO $db, array $user): void
{
    Security::requirePermission($db,'approvals.request');
    page_start($db,$user,'approvals','Approval desk','Separate request and decision responsibilities with a documented reason.');
    $ids=Security::branchIds($db);
    $stmt=$db->prepare('SELECT ar.*,u.name maker,ap.approver_permission FROM approval_requests ar JOIN users u ON u.id=ar.maker_id JOIN approval_policies ap ON ap.id=ar.policy_id WHERE ar.branch_id IN (' . implode(',',array_fill(0,count($ids),'?')) . ') ORDER BY ar.id DESC LIMIT 100');
    $stmt->execute($ids); $requests=$stmt->fetchAll();
    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">WORK QUEUE</span><h3>Requests</h3></div><span class="pill">' . count($requests) . ' shown</span></div>';
    if(!$requests) echo '<div class="empty-state">No approval requests yet.</div>';
    foreach($requests as $r) {
        echo '<div class="approval-item"><div class="approval-top"><strong>#' . e($r['id']) . ' · ' . e(ucwords(str_replace('_',' ',$r['action_type']))) . '</strong><span class="status ' . ($r['status']==='pending'?'pending':($r['status']==='approved'?'on':'off')) . '">' . e(ucfirst($r['status'])) . '</span></div><p>' . e($r['entity_type']) . ' #' . e($r['entity_id']) . ' · BDT ' . e(number_format((float)$r['amount'],2)) . '</p><small>Requested by ' . e($r['maker']) . ' · ' . e($r['created_at']) . '</small><small class="cell-sub">Reason: ' . e($r['request_reason']) . '</small>';
        if($r['status']==='pending' && (int)$r['maker_id']!==(int)$user['id'] && Security::can($db,$r['approver_permission'])) {
            echo '<form method="post" action="/index.php?page=approvals" class="decision-form"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="operation" value="decision"><input type="hidden" name="id" value="' . e($r['id']) . '"><input name="reason" placeholder="Decision reason" required maxlength="500"><button class="button button-primary" name="decision" value="approved">Approve</button><button class="button button-outline" name="decision" value="rejected">Reject</button></form>';
        }
        echo '</div>';
    }
    echo '</section><section class="card"><div class="card-head"><div><span class="eyebrow">NEW REQUEST</span><h3>Submit for review</h3></div></div><p class="helper">Provides central approval infrastructure. Sub-modules submit their transactions through the approval service.</p><form method="post" action="/index.php?page=approvals" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="operation" value="request"><label class="field">Action type<select name="action_type" required>';
    foreach(['discount','refund','result_correction','credit_note','purchase','journal_posting'] as $a) echo '<option value="' . $a . '">' . e(ucwords(str_replace('_',' ',$a))) . '</option>';
    echo '</select></label><label class="field">Branch<select name="branch_id" required>';
    foreach(Masters::choices($db,'branches') as $b) echo '<option value="' . e($b['id']) . '">' . e($b['name']) . '</option>';
    echo '</select></label><label class="field">Record type<input name="entity_type" maxlength="80" placeholder="e.g. invoice" required></label><label class="field">Record ID<input name="entity_id" maxlength="80" placeholder="e.g. 1024" required></label><label class="field span-2">Amount in BDT<input type="number" name="amount" step="0.01" min="0" value="0" required></label><label class="field span-2">Request reason<textarea name="reason" maxlength="500" rows="3" required></textarea></label><div class="form-actions span-2"><button class="button button-primary">Submit request</button></div></form></section></div>';
    page_end();
}
function render_audit(PDO $db, array $user): void
{
    Security::requirePermission($db,'audit.view');
    page_start($db,$user,'audit','Audit history','Review changes with user, time and record context.');
    $ids=Security::branchIds($db);
    $global=Security::can($db,'settings.manage') ? 'a.branch_id IS NULL OR ' : '';
    $stmt=$db->prepare('SELECT a.*,u.name actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id WHERE ' . $global . 'a.branch_id IN (' . implode(',',array_fill(0,count($ids),'?')) . ') ORDER BY a.id DESC LIMIT 100');
    $stmt->execute($ids);
    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">TRACEABILITY</span><h3>Recent events</h3></div><span class="pill">Latest 100</span></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Record</th><th>Action</th><th>Reason</th></tr></thead><tbody>';
    foreach($stmt->fetchAll() as $r) echo '<tr><td>' . e($r['occurred_at']) . '</td><td>' . e($r['actor']??'System') . '</td><td><strong>' . e($r['entity_type']) . '</strong> #' . e($r['entity_id']) . '</td><td><span class="code-chip">' . e($r['action']) . '</span></td><td>' . e($r['reason']??'—') . '</td></tr>';
    echo '</tbody></table></div></section>'; page_end();
}
function render_sequences(PDO $db, array $user): void
{
    Security::requirePermission($db,'sequences.manage');
    page_start($db,$user,'sequences','Numbering','Define how each branch issues unique document identifiers.');
    $ids=Security::branchIds($db);
    $stmt=$db->prepare('SELECT n.*,b.name branch_name FROM number_sequences n JOIN branches b ON b.id=n.branch_id WHERE n.branch_id IN (' . implode(',',array_fill(0,count($ids),'?')) . ') ORDER BY b.name,n.document_type');
    $stmt->execute($ids);
    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">DOCUMENT IDS</span><h3>Number sequences</h3></div></div><div class="table-wrap"><table><thead><tr><th>Branch / document</th><th>Prefix</th><th>Digits</th><th>Reset</th><th>Next</th><th>Save</th></tr></thead><tbody>';
    foreach($stmt->fetchAll() as $r) {
        $formId = 'seq-' . (int)$r['id'];
        echo '<tr><td><form id="' . $formId . '" method="post" action="/index.php?page=sequences"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="id" value="' . e($r['id']) . '"></form><strong>' . e($r['branch_name']) . '</strong><small class="cell-sub">' . e(ucfirst($r['document_type'])) . '</small></td><td><input form="' . $formId . '" class="table-input" name="prefix" value="' . e($r['prefix']) . '" required maxlength="25"></td><td><input form="' . $formId . '" class="table-input small-input" type="number" name="padding" min="1" max="12" value="' . e($r['padding']) . '"></td><td><select form="' . $formId . '" class="table-input" name="reset_period">';
        foreach(['never','year','month'] as $p) echo '<option value="' . $p . '" ' . ($r['reset_period']===$p?'selected':'') . '>' . ucfirst($p) . '</option>';
        echo '</select></td><td>' . e($r['period_key']) . ' / ' . e($r['next_value']) . '</td><td><button form="' . $formId . '" class="text-link">Save</button></td></tr>';
    }
    echo '</tbody></table></div></section>'; page_end();
}
function render_policies(PDO $db, array $user): void
{
    Security::requirePermission($db,'settings.manage');
    page_start($db,$user,'policies','Approval rules','Set thresholds and ownership for sensitive actions.');
    $policies=$db->query('SELECT ap.*,b.name branch_name FROM approval_policies ap LEFT JOIN branches b ON b.id=ap.branch_id ORDER BY ap.action_type,ap.min_amount')->fetchAll();
    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">POLICY REGISTER</span><h3>Approval thresholds</h3></div></div><div class="table-wrap"><table><thead><tr><th>Action</th><th>Branch</th><th>Amount BDT</th><th>Status</th></tr></thead><tbody>';
    foreach($policies as $r) echo '<tr><td><strong>' . e(ucwords(str_replace('_',' ',$r['action_type']))) . '</strong></td><td>' . e($r['branch_name']??'All branches') . '</td><td>' . e($r['min_amount']) . ' – ' . e($r['max_amount']??'∞') . '</td><td><span class="status ' . ($r['active']?'on':'off') . '">' . ($r['active']?'Active':'Inactive') . '</span></td></tr>';
    echo '</tbody></table></div></section><section class="card"><div class="card-head"><div><span class="eyebrow">NEW THRESHOLD</span><h3>Add policy</h3></div></div><form method="post" action="/index.php?page=policies" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="approver_permission" value="approvals.decide"><label class="field">Action<select name="action_type">';
    foreach(['discount','refund','result_correction','credit_note','purchase','journal_posting'] as $a) echo '<option value="' . $a . '">' . e(ucwords(str_replace('_',' ',$a))) . '</option>';
    echo '</select></label><label class="field">Branch<select name="branch_id"><option value="0">All branches</option>';
    foreach(Masters::choices($db,'branches') as $b) echo '<option value="' . e($b['id']) . '">' . e($b['name']) . '</option>';
    echo '</select></label><label class="field">Minimum amount<input type="number" name="min_amount" step="0.01" min="0" value="0" required></label><label class="field">Maximum amount<input type="number" name="max_amount" step="0.01" min="0" placeholder="No limit"></label><div class="form-actions span-2"><button class="button button-primary">Add rule</button></div></form></section></div>'; page_end();
}

function render_patients(PDO $db, array $user): void
{
    Security::requirePermission($db, 'patients.view');
    $branchId  = Security::branchIds($db)[0];
    $q         = mb_substr(trim((string) ($_GET['q'] ?? '')), 0, 80);
    $viewId    = (int) ($_GET['view'] ?? 0);
    
    // Default category based on navigation context
    $defaultCat = 'doctor_prescribed';
    $filterCat = isset($_GET['cat']) ? (string)$_GET['cat'] : $defaultCat;
    if ($filterCat === 'all') $filterCat = '';

    page_start($db, $user, 'patients', 'Patient Master & Health Records', 'Corporate Medical Directory, Distinct Patient Categories, Longitudinal Clinical History & Financial Ledgers.');

    // Category Identification & Style Master Definition
    $catMeta = [
        'doctor_prescribed' => [
            'label'       => 'Doctor Prescribed Patient',
            'short_label' => 'Prescribed Patient',
            'desc'        => 'Consulted Doctor at Chamber, Authorized for Prescribed Medicine & Diagnostic Investigations',
            'prefix'      => 'DOC-',
            'unique_pfx'  => 'DOC-PAT-',
            'color'       => '#4338ca',
            'bg'          => '#eef2ff',
            'border'      => '#c7d2fe',
            'icon'        => 'stethoscope',
            'module'      => 'Patient Management',
        ],
        'clinical_patient' => [
            'label'       => 'Clinical Diagnostic Patient',
            'short_label' => 'Clinical Test Patient',
            'desc'        => 'Registered Specifically for Clinical Diagnostic Tests (Pathology, LIS, Radiology & Imaging)',
            'prefix'      => 'CLN-',
            'unique_pfx'  => 'CLN-PAT-',
            'color'       => '#0284c7',
            'bg'          => '#f0f9ff',
            'border'      => '#bae6fd',
            'icon'        => 'microscope',
            'module'      => 'Hospital & Clinical Departments',
        ],
        'local_customer' => [
            'label'       => 'Local Walk-in Customer',
            'short_label' => 'Local Walk-in',
            'desc'        => 'Local Physical Counter Patron for Direct OTC Medicine Purchases & Walk-in Diagnostics',
            'prefix'      => 'LOC-',
            'unique_pfx'  => 'LOC-CUST-',
            'color'       => '#15803d',
            'bg'          => '#f0fdf4',
            'border'      => '#bbf7d0',
            'icon'        => 'store',
            'module'      => 'Local Walk-in Customers',
        ],
        'online_customer' => [
            'label'       => 'Online Web Customer',
            'short_label' => 'Online Portal',
            'desc'        => 'Registered Patient via Online Website Portal & Remote Digital Booking Services',
            'prefix'      => 'ONL-',
            'unique_pfx'  => 'ONL-CUST-',
            'color'       => '#7e22ce',
            'bg'          => '#faf5ff',
            'border'      => '#e9d5ff',
            'icon'        => 'globe',
            'module'      => 'Patient Web Portal',
        ],
    ];

    // Helper for category badge
    $getBadge = function(string $cat) use ($catMeta): string {
        $meta = $catMeta[$cat] ?? $catMeta['doctor_prescribed'];
        return '<span style="font-size:11px;font-weight:800;background:' . $meta['bg'] . ';color:' . $meta['color'] . ';border:1px solid ' . $meta['border'] . ';padding:3px 10px;border-radius:20px;display:inline-flex;align-items:center;gap:5px;"><i class="fa-solid fa-' . $meta['icon'] . '" style="font-size:10px;"></i> ' . e($meta['label']) . '</span>';
    };

    // Helper for Unique ID
    $getUniqueId = function(array $p) use ($catMeta): string {
        $cat = $p['category'] ?? 'doctor_prescribed';
        $meta = $catMeta[$cat] ?? $catMeta['doctor_prescribed'];
        return $meta['unique_pfx'] . str_pad((string)$p['id'], 5, '0', STR_PAD_LEFT);
    };

    // ──────────────────────────────────────────────────────────────────────────
    // 1. PATIENT DETAIL VIEW
    // ──────────────────────────────────────────────────────────────────────────
    if ($viewId) {
        $history = \Diagnostic\Patients::getHistory($db, $viewId);
        $p       = $history['patient'];
        $catKey  = $p['category'] ?? 'doctor_prescribed';
        $pMeta   = $catMeta[$catKey] ?? $catMeta['doctor_prescribed'];
        $uniqueId = $getUniqueId($p);

        // Fetch Pharmacy counter invoices
        $phStmt = $db->prepare('SELECT * FROM pharmacy_invoices WHERE patient_id=? OR (patient_mobile IS NOT NULL AND patient_mobile = ?) ORDER BY created_at DESC LIMIT 30');
        $phStmt->execute([$viewId, $p['mobile']]);
        $pharmacyInvoices = $phStmt->fetchAll(PDO::FETCH_ASSOC);

        // Fetch Diagnostic invoices (FIXED: Uses actual column names total_amount, payable_amount, due_amount)
        $diagPayStmt = $db->prepare(
            'SELECT inv.id, inv.invoice_no, inv.total_amount, inv.discount_amount,
                    inv.payable_amount, inv.paid_amount, inv.due_amount, inv.status, inv.created_at,
                    pm.name AS payment_method_name
             FROM invoices inv
             LEFT JOIN payments pay ON pay.invoice_id = inv.id
             LEFT JOIN payment_methods pm ON pm.id = pay.payment_method_id
             WHERE inv.patient_id = ?
             ORDER BY inv.created_at DESC LIMIT 30'
        );
        $diagPayStmt->execute([$viewId]);
        $diagPayments = $diagPayStmt->fetchAll(PDO::FETCH_ASSOC);

        // Top Main Header
        echo '<section class="card" style="background:#ffffff;border:1.5px solid #e2e8f0;border-radius:16px;box-shadow:0 4px 20px rgba(15,23,42,0.05);overflow:hidden;margin-bottom:20px;">';
        echo '<div class="card-head" style="background:linear-gradient(135deg,#f0fdfa 0%,#f8fafc 100%);border-bottom:1.5px solid #e2e8f0;padding:20px 24px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;">';
        echo '<div>';
        echo '  <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">';
        echo '    <span class="eyebrow" style="color:#0c928c;font-size:10.5px;font-weight:900;letter-spacing:0.12em;">' . strtoupper(e($pMeta['module'])) . '</span>';
        echo '    ' . $getBadge($catKey);
        echo '  </div>';
        echo '  <h3 style="margin:6px 0 2px;font-size:20px;color:#0f172a;display:flex;align-items:center;gap:10px;">' . e($p['name']);
        echo '  </h3>';
        echo '  <div style="font-size:13px;color:#64748b;display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin-top:4px;">';
        echo '    <span>Unique ID: <strong style="color:#0f172a;background:#f1f5f9;padding:2px 8px;border-radius:6px;border:1px solid #e2e8f0;">' . e($uniqueId) . '</strong></span>';
        echo '    <span>MRN: <strong style="color:#0f172a;">' . e($p['mrn']) . '</strong></span>';
        echo '    <span>Primary Contact: <strong style="color:#0f172a;">' . e($p['mobile']) . '</strong></span>';
        echo '  </div>';
        echo '</div>';

        // Action Buttons Header
        echo '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">';
        if (Security::can($db, 'patients.edit')) {
