            echo '<label class="field span-2">Address<textarea name="address" rows="2">'.e($p['address']??'').'</textarea></label>';

            echo '<div class="form-actions span-2" style="display:flex;gap:12px;margin-top:10px;">';
            echo '<button class="button button-primary" type="submit" style="padding:10px 22px;font-weight:800;"><i class="fa-solid fa-floppy-disk"></i> Save & Apply Changes</button>';
            echo '<button type="button" onclick="document.getElementById(\'editPatientModal\').style.display=\'none\'" class="button button-outline" style="padding:10px 18px;">Cancel</button>';
            echo '</div></form></div></div>';

            echo '<script>
            function updatePrefixHint(cat) {
                var pfx = {
                    "doctor_prescribed": "DOC-",
                    "clinical_patient": "CLN-",
                    "local_customer": "LOC-",
                    "online_customer": "ONL-"
                };
                var mrnInput = document.getElementById("editModalMrnInput");
                if (mrnInput && pfx[cat]) {
                    var cur = mrnInput.value;
                    // if currently has a standard prefix, replace it
                    if (cur.match(/^(DOC|CLN|LOC|ONL|MRN|PAT)-/)) {
                        mrnInput.value = cur.replace(/^(DOC|CLN|LOC|ONL|MRN|PAT)-/, pfx[cat]);
                    }
                }
            }
            </script>';
        }

        page_end();
        return;
    }

    // ──────────────────────────────────────────────────────────────────────────
    // 2. PATIENT DIRECTORY & LIST VIEW (Category-Specific)
    // ──────────────────────────────────────────────────────────────────────────

    // Counts per category
    $cntStmt = $db->prepare('SELECT category, COUNT(*) AS cnt FROM patients WHERE branch_id=? AND active=1 GROUP BY category');
    $cntStmt->execute([$branchId]);
    $catCounts = [
        'doctor_prescribed' => 0,
        'clinical_patient'  => 0,
        'local_customer'    => 0,
        'online_customer'   => 0
    ];
    foreach ($cntStmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
        $catCounts[$row['category']] = (int)$row['cnt'];
    }
    $totalAll = array_sum($catCounts);

    // Active category banner & meta
    $activeMeta = $catMeta[$filterCat] ?? null;

    // Header KPI Category Switcher
    echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-bottom:22px;">';
    
    // Doctor Prescribed card
    $dpActive = ($filterCat === 'doctor_prescribed');
    echo '<a href="/index.php?page=patients&cat=doctor_prescribed" style="background:'.($dpActive?'#4338ca':'#f8fafc').';border:'.($dpActive?'2.5px solid #4338ca':'1.5px solid #e2e8f0').';border-radius:14px;padding:16px 18px;display:flex;align-items:center;gap:14px;text-decoration:none;box-shadow:'.($dpActive?'0 6px 20px rgba(67,56,202,0.25)':'0 2px 6px rgba(0,0,0,0.03)').';transition:all 0.2s;">';
    echo '  <div style="width:46px;height:46px;border-radius:12px;background:'.($dpActive?'#ffffff':'#eef2ff').';color:'.($dpActive?'#4338ca':'#4338ca').';display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0;"><i class="fa-solid fa-stethoscope"></i></div>';
    echo '  <div><div style="font-size:26px;font-weight:900;color:'.($dpActive?'#ffffff':'#0f172a').';line-height:1.1;">'.$catCounts['doctor_prescribed'].'</div><div style="font-size:12px;font-weight:800;color:'.($dpActive?'rgba(255,255,255,0.9)':'#4338ca').';margin-top:2px;">Doctor Prescribed</div><small style="color:'.($dpActive?'rgba(255,255,255,0.7)':'#64748b').';font-size:11px;">Chamber & Rx Patients</small></div></a>';

    // Clinical Patient card
    $cpActive = ($filterCat === 'clinical_patient');
    echo '<a href="/index.php?page=patients&cat=clinical_patient" style="background:'.($cpActive?'#0284c7':'#f8fafc').';border:'.($cpActive?'2.5px solid #0284c7':'1.5px solid #e2e8f0').';border-radius:14px;padding:16px 18px;display:flex;align-items:center;gap:14px;text-decoration:none;box-shadow:'.($cpActive?'0 6px 20px rgba(2,132,199,0.25)':'0 2px 6px rgba(0,0,0,0.03)').';transition:all 0.2s;">';
    echo '  <div style="width:46px;height:46px;border-radius:12px;background:'.($cpActive?'#ffffff':'#f0f9ff').';color:'.($cpActive?'#0284c7':'#0284c7').';display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0;"><i class="fa-solid fa-microscope"></i></div>';
    echo '  <div><div style="font-size:26px;font-weight:900;color:'.($cpActive?'#ffffff':'#0f172a').';line-height:1.1;">'.$catCounts['clinical_patient'].'</div><div style="font-size:12px;font-weight:800;color:'.($cpActive?'rgba(255,255,255,0.9)':'#0284c7').';margin-top:2px;">Clinical Diagnostic</div><small style="color:'.($cpActive?'rgba(255,255,255,0.7)':'#64748b').';font-size:11px;">Lab & Radiology Tests</small></div></a>';

    // Local Walk-in card
    $lcActive = ($filterCat === 'local_customer');
    echo '<a href="/index.php?page=patients&cat=local_customer" style="background:'.($lcActive?'#15803d':'#f8fafc').';border:'.($lcActive?'2.5px solid #15803d':'1.5px solid #e2e8f0').';border-radius:14px;padding:16px 18px;display:flex;align-items:center;gap:14px;text-decoration:none;box-shadow:'.($lcActive?'0 6px 20px rgba(21,128,61,0.25)':'0 2px 6px rgba(0,0,0,0.03)').';transition:all 0.2s;">';
    echo '  <div style="width:46px;height:46px;border-radius:12px;background:'.($lcActive?'#ffffff':'#f0fdf4').';color:'.($lcActive?'#15803d':'#15803d').';display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0;"><i class="fa-solid fa-store"></i></div>';
    echo '  <div><div style="font-size:26px;font-weight:900;color:'.($lcActive?'#ffffff':'#0f172a').';line-height:1.1;">'.$catCounts['local_customer'].'</div><div style="font-size:12px;font-weight:800;color:'.($lcActive?'rgba(255,255,255,0.9)':'#15803d').';margin-top:2px;">Local Walk-in</div><small style="color:'.($lcActive?'rgba(255,255,255,0.7)':'#64748b').';font-size:11px;">Counter OTC & Tests</small></div></a>';

    // All Profiles card
    $allActive = ($filterCat === '');
    echo '<a href="/index.php?page=patients&cat=all" style="background:'.($allActive?'#334155':'#f8fafc').';border:'.($allActive?'2.5px solid #334155':'1.5px solid #e2e8f0').';border-radius:14px;padding:16px 18px;display:flex;align-items:center;gap:14px;text-decoration:none;box-shadow:'.($allActive?'0 6px 20px rgba(51,65,85,0.25)':'0 2px 6px rgba(0,0,0,0.03)').';transition:all 0.2s;">';
    echo '  <div style="width:46px;height:46px;border-radius:12px;background:'.($allActive?'#ffffff':'#f1f5f9').';color:'.($allActive?'#334155':'#475569').';display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0;"><i class="fa-solid fa-users"></i></div>';
    echo '  <div><div style="font-size:26px;font-weight:900;color:'.($allActive?'#ffffff':'#0f172a').';line-height:1.1;">'.$totalAll.'</div><div style="font-size:12px;font-weight:800;color:'.($allActive?'rgba(255,255,255,0.9)':'#334155').';margin-top:2px;">All Registered</div><small style="color:'.($allActive?'rgba(255,255,255,0.7)':'#64748b').';font-size:11px;">Central Master Index</small></div></a>';

    echo '</div>';

    // Query patients with search & category filter
    if ($filterCat !== '') {
        if ($q !== '') {
            $like = '%' . $q . '%';
            $stmt = $db->prepare('SELECT p.*, b.name AS branch_name FROM patients p JOIN branches b ON b.id=p.branch_id WHERE p.branch_id=? AND p.active=1 AND p.category=? AND (p.mrn LIKE ? OR p.name LIKE ? OR p.mobile LIKE ? OR p.blood_group LIKE ?) ORDER BY p.id DESC LIMIT 100');
            $stmt->execute([$branchId, $filterCat, $like, $like, $like, $like]);
        } else {
            $stmt = $db->prepare('SELECT p.*, b.name AS branch_name FROM patients p JOIN branches b ON b.id=p.branch_id WHERE p.branch_id=? AND p.active=1 AND p.category=? ORDER BY p.id DESC LIMIT 100');
            $stmt->execute([$branchId, $filterCat]);
        }
        $patients = $stmt->fetchAll(PDO::FETCH_ASSOC);
    } else {
        if ($q !== '') {
            $patients = \Diagnostic\Patients::search($db, $q, $branchId, 100);
        } else {
            $stmt = $db->prepare('SELECT p.*, b.name AS branch_name FROM patients p JOIN branches b ON b.id=p.branch_id WHERE p.branch_id=? AND p.active=1 ORDER BY p.id DESC LIMIT 100');
            $stmt->execute([$branchId]);
            $patients = $stmt->fetchAll(PDO::FETCH_ASSOC);
        }
    }

    $pageTitle = $activeMeta ? $activeMeta['label'] : 'All Registered Patients';
    $pageDesc  = $activeMeta ? $activeMeta['desc'] : 'Comprehensive central index of all patients, clients and counter patrons across hospital wings.';

    echo '<section class="card" style="background:#ffffff;border:1.5px solid #e2e8f0;border-radius:16px;box-shadow:0 4px 18px rgba(15,23,42,0.04);overflow:hidden;">';
    echo '<div class="card-head" style="background:linear-gradient(135deg,#f8fafc 0%,#ffffff 100%);border-bottom:1.5px solid #e2e8f0;padding:18px 22px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">';
    echo '<div>';
    echo '  <span class="eyebrow" style="color:#0c928c;font-weight:800;letter-spacing:0.08em;">' . ($activeMeta ? strtoupper(e($activeMeta['module'])) : 'CENTRAL PATIENT REGISTRY') . '</span>';
    echo '  <h3 style="margin:3px 0 0;font-size:18px;color:#0f172a;">' . e($pageTitle) . ' <span style="font-size:13px;font-weight:700;color:#64748b;">(' . count($patients) . ' records)</span></h3>';
    echo '  <p style="margin:2px 0 0;font-size:12px;color:#64748b;">' . e($pageDesc) . '</p>';
    echo '</div>';
    echo '<div style="display:flex;align-items:center;gap:8px;">';
    echo '  <a href="/index.php?page=patients&export=csv' . ($filterCat ? '&cat=' . e($filterCat) : '') . '" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '</div></div>';

    // Search bar
    echo '<div style="padding:14px 22px;border-bottom:1px solid #f1f5f9;background:#fcfdfd;">';
    echo '<form method="get" action="/index.php" style="display:flex;gap:10px;">';
    echo '<input type="hidden" name="page" value="patients">';
    if ($filterCat) echo '<input type="hidden" name="cat" value="' . e($filterCat) . '">';
    echo '<input id="patientSearchInput" name="q" value="' . e($q) . '" placeholder="Instant search by Name, Mobile, Unique ID, MRN or Blood Group..." style="flex:1;border:1.5px solid #cbd5e1;border-radius:10px;padding:10px 16px;font-size:13.5px;" autocomplete="off">';
    echo '<button class="button button-primary" style="padding:10px 20px;font-weight:800;"><i class="fa-solid fa-magnifying-glass"></i> Search</button>';
    if ($q) echo '<a href="/index.php?page=patients' . ($filterCat ? '&cat=' . e($filterCat) : '') . '" class="button button-outline" style="padding:10px 16px;">✕ Clear</a>';
    echo '</form></div>';

    // Patients Table
    echo '<div class="table-wrap"><table id="patientsTable"><thead><tr>';
    echo '<th style="width:40px;">#</th>';
    echo '<th>Unique ID</th>';
    echo '<th>MRN / UHID</th>';
    echo '<th>Name & Mobile</th>';
    echo '<th>Category / Type</th>';
    echo '<th>Blood</th>';
    echo '<th>Registered</th>';
    echo '<th style="min-width:270px;text-align:center;">Direct Corporate Actions & Desks</th>';
    echo '</tr></thead><tbody id="patientsTableBody">';

    if (!$patients) {
        echo '<tr><td colspan="8"><div class="empty-state" style="padding:40px;text-align:center;color:#64748b;">No patients found in this classification. Use the form below to register a new record.</div></td></tr>';
    } else {
        $sl = 1;
        foreach ($patients as $pt) {
            $cat = $pt['category'] ?? 'doctor_prescribed';
            $meta = $catMeta[$cat] ?? $catMeta['doctor_prescribed'];
            $uid = $getUniqueId($pt);

            echo '<tr class="patient-row" data-search="' . strtolower(e($uid . ' ' . $pt['mrn'] . ' ' . $pt['name'] . ' ' . $pt['mobile'] . ' ' . ($pt['blood_group'] ?? '') . ' ' . $meta['label'])) . '">';
            echo '<td><small style="color:#94a3b8;font-weight:700;">' . $sl++ . '</small></td>';
            echo '<td><span class="code-chip" style="font-size:11px;font-weight:800;background:' . $meta['bg'] . ';color:' . $meta['color'] . ';border:1.5px solid ' . $meta['border'] . ';letter-spacing:0.04em;">' . e($uid) . '</span></td>';
            echo '<td><span class="code-chip" style="font-size:11px;font-weight:700;">' . e($pt['mrn']) . '</span></td>';
            echo '<td><strong style="color:#0f172a;font-size:13.5px;">' . e($pt['name']) . '</strong><br><small style="color:#475569;font-weight:600;"><i class="fa-solid fa-phone" style="font-size:9px;color:#0d9488;"></i> ' . e($pt['mobile']) . '</small></td>';
            echo '<td>' . $getBadge($cat) . '</td>';
            echo '<td><span class="pill" style="font-weight:800;font-size:10.5px;">' . e($pt['blood_group'] ?? 'N/A') . '</span></td>';
            echo '<td><small style="color:#64748b;font-weight:600;">' . e(date('d M Y', strtotime($pt['created_at']))) . '</small></td>';

            // Distinct Corporate Actions
            echo '<td style="text-align:center;"><div class="table-actions-cell" style="justify-content:center;gap:5px;">';

            if ($cat === 'doctor_prescribed') {
                // Direct Medicine POS & Direct Diagnostic Booking
                echo '<a class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:800;color:#0d9488;border-color:#99f6e4;background:#f0fdfa;" href="/index.php?page=pharmacy_pos&patient_id=' . (int)$pt['id'] . '&patient_name=' . urlencode($pt['name']) . '&patient_uhid=' . urlencode($pt['mrn']) . '" title="Instant Counter Sales & POS for Prescribed Medicines"><i class="fa-solid fa-cart-shopping"></i> POS Rx</a>';
                echo '<a class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:800;color:#2563eb;border-color:#bfdbfe;background:#eff6ff;" href="/index.php?page=orders&patient_id=' . (int)$pt['id'] . '" title="Direct Diagnostic Booking for Prescribed Tests"><i class="fa-solid fa-file-waveform"></i> Book Test</a>';
            } elseif ($cat === 'clinical_patient') {
                echo '<a class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:800;color:#0284c7;border-color:#bae6fd;background:#f0f9ff;" href="/index.php?page=orders&patient_id=' . (int)$pt['id'] . '" title="Direct Diagnostic Booking (Pathology / Radiology)"><i class="fa-solid fa-vial-circle-check"></i> Book Test</a>';
                echo '<a class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:800;color:#0369a1;border-color:#bae6fd;background:#f0f9ff;" href="/index.php?page=patient_documents&patient_id=' . (int)$pt['id'] . '" title="Clinical Documents & EHR"><i class="fa-solid fa-file-medical"></i> EHR</a>';
            } else {
                echo '<a class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:800;color:#15803d;border-color:#bbf7d0;background:#f0fdf4;" href="/index.php?page=pharmacy_pos&patient_id=' . (int)$pt['id'] . '&patient_name=' . urlencode($pt['name']) . '&patient_uhid=' . urlencode($pt['mrn']) . '" title="Instant Counter Sales & POS (Cash Billing)"><i class="fa-solid fa-cash-register"></i> POS</a>';
                echo '<a class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:800;color:#0284c7;border-color:#bae6fd;background:#f0f9ff;" href="/index.php?page=orders&patient_id=' . (int)$pt['id'] . '" title="Direct Diagnostic Booking"><i class="fa-solid fa-clipboard-check"></i> Test</a>';
            }

            // General Profile View, PDF & Print
            echo '<a class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:700;color:#334155;border-color:#cbd5e1;background:#f8fafc;" href="/index.php?page=patients&view=' . (int)$pt['id'] . ($filterCat ? '&cat=' . e($filterCat) : '') . '"><i class="fa-solid fa-eye"></i> Profile</a>';
            echo '<a class="btn-action-pdf" href="/index.php?page=download_pdf&type=patient_summary&id=' . (int)$pt['id'] . '" title="Download PDF">PDF</a>';
            echo '<a class="btn-action-print" target="_blank" href="/index.php?page=print_voucher&type=patient_summary&id=' . (int)$pt['id'] . '" title="Print Dossier">Print</a>';
            echo '</div></td>';
            echo '</tr>';
        }
    }

    echo '</tbody></table></div>';

    // Instant client-side live search
    echo '<script>
    (function(){
        var i = document.getElementById("patientSearchInput");
        var tb = document.getElementById("patientsTableBody");
        if (!i || !tb) return;
        var t = null;
        i.addEventListener("input", function(){
            var v = i.value.trim().toLowerCase();
            var rs = tb.querySelectorAll("tr.patient-row");
            var vis = 0;
            rs.forEach(function(r){
                var d = r.getAttribute("data-search") || "";
                if (!v || d.indexOf(v) !== -1) { r.style.display = ""; vis++; }
                else { r.style.display = "none"; }
            });
            clearTimeout(t);
            if (v.length >= 2 && vis === 0) {
                t = setTimeout(function(){ i.form.submit(); }, 600);
            }
        });
    })();
    </script>';
    echo '</section>';

    // ──────────────────────────────────────────────────────────────────────────
    // 3. REGISTRATION FORM WITH CATEGORY-SPECIFIC UNIQUE ID GENERATION
    // ──────────────────────────────────────────────────────────────────────────
    if (Security::can($db, 'patients.edit')) {
        echo '<section class="card" style="margin-top:24px;background:#ffffff;border:1.5px solid #e2e8f0;border-radius:16px;box-shadow:0 4px 18px rgba(15,23,42,0.04);">';
        echo '<div class="card-head" style="background:#f8fafc;padding:18px 22px;border-bottom:1px solid #e2e8f0;">';
        echo '<div><span class="eyebrow" style="color:#0c928c;font-weight:800;">REGISTRATION DESK</span><h3 style="margin:3px 0 0;font-size:17px;color:#0f172a;">Register New Patient with Automatic Category Identification</h3></div>';
        echo '</div>';

        echo '<form method="post" action="/index.php?page=patients" class="field-grid" style="padding:22px;">';
        echo '<input type="hidden" name="_csrf" value="'.e(csrf_token()).'">';
        echo '<input type="hidden" name="branch_id" value="'.(int)$branchId.'">';

        echo '<label class="field span-2"><strong>Patient Classification & Workflow Category *</strong>';
        echo '<select name="category" id="regCategorySelect" onchange="updateRegPrefixPreview(this.value)" style="border:2px solid #0d9488;font-weight:750;">';
        foreach ($catMeta as $ck => $cm) {
            $sel = ($filterCat === $ck) ? ' selected' : '';
            echo '<option value="' . $ck . '"' . $sel . '>' . e($cm['label']) . ' — (' . e($cm['desc']) . ')</option>';
        }
        echo '</select>';
        echo '<small style="color:#0f766e;font-weight:700;margin-top:4px;display:block;" id="regPrefixHint"><i class="fa-solid fa-circle-info"></i> Automatically assigns a distinct Unique ID & MRN based on category.</small>';
        echo '</label>';

        echo '<label class="field">Full Name *<input name="name" required placeholder="Patient full name"></label>';
        echo '<label class="field">Mobile Number *<input name="mobile" required placeholder="017xxxxxxxx"></label>';
        echo '<label class="field">Gender<select name="gender"><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select></label>';
        echo '<label class="field">Date of Birth<input type="date" name="dob"></label>';
        echo '<label class="field">Blood Group<select name="blood_group"><option value="unknown">Unknown</option><option value="A+">A+</option><option value="A-">A-</option><option value="B+">B+</option><option value="B-">B-</option><option value="AB+">AB+</option><option value="AB-">AB-</option><option value="O+">O+</option><option value="O-">O-</option></select></label>';
        echo '<label class="field">Email <small>(Optional)</small><input type="email" name="email" placeholder="patient@example.com"></label>';
        echo '<label class="field">NID / Passport <small>(Optional)</small><input name="nid_passport" placeholder="Optional"></label>';
        echo '<label class="field">Occupation <small>(Optional)</small><input name="occupation" placeholder="Occupation"></label>';
        echo '<label class="field span-2">Address<textarea name="address" rows="2" placeholder="Full residential address"></textarea></label>';

        echo '<div class="form-actions span-2" style="margin-top:8px;">';
        echo '<button class="button button-primary" style="padding:10px 24px;font-weight:800;"><i class="fa-solid fa-user-plus"></i> Register Patient & Generate Unique Identification</button>';
        echo '</div>';
        echo '</form></section>';

        echo '<script>
        function updateRegPrefixPreview(cat) {
            var hints = {
                "doctor_prescribed": "<i class=\"fa-solid fa-stethoscope\"></i> Category: Doctor Prescribed — Assigns DOC- prefix. Patient will appear in Patient Management and be eligible for Prescribed Rx POS and Prescribed Test Booking.",
                "clinical_patient": "<i class=\"fa-solid fa-microscope\"></i> Category: Clinical Diagnostic — Assigns CLN- prefix. Patient will appear in Hospital & Clinical Departments for Lab and Radiology orders.",
                "local_customer": "<i class=\"fa-solid fa-store\"></i> Category: Local Walk-in — Assigns LOC- prefix. Patient will appear in Local Walk-in Customers module for instant retail counter POS sales.",
                "online_customer": "<i class=\"fa-solid fa-globe\"></i> Category: Online Customer — Assigns ONL- prefix. Patient is linked to Web Portal."
            };
            var hintEl = document.getElementById("regPrefixHint");
            if (hintEl && hints[cat]) hintEl.innerHTML = hints[cat];
        }
        </script>';
    }

    page_end();
}

function render_appointments(PDO $db, array $user): void
{
    Security::requirePermission($db, 'appointments.manage');
    $branchId = Security::branchIds($db)[0];
    $date = (string) ($_GET['date'] ?? date('Y-m-d'));

    page_start($db, $user, 'appointments', 'Appointments & Chamber Scheduling', 'Manage consultant availability schedules and patient appointments.');

    $appts = \Diagnostic\Appointments::list($db, $branchId, $date);
    $schedules = \Diagnostic\Appointments::getSchedules($db, $branchId);
    $doctors = Masters::scoped($db, 'doctors', 100);
    $rooms = Masters::scoped($db, 'rooms', 100);

    // Success Appointment Banner
    $successApptId = (int)($_GET['success_appt_id'] ?? 0);
    if ($successApptId > 0) {
        $succAppt = \Diagnostic\Appointments::getAppointment($db, $successApptId);
        if ($succAppt) {
            echo '<div style="background:linear-gradient(135deg, #ecfdf5 0%, #f0fdf4 100%);border:2px solid #34d399;border-radius:12px;padding:20px;box-shadow:0 6px 20px rgba(16,185,129,0.12);margin-bottom:20px;">';
            echo '  <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;">';
            echo '    <div style="display:flex;align-items:center;gap:14px;">';
            echo '      <div style="width:48px;height:48px;border-radius:50%;background:#10b981;color:#ffffff;display:flex;align-items:center;justify-content:center;font-size:24px;box-shadow:0 3px 8px rgba(16,185,129,0.3);"><i class="fa-solid fa-ticket"></i></div>';
            echo '      <div>';
            echo '        <h4 style="margin:0;font-size:17px;color:#065f46;">Doctor Chamber Appointment Booked &amp; Token Issued!</h4>';
