    echo '<section class="card" style="background:#f8fafc;border:1.5px solid #cbd5e1;border-radius:14px;box-shadow:0 4px 18px rgba(15,23,42,0.04);overflow:hidden;">';
    echo '<div class="card-head" style="background:linear-gradient(135deg, #f0fdfa 0%, #f8fafc 100%);border-bottom:1px solid #e2e8f0;padding:16px 20px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;"><div><span class="eyebrow" style="color:#0c928c;font-weight:800;letter-spacing:0.08em;">SCHEDULED APPOINTMENTS</span><h3 style="margin:2px 0 0;font-size:16px;color:#0f172a;">Bookings for ' . e($date) . '</h3></div><div style="display:flex;align-items:center;gap:8px;"><a href="/index.php?page=appointments&date=' . e($date) . '&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Export PDF</a><a href="/index.php?page=appointments&date=' . e($date) . '&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a><form method="get" action="/index.php" style="margin:0;"><input type="hidden" name="page" value="appointments"><input type="date" name="date" value="' . e($date) . '" onchange="this.form.submit()" style="background:#ffffff;border:1.5px solid #0c928c;border-radius:8px;padding:6px 12px;font-size:13px;font-weight:750;color:#0f172a;box-shadow:0 2px 6px rgba(12,146,140,0.15);cursor:pointer;outline:none;"></form></div></div>';
    echo '<div class="table-wrap" style="background:#ffffff;margin:16px;border-radius:10px;border:1px solid #e2e8f0;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,0.02);">';
    echo '<table><thead><tr style="background:#f8fafc;"><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Token / Appt #</th><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Patient</th><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Doctor</th><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Fee &amp; Paid</th><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Slot</th><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Status</th><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Actions</th></tr></thead><tbody>';
    if (!$appts) echo '<tr><td colspan="7"><div class="empty-state" style="padding:48px 20px;text-align:center;color:#64748b;font-weight:600;font-size:13.5px;">No appointments booked for this date.</div></td></tr>';
