        echo '<td style="padding:12px 14px;"><strong>' . e($a['patient_name']) . '</strong><br><small class="muted">' . e($a['patient_mobile']) . '</small></td>';
        echo '<td style="padding:12px 14px;"><strong>' . e($a['doctor_name']) . '</strong><br><small style="color:#64748b;">' . e($a['specialty'] ?? 'Chamber') . '</small></td>';
        echo '<td style="padding:12px 14px;"><strong style="color:#092c36;">৳ ' . number_format((float)($a['payable_amount'] ?? 1000), 2) . '</strong><br><span style="font-size:10px;font-weight:700;color:#059669;background:#ecfdf5;padding:1px 6px;border-radius:4px;border:1px solid #a7f3d0;">Paid (' . e($a['payment_method'] ?? 'CASH') . ')</span></td>';
        echo '<td style="padding:12px 14px;">' . e($a['time_slot']) . '</td>';
        echo '<td style="padding:12px 14px;"><span class="status ' . ($a['status']==='confirmed'||$a['status']==='arrived'?'on':'off') . '">' . e(ucfirst($a['status'])) . '</span></td>';
        echo '<td style="padding:12px 14px;"><div class="table-actions-cell"><a class="btn-action-pdf" href="/index.php?page=download_pdf&type=appointment&id=' . e((string)$a['id']) . '" title="Download Chamber Slip PDF"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg> PDF</a><a class="btn-action-print" target="_blank" href="/index.php?page=print_voucher&type=appointment&id=' . e((string)$a['id']) . '" title="Print Official OPD Slip"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg> Print</a></div></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section>';

    // Fetch Referrers for referral dropdown
    $referrersList = $db->query('SELECT id, name, code, type FROM referrers WHERE active=1 ORDER BY name ASC LIMIT 50')->fetchAll(PDO::FETCH_ASSOC);

    echo '<section class="card" style="background:#ffffff;border:1.5px solid #cbd5e1;border-radius:14px;box-shadow:0 4px 18px rgba(15,23,42,0.05);overflow:hidden;">';
    echo '<div class="card-head" style="background:linear-gradient(135deg, #f0fdfa 0%, #f8fafc 100%);border-bottom:1px solid #e2e8f0;padding:16px 20px;"><div><span class="eyebrow" style="color:#0c928c;font-weight:800;letter-spacing:0.08em;">COUNTER &amp; DOCTOR MODULE DESK</span><h3 style="margin:2px 0 0;font-size:16px;color:#0f172a;">Instant Doctor Booking, Fee Billing &amp; Token</h3></div></div>';
    
    echo '<form method="post" action="/index.php?page=appointments" id="chamberBookingForm" style="padding:20px;display:flex;flex-direction:column;gap:16px;">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="branch_id" value="' . e($branchId) . '">';

    // Patient Registration or Selection
    echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:14px 16px;">';
    echo '  <strong style="display:block;font-size:11.5px;color:#0c928c;text-transform:uppercase;margin-bottom:10px;">1. Patient Identification (Walk-in or Registered)</strong>';
    echo '  <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(200px, 1fr));gap:12px;">';
    echo '    <label class="field">Patient Name *<input type="text" name="patient_name" placeholder="Enter patient name" required style="font-weight:600;"></label>';
    echo '    <label class="field">Patient Mobile *<input type="text" name="patient_mobile" placeholder="017XXXXXXXX" required style="font-weight:600;"></label>';
    echo '    <label class="field">Gender<select name="gender"><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select></label>';
    echo '    <label class="field">Patient Category<select name="patient_category" style="font-weight:700;color:#0c928c;"><option value="doctor_prescribed" selected>🩺 Doctor Prescribed Patient</option><option value="clinical_patient">🔬 Clinical Patient</option><option value="local_customer">🛍️ Local Customer</option></select></label>';
    echo '  </div>';
    echo '</div>';

    // Doctor & Schedule Details
    echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:14px 16px;">';
    echo '  <strong style="display:block;font-size:11.5px;color:#0284c7;text-transform:uppercase;margin-bottom:10px;">2. Consultant Doctor &amp; Appointment Slot</strong>';
    echo '  <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(200px, 1fr));gap:12px;">';
    
    echo '    <label class="field">Doctor / Consultant *<select name="doctor_id" id="apptDoctorSelect" required style="font-weight:700;">';
    foreach ($doctors as $d) {
        $dFee = (float)($d['consultation_fee'] ?? 1000.00);
        echo '<option value="' . e($d['id']) . '" data-fee="' . $dFee . '">' . e($d['name']) . ' (' . e($d['specialty'] ?? 'Specialist') . ') - ৳' . number_format($dFee, 0) . '</option>';
    }
    echo '    </select></label>';
    echo '    <label class="field">Chamber Room<select name="room_id">';
    foreach ($rooms as $r) echo '<option value="' . e($r['id']) . '">' . e($r['name']) . '</option>';
    echo '    </select></label>';
    echo '    <label class="field">Appointment Date *<input type="date" name="appointment_date" value="' . e(date('Y-m-d')) . '" required></label>';
    echo '    <label class="field">Time Slot *<input name="time_slot" value="10:00 AM" placeholder="10:00 AM" required></label>';
    echo '    <label class="field">Booking Source<select name="booking_source"><option value="walkin">Walk-in Counter</option><option value="phone">Phone Call</option><option value="website">Website Portal</option></select></label>';
    echo '  </div>';
    echo '</div>';

    // Consultation Fee, Referral & Cash Counter Settlement
    echo '<div style="background:#ffffff;border:1.5px solid #0c928c;border-radius:8px;padding:14px 16px;box-shadow:0 2px 10px rgba(12,146,140,0.06);">';
    echo '  <strong style="display:block;font-size:11.5px;color:#0c928c;text-transform:uppercase;margin-bottom:10px;">3. Consultation Fee, Referral Voucher &amp; Instant POS Settlement</strong>';
    echo '  <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(180px, 1fr));gap:12px;align-items:end;">';
    echo '    <label class="field">Consultation Fee (BDT) *<input type="number" step="0.01" id="apptFee" name="consultation_fee" value="1000.00" required style="font-weight:800;color:#0f172a;"></label>';
    echo '    <label class="field">Referral / Doctor<select name="referrer_id"><option value="">-- Direct Walk-in (No Referral) --</option>';
    foreach ($referrersList as $ref) echo '<option value="' . e($ref['id']) . '">' . e($ref['name']) . ' (' . e($ref['code']) . ')</option>';
    echo '    </select></label>';
    echo '    <label class="field">Voucher / Promo Code<input type="text" name="voucher_code" placeholder="Optional voucher (e.g. VIP50)" style="font-weight:600;"></label>';
    echo '    <label class="field">Discount (BDT)<input type="number" step="0.01" id="apptDiscount" name="discount_amount" value="0.00" style="font-weight:800;color:#dc2626;"></label>';
    echo '    <label class="field">Net Payable (BDT)<input type="number" step="0.01" id="apptPayable" name="payable_amount" value="1000.00" readonly style="background:#f0fdf4;border-color:#34d399;font-weight:900;color:#065f46;"></label>';
    echo '    <label class="field">Paid Amount (BDT) *<input type="number" step="0.01" id="apptPaid" name="paid_amount" value="1000.00" required style="font-weight:800;color:#059669;"></label>';
    echo '    <label class="field">Payment Method<select name="payment_method" style="font-weight:700;"><option value="CASH">Cash Counter</option><option value="BKASH">bKash</option><option value="NAGAD">Nagad</option><option value="CARD">Debit / Credit Card</option></select></label>';
    echo '  </div>';
    echo '</div>';

    echo '<div style="display:flex;justify-content:flex-end;margin-top:4px;">';
    echo '  <button class="button button-primary" style="padding:12px 28px;font-size:14px;font-weight:800;border-radius:8px;box-shadow:0 4px 12px rgba(12,146,140,0.25);"><i class="fa-solid fa-ticket" style="margin-right:8px;"></i> Confirm Booking, Generate Token &amp; Cash Memo</button>';
    echo '</div>';
    echo '</form>';

    // Live JS Calculation Script for Doctor Booking
    echo '<script>
    (function(){
      var docSelect = document.getElementById("apptDoctorSelect");
      var feeInput = document.getElementById("apptFee");
      var discInput = document.getElementById("apptDiscount");
      var payInput = document.getElementById("apptPayable");
      var paidInput = document.getElementById("apptPaid");

      function updateDoctorFee() {
        if(docSelect && feeInput){
          var opt = docSelect.options[docSelect.selectedIndex];
          if(opt){
            var fee = parseFloat(opt.getAttribute("data-fee") || 1000);
            feeInput.value = fee.toFixed(2);
            calcNet();
          }
        }
      }

      function calcNet() {
        var fee = parseFloat(feeInput.value || 0);
        var disc = parseFloat(discInput.value || 0);
        var net = Math.max(0, fee - disc);
        payInput.value = net.toFixed(2);
        paidInput.value = net.toFixed(2);
      }

      if(docSelect) docSelect.addEventListener("change", updateDoctorFee);
      if(feeInput) feeInput.addEventListener("input", calcNet);
      if(discInput) discInput.addEventListener("input", calcNet);
      updateDoctorFee();
    })();
    </script>';

    echo '</section></div>';
    page_end();
}

function render_orders(PDO $db, array $user): void
{
    Security::requirePermission($db, 'orders.view');
    $branchId = Security::branchIds($db)[0];
    $viewId = (int) ($_GET['view'] ?? 0);

    page_start($db, $user, 'orders', 'Front Desk Order Entry & Service Selection', 'Convert patient visits into diagnostic test orders with preparation instructions.');

    if ($viewId) {
        $order = \Diagnostic\Orders::getOrder($db, $viewId);
        
        // Find or check invoice for this order
        $invStmt = $db->prepare('SELECT id, invoice_no, paid_amount, due_amount, status FROM invoices WHERE order_id = ? LIMIT 1');
        $invStmt->execute([$viewId]);
        $existingInvoice = $invStmt->fetch(PDO::FETCH_ASSOC);

        echo '<section class="card" style="background:#ffffff;border:1.5px solid #cbd5e1;border-radius:14px;box-shadow:0 4px 18px rgba(15,23,42,0.05);overflow:hidden;">';
        echo '<div class="card-head" style="background:linear-gradient(135deg, #f0fdfa 0%, #f8fafc 100%);border-bottom:1px solid #e2e8f0;padding:16px 20px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;"><div><span class="eyebrow" style="color:#0c928c;font-weight:800;letter-spacing:0.08em;">ORDER DETAILS</span><h3 style="margin:2px 0 0;font-size:18px;color:#0f172a;">Order #' . e($order['order_no']) . '</h3></div><div style="display:flex;gap:10px;align-items:center;">';
        
        // Direct Payment / Invoice button
        if ($existingInvoice) {
            echo '<a class="button button-primary" href="/index.php?page=billing&view=' . e((string)$existingInvoice['id']) . '" style="background:#059669;color:#ffffff;border-color:#059669;padding:8px 18px;border-radius:8px;font-weight:800;display:inline-flex;align-items:center;gap:6px;box-shadow:0 2px 10px rgba(5,150,105,0.25);">💳 Open Cash Counter & Pay (Inv #' . e($existingInvoice['invoice_no']) . ') →</a>';
        } else {
            echo '<form method="post" action="/index.php?page=billing" style="margin:0;display:inline-block;">';
            echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
            echo '<input type="hidden" name="action" value="create_invoice">';
            echo '<input type="hidden" name="order_id" value="' . e((string)$order['id']) . '">';
            echo '<button type="submit" class="button button-primary" style="background:#059669;border-color:#059669;color:#ffffff;padding:8px 18px;border-radius:8px;font-weight:800;display:inline-flex;align-items:center;gap:6px;box-shadow:0 2px 10px rgba(5,150,105,0.25);">💳 Complete Order Payment & Bill Cash Memo →</button>';
            echo '</form>';
        }

        echo '<a class="button button-outline" href="/index.php?page=download_pdf&type=order&id=' . e((string)$order['id']) . '" style="background:#ffffff;color:#0284c7;border:1.5px solid #0284c7;padding:8px 16px;border-radius:8px;font-weight:750;display:inline-flex;align-items:center;gap:6px;text-decoration:none;"><i class="fa-solid fa-file-pdf"></i> Download PDF (mPDF)</a>';
        echo '<a class="button button-outline" target="_blank" href="/index.php?page=print_voucher&type=order&id=' . e((string)$order['id']) . '" style="background:#ffffff;color:#0d9488;border:1.5px solid #0d9488;padding:8px 16px;border-radius:8px;font-weight:750;display:inline-flex;align-items:center;gap:6px;text-decoration:none;"><i class="fa-solid fa-print"></i> Print Requisition Slip</a>';
        echo '<a class="button" href="/index.php?page=orders" style="background:#0c928c;color:#ffffff;border:1px solid #0c928c;padding:8px 16px;border-radius:8px;font-weight:750;display:inline-flex;align-items:center;gap:6px;text-decoration:none;box-shadow:0 2px 8px rgba(12,146,140,0.25);transition:all 0.2s ease;">← Back to orders</a>';
        echo '</div></div>';
        echo '<div style="padding:20px;">';
        echo '<div class="stats-grid" style="gap:16px;margin-bottom:24px;">';
        echo '<a href="/index.php?page=patients&view=' . e((string)$order['patient_id']) . '" class="stat-card" style="background:#f0f9ff;border:1px solid #bae6fd;border-left:4px solid #0284c7;border-radius:12px;padding:16px 18px;box-shadow:0 2px 6px rgba(2,132,199,0.06);text-decoration:none;cursor:pointer;transition:transform 0.15s;" onmouseover="this.style.transform=\'translateY(-2px)\'" onmouseout="this.style.transform=\'none\'"><span style="color:#0369a1;font-size:11px;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;">PATIENT PROFILE ↗</span><strong style="color:#0c4a6e;font-size:16px;margin-top:4px;display:block;">' . e($order['patient_name']) . ' <small style="color:#0284c7;font-weight:700;">(' . e($order['mrn']) . ')</small></strong></a>';
        echo '<a href="/index.php?page=billing' . ($existingInvoice ? '&view=' . e((string)$existingInvoice['id']) : '') . '" class="stat-card" style="background:#f0fdf4;border:1px solid #bbf7d0;border-left:4px solid #16a34a;border-radius:12px;padding:16px 18px;box-shadow:0 2px 6px rgba(22,163,74,0.06);text-decoration:none;cursor:pointer;transition:transform 0.15s;" onmouseover="this.style.transform=\'translateY(-2px)\'" onmouseout="this.style.transform=\'none\'"><span style="color:#15803d;font-size:11px;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;">ORDER & PAYMENT STATUS ↗</span><strong style="color:#14532d;font-size:17px;margin-top:4px;display:block;">' . e(str_replace('_',' ',strtoupper($order['status']))) . '</strong></a>';
        echo '<a href="/index.php?page=queue" class="stat-card" style="background:#fffbeb;border:1px solid #fde68a;border-left:4px solid #d97706;border-radius:12px;padding:16px 18px;box-shadow:0 2px 6px rgba(217,119,6,0.06);text-decoration:none;cursor:pointer;transition:transform 0.15s;" onmouseover="this.style.transform=\'translateY(-2px)\'" onmouseout="this.style.transform=\'none\'"><span style="color:#b45309;font-size:11px;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;">URGENCY & QUEUE PRIORITY ↗</span><strong style="color:#78350f;font-size:17px;margin-top:4px;display:block;">' . e(strtoupper($order['urgency'])) . '</strong></a>';
        echo '<a href="/index.php?page=billing" class="stat-card" style="background:#f0fdfa;border:1px solid #99f6e4;border-left:4px solid #0d9488;border-radius:12px;padding:16px 18px;box-shadow:0 2px 6px rgba(13,148,136,0.06);text-decoration:none;cursor:pointer;transition:transform 0.15s;" onmouseover="this.style.transform=\'translateY(-2px)\'" onmouseout="this.style.transform=\'none\'"><span style="color:#0f766e;font-size:11px;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;">PAYABLE AMOUNT (BILLING DESK) ↗</span><strong style="color:#134e4a;font-size:20px;font-weight:850;margin-top:4px;display:block;">BDT ' . number_format((float)$order['payable_amount'], 2) . '</strong></a>';
        echo '</div>';
        
        echo '<div><h4 style="margin:0 0 14px;font-size:15px;color:#0f172a;font-weight:800;">Selected Test Items</h4><div class="table-wrap" style="background:#ffffff;border-radius:10px;border:1px solid #e2e8f0;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,0.02);"><table><thead><tr style="background:#f8fafc;"><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Test Name</th><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Price</th><th style="padding:10px 14px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;">Fasting / Instructions</th></tr></thead><tbody>';
        foreach ($order['items'] as $it) {
            echo '<tr><td style="padding:12px 14px;"><strong>' . e($it['item_name']) . '</strong></td><td style="padding:12px 14px;"><span class="price-badge" style="background:#f0fdf4;color:#166534;border:1.5px solid #bbf7d0;padding:5px 12px;border-radius:6px;font-weight:800;font-size:12.5px;display:inline-block;">BDT ' . number_format((float)$it['price'], 2) . '</span></td><td style="padding:12px 14px;">' . ($it['fasting_required'] ? '<span class="status off">12h Fasting Required</span>' : '<span class="status on">Normal</span>') . '</td></tr>';
        }
        echo '</tbody></table></div></div></div></section>';
        page_end();
        return;
    }

    $orders = \Diagnostic\Orders::listOrders($db, $branchId);
    $tests = Masters::scoped($db, 'diagnostic_tests', 100);
    $doctors = Masters::scoped($db, 'doctors', 100);

    echo '<div class="two-columns"><section class="card"><div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;"><div><span class="eyebrow">ACTIVE ORDERS</span><h3>Recent Orders</h3></div><div style="display:flex;align-items:center;gap:8px;"><a href="/index.php?page=orders&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Export PDF</a><a href="/index.php?page=orders&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a><span class="pill">' . count($orders) . ' orders</span></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Order #</th><th>Patient</th><th>Urgency</th><th>Status</th><th>Amount</th><th style="min-width:210px;">Actions</th></tr></thead><tbody>';
    if (!$orders) echo '<tr><td colspan="6"><div class="empty-state">No orders found.</div></td></tr>';
    foreach ($orders as $o) {
        echo '<tr><td><span class="code-chip">' . e($o['order_no']) . '</span></td><td><strong>' . e($o['patient_name']) . '</strong></td><td>' . e(strtoupper($o['urgency'])) . '</td><td><span class="code-chip">' . e($o['status']) . '</span></td><td>BDT ' . e($o['payable_amount']) . '</td><td><div class="table-actions-cell"><a class="text-link" href="/index.php?page=orders&view=' . e($o['id']) . '" style="margin-right:4px;">Details →</a><a class="btn-action-pdf" href="/index.php?page=download_pdf&type=order&id=' . e((string)$o['id']) . '" title="Download Requisition PDF"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg> PDF</a><a class="btn-action-print" target="_blank" href="/index.php?page=print_voucher&type=order&id=' . e((string)$o['id']) . '" title="Print Official Requisition"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg> Print</a></div></td></tr>';
    }
    echo '</tbody></table></div></section>';

    if (Security::can($db, 'orders.create')) {
        echo '<section class="card"><div class="card-head"><div><span class="eyebrow">NEW DIAGNOSTIC ORDER</span><h3>Create Order</h3></div></div>';
        echo '<form method="post" action="/index.php?page=orders" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="branch_id" value="' . e($branchId) . '">';
        echo '<label class="field">Patient *<select name="patient_id" required>';
        foreach (\Diagnostic\Patients::search($db, '', $branchId, 20) as $p) echo '<option value="' . e($p['id']) . '">' . e($p['name']) . ' (' . e($p['mrn']) . ')</option>';
        echo '</select></label>';
        echo '<label class="field">Referring Doctor<select name="doctor_id"><option value="">Self / Walk-in</option>';
        foreach ($doctors as $d) echo '<option value="' . e($d['id']) . '">' . e($d['name']) . '</option>';
        echo '</select></label>';
        echo '<label class="field">Urgency Priority<select name="urgency"><option value="routine">Routine</option><option value="urgent">Urgent</option><option value="stat">STAT (Critical)</option></select></label>';
        echo '<label class="field">Discount BDT<input type="number" name="discount_amount" step="0.01" value="0.00"></label>';
        
        echo '<div class="field span-2"><strong>Select Diagnostic Tests *</strong><div class="test-selection-grid" style="max-height:220px;overflow-y:auto;border:1px solid #dce8e9;padding:12px;border-radius:10px;background:#f8fafb;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:8px;margin-top:6px;">';
        foreach ($tests as $idx => $t) {
            $price = number_format((float)($t['price'] ?? 0), 2);
            echo '<label style="display:flex;align-items:center;gap:10px;background:white;border:1px solid #e2ecee;padding:8px 12px;border-radius:8px;cursor:pointer;transition:all 0.15s ease;" onmouseover="this.style.borderColor=\'#0c928c\'" onmouseout="this.style.borderColor=\'#e2ecee\'"><input type="checkbox" name="items[' . $idx . '][item_id]" value="' . e($t['id']) . '"> <div style="flex:1;min-width:0;"><strong style="font-size:12px;display:block;color:#132f36;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' . e($t['name']) . '</strong><span style="font-size:10px;color:#71868e;">Code: ' . e($t['code']) . ' · <span style="color:#0c928c;font-weight:700;">BDT ' . $price . '</span></span></div></label>';
        }
        echo '</div></div>';

        echo '<div class="form-actions span-2"><button class="button button-primary">Generate Order & Issue Billing Token</button></div></form></section>';
    }
    echo '</div>';
    page_end();
}

function render_queue(PDO $db, array $user): void
{
    Security::requirePermission($db, 'queue.manage');
    $branchId = Security::branchIds($db)[0];
    $tokens = \Diagnostic\Queue::getQueue($db, $branchId);
    $counters = Masters::scoped($db, 'counters', 50);

    page_start($db, $user, 'queue', 'Queue Desk & Counter Management', 'Control patient waiting lines, counter calls, and service area routing.');

    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">COUNTER CALL DESK</span><h3>Active Counter Operations</h3></div></div>';
    echo '<form method="post" action="/index.php?page=queue" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="call">';
    echo '<label class="field">Select Counter *<select name="counter_id" required>';
    foreach ($counters as $c) echo '<option value="' . e($c['id']) . '">' . e($c['name']) . ' (' . e(ucfirst($c['purpose'])) . ')</option>';
    echo '</select></label>';
    echo '<label class="field">Service Area *<select name="service_area"><option value="billing">Billing</option><option value="registration">Registration</option><option value="sample_collection">Sample Collection</option><option value="doctor_chamber">Doctor Chamber</option><option value="imaging">Imaging</option></select></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary" style="font-size:1.1rem;padding:12px;">📢 Call Next Patient</button></div></form></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">LIVE QUEUE TOKENS</span><h3>Today\'s Tokens</h3></div><span class="pill">' . count($tokens) . ' tokens</span></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Token #</th><th>Area</th><th>Patient</th><th>Counter</th><th>Status</th></tr></thead><tbody>';
    if (!$tokens) echo '<tr><td colspan="5"><div class="empty-state">No tokens issued today.</div></td></tr>';
    foreach ($tokens as $t) {
        echo '<tr><td><strong style="font-size:1.1rem;">' . e($t['token_no']) . '</strong></td><td>' . e(ucwords(str_replace('_',' ',$t['service_area']))) . '</td><td>' . e($t['patient_name'] ?? 'Walk-in') . '</td><td>' . e($t['counter_name'] ?? 'Waiting') . '</td><td><span class="code-chip">' . e(strtoupper($t['status'])) . '</span></td></tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_display_board(PDO $db, array $user): void
{
    Security::requirePermission($db, 'queue.manage');
    $branchId = Security::branchIds($db)[0];
    $display = \Diagnostic\Queue::getDisplayBoard($db, $branchId);

    page_start($db, $user, 'display_board', 'Public TV Display Board', 'Real-time patient call announcements for waiting lounges.');

    echo '<section class="card" style="background:linear-gradient(135deg,#092c36,#0f3b45);color:#ffffff;padding:40px;border-radius:16px;box-shadow:0 10px 30px rgba(9,44,54,0.3);"><div style="text-align:center;margin-bottom:35px;"><span class="eyebrow" style="color:#32d7c1;font-size:14px;letter-spacing:0.2em;">PATIENT QUEUE ANNOUNCEMENT</span><h1 style="font-size:3.2rem;margin:10px 0;color:#ffffff;font-weight:800;letter-spacing:-0.03em;">NOW CALLING</h1></div>';
    echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:24px;">';
    if (!$display['active_calling']) echo '<div class="empty-state" style="color:#b6eee4;grid-column:1/-1;font-size:18px;">No tokens currently being called.</div>';
    foreach ($display['active_calling'] as $item) {
        echo '<div style="background:#164754;padding:26px;border-radius:14px;border-left:6px solid #32d7c1;box-shadow:0 6px 20px rgba(0,0,0,0.2);">';
        echo '<div style="font-size:3rem;font-weight:900;color:#32d7c1;letter-spacing:0.04em;">' . e($item['token_no']) . '</div>';
        echo '<div style="font-size:1.4rem;font-weight:800;margin-top:8px;color:#ffffff;">' . e($item['counter_name'] ?? 'Counter Desk') . '</div>';
        echo '<div style="color:#b6eee4;font-size:1rem;margin-top:6px;font-weight:600;">' . e(ucwords(str_replace('_',' ',$item['service_area']))) . ' · <span style="color:#ffffff;font-weight:700;">' . e($item['patient_name'] ?? 'Walk-in Patient') . '</span></div>';
        echo '</div>';
    }
    echo '</div></section>';
    page_end();
}

function render_billing(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $viewId = (int) ($_GET['view'] ?? 0);

    page_start($db, $user, 'billing', 'Billing, Receipts & Cash Collection', 'Process multi-mode payments, generate invoices, due collection and printable receipts.');

    if ($viewId) {
        $inv = \Diagnostic\Billing::getInvoice($db, $viewId);
        echo '<section class="card"><div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;"><div><span class="eyebrow">INVOICE & RECEIPT</span><h3>Invoice #' . e($inv['invoice_no']) . '</h3></div><div style="display:flex;gap:8px;"><a class="button button-outline" href="/index.php?page=download_pdf&type=billing&id=' . e((string)$inv['id']) . '" style="background:#ffffff;color:#0284c7;border:1.5px solid #0284c7;padding:8px 16px;border-radius:8px;font-weight:750;display:inline-flex;align-items:center;gap:6px;text-decoration:none;"><i class="fa-solid fa-file-pdf"></i> Download PDF (mPDF)</a><a class="button button-outline" target="_blank" href="/index.php?page=print_voucher&type=billing&id=' . e((string)$inv['id']) . '" style="background:#ffffff;color:#0d9488;border:1.5px solid #0d9488;padding:8px 16px;border-radius:8px;font-weight:750;display:inline-flex;align-items:center;gap:6px;text-decoration:none;"><i class="fa-solid fa-print"></i> Print Official Receipt</a><a class="button button-back-light" href="/index.php?page=billing">← Back to billing</a></div></div>';
        echo '<div class="stats-grid"><div class="stat-card invoice-detail-card card-light-teal"><span>Patient</span><strong>' . e($inv['patient_name']) . ' (' . e($inv['mrn']) . ')</strong></div><div class="stat-card invoice-detail-card card-light-blue"><span>Total Payable</span><strong>BDT ' . number_format((float)$inv['payable_amount'], 2) . '</strong></div><div class="stat-card invoice-detail-card card-light-emerald"><span>Paid Amount</span><strong>BDT ' . number_format((float)$inv['paid_amount'], 2) . '</strong></div><div class="stat-card invoice-detail-card card-light-amber"><span>Remaining Due</span><strong>BDT ' . number_format((float)$inv['due_amount'], 2) . '</strong></div></div>';
        
        if ((float)$inv['due_amount'] > 0) {
            $methods = Masters::scoped($db, 'payment_methods', 20);
            if (!$methods) {
                $stmt = $db->query('SELECT * FROM payment_methods WHERE active=1');
                $methods = $stmt->fetchAll();
            }
            echo '<form method="post" action="/index.php?page=billing" class="field-grid" style="margin-top:20px;background:#f8fafc;padding:22px;border-radius:14px;border:1px solid #e2e8f0;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="pay"><input type="hidden" name="invoice_id" value="' . e($inv['id']) . '">';
            echo '<h4 class="span-2" style="margin:0 0 10px;color:#092c36;font-size:16px;">💳 Collect Due Payment & Online Gateway Checkout</h4>';
            echo '<label class="field">Payment Method *<select name="payment_method_id" id="pm_select" required onchange="updateGatewayLink(this.value)">';
            foreach ($methods as $pm) echo '<option value="' . e($pm['id']) . '" data-code="' . e($pm['code']) . '">' . e($pm['name']) . '</option>';
            echo '</select></label>';
            echo '<label class="field">Amount (BDT) *<input type="number" name="amount" id="pm_amount" step="0.01" max="' . e($inv['due_amount']) . '" value="' . e($inv['due_amount']) . '" required></label>';
            echo '<label class="field span-2">Gateway Reference / TxID <small>(Enter TxID for bKash / SSLCommerz or leave blank to auto-generate)</small><div style="display:flex;gap:8px;"><input name="reference_no" id="txid_input" placeholder="e.g. SSL-8923412 or BKASH-991203" value="SSL-' . strtoupper(substr(md5((string)time()), 0, 8)) . '"><button type="button" class="button button-outline" onclick="document.getElementById(\'txid_input\').value=\'BKASH-\'+Math.floor(100000+Math.random()*900000);">Auto TxID</button></div></label>';
            echo '<div class="form-actions span-2" style="display:flex;gap:12px;flex-wrap:wrap;align-items:center;">';
            echo '<button class="button button-receive-cash-light" name="submit_mode" value="direct">Receive Cash Payment & Print Receipt</button>';
            echo '<a id="gw_redirect_btn" href="/index.php?page=payment_gateway&invoice_id=' . e($inv['id']) . '&method_id=2&amount=' . e($inv['due_amount']) . '" class="button button-gateway-light">🚀 Launch Gateway Checkout (SSLCommerz / bKash) →</a>';
            echo '</div></form>';
            echo '<script>
            function updateGatewayLink(methodId) {
                var amt = document.getElementById("pm_amount").value || "' . e($inv['due_amount']) . '";
                document.getElementById("gw_redirect_btn").href = "/index.php?page=payment_gateway&invoice_id=' . e($inv['id']) . '&method_id=" + methodId + "&amount=" + amt;
            }
            </script>';
        }

        echo '<div style="margin-top:20px;"><h4>Payment Receipts</h4><div class="table-wrap"><table><thead><tr><th>Receipt #</th><th>Date</th><th>Method</th><th>Amount</th><th>Collector</th></tr></thead><tbody>';
        if (!$inv['payments']) echo '<tr><td colspan="5"><div class="empty-state">No payment transactions.</div></td></tr>';
        foreach ($inv['payments'] as $pay) {
            echo '<tr><td><span class="code-chip">' . e($pay['receipt_no']) . '</span></td><td>' . e($pay['created_at']) . '</td><td>' . e($pay['method_name']) . '</td><td>BDT ' . e($pay['amount']) . '</td><td>' . e($pay['receiver_name']) . '</td></tr>';
        }
        echo '</tbody></table></div></div></section>';
        page_end();
        return;
    }

    $invoices = \Diagnostic\Billing::listInvoices($db, $branchId);
    $ordersWithoutInvoice = $db->query('SELECT o.*, p.name AS patient_name FROM diagnostic_orders o JOIN patients p ON p.id=o.patient_id WHERE o.branch_id=' . $branchId . ' AND o.id NOT IN (SELECT order_id FROM invoices) ORDER BY o.id DESC')->fetchAll();

    // Stacked Layout: Recent Invoices (Top) + Generate Invoice (Below)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Top Section: Recent Invoices
    echo '<section class="card"><div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;"><div><span class="eyebrow">INVOICE REGISTER</span><h3>Recent Invoices</h3></div><div style="display:flex;align-items:center;gap:8px;"><a href="/index.php?page=billing&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Export PDF</a><a href="/index.php?page=billing&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a><span class="pill">' . count($invoices) . ' invoices</span></div></div>';

    // Live Auto-Search Bar for Billing Invoices
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search invoice #, patient or status..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Invoice #</th><th>Patient</th><th>Payable</th><th>Status</th><th style="min-width:250px;">Actions</th></tr></thead><tbody>';
    if (!$invoices) echo '<tr><td colspan="5"><div class="empty-state">No invoices found.</div></td></tr>';
    foreach ($invoices as $i) {
        echo '<tr><td><span class="code-chip">' . e($i['invoice_no']) . '</span></td><td><strong>' . e($i['patient_name']) . '</strong></td><td><span class="billing-payable-badge">BDT ' . number_format((float)$i['payable_amount'], 2) . '</span></td><td><span class="status ' . ($i['status']==='paid'?'on':'off') . '">' . e(strtoupper($i['status'])) . '</span></td><td><div class="table-actions-cell"><a class="button button-manage-pay-light small" href="/index.php?page=billing&view=' . e($i['id']) . '">Manage / Pay →</a><a class="btn-action-pdf" href="/index.php?page=download_pdf&type=billing&id=' . e((string)$i['id']) . '" title="Download Receipt PDF"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg> PDF</a><a class="btn-action-print" target="_blank" href="/index.php?page=print_voucher&type=billing&id=' . e((string)$i['id']) . '" title="Print Official Money Receipt"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg> Print</a></div></td></tr>';
    }
    echo '</tbody></table></div></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">UNINVOICED ORDERS</span><h3>Generate Invoice</h3></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Order #</th><th>Patient</th><th>Payable</th><th>Generate</th></tr></thead><tbody>';
    if (!$ordersWithoutInvoice) echo '<tr><td colspan="4"><div class="empty-state">All orders have been invoiced.</div></td></tr>';
    foreach ($ordersWithoutInvoice as $ord) {
        echo '<tr><td><span class="code-chip">' . e($ord['order_no']) . '</span></td><td>' . e($ord['patient_name']) . '</td><td><span class="billing-payable-badge">BDT ' . number_format((float)$ord['payable_amount'], 2) . '</span></td><td><form method="post" action="/index.php?page=billing" style="margin:0;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="create_invoice"><input type="hidden" name="order_id" value="' . e($ord['id']) . '"><button class="button button-outline button-generate-light small">Generate Invoice</button></form></td></tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_cashier_shift(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $counters = Masters::scoped($db, 'counters', 20);
    $shifts = \Diagnostic\Cashier::listShifts($db, $branchId);

    // Check if current user has an active open shift
    $stmtOpen = $db->prepare('SELECT s.*, c.name AS counter_name FROM cashier_shifts s JOIN counters c ON c.id=s.counter_id WHERE s.cashier_id=? AND s.status="open" ORDER BY s.id DESC LIMIT 1');
    $stmtOpen->execute([(int)$user['id']]);
    $activeShift = $stmtOpen->fetch();

    page_start($db, $user, 'cashier_shift', 'Cashier Shifts & Day Closing Reconciliation', 'Track cashier opening float, system expected collections, declared cash and supervisor closing variance.');

    echo '<div class="two-columns"><section class="card shift-register-card"><div class="card-head"><div><span class="eyebrow">SHIFT REGISTER</span><h3>Recent Cashier Shifts</h3></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Counter</th><th>Cashier</th><th>Expected</th><th>Declared</th><th>Variance</th><th>Status</th></tr></thead><tbody>';
    if (!$shifts) echo '<tr><td colspan="6"><div class="empty-state">No shift records.</div></td></tr>';
    foreach ($shifts as $s) {
        echo '<tr><td><strong>' . e($s['counter_name']) . '</strong></td><td>' . e($s['cashier_name']) . '</td><td>BDT ' . e($s['system_expected_cash']) . '</td><td>BDT ' . e($s['declared_cash']) . '</td><td><span class="' . ($s['variance'] < 0 ? 'status off' : 'status on') . '">BDT ' . e($s['variance']) . '</span></td><td><span class="code-chip">' . e(strtoupper($s['status'])) . '</span></td></tr>';
    }
    echo '</tbody></table></div></section>';

    echo '<section class="card shift-control-card"><div class="card-head"><div><span class="eyebrow">SHIFT CONTROL</span><h3>' . ($activeShift ? 'Active Shift Management' : 'Start Shift') . '</h3></div></div>';
    if ($activeShift) {
        echo '<div style="background:#e4f6f0;border:1px solid #0a8372;padding:16px;border-radius:9px;margin-bottom:18px;">';
        echo '<span class="status on" style="margin-bottom:8px;">● ACTIVE OPEN SHIFT</span>';
        echo '<h4 style="margin:4px 0;">Counter: ' . e($activeShift['counter_name']) . '</h4>';
        echo '<p style="margin:4px 0;font-size:12px;color:#496369;">Opened At: ' . e($activeShift['opened_at']) . ' | Float: ৳' . number_format((float)$activeShift['opening_float'], 2) . '</p>';
        echo '</div>';
        echo '<form method="post" action="/index.php?page=cashier_shift" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="close"><input type="hidden" name="shift_id" value="' . e($activeShift['id']) . '">';
        echo '<h4 class="span-2">Close & Reconcile Active Shift</h4>';
        echo '<label class="field">Declared Cash Collected (BDT) *<input type="number" name="declared_cash" step="0.01" value="' . e($activeShift['system_expected_cash']) . '" required></label>';
        echo '<label class="field">Supervisor Notes<input name="notes" placeholder="Cash drawer notes or variance justification"></label>';
        echo '<div class="form-actions span-2"><button class="button button-primary">Close Shift & Record Variance</button></div></form>';
    } else {
        echo '<form method="post" action="/index.php?page=cashier_shift" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="open"><input type="hidden" name="branch_id" value="' . e($branchId) . '">';
        echo '<h4>Start New Shift</h4>';
        echo '<label class="field">Select Counter *<select name="counter_id" class="select-counter-input" required>';
        echo '<option value="">-- Choose Active Counter Desk --</option>';
        foreach ($counters as $c) echo '<option value="' . e($c['id']) . '">' . e($c['name']) . '</option>';
        echo '</select></label>';
        echo '<label class="field">Opening Float (BDT)<input type="number" name="opening_float" step="0.01" value="500.00"></label>';
        echo '<div class="form-actions span-2"><button class="button button-primary">Open Shift</button></div></form>';
    }
    echo '</section></div>';
    page_end();
}

function render_test_categories(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');

    $search = trim((string)($_GET['q'] ?? ''));
    $catFilter = (int)($_GET['cat_id'] ?? 0);

    // Fetch categories with active test count
    $categories = $db->query("SELECT c.*, COUNT(t.id) as test_count FROM test_categories c LEFT JOIN diagnostic_tests t ON t.category_id=c.id AND t.active=1 GROUP BY c.id ORDER BY c.display_order ASC")->fetchAll(PDO::FETCH_ASSOC);
    $departments = $db->query("SELECT id, name FROM departments WHERE active=1 ORDER BY name ASC")->fetchAll(PDO::FETCH_ASSOC);

    // Tests query
    $sql = "SELECT t.*, c.name as category_name, c.code as category_code, d.name as department_name FROM diagnostic_tests t LEFT JOIN test_categories c ON c.id=t.category_id LEFT JOIN departments d ON d.id=t.department_id WHERE 1=1";
    $params = [];
    if ($search !== '') {
        $sql .= " AND (t.name LIKE ? OR t.code LIKE ? OR t.normal_range LIKE ?)";
        $params[] = "%$search%";
        $params[] = "%$search%";
        $params[] = "%$search%";
    }
    if ($catFilter > 0) {
        $sql .= " AND t.category_id = ?";
        $params[] = $catFilter;
    }
    $sql .= " ORDER BY t.category_id ASC, t.id ASC";
    $stmt = $db->prepare($sql);
    $stmt->execute($params);
    $tests = $stmt->fetchAll(PDO::FETCH_ASSOC);

    $totalTests = (int) $db->query("SELECT COUNT(*) FROM diagnostic_tests WHERE active=1")->fetchColumn();
    $totalCats = count($categories);

    page_start($db, $user, 'test_categories', 'Diagnostic Test Categories & Master Catalog', 'Structured medical laboratory disciplines, turnaround SLAs, sample containers and clinical test tariffs.');

