        echo '      <td><strong style="color:#092c36;">' . e($t['name']) . '</strong></td>';
        echo '      <td><span style="font-size:11px;font-weight:750;color:#000000;background:rgba(12,146,140,0.12);padding:4px 9px;border-radius:6px;border:1px solid rgba(12,146,140,0.2);display:inline-block;">' . e($t['category_name'] ?? 'General Lab') . '</span></td>';
