        echo '      <td><strong style="color:#0f172a;font-size:13px;">৳ ' . number_format((float)($t['price'] ?? 500), 2) . '</strong></td>';
        echo '      <td><span class="status on">Active</span></td>';
        echo '    </tr>';
    }
    echo '      </tbody>';
    echo '    </table>';
    echo '  </div>';
    echo '</section>';

    echo '<script>
    function toggleDrawer(id) {
        var el = document.getElementById(id);
        if (!el) return;
        el.style.display = (el.style.display === "none" || el.style.display === "") ? "block" : "none";
        if (el.style.display === "block") el.scrollIntoView({behavior: "smooth"});
    }
    </script>';

    page_end();
}

function render_lab_reports(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');

    $search = trim((string)($_GET['q'] ?? ''));
    $statusFilter = trim((string)($_GET['status'] ?? ''));
    $viewReportId = (int)($_GET['view_report'] ?? 0);

    // If viewing a single official clinical report
    $singleReport = null;
    $reportResults = [];
    if ($viewReportId > 0) {
        $stmt = $db->prepare("SELECT lr.*, o.order_no, o.urgency, o.collection_location, o.clinical_notes, p.name AS patient_name, p.mrn, p.gender, p.dob, p.mobile, p.address, u.name AS approver_name, rd.qr_verification_hash, rd.acted_at AS delivered_at FROM lab_reports lr JOIN diagnostic_orders o ON o.id=lr.order_id JOIN patients p ON p.id=lr.patient_id LEFT JOIN users u ON u.id=lr.approved_by LEFT JOIN (SELECT * FROM report_deliveries WHERE id IN (SELECT MAX(id) FROM report_deliveries GROUP BY report_id)) rd ON rd.report_id=lr.id WHERE lr.id = ?");
        $stmt->execute([$viewReportId]);
        $singleReport = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($singleReport) {
            $stmtRes = $db->prepare("SELECT lres.*, dt.name AS test_name, dt.code AS test_code, dt.sample_requirement FROM lab_results lres JOIN diagnostic_tests dt ON dt.id=lres.test_id WHERE lres.order_id = ? ORDER BY lres.id ASC");
            $stmtRes->execute([$singleReport['order_id']]);
            $reportResults = $stmtRes->fetchAll(PDO::FETCH_ASSOC);
        }
    }

    // Reports list query
    $sql = "SELECT lr.*, o.order_no, o.urgency, p.name AS patient_name, p.mrn, p.gender, p.dob, u.name AS approver_name, rd.qr_verification_hash, rd.action_type AS delivery_action, (SELECT GROUP_CONCAT(dt.name SEPARATOR ', ') FROM diagnostic_order_items oi JOIN diagnostic_tests dt ON dt.id=oi.item_id WHERE oi.order_id=lr.order_id) AS test_names, (SELECT MAX(CASE WHEN lres.result_flag='critical' THEN 'critical' WHEN lres.result_flag='high' THEN 'high' ELSE 'normal' END) FROM lab_results lres WHERE lres.order_id=lr.order_id) AS worst_flag FROM lab_reports lr JOIN diagnostic_orders o ON o.id=lr.order_id JOIN patients p ON p.id=lr.patient_id LEFT JOIN users u ON u.id=lr.approved_by LEFT JOIN (SELECT * FROM report_deliveries WHERE id IN (SELECT MAX(id) FROM report_deliveries GROUP BY report_id)) rd ON rd.report_id=lr.id WHERE 1=1";
    $params = [];
    if ($search !== '') {
        $sql .= " AND (lr.report_no LIKE ? OR p.name LIKE ? OR p.mrn LIKE ? OR o.order_no LIKE ?)";
        $params[] = "%$search%";
        $params[] = "%$search%";
        $params[] = "%$search%";
        $params[] = "%$search%";
    }
    if ($statusFilter !== '') {
        $sql .= " AND lr.status = ?";
        $params[] = $statusFilter;
    }
    $sql .= " ORDER BY lr.id DESC";
    $stmt = $db->prepare($sql);
    $stmt->execute($params);
    $reports = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // KPI counts
    $totalReports = (int) $db->query("SELECT COUNT(*) FROM lab_reports")->fetchColumn();
    $approvedReports = (int) $db->query("SELECT COUNT(*) FROM lab_reports WHERE status='approved'")->fetchColumn();
    $criticalAlerts = (int) $db->query("SELECT COUNT(DISTINCT order_id) FROM lab_results WHERE result_flag='critical'")->fetchColumn();
    $deliveredCount = (int) $db->query("SELECT COUNT(DISTINCT report_id) FROM report_deliveries WHERE report_type='lab'")->fetchColumn();

    page_start($db, $user, 'lab_reports', 'Diagnostic Lab Reports & Verification Archive', 'Pathologist-authorized patient diagnostic reports, multi-parametric findings, ISO 15189 format and QR verification.');

    // Top KPI Summary Cards (Side-by-side 4-column layout, light theme, direct navigation)
    echo '<div class="lis-kpi-row" style="display:grid;grid-template-columns:repeat(4, 1fr);gap:16px;margin-bottom:24px;">';
    echo '  <a href="/index.php?page=lab_reports" class="stat-card card-clickable-nav card-light-teal" style="border-left:4px solid #0c928c;text-decoration:none;padding:18px;display:flex;align-items:center;gap:14px;">';
    echo '    <div class="kpi-icon-box" style="background:#ecfdf5;color:#059669;">' . get_svg_icon('file-text') . '</div>';
    echo '    <div><div style="font-size:11px;font-weight:750;color:#64748b;text-transform:uppercase;letter-spacing:0.5px;">Lab Reports</div><div style="font-size:22px;font-weight:800;color:#092c36;">' . $totalReports . ' Generated</div><div style="font-size:11px;color:#10b981;font-weight:700;">EHR Central Archive</div></div>';
    echo '  </a>';
    echo '  <a href="/index.php?page=pathologist_desk" class="stat-card card-clickable-nav card-light-blue" style="border-left:4px solid #0284c7;text-decoration:none;padding:18px;display:flex;align-items:center;gap:14px;">';
    echo '    <div class="kpi-icon-box" style="background:#eff6ff;color:#2563eb;">' . get_svg_icon('check-circle') . '</div>';
    echo '    <div><div style="font-size:11px;font-weight:750;color:#64748b;text-transform:uppercase;letter-spacing:0.5px;">Consultant Approved</div><div style="font-size:22px;font-weight:800;color:#092c36;">' . $approvedReports . ' Released</div><div style="font-size:11px;color:#2563eb;font-weight:700;">E-Signature Certified</div></div>';
    echo '  </a>';
    echo '  <a href="/index.php?page=lab_reports&status=draft" class="stat-card card-clickable-nav card-light-amber" style="border-left:4px solid #f59e0b;text-decoration:none;padding:18px;display:flex;align-items:center;gap:14px;">';
    echo '    <div class="kpi-icon-box" style="background:#fef3c7;color:#d97706;">' . get_svg_icon('alert') . '</div>';
    echo '    <div><div style="font-size:11px;font-weight:750;color:#64748b;text-transform:uppercase;letter-spacing:0.5px;">Critical Panic Alerts</div><div style="font-size:22px;font-weight:800;color:#b45309;">' . $criticalAlerts . ' Cases</div><div style="font-size:11px;color:#d97706;font-weight:700;">Immediate Clinical Action</div></div>';
    echo '  </a>';
    echo '  <a href="/index.php?page=report_center" class="stat-card card-clickable-nav card-light-purple" style="border-left:4px solid #8b5cf6;text-decoration:none;padding:18px;display:flex;align-items:center;gap:14px;">';
    echo '    <div class="kpi-icon-box" style="background:#f5f3ff;color:#7c3aed;">' . get_svg_icon('shield') . '</div>';
