    echo '    <input type="text" name="q" value="' . e($search) . '" placeholder="Search by Report #, Patient Name, MRN..." style="padding:9px 14px;border:1px solid #cbd5e1;border-radius:8px;font-size:13px;flex:1;min-width:220px;">';
    echo '    <select name="status" style="padding:9px 14px;border:1px solid #cbd5e1;border-radius:8px;font-size:13px;background:#ffffff;">';
