    echo '  </form>';
    echo '  <div>';
    echo '    <a href="/index.php?page=result_entry" class="button button-primary">+ Enter New Results</a>';
    echo '  </div>';
    echo '</div>';

    // Reports Table
    echo '<section class="card">';
    echo '  <div class="card-head" style="display:flex;justify-content:space-between;align-items:center;">';
    echo '    <div>';
    echo '      <span class="eyebrow">DIAGNOSTIC ARCHIVE</span>';
    echo '      <h3>Central Laboratory Reports Repository (' . count($reports) . ' Total)</h3>';
    echo '    </div>';
    echo '    <span class="pill">' . count($reports) . ' reports</span>';
    echo '  </div>';
    echo '  <div class="table-wrap">';
    echo '    <table>';
    echo '      <thead>';
    echo '        <tr>';
    echo '          <th>Report #</th>';
    echo '          <th>Patient Profile</th>';
    echo '          <th>Order #</th>';
    echo '          <th>Investigations Included</th>';
    echo '          <th>Clinical Severity</th>';
    echo '          <th>Validation Status</th>';
    echo '          <th>Approving Pathologist</th>';
    echo '          <th>Delivery</th>';
    echo '          <th>Actions</th>';
    echo '        </tr>';
    echo '      </thead>';
    echo '      <tbody>';
    if (empty($reports)) {
        echo '    <tr><td colspan="9"><div class="empty-state">No laboratory reports matching criteria.</div></td></tr>';
    }
    foreach ($reports as $r) {
        $worstFlag = $r['worst_flag'] ?? 'normal';
        $flagClass = 'flag-badge ' . $worstFlag;
        $statusClass = $r['status'] === 'approved' ? 'status on' : 'status off';
        $statusText = $r['status'] === 'approved' ? 'Approved &amp; Released' : 'Draft Review';
        $delivText = !empty($r['delivery_action']) ? 'Delivered (' . ucfirst($r['delivery_action']) . ')' : 'Ready for Dispatch';
        $delivColor = !empty($r['delivery_action']) ? '#059669' : '#64748b';

        echo '    <tr>';
        echo '      <td>';
        echo '        <a href="/index.php?page=lab_reports&view_report=' . e((string)$r['id']) . '" style="text-decoration:none;">';
        echo '          <span class="code-chip" style="font-weight:800;color:#000000 !important;background:rgba(12,146,140,0.12);border:1px solid rgba(12,146,140,0.25);">' . e($r['report_no']) . '</span>';
        echo '        </a>';
        echo '      </td>';
        echo '      <td>';
        echo '        <strong style="color:#092c36;">' . e($r['patient_name']) . '</strong>';
        echo '        <div style="font-size:11px;color:#64748b;">MRN: ' . e($r['mrn']) . ' | ' . ucfirst(e($r['gender'])) . '</div>';
        echo '      </td>';
        echo '      <td><span style="font-size:12px;font-family:monospace;color:#475569;">' . e($r['order_no']) . '</span></td>';
        echo '      <td style="max-width:240px;font-size:12px;color:#334155;line-height:1.35;">' . e($r['test_names'] ?? 'Routine Clinical Panel') . '</td>';
        echo '      <td><span class="' . $flagClass . '">' . strtoupper(e($worstFlag)) . '</span></td>';
        echo '      <td><span class="' . $statusClass . '">' . $statusText . '</span></td>';
        echo '      <td><span style="font-size:12px;color:#092c36;font-weight:600;">' . e($r['approver_name'] ?? 'Pending') . '</span></td>';
        echo '      <td><span style="font-size:11px;font-weight:700;color:' . $delivColor . ';">● ' . e($delivText) . '</span></td>';
        echo '      <td>';
        echo '        <div style="display:flex;gap:6px;">';
        echo '          <a href="/index.php?page=lab_reports&view_report=' . e((string)$r['id']) . '" class="button button-view-light small" style="padding:4px 9px;">👁️ View</a>';
        echo '          <a href="/index.php?page=lab_reports&view_report=' . e((string)$r['id']) . '&print=1" class="button button-print-light small" title="Print Official Laboratory Report" style="padding:4px 10px;">';
        echo '            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle;"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg>';
        echo '          </a>';
        echo '        </div>';
        echo '      </td>';
        echo '    </tr>';
    }
    echo '      </tbody>';
    echo '    </table>';
    echo '  </div>';
    echo '</section>';

    page_end();
}

function render_sample_desk(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $worklist = \Diagnostic\LIS::getWorklist($db, $branchId);

    page_start($db, $user, 'sample_desk', 'Specimen Collection & Barcode Chain of Custody', 'Generate unique barcode labels, record collection desk worklists and specimen status.');

    // Top KPI Cards (Light gradient, professional icons, clickable)
    $collectedCount = count($worklist);
    $edtaCount = 0; $serumCount = 0;
    foreach ($worklist as $w) {
        $st = strtolower($w['sample_type_name'] ?? '');
        if (str_contains($st, 'edta') || str_contains($st, 'blood')) $edtaCount++;
        else $serumCount++;
    }

    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=sample_desk" class="stat-card dash-clickable-card card-light-teal" style="text-decoration:none;">';
    echo '    <div class="stat-icon teal"><svg viewBox="0 0 24 24"><path d="M10 2v7.31L4.69 18A2 2 0 0 0 6.4 21h11.2a2 2 0 0 0 1.71-3L14 9.31V2"></path></svg></div>';
    echo '    <span>Accessioned Samples</span><strong>' . $collectedCount . ' Specimens</strong><small style="color:#0d9488;">Unique Barcode Identifiers</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=lab_worklist" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg></div>';
    echo '    <span>Ready for Testing</span><strong>Lab Analyzer Queue</strong><small style="color:#2563eb;">View Laboratory Worklist →</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=quality_qc_tat" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div>';
    echo '    <span>Pre-Analytical Integrity</span><strong>Zero Hemolysis</strong><small style="color:#b45309;">Chain-of-Custody Verified</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=home_collections" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path><polyline points="9 22 9 12 15 12 15 22"></polyline></svg></div>';
    echo '    <span>Home Collection Handover</span><strong>Phlebotomy Visits</strong><small style="color:#7c3aed;">Track Mobile Collectors →</small>';
    echo '  </a>';
    echo '</div>';

    // Main Worklist Card
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">COLLECTION DESK</span><h3>Specimen Collections (' . count($worklist) . ' Samples)</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=sample_desk&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=print_voucher&type=sample_desk" target="_blank" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0f172a;border-color:#94a3b8;background:#f1f5f9;"><i class="fa-solid fa-print"></i> Print Worklist</a>';
    echo '    <a href="/index.php?page=sample_desk&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar for Specimens
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search barcode, order # or patient..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Barcode</th><th>Order #</th><th>Patient Details</th><th>Test Item</th><th>Sample Type & Container</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
    if (!$worklist) echo '<tr><td colspan="7"><div class="empty-state">No specimens collected yet.</div></td></tr>';
    foreach ($worklist as $w) {
        $stName = !empty($w['sample_type_name']) ? $w['sample_type_name'] : 'Blood / EDTA (Lavender Top)';
        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;font-size:12px;">' . e($w['barcode']) . '</span></td>';
        echo '<td>' . e($w['order_no']) . '</td>';
        echo '<td><strong>' . e($w['patient_name']) . '</strong><br><small style="color:#64748b;">MRN: ' . e($w['mrn']) . ' | ' . e(ucfirst($w['gender'] ?? 'N/A')) . '</small></td>';
        echo '<td><strong style="color:#092c36;">' . e($w['item_name']) . '</strong></td>';
        echo '<td>' . e($stName) . '</td>';
        echo '<td><span class="status on" style="background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;">' . e(strtoupper($w['status'])) . '</span></td>';
        echo '<td><a href="/index.php?page=print_voucher&type=order&id=' . e((string)$w['order_id']) . '" target="_blank" class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:700;"><i class="fa-solid fa-barcode"></i> Voucher</a></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section>';
    page_end();
}

function render_lab_worklist(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $samples = \Diagnostic\LIS::getWorklist($db, $branchId, null, 'collected');

    page_start($db, $user, 'lab_worklist', 'Lab Department Worklists', 'Operational queue for Hematology, Biochemistry, Immunology, Microbiology and Pathology.');

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">LAB QUEUE</span><h3>Collected Specimens Ready for Testing</h3></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Barcode</th><th>Patient Name</th><th>Gender / Age</th><th>Test Name</th><th>Action</th></tr></thead><tbody>';
    if (!$samples) echo '<tr><td colspan="5"><div class="empty-state">No collected samples pending in lab queue.</div></td></tr>';
    foreach ($samples as $s) {
        echo '<tr><td><span class="code-chip">' . e($s['barcode']) . '</span></td><td><strong>' . e($s['patient_name']) . '</strong></td><td>' . e(ucfirst($s['gender'])) . '</td><td>' . e($s['item_name']) . '</td><td><a class="button button-primary small" href="/index.php?page=result_entry&order_id=' . e($s['order_id']) . '&item_id=' . e($s['order_item_id']) . '">Enter Result →</a></td></tr>';
    }
    echo '</tbody></table></div></section>';
    page_end();
}

function render_result_entry(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $orderId = (int) ($_GET['order_id'] ?? 0);
    $itemId = (int) ($_GET['item_id'] ?? 0);
    $tests = Masters::scoped($db, 'diagnostic_tests', 100);

    page_start($db, $user, 'result_entry', 'Result Entry & Clinical Flagging', 'Record clinical test results with automatic HIGH / LOW / CRITICAL range evaluation.');

    // Top KPI Indicators (Light gradient, professional icons)
    $results = $db->query('SELECT lr.*, dt.name AS test_name, u.name AS tech_name FROM lab_results lr JOIN diagnostic_tests dt ON dt.id=lr.test_id JOIN users u ON u.id=lr.entered_by ORDER BY lr.id DESC LIMIT 20')->fetchAll();
    $critCnt = 0; $highCnt = 0; $normCnt = 0;
    foreach ($results as $r) {
        if ($r['result_flag'] === 'critical') $critCnt++;
        elseif ($r['result_flag'] === 'high' || $r['result_flag'] === 'low') $highCnt++;
        else $normCnt++;
    }

    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=result_entry" class="stat-card dash-clickable-card card-light-teal" style="text-decoration:none;">';
    echo '    <div class="stat-icon teal"><svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg></div>';
    echo '    <span>Evaluated Findings</span><strong>' . count($results) . ' Clinical Tests</strong><small style="color:#0d9488;">Multi-Param Verified</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=pathologist_desk" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg></div>';
    echo '    <span>Physiological Normal</span><strong>' . $normCnt . ' In-Range</strong><small style="color:#16a34a;">Reference Range Normal</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=result_entry" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg></div>';
    echo '    <span>Borderline / High</span><strong>' . $highCnt . ' Flagged</strong><small style="color:#b45309;">Requires Pathologist Review</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=quality_qc_tat" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"></polygon></svg></div>';
    echo '    <span>Critical Panic Values</span><strong>' . $critCnt . ' Immediate Alert</strong><small style="color:#7c3aed;">SMS &amp; Emergency Escalation</small>';
    echo '  </a>';
    echo '</div>';

    // Stacked Layout: Enter Test Findings (Top) + Evaluated Results (Below)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Top Section: Enter Test Findings Form
    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">RESULT ENTRY</span><h3>Enter Test Findings</h3></div></div>';
    echo '<form method="post" action="/index.php?page=result_entry" class="field-grid" style="grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<label class="field">Order ID *<input type="number" name="order_id" value="' . e($orderId ?: 1) . '" required></label>';
    echo '<label class="field">Order Item ID *<input type="number" name="order_item_id" value="' . e($itemId ?: 1) . '" required></label>';
    echo '<label class="field">Test Name *<select name="test_id" required>';
    foreach ($tests as $t) echo '<option value="' . e($t['id']) . '">' . e($t['name']) . ' (Code: ' . e($t['code']) . ')</option>';
    echo '</select></label>';
    echo '<label class="field">Result Value *<input name="result_value" placeholder="e.g. 14.5 or Positive" required></label>';
    echo '<label class="field span-2" style="grid-column:1/-1;">Technologist Comments<textarea name="comments" rows="2" placeholder="Clinical notes or interpretation comments" style="min-height:55px;"></textarea></label>';
    echo '<div class="form-actions span-2" style="grid-column:1/-1;"><button class="button button-primary" style="width:100%;font-weight:700;padding:12px;"><i class="fa-solid fa-microscope" style="margin-right:6px;"></i> Save Result &amp; Evaluate Flags</button></div></form></section>';

    // Bottom Section: Evaluated Results (Directly Below Enter Test Findings Form)
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">RECENT RESULTS</span><h3>Evaluated Results (' . count($results) . ' Findings)</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=result_entry&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=print_voucher&type=result_entry" target="_blank" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0f172a;border-color:#94a3b8;background:#f1f5f9;"><i class="fa-solid fa-print"></i> Print Findings</a>';
    echo '    <a href="/index.php?page=result_entry&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar for Evaluated Results
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search test, finding or flag..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Test Item</th><th>Result Value &amp; Unit</th><th>Clinical Flag</th><th>Technologist</th><th>Actions</th></tr></thead><tbody>';
    if (!$results) echo '<tr><td colspan="5"><div class="empty-state">No results entered yet.</div></td></tr>';
    foreach ($results as $r) {
        $flagClass = ($r['result_flag'] === 'critical') 
            ? 'background:#fee2e2;color:#b91c1c;border:1px solid #fecaca;' 
            : (($r['result_flag'] === 'high' || $r['result_flag'] === 'low') 
                ? 'background:#fef3c7;color:#b45309;border:1px solid #fde68a;' 
                : 'background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;');

        echo '<tr>';
        echo '<td><strong style="color:#092c36;">' . e($r['test_name']) . '</strong></td>';
        echo '<td><strong style="font-size:13px;">' . e($r['result_value']) . '</strong></td>';
        echo '<td><span class="status on" style="' . $flagClass . '">' . e(strtoupper($r['result_flag'])) . '</span></td>';
        echo '<td>' . e($r['tech_name']) . '</td>';
        echo '<td><a href="/index.php?page=print_voucher&type=order&id=' . e((string)$r['order_id']) . '" target="_blank" class="button button-outline small" style="padding:4px 8px;font-size:11px;font-weight:700;"><i class="fa-solid fa-file-waveform"></i> Report</a></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_pathologist_desk(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];

    page_start($db, $user, 'pathologist_desk', 'Pathologist & Consultant Approval Desk', 'Two-stage clinical report validation, electronic signatures and final report authorization.');

    $pendingResults = $db->query('SELECT lr.*, dt.name AS test_name, p.name AS patient_name, o.order_no FROM lab_results lr JOIN diagnostic_tests dt ON dt.id=lr.test_id JOIN diagnostic_orders o ON o.id=lr.order_id JOIN patients p ON p.id=o.patient_id WHERE lr.status="draft" ORDER BY lr.id DESC')->fetchAll();

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">APPROVAL DESK</span><h3>Pending Clinical Report Validation</h3></div><span class="pill">' . count($pendingResults) . ' pending</span></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Order #</th><th>Patient</th><th>Test</th><th>Result</th><th>Flag</th><th>Action</th></tr></thead><tbody>';
    if (!$pendingResults) echo '<tr><td colspan="6"><div class="empty-state">No results pending approval.</div></td></tr>';
    foreach ($pendingResults as $pr) {
        echo '<tr><td><span class="code-chip">' . e($pr['order_no']) . '</span></td><td><strong>' . e($pr['patient_name']) . '</strong></td><td>' . e($pr['test_name']) . '</td><td><strong>' . e($pr['result_value']) . '</strong></td><td><span class="code-chip">' . e(strtoupper($pr['result_flag'])) . '</span></td><td><form method="post" action="/index.php?page=pathologist_desk"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="approve"><input type="hidden" name="order_id" value="' . e($pr['order_id']) . '"><button class="button button-primary small">Authorize & Release Report</button></form></td></tr>';
    }
    echo '</tbody></table></div></section>';
    page_end();
}

function render_microbiology(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $cultures = \Diagnostic\Microbiology::listCultures($db, $branchId);

    page_start($db, $user, 'microbiology', 'Microbiology & Antibiogram Sensitivity Workflow', 'Culture incubation tracking, isolated organism identification and antibiotic susceptibility matrix.');

    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">CULTURE WORKLIST</span><h3>Microbiology Reports</h3></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Patient</th><th>Test Item</th><th>Growth Status</th><th>Isolated Organism</th></tr></thead><tbody>';
    if (!$cultures) echo '<tr><td colspan="4"><div class="empty-state">No culture tests reported.</div></td></tr>';
    foreach ($cultures as $mc) {
        echo '<tr><td><strong>' . e($mc['patient_name']) . '</strong></td><td>' . e($mc['item_name']) . '</td><td><span class="code-chip">' . e(ucwords(str_replace('_',' ',$mc['growth_status']))) . '</span></td><td>' . e($mc['isolated_organism'] ?? 'Pending') . '</td></tr>';
    }
    echo '</tbody></table></div></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">RECORD CULTURE</span><h3>New Microbiology Entry</h3></div></div>';
    echo '<form method="post" action="/index.php?page=microbiology" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<label class="field">Order Item ID *<input type="number" name="order_item_id" value="1" required></label>';
    echo '<label class="field">Specimen Collection ID *<input type="number" name="sample_collection_id" value="1" required></label>';
    echo '<label class="field">Gram Stain Findings<input name="gram_stain_findings" placeholder="e.g. Gram-negative bacilli"></label>';
    echo '<label class="field">Growth Status<select name="growth_status"><option value="incubation">Incubation</option><option value="growth_observed">Growth Observed</option><option value="no_growth">No Growth</option></select></label>';
    echo '<label class="field">Isolated Organism<input name="isolated_organism" placeholder="e.g. Escherichia coli"></label>';
    echo '<label class="field">Colony Count<input name="colony_count" placeholder="e.g. >10^5 CFU/mL"></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Save Culture Record</button></div></form></section></div>';
    page_end();
}

