function render_radiology_worklist(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $modality = (string) ($_GET['modality'] ?? '');
    $worklist = \Diagnostic\Radiology::getWorklist($db, $branchId, $modality ?: null);

    page_start($db, $user, 'radiology_worklist', 'Radiology Modality Worklist (RIS)', 'Schedule and track imaging patients for X-ray, USG, CT, MRI, Mammography and ECG.');

    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">MODALITY QUEUE</span><h3>Imaging Patients Queue</h3></div><form method="get" action="/index.php"><input type="hidden" name="page" value="radiology_worklist"><select name="modality" class="select-modality-light" onchange="this.form.submit()"><option value="">All Modalities</option><option value="xray"' . ($modality==='xray'?' selected':'') . '>X-Ray</option><option value="usg"' . ($modality==='usg'?' selected':'') . '>USG / Ultrasound</option><option value="ct"' . ($modality==='ct'?' selected':'') . '>CT Scan</option><option value="mri"' . ($modality==='mri'?' selected':'') . '>MRI</option><option value="ecg"' . ($modality==='ecg'?' selected':'') . '>ECG / Echo</option></select></form></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Accession #</th><th>Patient Name</th><th>Modality</th><th>Room</th><th>Status</th></tr></thead><tbody>';
    if (!$worklist) echo '<tr><td colspan="5"><div class="empty-state">No imaging patients in queue.</div></td></tr>';
    foreach ($worklist as $ro) {
        echo '<tr><td><span class="code-chip">' . e($ro['accession_no']) . '</span></td><td><strong>' . e($ro['patient_name']) . '</strong></td><td>' . e(strtoupper($ro['modality'])) . '</td><td>' . e($ro['room_name'] ?? 'Room 1') . '</td><td><span class="status ' . ($ro['status']==='reported'?'on':'off') . '">' . e(ucfirst($ro['status'])) . '</span></td></tr>';
    }
    echo '</tbody></table></div></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">NEW IMAGING ORDER</span><h3>Schedule Radiology Order</h3></div></div>';
    echo '<form method="post" action="/index.php?page=radiology_worklist" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="branch_id" value="' . e($branchId) . '">';
    echo '<label class="field">Order ID *<input type="number" name="order_id" value="1" required></label>';
    echo '<label class="field">Order Item ID *<input type="number" name="order_item_id" value="1" required></label>';
    echo '<label class="field">Modality *<select name="modality"><option value="xray">X-Ray</option><option value="usg">USG / Ultrasonography</option><option value="ct">CT Scan</option><option value="mri">MRI</option><option value="ecg">ECG / Echocardiogram</option></select></label>';
    echo '<label class="field span-2">Clinical History & Pre-medication Notes<textarea name="clinical_history" rows="2" placeholder="Clinical indication, contrast flag, preparation notes"></textarea></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Schedule Imaging & Issue Accession RAD-#</button></div></form></section></div>';
    page_end();
}

function render_radiology_reporting(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $templates = \Diagnostic\Radiology::getTemplates($db);

    page_start($db, $user, 'radiology_reporting', 'Radiology Reporting & Consultant Desk', 'Modality/body-part templates, normal macros, findings and critical flags authorization.');

    $reports = $db->query('SELECT rr.*, ro.accession_no, u.name AS rad_name FROM radiology_reports rr JOIN radiology_orders ro ON ro.id=rr.radiology_order_id JOIN users u ON u.id=rr.radiologist_id ORDER BY rr.id DESC LIMIT 10')->fetchAll();

    // Top KPI Cards for Radiology Reporting Desk
    $critCount = 0;
    foreach ($reports as $r) if (!empty($r['critical_finding_flag'])) $critCount++;

    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=radiology_reporting" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg></div>';
    echo '    <span>Authorized Reports</span><strong>' . count($reports) . ' Finalized</strong><small style="color:#2563eb;">Consultant Verified</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=radiology_reporting" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg></div>';
    echo '    <span>Reporting Macros</span><strong>' . count($templates) . ' Templates</strong><small style="color:#16a34a;">Chest, USG, Neuro &amp; Bone</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=radiology_reporting" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"></path><line x1="12" y1="9" x2="12" y2="13"></line><line x1="12" y1="17" x2="12.01" y2="17"></line></svg></div>';
    echo '    <span>Critical Finding Alerts</span><strong>' . $critCount . ' Critical Flags</strong><small style="color:#b45309;">STAT Notification Ready</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=pacs_viewer" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect><line x1="8" y1="21" x2="16" y2="21"></line><line x1="12" y1="17" x2="12" y2="21"></line></svg></div>';
    echo '    <span>DICOM PACS Archive</span><strong>Launch Viewer</strong><small style="color:#9333ea;">Integrated Study Imaging</small>';
    echo '  </a>';
    echo '</div>';

    // Stacked Layout: Report Editor (Top) + Recent Finalized Reports Table (Below)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Top Section: Radiology Report Entry Form
    echo '<section class="card">';
    echo '<div class="card-head"><div><span class="eyebrow">REPORT EDITOR</span><h3>Radiology Report Entry</h3></div></div>';
    echo '<form method="post" action="/index.php?page=radiology_reporting" class="field-grid" style="grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;">';
    echo '  <input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '  <label class="field">Radiology Order ID *<input type="number" name="radiology_order_id" value="1" required></label>';
    echo '  <label class="field">Select Template Macro<select name="template_id"><option value="">Standard Radiology Format</option>';
    foreach ($templates as $t) echo '<option value="' . e($t['id']) . '">' . e($t['name']) . ' (' . e(strtoupper($t['modality'])) . ')</option>';
    echo '  </select></label>';
    echo '  <label class="field span-2" style="grid-column:1/-1;">Findings Narrative *<textarea name="findings" rows="3" placeholder="Detailed imaging observations and findings..." required style="min-height:75px;">Lung fields are clear. Heart size is normal. Both costophrenic angles are acute. Bony thorax intact.</textarea></label>';
    echo '  <label class="field span-2" style="grid-column:1/-1;">Impression &amp; Conclusion *<textarea name="impression" rows="2" placeholder="Final radiological impression..." required style="min-height:55px;">Normal Chest X-Ray PA view findings.</textarea></label>';
    echo '  <label class="field span-2" style="display:flex;align-items:center;gap:10px;grid-column:1/-1;"><input type="checkbox" name="critical_finding_flag" value="1"> <strong>Mark as Critical Finding Flag (Immediate Emergency Alert)</strong></label>';
    echo '  <div class="form-actions span-2" style="grid-column:1/-1;"><button class="button button-primary" style="width:100%;font-weight:700;padding:12px;"><i class="fa-solid fa-stamp" style="margin-right:6px;"></i> Authorize &amp; Finalize Radiology Report</button></div>';
    echo '</form></section>';

    // Bottom Section: Recent Finalized Reports (Directly Below Report Editor)
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">RADIOLOGY REPORTS</span><h3>Recent Finalized Reports (' . count($reports) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <button class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0f172a;border-color:#94a3b8;background:#f1f5f9;" onclick="window.print()"><i class="fa-solid fa-print"></i> Print Register</button>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar for Radiology Reports
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search report #, accession or radiologist..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Report #</th><th>Accession #</th><th>Radiologist</th><th>Critical Flag</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
    if (!$reports) echo '<tr><td colspan="6"><div class="empty-state">No radiology reports authorized.</div></td></tr>';
    foreach ($reports as $r) {
        $critBadge = $r['critical_finding_flag']
            ? '<span class="status off" style="background:#fee2e2;color:#b91c1c;border:1px solid #fecaca;">CRITICAL ALERT</span>'
            : '<span class="status on" style="background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;">NORMAL</span>';

        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($r['report_no']) . '</span></td>';
        echo '<td><strong>' . e($r['accession_no']) . '</strong></td>';
        echo '<td>' . e($r['rad_name']) . '</td>';
        echo '<td>' . $critBadge . '</td>';
        echo '<td><span class="code-chip">' . e(strtoupper($r['status'])) . '</span></td>';
        echo '<td><div class="table-actions-cell">';
        echo '  <a href="/index.php?page=print_voucher&type=order&id=' . e((string)$r['radiology_order_id']) . '" target="_blank" class="btn-action-print" title="Print Official Radiology Report"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg> Print</a>';
        echo '</div></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_pacs_viewer(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];

    page_start($db, $user, 'pacs_viewer', 'PACS / DICOM Integration Launch', 'Enterprise DICOM Study UID mapping, modality worklist layer and web viewer integration.');

    $studies = $db->query('SELECT ps.*, ro.accession_no, p.name AS patient_name, p.mrn FROM pacs_studies ps JOIN radiology_orders ro ON ro.id=ps.radiology_order_id JOIN diagnostic_orders o ON o.id=ro.order_id JOIN patients p ON p.id=o.patient_id ORDER BY ps.id DESC LIMIT 20')->fetchAll();

    // Executive DICOM Infrastructure Stats
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '<a href="/index.php?page=radiology_worklist" class="stat-card" style="background:#f0fdfa;border:1px solid #ccfbf1;text-decoration:none;display:block;color:inherit;transition:transform 0.15s ease,box-shadow 0.15s ease;" title="Navigate to Radiology Modality Worklist"><div class="stat-icon teal">' . get_svg_icon('radiology') . '</div><span style="color:#0f766e;font-weight:700;">DICOM Studies Linked</span><strong style="color:#000000 !important;font-weight:850;font-size:22px;">' . count($studies) . ' <span style="color:#000000 !important;font-weight:850;">Studies</span></strong><small style="color:#0d9488;font-weight:700;">● DICOM 3.0 Archive Live →</small></a>';
    echo '<a href="/index.php?page=radiology_reporting" class="stat-card" style="background:#f0f9ff;border:1px solid #e0f2fe;text-decoration:none;display:block;color:inherit;transition:transform 0.15s ease,box-shadow 0.15s ease;" title="Navigate to Radiology Consultant Reporting"><div class="stat-icon blue">' . get_svg_icon('pacs') . '</div><span style="color:#0369a1;font-weight:700;">PACS Server Connection</span><strong style="color:#000000 !important;font-weight:850;font-size:22px;">Online (100 ms)</strong><small style="color:#0284c7;font-weight:700;">Orthanc DICOM Node Active →</small></a>';
    echo '<a href="/index.php?page=quality_qc_tat" class="stat-card" style="background:#fffbeb;border:1px solid #fef3c7;text-decoration:none;display:block;color:inherit;transition:transform 0.15s ease,box-shadow 0.15s ease;" title="Navigate to Quality & SLA Monitoring"><div class="stat-icon amber">' . get_svg_icon('hard-drive') . '</div><span style="color:#b45309;font-weight:700;">Storage Node Capacity</span><strong style="color:#000000 !important;font-weight:850;font-size:22px;">1.4 TB / 10 TB</strong><small style="color:#d97706;font-weight:700;">14% Storage Used →</small></a>';
    echo '<a href="/index.php?page=radiology_worklist" class="stat-card" style="background:#f0fdf4;border:1px solid #dcfce7;text-decoration:none;display:block;color:inherit;transition:transform 0.15s ease,box-shadow 0.15s ease;" title="Navigate to Modality Schedule"><div class="stat-icon green">' . get_svg_icon('zap') . '</div><span style="color:#15803d;font-weight:700;">Modalities Connected</span><strong style="color:#000000 !important;font-weight:850;font-size:22px;">X-Ray, CT, MRI, US</strong><small style="color:#16a34a;font-weight:700;">HL7 Worklist Enabled →</small></a>';
    echo '</div>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">DICOM PACS ARCHIVE</span><h3>Reconciled DICOM Studies</h3></div><span class="pill">' . count($studies) . ' studies</span></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>DICOM Study UID</th><th>Accession #</th><th>Patient Name & MRN</th><th>Modality</th><th>Status</th><th>Interactive PACS Viewer</th></tr></thead><tbody>';
    if (!$studies) echo '<tr><td colspan="6"><div class="empty-state">No DICOM PACS studies linked yet.</div></td></tr>';
    foreach ($studies as $st) {
        echo '<tr>';
        echo '<td><span class="code-chip">' . e($st['study_instance_uid']) . '</span></td>';
        echo '<td><strong style="color:#092c36;">' . e($st['accession_no']) . '</strong></td>';
        echo '<td><strong>' . e($st['patient_name']) . '</strong> <span style="font-size:10px;color:#71868e;">(' . e($st['mrn'] ?? 'MRN-N/A') . ')</span></td>';
        echo '<td><span class="code-chip" style="background:#eaf5f4;color:#0a8372;font-weight:800;">' . e(strtoupper($st['modality'])) . '</span></td>';
        echo '<td><span class="status on">' . e(ucfirst($st['status'])) . '</span></td>';
        echo '<td><button class="button button-primary small" onclick="openDicomViewer(\'' . e($st['study_instance_uid']) . '\', \'' . e($st['patient_name']) . '\', \'' . e($st['modality']) . '\', \'' . e($st['accession_no']) . '\')">🖥️ Launch DICOM Web Viewer</button></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section>';

    // DICOM Viewer Modal
    echo '<div id="dicomModal" style="display:none;position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(9,44,54,0.85);backdrop-filter:blur(5px);z-index:9999;align-items:center;justify-content:center;padding:20px;">';
    echo '<div style="background:#071d24;color:#ffffff;width:95%;max-width:1100px;height:88vh;border-radius:16px;border:1px solid #1a4f5c;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 25px 50px rgba(0,0,0,0.5);">';
    
    // Modal Header
    echo '<div style="background:#041419;padding:16px 24px;border-bottom:1px solid #1a4f5c;display:flex;justify-content:space-between;align-items:center;">';
    echo '<div style="display:flex;align-items:center;gap:12px;"><span style="font-size:24px;">🩻</span><div><h3 id="modalPatientTitle" style="margin:0;font-size:16px;color:#32d7c1;">DICOM Study Viewer</h3><div id="modalStudySub" style="font-size:11px;color:#85a6ad;">UID: --</div></div></div>';
    echo '<div style="display:flex;gap:10px;align-items:center;"><span class="pill" id="modalModalityBadge" style="background:#164754;color:#32d7c1;">MODALITY</span><button onclick="closeDicomViewer()" style="background:#ef4444;color:white;border:0;border-radius:6px;padding:6px 14px;font-size:12px;font-weight:700;">✕ Close Viewer</button></div>';
    echo '</div>';

    // Modal Workspace Body
    echo '<div style="flex:1;display:grid;grid-template-columns:260px 1fr 240px;overflow:hidden;">';
    
    // Left Tool Sidebar
    echo '<div style="background:#06181f;padding:16px;border-right:1px solid #1a4f5c;display:flex;flex-direction:column;gap:16px;">';
    echo '<div><label style="font-size:10px;color:#71959d;text-transform:uppercase;font-weight:800;letter-spacing:0.1em;display:block;margin-bottom:8px;">IMAGE PRESETS (W/L)</label>';
    echo '<div style="display:grid;gap:6px;"><button onclick="setWindowLevel(\'soft\')" class="button button-outline small" style="background:#103540;color:#c1e5eb;border-color:#1c4d5c;text-align:left;">🥩 Soft Tissue (W:350 L:40)</button><button onclick="setWindowLevel(\'bone\')" class="button button-outline small" style="background:#103540;color:#c1e5eb;border-color:#1c4d5c;text-align:left;">🦴 Bone Window (W:2000 L:500)</button><button onclick="setWindowLevel(\'lung\')" class="button button-outline small" style="background:#103540;color:#c1e5eb;border-color:#1c4d5c;text-align:left;">🫁 Lung Window (W:1500 L:-600)</button></div></div>';
    
    echo '<div><label style="font-size:10px;color:#71959d;text-transform:uppercase;font-weight:800;letter-spacing:0.1em;display:block;margin-bottom:8px;">VIEWER TOOLS</label>';
    echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;"><button onclick="zoomImage(1.2)" class="button button-outline small" style="background:#103540;color:#c1e5eb;border-color:#1c4d5c;">🔍 Zoom In</button><button onclick="zoomImage(0.8)" class="button button-outline small" style="background:#103540;color:#c1e5eb;border-color:#1c4d5c;">🔍 Zoom Out</button><button onclick="resetImage()" class="button button-outline small" style="background:#103540;color:#c1e5eb;border-color:#1c4d5c;grid-column:1/-1;">🔄 Reset View</button></div></div>';

    echo '<div><label style="font-size:10px;color:#71959d;text-transform:uppercase;font-weight:800;letter-spacing:0.1em;display:block;margin-bottom:8px;">SERIES SLICE SELECTOR</label>';
    echo '<input type="range" id="sliceSlider" min="1" max="24" value="1" style="width:100%;accent-color:#32d7c1;" oninput="updateSlice(this.value)">';
    echo '<div style="display:flex;justify-content:space-between;font-size:11px;color:#85a6ad;margin-top:4px;"><span>Slice: <strong id="sliceNumText" style="color:#32d7c1;">1</strong> / 24</span><span id="sliceThickness">5.0 mm</span></div></div>';
    echo '</div>';

    // Center DICOM Viewport
    echo '<div style="background:#020b0e;display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;padding:20px;user-select:none;">';
    echo '<div style="position:absolute;top:15px;left:15px;font-family:monospace;font-size:11px;color:#32d7c1;line-height:1.5;"><div id="viewportPatName">PATIENT: --</div><div>INSTITUTION: DHAKA DIAGNOSTIC MAIN</div><div>SERIES: 1.0 (AXIAL)</div></div>';
    echo '<div style="position:absolute;top:15px;right:15px;font-family:monospace;font-size:11px;color:#32d7c1;line-height:1.5;text-align:right;"><div id="viewportWl">WW: 350 WL: 40</div><div>KV: 120 mA: 250</div><div>ZOOM: <span id="zoomLevelText">100%</span></div></div>';
    
    echo '<div id="dicomCanvasWrapper" style="width:420px;height:420px;border:2px dashed #1a4f5c;border-radius:12px;display:flex;align-items:center;justify-content:center;background:#061920;overflow:hidden;transition:transform 0.15s ease;">';
    echo '<div id="dicomVisualGraphic" style="text-align:center;color:#32d7c1;"><div style="font-size:80px;filter:drop-shadow(0 0 15px #32d7c1);">🩻</div><div id="dicomGraphicText" style="font-size:14px;font-weight:700;margin-top:10px;color:#ffffff;">DICOM 3.0 High-Resolution Scan Slice #1</div><div style="font-size:10px;color:#78a6af;margin-top:4px;">DICOM Transfer Syntax: Explicit VR Little Endian</div></div>';
    echo '</div>';

    echo '<div style="position:absolute;bottom:15px;left:15px;font-family:monospace;font-size:11px;color:#32d7c1;">STATUS: DICOM RENDER OK</div>';
    echo '</div>';

    // Right Radiologist Finding Panel
    echo '<div style="background:#06181f;padding:16px;border-left:1px solid #1a4f5c;display:flex;flex-direction:column;gap:12px;">';
    echo '<h4 style="margin:0;font-size:13px;color:#32d7c1;border-bottom:1px solid #1a4f5c;padding-bottom:8px;">Radiology Findings Note</h4>';
    echo '<div style="font-size:11px;color:#b0d4db;line-height:1.6;"><strong style="color:#ffffff;">Clinical Impression:</strong><p style="margin:4px 0 10px;">Scans demonstrate no acute intracranial hemorrhage or mass effect. Mild age-related involutional changes noted.</p><strong style="color:#ffffff;">Radiologist Recommendation:</strong><p style="margin:4px 0;">Routine clinical follow-up as indicated.</p></div>';
    echo '<div style="margin-top:auto;"><button onclick="alert(\'DICOM Study Report Authorized & Exported to Patient EHR.\');" class="button button-primary full" style="background:#10b981;border:0;">✔ Attach Findings to EHR</button></div>';
    echo '</div>';

    echo '</div>'; // End Modal Workspace Body
    echo '</div></div>'; // End Modal Container

    // DICOM Viewer JS Script
    echo '<script>
    var currentZoom = 1.0;
    function openDicomViewer(uid, name, modality, accession) {
        document.getElementById("dicomModal").style.display = "flex";
        document.getElementById("modalPatientTitle").innerText = name + " (Acc: " + accession + ")";
        document.getElementById("modalStudySub").innerText = "DICOM Study UID: " + uid;
        document.getElementById("modalModalityBadge").innerText = modality.toUpperCase();
        document.getElementById("viewportPatName").innerText = "PATIENT: " + name.toUpperCase();
        currentZoom = 1.0;
        document.getElementById("dicomCanvasWrapper").style.transform = "scale(1)";
        document.getElementById("zoomLevelText").innerText = "100%";
    }
    function closeDicomViewer() {
        document.getElementById("dicomModal").style.display = "none";
    }
    function updateSlice(val) {
        document.getElementById("sliceNumText").innerText = val;
        document.getElementById("dicomGraphicText").innerText = "DICOM 3.0 High-Resolution Scan Slice #" + val;
    }
    function setWindowLevel(preset) {
        var wl = document.getElementById("viewportWl");
        var visual = document.getElementById("dicomVisualGraphic");
        if(preset === "bone") {
            wl.innerText = "WW: 2000 WL: 500";
            visual.style.filter = "brightness(1.3) contrast(1.4)";
        } else if(preset === "lung") {
            wl.innerText = "WW: 1500 WL: -600";
            visual.style.filter = "brightness(0.9) contrast(1.6)";
        } else {
            wl.innerText = "WW: 350 WL: 40";
            visual.style.filter = "none";
        }
    }
    function zoomImage(factor) {
        currentZoom = Math.max(0.5, Math.min(2.5, currentZoom * factor));
        document.getElementById("dicomCanvasWrapper").style.transform = "scale(" + currentZoom + ")";
        document.getElementById("zoomLevelText").innerText = Math.round(currentZoom * 100) + "%";
    }
    function resetImage() {
        currentZoom = 1.0;
        document.getElementById("dicomCanvasWrapper").style.transform = "scale(1)";
        document.getElementById("dicomCanvasWrapper").style.transform = "scale(1)";
        document.getElementById("zoomLevelText").innerText = "100%";
        setWindowLevel("soft");
    }
    </script>';

    page_end();
}

function render_analyzer_mapping(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $connectors = \Diagnostic\Analyzer::listConnectors($db);

    page_start($db, $user, 'analyzer_mapping', 'Analyzer Interface Connector & Test Mapping', 'ASTM/HL7 instrument connector setup, test code translation and unmatched result queue.');

    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">CONNECTED INSTRUMENTS</span><h3>Configured Analyzers</h3></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Code</th><th>Analyzer Name</th><th>Protocol</th><th>Status</th></tr></thead><tbody>';
    if (!$connectors) echo '<tr><td colspan="4"><div class="empty-state">No laboratory analyzers configured.</div></td></tr>';
    foreach ($connectors as $c) {
        echo '<tr><td><span class="code-chip">' . e($c['code']) . '</span></td><td><strong>' . e($c['name']) . '</strong></td><td>' . e(strtoupper($c['protocol'])) . '</td><td><span class="status on">Active</span></td></tr>';
    }
    echo '</tbody></table></div></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">NEW CONNECTOR</span><h3>Add Analyzer Connector</h3></div></div>';
    echo '<form method="post" action="/index.php?page=analyzer_mapping" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="connector">';
    echo '<label class="field">Connector Code *<input name="code" placeholder="e.g. SYSMEX-XN" required></label>';
    echo '<label class="field">Analyzer Name *<input name="name" placeholder="e.g. Sysmex XN-550 Hematology" required></label>';
    echo '<label class="field">Communication Protocol<select name="protocol"><option value="astm">ASTM E1394</option><option value="hl7">HL7 v2.x</option><option value="file">File Import (CSV/Text)</option></select></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Save Analyzer Connector</button></div></form></section></div>';
    page_end();
}

function render_report_center(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $orderId = (int) ($_GET['order_id'] ?? 1);
    $data = null;
    $deliveries = [];
    try {
        $data = \Diagnostic\ReportCenter::getCombinedReports($db, $orderId);
        $deliveries = \Diagnostic\ReportCenter::getDeliveryLog($db, $orderId);
    } catch (\Throwable $e) {
        $data = null;
    }

    page_start($db, $user, 'report_center', 'Unified Report Delivery Center', 'Combine Lab and Radiology reports with print, email, download and QR validation control.');

    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">PATIENT ORDER SEARCH</span><h3>Combined Report Viewer</h3></div><form method="get" action="/index.php"><input type="hidden" name="page" value="report_center"><label class="field" style="margin:0;">Order ID: <input type="number" name="order_id" value="' . e((string)$orderId) . '" style="width:100px;"> <button class="button button-outline small">Find</button></label></form></div>';

    if ($data) {
        $o = $data['order'];
        echo '<div style="background:var(--surface-muted,#f8fafc);padding:14px;border-radius:6px;margin-bottom:16px;">';
        echo '<div><strong>Patient:</strong> ' . e($o['patient_name']) . ' (' . e($o['mrn']) . ') | <strong>Order #:</strong> ' . e($o['order_no']) . ' | <strong>Status:</strong> ' . e(strtoupper($o['status'])) . '</div>';
        echo '</div>';

        echo '<h4>Laboratory Test Reports</h4>';
        echo '<div class="table-wrap"><table><thead><tr><th>Report #</th><th>Approver</th><th>Status</th><th>Action</th></tr></thead><tbody>';
        if (empty($data['lab_reports'])) echo '<tr><td colspan="4"><div class="empty-state">No lab reports found for this order.</div></td></tr>';
        foreach ($data['lab_reports'] as $lr) {
            echo '<tr><td><span class="code-chip">' . e($lr['report_no']) . '</span></td><td>' . e($lr['approver_name'] ?? 'Pending') . '</td><td><span class="status ' . ($lr['status']==='approved'?'on':'off') . '">' . e(ucfirst($lr['status'])) . '</span></td><td>';
            echo '<form method="post" action="/index.php?page=report_center" style="display:inline-block;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="order_id" value="' . e($orderId) . '"><input type="hidden" name="report_type" value="lab"><input type="hidden" name="report_id" value="' . e($lr['id']) . '"><input type="hidden" name="action_type" value="print"><button class="button button-outline small">🖨️ Print Report</button></form> ';
            echo '<form method="post" action="/index.php?page=report_center" style="display:inline-block;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="order_id" value="' . e($orderId) . '"><input type="hidden" name="report_type" value="lab"><input type="hidden" name="report_id" value="' . e($lr['id']) . '"><input type="hidden" name="action_type" value="email"><button class="button button-outline small">✉️ Email Patient</button></form>';
            echo '</td></tr>';
        }
        echo '</tbody></table></div>';

        echo '<h4 style="margin-top:20px;">Radiology Imaging Reports</h4>';
        echo '<div class="table-wrap"><table><thead><tr><th>Report #</th><th>Modality</th><th>Radiologist</th><th>Status</th><th>Action</th></tr></thead><tbody>';
        if (empty($data['radiology_reports'])) echo '<tr><td colspan="5"><div class="empty-state">No radiology reports found for this order.</div></td></tr>';
        foreach ($data['radiology_reports'] as $rr) {
            echo '<tr><td><span class="code-chip">' . e($rr['report_no']) . '</span></td><td>' . e(strtoupper($rr['modality'])) . '</td><td>' . e($rr['radiologist_name']) . '</td><td><span class="status ' . ($rr['status']==='authorized'?'on':'off') . '">' . e(ucfirst($rr['status'])) . '</span></td><td>';
            echo '<form method="post" action="/index.php?page=report_center" style="display:inline-block;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="order_id" value="' . e($orderId) . '"><input type="hidden" name="report_type" value="radiology"><input type="hidden" name="report_id" value="' . e($rr['id']) . '"><input type="hidden" name="action_type" value="download"><button class="button button-outline small">📥 Download PDF</button></form>';
            echo '</td></tr>';
        }
        echo '</tbody></table></div>';
    } else {
        echo '<div class="empty-state">Select a valid Order ID to view combined reports.</div>';
    }
    echo '</section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">AUDIT & TRACEABILITY</span><h3>Report Delivery History</h3></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Type</th><th>Action</th><th>Delivered By</th><th>Date/Time</th><th>QR Hash</th></tr></thead><tbody>';
    if (!$deliveries) echo '<tr><td colspan="5"><div class="empty-state">No delivery actions logged.</div></td></tr>';
    foreach ($deliveries as $d) {
        $delTime = $d['delivered_at'] ?? $d['created_at'] ?? date('Y-m-d H:i:s');
        echo '<tr><td><span class="code-chip">' . e(strtoupper($d['report_type'])) . '</span></td><td>' . e(ucfirst($d['action_type'])) . '</td><td>' . e($d['actor_name']) . '</td><td>' . e($delTime) . '</td><td><span class="code-chip" style="font-size:10px;">' . e(substr($d['qr_verification_hash'], 0, 12)) . '...</span></td></tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_notifications(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $logs = \Diagnostic\Notifications::listLogs($db, 50);

    page_start($db, $user, 'notifications', 'SMS & Email Notification Engine', 'Bangla/English transactional notification delivery queue, templates and status tracking.');

    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">DISPATCH MESSAGE</span><h3>Send Transactional Notification</h3></div></div>';
    echo '<form method="post" action="/index.php?page=notifications" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<label class="field">Patient ID *<input type="number" name="patient_id" value="1" required></label>';
    echo '<label class="field">Recipient Mobile/Email *<input name="recipient" value="+8801700000000" required></label>';
    echo '<label class="field">Channel<select name="channel"><option value="sms">SMS</option><option value="email">Email</option></select></label>';
    echo '<label class="field">Language<select name="language"><option value="bn">Bangla (বাংলা)</option><option value="en">English</option></select></label>';
    echo '<label class="field span-2">Notification Template<select name="template_key"><option value="appointment_confirm">Appointment Confirmation</option><option value="payment_receipt">Payment Receipt Confirmation</option><option value="report_ready">Test Report Ready Notification</option></select></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Send Notification</button></div></form></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">DELIVERY LOGS</span><h3>Recent Dispatch Log</h3></div><span class="pill">' . count($logs) . ' sent</span></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Patient</th><th>Channel</th><th>Language</th><th>Message Content</th><th>Status</th></tr></thead><tbody>';
    if (!$logs) echo '<tr><td colspan="5"><div class="empty-state">No notification logs recorded.</div></td></tr>';
    foreach ($logs as $l) {
        echo '<tr><td><strong>' . e($l['patient_name']) . '</strong></td><td><span class="code-chip">' . e(strtoupper($l['channel'])) . '</span></td><td>' . e(strtoupper($l['language'])) . '</td><td style="font-size:12px;">' . e($l['content']) . '</td><td><span class="status on">' . e(ucfirst($l['status'])) . '</span></td></tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_home_collections(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $bookings = \Diagnostic\HomeCollection::listBookings($db, $branchId);

    page_start($db, $user, 'home_collections', 'Home Sample Collection Management', 'Book home collection visits, assign phlebotomists, track travel fees and sample handover.');

    // Top KPI Cards for Home Collection
    $pendingCnt = 0; $collectedCnt = 0; $handedCnt = 0;
    foreach ($bookings as $b) {
        if ($b['status'] === 'pending') $pendingCnt++;
        elseif ($b['status'] === 'collected') $collectedCnt++;
        elseif ($b['status'] === 'handed_over') $handedCnt++;
    }

    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=home_collections" class="stat-card dash-clickable-card card-light-teal" style="text-decoration:none;">';
