    echo '  <a href="/index.php?page=home_collections" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div>';
    echo '    <span>Pending Dispatch</span><strong>' . $pendingCnt . ' Visits</strong><small style="color:#b45309;">Awaiting Phlebotomist</small>';
