    echo '  <a href="/index.php?page=home_collections" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg></div>';
    echo '    <span>Collected Samples</span><strong>' . $collectedCnt . ' En-route</strong><small style="color:#2563eb;">Cold Chain Sealed</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=sample_desk" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg></div>';
    echo '    <span>Handed Over to LIS</span><strong>' . $handedCnt . ' Processed</strong><small style="color:#16a34a;">Barcode Scanned at Lab</small>';
    echo '  </a>';
    echo '</div>';

    // Stacked Layout: Form (Top) + Table (Below)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Success Booking & Token Notification Banner
    $successBookingId = (int)($_GET['success_booking_id'] ?? 0);
    if ($successBookingId > 0) {
        $succBooking = \Diagnostic\HomeCollection::getBooking($db, $successBookingId);
        if ($succBooking) {
            echo '<div style="background:linear-gradient(135deg, #ecfdf5 0%, #f0fdf4 100%);border:2px solid #34d399;border-radius:12px;padding:20px;box-shadow:0 6px 20px rgba(16,185,129,0.12);margin-bottom:8px;">';
            echo '  <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;">';
            echo '    <div style="display:flex;align-items:center;gap:14px;">';
            echo '      <div style="width:48px;height:48px;border-radius:50%;background:#10b981;color:#ffffff;display:flex;align-items:center;justify-content:center;font-size:24px;box-shadow:0 3px 8px rgba(16,185,129,0.3);"><i class="fa-solid fa-check"></i></div>';
            echo '      <div>';
            echo '        <h4 style="margin:0;font-size:17px;color:#065f46;">Home Collection Visit Booked &amp; Confirmed!</h4>';
            echo '        <p style="margin:3px 0 0;font-size:13px;color:#047857;">Booking #: <strong style="font-family:monospace;font-size:15px;background:#d1fae5;padding:2px 8px;border-radius:6px;color:#065f46;">' . e($succBooking['booking_no']) . '</strong> | Patient: <strong>' . e($succBooking['patient_name']) . '</strong> (' . e($succBooking['mobile']) . ') | Total: <strong>৳ ' . number_format((float)($succBooking['total_payable'] ?? 0), 2) . '</strong></p>';
            echo '      </div>';
            echo '    </div>';
            echo '    <div style="display:flex;gap:10px;">';
            echo '      <a href="/index.php?page=print_voucher&type=home_collection&id=' . e((string)$succBooking['id']) . '" target="_blank" class="button" style="background:#059669;color:#ffffff;border:none;padding:10px 18px;border-radius:8px;font-weight:750;display:inline-flex;align-items:center;gap:8px;box-shadow:0 2px 8px rgba(5,150,105,0.25);"><i class="fa-solid fa-print"></i> 🖨️ Print Money Receipt &amp; Booking Voucher</a>';
            echo '      <a href="/index.php?page=download_pdf&type=home_collection&id=' . e((string)$succBooking['id']) . '" class="button button-outline" style="background:#ffffff;color:#0284c7;border:1.5px solid #0284c7;padding:10px 18px;border-radius:8px;font-weight:750;display:inline-flex;align-items:center;gap:8px;"><i class="fa-solid fa-file-pdf"></i> 📥 Download Official PDF</a>';
            echo '    </div>';
            echo '  </div>';
            echo '</div>';
        }
    }

    // Top Section: New Corporate Home Collection Booking Form
    $activeTests = $db->query('SELECT id, code, name, price FROM diagnostic_tests WHERE active=1 ORDER BY name ASC LIMIT 60')->fetchAll(PDO::FETCH_ASSOC);

    echo '<section class="card" style="background:#ffffff;border:1.5px solid #cbd5e1;border-radius:14px;box-shadow:0 4px 18px rgba(15,23,42,0.05);overflow:hidden;">';
    echo '<div class="card-head" style="background:linear-gradient(135deg, #f0fdfa 0%, #f8fafc 100%);border-bottom:1px solid #e2e8f0;padding:16px 20px;"><div><span class="eyebrow" style="color:#0c928c;font-weight:800;letter-spacing:0.08em;">DIAGNOSTIC HOME SERVICE</span><h3 style="margin:2px 0 0;font-size:17px;color:#0f172a;">New Home Specimen Collection Registration &amp; POS</h3></div></div>';
    
    echo '<form method="post" action="/index.php?page=home_collections" id="homeCollectionForm" style="padding:20px;">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="book"><input type="hidden" name="branch_id" value="' . e($branchId) . '">';

    // Step 1: Patient Details & Unique Categorization
    echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:16px 18px;margin-bottom:20px;">';
    echo '  <div style="font-size:12px;font-weight:800;color:#0c928c;letter-spacing:0.05em;text-transform:uppercase;margin-bottom:12px;">Step 1: Patient Identity &amp; Category Registration</div>';
    echo '  <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(220px, 1fr));gap:14px;">';
    echo '    <label class="field">Patient Name *<input type="text" name="patient_name" placeholder="Full name of patient" required style="font-weight:600;"></label>';
    echo '    <label class="field">Phone Number *<input type="text" name="patient_mobile" placeholder="017XXXXXXXX" required style="font-weight:600;"></label>';
    echo '    <label class="field">Patient Category *<select name="patient_category" required style="font-weight:700;color:#0c928c;">';
    echo '      <option value="doctor_prescribed">🩺 Doctor Prescribed Patient (Prescription Meds &amp; Direct Tests)</option>';
    echo '      <option value="clinical_patient">🔬 Clinical Patient (Diagnostic Tests Only)</option>';
    echo '      <option value="local_customer">🛍️ Local Customer (Walk-in OTC Medicine &amp; Counter Tests)</option>';
    echo '    </select></label>';
    echo '    <label class="field">Gender<select name="gender"><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select></label>';
    echo '    <label class="field">Geo Zone / Service Sector<select name="geo_zone"><option value="Gulshan / Banani Zone">Gulshan / Banani Zone</option><option value="Dhanmondi Zone">Dhanmondi Zone</option><option value="Uttara Zone">Uttara Zone</option><option value="Mirpur Zone">Mirpur Zone</option><option value="Mohakhali / Badda Zone">Mohakhali / Badda Zone</option><option value="Motijheel / Old Dhaka">Motijheel / Old Dhaka</option></select></label>';
    echo '    <label class="field">Preferred Visit Slot<select name="time_slot"><option value="07:00 AM - 09:00 AM">07:00 AM - 09:00 AM (Fasting Profile)</option><option value="09:00 AM - 11:00 AM">09:00 AM - 11:00 AM (Morning Slot)</option><option value="11:00 AM - 01:00 PM">11:00 AM - 01:00 PM (Midday Slot)</option><option value="04:00 PM - 06:00 PM">04:00 PM - 06:00 PM (Evening Slot)</option></select></label>';
    echo '    <label class="field" style="grid-column:1/-1;">Detailed Collection Address *<textarea name="address" rows="2" placeholder="House #, Flat #, Road #, Landmark for phlebotomist..." required style="min-height:55px;resize:vertical;">House 12, Road 5, Block B, Niketan, Gulshan, Dhaka</textarea></label>';
    echo '  </div>';
    echo '</div>';

    // Step 2: Diagnostic Tests Selection with Live Price Calculation
    echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:16px 18px;margin-bottom:20px;">';
    echo '  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;">';
    echo '    <div style="font-size:12px;font-weight:800;color:#0284c7;letter-spacing:0.05em;text-transform:uppercase;">Step 2: Select Diagnostic Tests for Specimen Collection</div>';
    echo '    <input type="text" id="hcTestFilter" placeholder="Filter tests (e.g. CBC, Sugar, Lipid)..." style="background:#ffffff;border:1px solid #cbd5e1;border-radius:6px;padding:5px 10px;font-size:12px;width:240px;">';
    echo '  </div>';
    echo '  <div id="hcTestList" style="max-height:220px;overflow-y:auto;border:1px solid #cbd5e1;border-radius:8px;background:#ffffff;padding:10px;display:grid;grid-template-columns:repeat(auto-fill, minmax(280px, 1fr));gap:8px;">';
    
    foreach ($activeTests as $t) {
        $p = (float)($t['price'] ?? 500.00);
        echo '    <label class="hc-test-label" style="display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid #f1f5f9;border-radius:6px;background:#f8fafc;cursor:pointer;transition:all 0.15s;" onmouseover="this.style.background=\'#eff6ff\'" onmouseout="this.style.background=\'#f8fafc\'">';
        echo '      <input type="checkbox" name="test_ids[]" value="' . e((string)$t['id']) . '" data-price="' . $p . '" class="hc-test-chk" style="width:16px;height:16px;cursor:pointer;">';
        echo '      <div style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">';
        echo '        <span style="font-weight:700;font-size:12.5px;color:#0f172a;">' . e($t['name']) . '</span><br>';
        echo '        <small style="color:#64748b;font-family:monospace;">' . e($t['code']) . '</small>';
        echo '      </div>';
        echo '      <strong style="color:#0284c7;font-size:13px;white-space:nowrap;">৳ ' . number_format($p, 2) . '</strong>';
        echo '    </label>';
    }

    echo '  </div>';
    echo '</div>';

    // Step 3: Billing, Travel Charge, Discounts & Settlement
    echo '<div style="background:#ffffff;border:1.5px solid #0c928c;border-radius:10px;padding:16px 18px;margin-bottom:20px;box-shadow:0 3px 12px rgba(12,146,140,0.06);">';
    echo '  <div style="font-size:12px;font-weight:800;color:#0c928c;letter-spacing:0.05em;text-transform:uppercase;margin-bottom:12px;">Step 3: Travel Fee, Discount Approval &amp; Payment Settlement</div>';
    echo '  <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(200px, 1fr));gap:14px;align-items:end;">';
    echo '    <label class="field">Tests Subtotal (BDT)<input type="number" id="hcTestsTotal" name="tests_amount" value="0.00" readonly style="background:#f1f5f9;font-weight:800;color:#0f172a;"></label>';
    echo '    <label class="field">Travel Fee (BDT)<input type="number" step="0.01" id="hcTravelCharge" name="travel_charge" value="300.00" style="font-weight:800;color:#0f172a;"></label>';
    echo '    <label class="field">Discount Amount (BDT)<input type="number" step="0.01" id="hcDiscount" name="discount_amount" value="0.00" style="font-weight:800;color:#dc2626;"></label>';
    echo '    <label class="field">Discount Approved By<input type="text" name="discount_approved_by" placeholder="e.g. Managing Director / Dr. Rahman" style="font-weight:600;"></label>';
    echo '    <label class="field">Net Total Payable (BDT)<input type="number" id="hcNetPayable" name="total_payable" value="300.00" readonly style="background:#f0fdf4;border-color:#34d399;font-weight:900;font-size:15px;color:#065f46;"></label>';
    echo '    <label class="field">Paid Amount (BDT) *<input type="number" step="0.01" id="hcPaidAmount" name="paid_amount" value="300.00" required style="font-weight:800;color:#059669;"></label>';
    echo '    <label class="field">Payment Method<select name="payment_method" style="font-weight:700;"><option value="CASH">Cash on Counter / Collection</option><option value="BKASH">bKash Merchant Pay</option><option value="NAGAD">Nagad</option><option value="CARD">Visa / Mastercard POS</option><option value="BANK">Bank Transfer</option></select></label>';
    echo '  </div>';
    echo '</div>';

    echo '<div style="display:flex;justify-content:flex-end;">';
    echo '  <button class="button button-primary" style="padding:12px 28px;font-size:14px;font-weight:800;border-radius:8px;box-shadow:0 4px 12px rgba(12,146,140,0.25);"><i class="fa-solid fa-file-invoice-dollar" style="margin-right:8px;"></i> Book Home Specimen Visit &amp; Issue Voucher</button>';
    echo '</div>';
    echo '</form>';

    // Live JS Calculation Script
    echo '<script>
    (function(){
      var chks = document.querySelectorAll(".hc-test-chk");
      var subtotalInput = document.getElementById("hcTestsTotal");
      var travelInput = document.getElementById("hcTravelCharge");
      var discountInput = document.getElementById("hcDiscount");
      var netInput = document.getElementById("hcNetPayable");
      var paidInput = document.getElementById("hcPaidAmount");
      var filterInput = document.getElementById("hcTestFilter");

      function recalc() {
        var testsSum = 0;
        chks.forEach(function(c){
          if(c.checked) testsSum += parseFloat(c.getAttribute("data-price") || 0);
        });
        subtotalInput.value = testsSum.toFixed(2);
        var travel = parseFloat(travelInput.value || 0);
        var discount = parseFloat(discountInput.value || 0);
        var net = Math.max(0, (testsSum + travel) - discount);
        netInput.value = net.toFixed(2);
        paidInput.value = net.toFixed(2);
      }

      chks.forEach(function(c){ c.addEventListener("change", recalc); });
      if(travelInput) travelInput.addEventListener("input", recalc);
      if(discountInput) discountInput.addEventListener("input", recalc);

      if(filterInput){
        filterInput.addEventListener("input", function(){
          var q = this.value.toLowerCase().trim();
          document.querySelectorAll(".hc-test-label").forEach(function(lbl){
            var txt = lbl.textContent.toLowerCase();
            lbl.style.display = (txt.indexOf(q) !== -1) ? "flex" : "none";
          });
        });
      }
    })();
    </script>';

    echo '</section>';

    // Bottom Section: Home Collection Worklist (Directly Below Booking Form)
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">COLLECTION SCHEDULE</span><h3>Home Collection Worklist (' . count($bookings) . ' Bookings)</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=home_collections&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=print_voucher&type=home_collections" target="_blank" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0f172a;border-color:#94a3b8;background:#f1f5f9;"><i class="fa-solid fa-print"></i> Print Worklist</a>';
    echo '    <a href="/index.php?page=home_collections&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar for Home Collections
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search patient, booking # or zone..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Booking #</th><th>Patient</th><th>Category</th><th>Zone & Address</th><th>Slot</th><th>Tests & Total</th><th>Status</th><th>Action</th></tr></thead><tbody>';
    if (!$bookings) echo '<tr><td colspan="8"><div class="empty-state">No home collection bookings.</div></td></tr>';
    foreach ($bookings as $b) {
        $stBadge = ($b['status'] === 'handed_over') 
            ? 'background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;'
            : (($b['status'] === 'collected') 
                ? 'background:#eff6ff;color:#2563eb;border:1px solid #bfdbfe;'
                : (($b['status'] === 'assigned') 
                    ? 'background:#fef3c7;color:#b45309;border:1px solid #fde68a;'
                    : 'background:#f1f5f9;color:#475569;border:1px solid #cbd5e1;'));

        $catLabel = ucwords(str_replace('_', ' ', $b['patient_category'] ?? 'doctor_prescribed'));
        $catStyle = ($b['patient_category'] === 'doctor_prescribed') ? 'background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;' : (($b['patient_category'] === 'clinical_patient') ? 'background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;' : 'background:#faf5ff;color:#7e22ce;border:1px solid #e9d5ff;');

        $testsCnt = !empty($b['tests_array']) ? count($b['tests_array']) : 0;
        $totalPayable = (float)($b['total_payable'] ?? ($b['travel_charge'] ?? 300));

        echo '<tr><td><span class="code-chip" style="font-weight:700;">' . e($b['booking_no']) . '</span></td>';
        echo '<td><strong>' . e($b['patient_name']) . '</strong><br><small style="color:#64748b;">' . e($b['mobile']) . '</small></td>';
        echo '<td><span class="status on" style="' . $catStyle . 'font-size:11px;">' . e($catLabel) . '</span></td>';
        echo '<td>' . e($b['geo_zone']) . '<br><small style="color:#64748b;">' . e($b['address']) . '</small></td>';
        echo '<td><strong>' . e($b['time_slot']) . '</strong></td>';
        echo '<td><strong style="color:#092c36;">৳ ' . number_format($totalPayable, 2) . '</strong><br><small style="color:#0284c7;">' . $testsCnt . ' test(s) booked</small></td>';
        echo '<td><span class="status on" style="' . $stBadge . '">' . e(ucwords(str_replace('_', ' ', $b['status']))) . '</span></td>';
        echo '<td><div class="table-actions-cell" style="display:flex;gap:6px;align-items:center;">';
        
        echo '<a class="btn-action-print" target="_blank" href="/index.php?page=print_voucher&type=home_collection&id=' . e((string)$b['id']) . '" title="Print Official Voucher"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg> Print</a>';
        echo '<a class="btn-action-pdf" href="/index.php?page=download_pdf&type=home_collection&id=' . e((string)$b['id']) . '" title="Download Voucher PDF"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg> PDF</a>';

        if ($b['status'] === 'pending') {
            echo '<form method="post" action="/index.php?page=home_collections" style="display:inline;margin:0;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="assign"><input type="hidden" name="booking_id" value="' . e($b['id']) . '"><input type="hidden" name="collector_id" value="' . e($user['id']) . '"><button class="button button-outline small">Assign</button></form>';
        } elseif ($b['status'] === 'assigned') {
            echo '<form method="post" action="/index.php?page=home_collections" style="display:inline;margin:0;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="status"><input type="hidden" name="booking_id" value="' . e($b['id']) . '"><input type="hidden" name="status" value="collected"><button class="button button-outline small">Collect</button></form>';
        } elseif ($b['status'] === 'collected') {
            echo '<form method="post" action="/index.php?page=home_collections" style="display:inline;margin:0;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="status"><input type="hidden" name="booking_id" value="' . e($b['id']) . '"><input type="hidden" name="status" value="handed_over"><button class="button button-outline small">Lab</button></form>';
        }
        
        echo '</div></td></tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_patient_portal_demo(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');

    page_start($db, $user, 'patient_portal', 'Patient Portal & Self-Service Experience', 'OTP authentication demo, mobile APIs and online patient report access.');

    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">PORTAL SIMULATION</span><h3>Patient Mobile OTP Login</h3></div></div>';
    echo '<form method="post" action="/index.php?page=patient_portal" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="request_otp">';
    echo '<label class="field span-2">Patient Mobile Number *<input name="mobile" value="+8801700000000" placeholder="+8801700000000" required></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Request Login OTP Code</button></div></form>';
    echo '<hr style="margin:20px 0;border:none;border-top:1px solid var(--border,#e2e8f0);">';
    echo '<form method="post" action="/index.php?page=patient_portal" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="verify_otp">';
    echo '<label class="field">Patient Mobile Number *<input name="mobile" value="+8801700000000" required></label>';
    echo '<label class="field">Enter 6-Digit OTP *<input name="otp_code" placeholder="123456" required></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Verify OTP & Authenticate</button></div></form></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">REST API ENDPOINTS</span><h3>Mobile App & Web Portal APIs</h3></div></div>';
    echo '<div style="display:flex;flex-direction:column;gap:12px;">';
    echo '<div style="background:var(--surface-muted,#f8fafc);padding:12px;border-radius:6px;"><strong>POST /api/v1/patient/login-otp</strong><br><small>Request SMS OTP for patient phone authentication.</small></div>';
