        echo '<td><span class="pill" style="font-weight:700;color:#0d9488;">' . e($ct['discount_percent']) . '% OFF</span></td>';
        echo '<td>' . $preAuth . '</td>';
        echo '<td>' . e(date('d-M-Y', strtotime($ct['agreement_start']))) . ' to ' . e(date('d-M-Y', strtotime($ct['agreement_end']))) . '</td>';
        echo '<td><span class="status on" style="background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;">ACTIVE</span></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

