    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Code</th><th>Referrer Doctor / Organization</th><th>Classification</th><th>Referred Orders</th><th>Total Billed Inflow</th><th>Performance Tier</th></tr></thead><tbody>';
    if (!$performance) echo '<tr><td colspan="6"><div class="empty-state">No referral performance metrics recorded.</div></td></tr>';
    $rank = 0;
    foreach ($performance as $p) {
        $rank++;
        $rev = (float)$p['total_revenue'];
        $tierBadge = match(true) {
            $rev >= 8000 => '<span class="status on" style="background:#fef3c7;color:#b45309;border:1px solid #fde68a;">★ PLATINUM</span>',
            $rev >= 4000 => '<span class="status on" style="background:#e0f2fe;color:#0369a1;border:1px solid #bae6fd;">GOLD</span>',
            default => '<span class="status off" style="background:#f1f5f9;color:#475569;">SILVER</span>'
        };

        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($p['code']) . '</span></td>';
        echo '<td><strong>' . e($p['name']) . '</strong></td>';
        echo '<td><span class="pill" style="font-size:11px;">' . e(ucfirst($p['type'])) . '</span></td>';
        echo '<td><strong style="color:#092c36;">' . (int)$p['total_orders'] . ' Orders</strong></td>';
        echo '<td><strong style="color:#16a34a;font-size:13px;">৳ ' . number_format($rev, 2) . '</strong></td>';
        echo '<td>' . $tierBadge . '</td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_commission_settlement(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $referrers = Masters::scoped($db, 'referrers', 200);
    $rules = \Diagnostic\Commission::listRules($db);
    $accruals = \Diagnostic\Commission::listAccruals($db);
    $batches = \Diagnostic\Commission::listBatches($db);

    page_start($db, $user, 'commission_settlement', 'Doctor Commission Engine & Settlement', 'Commission eligibility rules, provisional accruals, TDS withholding calculation and settlement payout batches.');

    // Top KPI Cards for Commission Settlement
    $totalSettledGross = 0.0;
    $totalSettledNet = 0.0;
    foreach ($batches as $b) {
        $totalSettledGross += (float)$b['gross_commission'];
        $totalSettledNet += (float)$b['net_payable'];
    }

    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=commission_settlement" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
