    echo '    <span>Commission Rules</span><strong>' . count($rules) . ' Active Policies</strong><small style="color:#2563eb;">15% Global Standard</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=commission_settlement" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg></div>';
    echo '    <span>Gross Approved</span><strong>৳ ' . number_format($totalSettledGross, 2) . '</strong><small style="color:#16a34a;">' . count($batches) . ' Batches Processed</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=doctor_commissions" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div>';
    echo '    <span>Net Payout Pool</span><strong>৳ ' . number_format($totalSettledNet, 2) . '</strong><small style="color:#b45309;">10% NBR TDS Deducted</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=referrer_desk" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle></svg></div>';
    echo '    <span>Consultant Referrers</span><strong>' . count($referrers) . ' Partners</strong><small style="color:#9333ea;">View Referrer Desk</small>';
    echo '  </a>';
    echo '</div>';

    // Stacked Layout: Set Commission Rate (Top) + Generate Settlement Batch (Below)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Top Section: Set Commission Rate Form
    echo '<section class="card">';
    echo '<div class="card-head"><div><span class="eyebrow">RULE CONFIGURATION</span><h3>Set Commission Rate</h3></div></div>';
    echo '<form method="post" action="/index.php?page=commission_settlement" class="field-grid" style="grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;">';
    echo '  <input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="rule">';
    echo '  <label class="field">Referrer Doctor<select name="referrer_id"><option value="">Global Default Rate</option>';
    foreach ($referrers as $r) echo '<option value="' . e($r['id']) . '">' . e($r['name']) . ' (' . e($r['code']) . ')</option>';
    echo '  </select></label>';
    echo '  <label class="field">Rate Type<select name="rate_type"><option value="percent_gross">Percentage of Billed Amount</option><option value="percent_realized">Percentage of Realized Cash</option><option value="fixed">Fixed BDT Amount per Test</option></select></label>';
    echo '  <label class="field">Rate Value (% or BDT)<input type="number" step="0.01" name="rate_value" value="15.00" required></label>';
    echo '  <label class="field">Effective From<input type="date" name="effective_from" value="' . date('Y-m-d') . '"></label>';
    echo '  <div class="form-actions span-2" style="grid-column:1/-1;"><button class="button button-primary" style="width:100%;font-weight:700;padding:12px;"><i class="fa-solid fa-floppy-disk" style="margin-right:6px;"></i> Save Commission Rule</button></div>';
    echo '</form></section>';

    // Second Section: Generate Settlement Batch (Directly Below Set Commission Rate)
    echo '<section class="card">';
    echo '<div class="card-head"><div><span class="eyebrow">SETTLEMENT BATCH</span><h3>Generate Settlement Batch</h3></div></div>';
    echo '<form method="post" action="/index.php?page=commission_settlement" class="field-grid" style="grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;">';
    echo '  <input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="batch">';
    echo '  <label class="field">Referrer Doctor *<select name="referrer_id" required>';
    foreach ($referrers as $r) echo '<option value="' . e($r['id']) . '">' . e($r['name']) . ' (' . e($r['code']) . ')</option>';
    echo '  </select></label>';
    echo '  <label class="field">Gross Commission (BDT) *<input type="number" step="0.01" name="gross_commission" value="25000.00" required></label>';
    echo '  <label class="field">TDS / Tax Deduction (%)<input type="number" step="0.01" name="tds_percent" value="10.00"></label>';
    echo '  <label class="field">Period Range<input type="text" name="period_notes" value="' . date('Y-01-01') . ' to ' . date('Y-12-31') . '"><input type="hidden" name="period_start" value="' . date('Y-01-01') . '"><input type="hidden" name="period_end" value="' . date('Y-12-31') . '"></label>';
    echo '  <div class="form-actions span-2" style="grid-column:1/-1;"><button class="button button-primary" style="width:100%;font-weight:700;padding:12px;"><i class="fa-solid fa-check-double" style="margin-right:6px;"></i> Approve Settlement &amp; Post TDS</button></div>';
    echo '</form></section></div>';

    echo '<section class="card" style="margin-top:20px;">';
