    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Batch #</th><th>Referrer Doctor</th><th>Period</th><th>Gross Amount</th><th>TDS Tax (10%)</th><th>Net Payable</th><th>Status</th></tr></thead><tbody>';
    if (!$batches) echo '<tr><td colspan="7"><div class="empty-state">No settlement batches generated.</div></td></tr>';
    foreach ($batches as $b) {
        echo '<tr><td><span class="code-chip">' . e($b['batch_no']) . '</span></td><td><strong>' . e($b['referrer_name']) . '</strong></td><td>' . e($b['period_start']) . ' to ' . e($b['period_end']) . '</td><td>BDT ' . number_format((float)$b['gross_commission'], 2) . '</td><td>BDT ' . number_format((float)$b['tds_deduction'], 2) . '</td><td><strong>BDT ' . number_format((float)$b['net_payable'], 2) . '</strong></td><td><span class="status on">' . e(strtoupper($b['status'])) . '</span></td></tr>';
    }
    echo '</tbody></table></div></section>';
    page_end();
}

