function render_inventory_stock(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $items = \Diagnostic\Inventory::listItems($db);
    $batches = \Diagnostic\Inventory::getFEFOStockList($db, $branchId);

    page_start($db, $user, 'inventory_stock', 'Reagent & Consumable Inventory (FEFO)', 'Track lab reagent stock batches, FEFO expiry recommendations, storage conditions and reorder alerts.');

    // Top KPI Cards (Light gradient, professional SVG icons, clickable)
    $totalQty = 0.0;
    $expiringSoon = 0;
    foreach ($batches as $b) {
        $totalQty += (float)$b['quantity_on_hand'];
        if (strtotime($b['expiry_date']) < strtotime('+60 days')) $expiringSoon++;
    }

    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=inventory_stock" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg></div>';
    echo '    <span>Active Batches (FEFO)</span><strong>' . count($batches) . ' Registered Lots</strong><small style="color:#16a34a;">' . number_format($totalQty, 0) . ' Total Units in Stock</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=inventory_stock" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div>';
    echo '    <span>Critical FEFO Queue</span><strong>' . $expiringSoon . ' Lots &lt; 60 Days</strong><small style="color:#b45309;">Prioritize First Expiry Use</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=procurement" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg></div>';
    echo '    <span>Reagent Master SKUs</span><strong>' . count($items) . ' Clinical Items</strong><small style="color:#2563eb;">Hematology, Biochemistry & QC</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=stock_transfers" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><polyline points="16 3 21 3 21 8"></polyline><line x1="4" y1="20" x2="21" y2="3"></line><polyline points="21 16 21 21 16 21"></polyline><line x1="15" y1="15" x2="21" y2="21"></line><line x1="4" y1="4" x2="9" y2="9"></line></svg></div>';
    echo '    <span>Storage Conditions</span><strong>100% Monitored</strong><small style="color:#9333ea;">Cold Chain & Ambient Verified</small>';
    echo '  </a>';
    echo '</div>';

    // Stacked Layout: Form (Top) + Table (Below)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Form Section
    echo '<section class="card">';
    echo '<div class="card-head"><div><span class="eyebrow">NEW ITEM / BATCH RECEIPT</span><h3>Add Reagent Batch (FEFO)</h3></div></div>';
    echo '<form method="post" action="/index.php?page=inventory_stock" class="field-grid" style="grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;">';
    echo '  <input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="batch"><input type="hidden" name="branch_id" value="' . e($branchId) . '">';
    echo '  <label class="field">Select Item *<select name="item_id" required>';
    foreach ($items as $it) echo '<option value="' . e($it['id']) . '">' . e($it['name']) . ' (' . e($it['code']) . ')</option>';
    echo '  </select></label>';
    echo '  <label class="field">Batch / Lot Number *<input name="batch_no" placeholder="e.g. BATCH-2026-XN" required></label>';
    echo '  <label class="field">Expiry Date (FEFO) *<input type="date" name="expiry_date" value="' . date('Y-12-31') . '" required></label>';
    echo '  <label class="field">Quantity Received *<input type="number" step="0.01" name="quantity_on_hand" value="50.00" required></label>';
    echo '  <label class="field">Unit Cost (BDT)<input type="number" step="0.01" name="unit_cost" value="1200.00"></label>';
    echo '  <div class="form-actions span-2" style="grid-column:1/-1;"><button class="button button-primary" style="width:100%;font-weight:700;padding:12px;"><i class="fa-solid fa-box-archive" style="margin-right:6px;"></i> Receive Batch Stock</button></div>';
    echo '</form></section>';

    // Table Section
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">FEFO STOCK WATCH</span><h3>Expiring Stock Queue (' . count($batches) . ' Batches)</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=inventory_stock&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=print_voucher&type=inventory_stock" target="_blank" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0f172a;border-color:#94a3b8;background:#f1f5f9;"><i class="fa-solid fa-print"></i> Print Stock List</a>';
    echo '    <a href="/index.php?page=inventory_stock&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search item name, batch # or code..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Code</th><th>Reagent Item &amp; Storage</th><th>Batch # / Lot</th><th>Expiry Date (FEFO)</th><th>Stock On Hand</th><th>Unit Cost</th><th>FEFO Status</th></tr></thead><tbody>';
    if (!$batches) echo '<tr><td colspan="7"><div class="empty-state">No inventory stock batches registered.</div></td></tr>';
    foreach ($batches as $b) {
        $expDate = strtotime($b['expiry_date']);
        $daysLeft = ceil(($expDate - time()) / 86400);
        $badgeClass = ($daysLeft < 60) ? 'background:#fee2e2;color:#b91c1c;border:1px solid #fecaca;' : 'background:#dcfce7;color:#15803d;border:1px solid #bbf7d0;';
        $badgeText = ($daysLeft < 60) ? 'EXPIRING (' . $daysLeft . 'd)' : 'VALID (' . $daysLeft . 'd)';

        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($b['code']) . '</span></td>';
        echo '<td><strong>' . e($b['item_name']) . '</strong><br><small style="color:#64748b;">' . e($b['storage_condition'] ?? 'Cold Chain') . '</small></td>';
        echo '<td><span class="code-chip">' . e($b['batch_no']) . '</span><br><small style="color:#64748b;">Lot: ' . e($b['lot_no'] ?? 'N/A') . '</small></td>';
        echo '<td><strong>' . e(date('d-M-Y', $expDate)) . '</strong></td>';
        echo '<td><strong style="color:#092c36;font-size:13px;">' . e($b['quantity_on_hand']) . ' ' . e($b['unit_name']) . '</strong></td>';
        echo '<td>৳ ' . number_format((float)($b['unit_cost'] ?? 0), 2) . '</td>';
        echo '<td><span class="status on" style="' . $badgeClass . '">' . $badgeText . '</span></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_procurement(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $suppliers = Masters::scoped($db, 'suppliers', 200);
    $reqs = \Diagnostic\Procurement::listRequisitions($db);
    $pos = \Diagnostic\Procurement::listPOs($db);
    $stats = \Diagnostic\Procurement::getProcurementStats($db);

    page_start($db, $user, 'procurement', 'Vendor & Supplier Procurement Lifecycle', 'Manage clinical supplier purchase orders, goods receipt notes (GRN), statutory NBR withholding and invoice reconciliation.');

    // Top KPI Cards (Light gradient, professional SVG icons, clickable redirection)
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=procurement" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
