    echo '  <label class="field">Expected Delivery Date<input type="date" name="delivery_date" value="' . date('Y-m-d', strtotime('+7 days')) . '"></label>';
    echo '  <label class="field span-2" style="grid-column:1/-1;">Requisition Notes / Item Description<input name="notes" placeholder="e.g. Roche Cobas C311 Reagents, Pipette Tips, Calibrator Pack..." value="Monthly reagent consumables procurement for central pathology"></label>';
    echo '  <div class="form-actions span-2" style="grid-column:1/-1;"><button class="button button-primary" style="width:100%;font-weight:700;padding:12px;"><i class="fa-solid fa-file-invoice" style="margin-right:6px;"></i> Issue Purchase Order (PO)</button></div>';
    echo '</form></section>';

    // Bottom Section: Issued Purchase Orders Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">PURCHASE REGISTER</span><h3>Issued Purchase Orders (' . count($pos) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=procurement&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=accounts_payable" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-receipt"></i> View AP Ledger</a>';
    echo '    <a href="/index.php?page=procurement&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar for Procurement Orders
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search PO #, supplier or notes..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>PO Number</th><th>Supplier &amp; Category</th><th>Total Amount</th><th>NBR TDS / VDS</th><th>GRN / Invoice</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
    if (!$pos) echo '<tr><td colspan="7"><div class="empty-state">No purchase orders issued yet.</div></td></tr>';
    foreach ($pos as $p) {
        $st = strtolower($p['status']);
        $statusBadge = ($st === 'received') 
            ? '<span class="status on" style="background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;">GRN RECEIVED</span>' 
            : '<span class="status alert" style="background:#fffbeb;color:#b45309;border:1px solid #fde68a;">ISSUED (TRANSIT)</span>';
        
        $pStatus = strtolower($p['payment_status'] ?? 'unpaid');
        $payBadge = match($pStatus) {
            'paid' => '<span class="pill" style="font-size:10px;background:#dcfce7;color:#15803d;">PAID</span>',
            'partial' => '<span class="pill" style="font-size:10px;background:#fef3c7;color:#b45309;">PARTIAL</span>',
            default => '<span class="pill" style="font-size:10px;background:#fee2e2;color:#b91c1c;">UNPAID</span>'
        };

        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($p['po_no']) . '</span><br><small style="color:#64748b;">' . e(date('d-M-Y', strtotime($p['created_at']))) . '</small></td>';
        echo '<td><strong>' . e($p['supplier_name']) . '</strong><br><small style="color:#64748b;">' . e($p['supplier_category'] ?? 'Medical Consumables') . '</small></td>';
        echo '<td><strong style="color:#092c36;">৳ ' . number_format((float)$p['total_amount'], 2) . '</strong><br>' . $payBadge . '</td>';
        echo '<td><small style="color:#2563eb;font-weight:600;">TDS (5%): ৳ ' . number_format((float)$p['tds_amount'], 2) . '</small><br><small style="color:#7c3aed;font-weight:600;">VDS (7.5%): ৳ ' . number_format((float)$p['vds_amount'], 2) . '</small></td>';
        echo '<td>';
        if (!empty($p['grn_no'])) {
            echo '<strong style="color:#15803d;">' . e($p['grn_no']) . '</strong><br><small style="color:#64748b;">Inv: ' . e($p['supplier_invoice_no'] ?? 'N/A') . '</small>';
        } else {
            echo '<span style="color:#94a3b8;font-size:12px;">Pending Delivery</span>';
        }
        echo '</td>';
        echo '<td>' . $statusBadge . '</td>';
        echo '<td><div class="table-actions-cell">';
        if ($st !== 'received') {
            echo '<form method="post" action="/index.php?page=procurement" style="margin:0;display:inline;">';
            echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
            echo '<input type="hidden" name="action" value="grn">';
            echo '<input type="hidden" name="po_id" value="' . e((string)$p['id']) . '">';
            echo '<button type="submit" class="button button-outline small" style="background:#f0fdf4;color:#15803d;border-color:#bbf7d0;font-weight:700;padding:4px 8px;" title="Receive Shipment & Generate GRN"><i class="fa-solid fa-box-open"></i> Receive GRN</button>';
            echo '</form>';
        } else {
            echo '<span style="color:#15803d;font-weight:700;font-size:12px;"><i class="fa-solid fa-circle-check"></i> Stocked</span>';
        }
        echo '</div></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

