    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Asset Code</th><th>Analyzer / Equipment Title</th><th>Model &amp; Serial #</th><th>Warranty Expiry</th><th>Status</th></tr></thead><tbody>';
