            ? '<span class="status on" style="background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;">OPERATIONAL</span>'
            : '<span class="status alert" style="background:#fffbeb;color:#b45309;border:1px solid #fde68a;">UNDER SERVICE</span>';

