        echo '<td>' . $stBadge . '</td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_stock_transfers(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $branches = Masters::scoped($db, 'branches', 100);
    $items = \Diagnostic\Inventory::listItems($db);
    $transfers = \Diagnostic\Inventory::listTransfers($db);

    page_start($db, $user, 'stock_transfers', 'Inter-branch & Department Stock Transfers', 'Central store transfer requests, in-transit tracking, and branch stock visibility.');

    $inTransit = 0; $received = 0;
    foreach ($transfers as $t) {
        if ($t['status'] === 'in_transit' || $t['status'] === 'pending') $inTransit++;
        if ($t['status'] === 'received') $received++;
    }

    // Top KPI Cards (Light gradient, professional SVG icons, clickable)
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=stock_transfers" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><path d="m16 3 4 4-4 4"></path><path d="M20 7H4"></path><path d="m8 21-4-4 4-4"></path><path d="M4 17h16"></path></svg></div>';
    echo '    <span>Total Transfers</span><strong>' . count($transfers) . ' Consignments</strong><small style="color:#2563eb;">All Inter-branch Movements</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=stock_transfers" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div>';
    echo '    <span>In-Transit Deliveries</span><strong>' . $inTransit . ' Dispatched</strong><small style="color:#b45309;">En route to satellite branches</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=stock_transfers" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="m9 12 2 2 4-4"></path></svg></div>';
    echo '    <span>Delivered &amp; Verified</span><strong>' . $received . ' Received</strong><small style="color:#16a34a;">Branch Stock Updated</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=inventory_stock" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"></rect><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path></svg></div>';
    echo '    <span>Connected Branches</span><strong>' . count($branches) . ' Active Hubs</strong><small style="color:#9333ea;">Dhaka, Uttara & Dhanmondi</small>';
    echo '  </a>';
    echo '</div>';

    // Stacked Layout: Form (Top) + Table (Below)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Form Section
    echo '<section class="card">';
    echo '<div class="card-head"><div><span class="eyebrow">CENTRAL DISPATCH DESK</span><h3>New Inter-branch Transfer</h3></div></div>';
    echo '<form method="post" action="/index.php?page=stock_transfers" class="field-grid" style="grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;">';
    echo '  <input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="from_branch_id" value="' . e($branchId) . '">';
    echo '  <label class="field">Destination Branch Hub *<select name="to_branch_id" required>';
    foreach ($branches as $b) echo '<option value="' . e($b['id']) . '">' . e($b['name']) . ' (' . e($b['code']) . ')</option>';
    echo '  </select></label>';
    echo '  <label class="field">Reagent / Consumable SKU *<select name="item_id" required>';
    foreach ($items as $it) echo '<option value="' . e($it['id']) . '">' . e($it['name']) . ' (' . e($it['code']) . ')</option>';
    echo '  </select></label>';
    echo '  <label class="field">Transfer Quantity *<input type="number" step="0.01" name="quantity" value="10.00" required></label>';
    echo '  <div class="form-actions span-2" style="grid-column:1/-1;"><button class="button button-primary" style="width:100%;font-weight:700;padding:12px;"><i class="fa-solid fa-truck-fast" style="margin-right:6px;"></i> Issue Transfer Request</button></div>';
    echo '</form></section>';

    // Table Section
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">TRANSIT REGISTRY</span><h3>Recent Stock Transfers (' . count($transfers) . ' Consignments)</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=stock_transfers&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=print_voucher&type=stock_transfers" target="_blank" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0f172a;border-color:#94a3b8;background:#f1f5f9;"><i class="fa-solid fa-print"></i> Print Transfer Challan</a>';
    echo '    <a href="/index.php?page=stock_transfers&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search transfer #, item or branch..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Transfer #</th><th>Reagent / Consumable Item</th><th>From Branch → Destination</th><th>Transfer Qty</th><th>Consignment Status</th></tr></thead><tbody>';
    if (!$transfers) echo '<tr><td colspan="5"><div class="empty-state">No stock transfers recorded.</div></td></tr>';
    foreach ($transfers as $tr) {
        $st = strtolower($tr['status']);
        $badgeClass = match($st) {
            'received' => 'background:#dcfce7;color:#15803d;border:1px solid #bbf7d0;',
            'in_transit' => 'background:#fffbeb;color:#b45309;border:1px solid #fde68a;',
            default => 'background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;'
        };

        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($tr['transfer_no']) . '</span></td>';
        echo '<td><strong>' . e($tr['item_name']) . '</strong></td>';
        echo '<td><span class="code-chip">' . e($tr['from_branch']) . '</span> <span style="color:#0d9488;font-weight:800;">→</span> <span class="code-chip" style="background:#f0fdf4;color:#15803d;">' . e($tr['to_branch']) . '</span></td>';
        echo '<td><strong style="color:#092c36;font-size:13px;">' . e($tr['quantity']) . ' Units</strong></td>';
        echo '<td><span class="status on" style="' . $badgeClass . '">' . strtoupper(e($tr['status'])) . '</span></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_chart_of_accounts(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $accounts = \Diagnostic\Accounting::listAccounts($db);

    $catCounts = ['asset' => 0, 'liability' => 0, 'equity' => 0, 'revenue' => 0, 'expense' => 0];
    $catBalances = ['asset' => 0.0, 'liability' => 0.0, 'equity' => 0.0, 'revenue' => 0.0, 'expense' => 0.0];

    foreach ($accounts as $a) {
        $t = strtolower($a['account_type']);
        if (isset($catCounts[$t])) {
            $catCounts[$t]++;
            $bal = (float)($a['current_balance'] ?? $a['balance'] ?? 0.0);
            $catBalances[$t] += $bal;
        }
    }

    $filterCat = strtolower(trim((string)($_GET['category'] ?? '')));
    $filteredAccounts = $accounts;
    if ($filterCat !== '' && $filterCat !== 'all') {
        $filteredAccounts = array_filter($accounts, fn($a) => strtolower($a['account_type']) === $filterCat);
    }

    page_start($db, $user, 'chart_of_accounts', 'Chart of Accounts & General Ledger Hierarchy', 'Statutory healthcare accounts classification, assets, liabilities, equity, diagnostic revenue and operational expenses.');

    // Top Metric Cards (Light styled, professional SVG icons, clickable redirection)
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=chart_of_accounts&category=asset" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><path d="M3 21h18M3 10h18M5 10v11M9 10v11M15 10v11M19 10v11M12 2 2 7h20L12 2z"></path></svg></div>';
    echo '    <span>Current & Fixed Assets (1000s)</span><strong>৳ ' . number_format($catBalances['asset'], 2) . '</strong><small style="color:#2563eb;">' . $catCounts['asset'] . ' Active Ledger Accounts</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=chart_of_accounts&category=liability" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg></div>';
    echo '    <span>Liabilities & AP (2000s)</span><strong>৳ ' . number_format(abs($catBalances['liability']), 2) . '</strong><small style="color:#b45309;">' . $catCounts['liability'] . ' Active Accounts</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=chart_of_accounts&category=equity" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><path d="M21.21 15.89A10 10 0 1 1 8 2.83"></path><path d="M22 12A10 10 0 0 0 12 2v10z"></path></svg></div>';
    echo '    <span>Owner Equity & Capital (3000s)</span><strong>৳ ' . number_format(abs($catBalances['equity']), 2) . '</strong><small style="color:#9333ea;">' . $catCounts['equity'] . ' Equity Accounts</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=chart_of_accounts&category=revenue" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg></div>';
    echo '    <span>Diagnostic Revenue (4000s)</span><strong>৳ ' . number_format(abs($catBalances['revenue']), 2) . '</strong><small style="color:#16a34a;">' . $catCounts['revenue'] . ' Revenue Streams</small>';
    echo '  </a>';
    echo '</div>';

    echo '<div style="display:flex;flex-direction:column;gap:24px;">';
    // New Account Form
    echo '<section class="card">';
    echo '<div class="card-head"><div><span class="eyebrow">NEW GL ACCOUNT</span><h3>Create Ledger Head</h3></div></div>';
    echo '<form method="post" action="/index.php?page=chart_of_accounts" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="account">';
    echo '<label class="field">Account Code *<input name="account_code" placeholder="e.g. 1045, 4030, 6060" required></label>';
    echo '<label class="field">Account Title *<input name="name" placeholder="e.g. Molecular Reagent Consumables" required></label>';
    echo '<label class="field">Account Classification *<select name="account_type" required>';
    echo '  <option value="asset">Asset (Cash, Bank, Receivables, Equipment)</option>';
    echo '  <option value="liability">Liability (Suppliers AP, Tax Dues, Doctor Accruals)</option>';
    echo '  <option value="equity">Equity (Paid-up Capital, Retained Earnings)</option>';
    echo '  <option value="revenue">Revenue / Income (Pathology, Radiology, OPD)</option>';
    echo '  <option value="expense">Operating Expense / COGS (Reagents, Salaries, Overheads)</option>';
    echo '</select></label>';
    echo '<label class="field">Parent Account (Optional)<select name="parent_id"><option value="">-- No Parent (Root Group) --</option>';
    foreach ($accounts as $a) {
        echo '<option value="' . e((string)$a['id']) . '">' . e($a['account_code']) . ' - ' . e($a['name']) . '</option>';
    }
    echo '</select></label>';
    echo '<label class="field span-2">Opening Balance (BDT)<input type="number" step="0.01" name="opening_balance" value="0.00"></label>';
    echo '<div class="form-actions span-2"><button type="submit" class="button button-primary" style="width:100%;"><i class="fa-solid fa-plus-circle" style="margin-right:6px;"></i> Create Ledger Account</button></div>';
    echo '</form></section>';

    // Chart of Accounts Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">GENERAL LEDGER</span><h3>Chart of Accounts (' . count($filteredAccounts) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=chart_of_accounts&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=chart_of_accounts&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search & Filter Badges Bar
    echo '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0 14px;">';
    echo '  <div style="flex:1;min-width:240px;position:relative;">';
    echo '    <input type="text" placeholder="Type 1-2 letters to search account code or title..." class="table-search" style="width:100%;padding:8px 12px 8px 32px;border:1px solid #cbd5e1;border-radius:8px;font-size:12.5px;background:#ffffff;">';
    echo '    <span style="position:absolute;left:10px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:13px;">🔍</span>';
    echo '  </div>';
    echo '</div>';

    // Filter Badges
    $cats = ['all' => 'All Categories', 'asset' => 'Assets', 'liability' => 'Liabilities', 'equity' => 'Equity', 'revenue' => 'Revenue', 'expense' => 'Expenses'];
    echo '<div style="display:flex;gap:6px;flex-wrap:wrap;margin:0 0 16px;">';
    foreach ($cats as $ck => $cv) {
        $active = ($filterCat === $ck || ($filterCat === '' && $ck === 'all')) ? 'background:#092c36;color:#ffffff;border-color:#092c36;' : 'background:#f1f5f9;color:#475569;border-color:#e2e8f0;';
        echo '<a href="/index.php?page=chart_of_accounts&category=' . e($ck) . '" class="pill" style="' . $active . 'text-decoration:none;font-weight:600;padding:5px 12px;border-radius:20px;border:1px solid;">' . e($cv) . '</a>';
    }
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Code</th><th>Account Name</th><th>Classification</th><th>Total Debit</th><th>Total Credit</th><th>Net Balance</th><th>Status</th></tr></thead><tbody>';
    if (!$filteredAccounts) echo '<tr><td colspan="7"><div class="empty-state">No accounts matching filter.</div></td></tr>';
    foreach ($filteredAccounts as $acc) {
        $type = strtolower($acc['account_type']);
        $typeBadge = match($type) {
            'asset' => '<span class="status on" style="background:#e0f2fe;color:#0369a1;border:1px solid #bae6fd;">ASSET</span>',
            'liability' => '<span class="status alert" style="background:#fee2e2;color:#b91c1c;border:1px solid #fecaca;">LIABILITY</span>',
            'equity' => '<span class="status off" style="background:#f3e8ff;color:#7e22ce;border:1px solid #e9d5ff;">EQUITY</span>',
            'revenue' => '<span class="status on" style="background:#dcfce7;color:#15803d;border:1px solid #bbf7d0;">REVENUE</span>',
            'expense' => '<span class="status alert" style="background:#fef3c7;color:#b45309;border:1px solid #fde68a;">EXPENSE</span>',
            default => '<span class="status off">' . strtoupper($acc['account_type']) . '</span>'
        };
        $curBal = (float)($acc['current_balance'] ?? $acc['balance'] ?? 0.0);
        $balFmt = ($curBal < 0) ? '(৳ ' . number_format(abs($curBal), 2) . ')' : '৳ ' . number_format($curBal, 2);

        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($acc['account_code']) . '</span></td>';
        echo '<td><strong>' . e($acc['name']) . '</strong></td>';
        echo '<td>' . $typeBadge . '</td>';
        echo '<td>৳ ' . number_format((float)$acc['total_debit'], 2) . '</td>';
        echo '<td>৳ ' . number_format((float)$acc['total_credit'], 2) . '</td>';
        echo '<td><strong style="color:#092c36;">' . $balFmt . '</strong></td>';
        echo '<td><span class="status on">Active</span></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_financial_vouchers(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $accounts = \Diagnostic\Accounting::listAccounts($db);

    $vType = strtolower(trim((string)($_GET['voucher_type'] ?? '')));
    $search = trim((string)($_GET['q'] ?? ''));
    $dateFrom = trim((string)($_GET['date_from'] ?? ''));
    $dateTo = trim((string)($_GET['date_to'] ?? ''));

    $filters = [];
    if ($vType !== '' && $vType !== 'all') $filters['type'] = $vType;
    if ($search !== '') $filters['search'] = $search;
    if ($dateFrom !== '') $filters['start_date'] = $dateFrom;
    if ($dateTo !== '') $filters['end_date'] = $dateTo;

    $vouchers = \Diagnostic\Accounting::listVouchers($db, $filters);

    $allVouchers = \Diagnostic\Accounting::listVouchers($db);
    $counts = ['journal' => 0, 'payment' => 0, 'receipt' => 0, 'contra' => 0];
    $sums = ['journal' => 0.0, 'payment' => 0.0, 'receipt' => 0.0, 'contra' => 0.0];
    foreach ($allVouchers as $av) {
        $vt = strtolower($av['voucher_type']);
        if (isset($counts[$vt])) {
            $counts[$vt]++;
            $sums[$vt] += (float)($av['total_amount'] ?? $av['amount'] ?? 0.0);
        }
    }

    page_start($db, $user, 'financial_vouchers', 'Double-Entry General Ledger Vouchers', 'Post balanced debit/credit journal, payment, receipt and contra vouchers with complete audit trace.');

    // Top KPI Cards (Light colored, Professional Corporate SVG Icons, Clickable filtering)
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=financial_vouchers&voucher_type=journal" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H20v20H6.5a2.5 2.5 0 0 1-2.5-2.5Z"></path><path d="M6 6h10"></path><path d="M6 10h10"></path></svg></div>';
    echo '    <span>Journal Vouchers (JV)</span><strong>৳ ' . number_format($sums['journal'], 2) . '</strong><small style="color:#2563eb;">' . $counts['journal'] . ' Posted Journals (Filter)</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=financial_vouchers&voucher_type=payment" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><rect x="2" y="5" width="20" height="14" rx="2"></rect><line x1="2" y1="10" x2="22" y2="10"></line><path d="M7 15h.01M11 15h2"></path></svg></div>';
    echo '    <span>Payment Vouchers (PV)</span><strong>৳ ' . number_format($sums['payment'], 2) . '</strong><small style="color:#b45309;">' . $counts['payment'] . ' Disbursed Payments (Filter)</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=financial_vouchers&voucher_type=receipt" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg></div>';
    echo '    <span>Receipt Vouchers (RV)</span><strong>৳ ' . number_format($sums['receipt'], 2) . '</strong><small style="color:#16a34a;">' . $counts['receipt'] . ' Collections (Filter)</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=financial_vouchers&voucher_type=contra" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><path d="m16 3 4 4-4 4"></path><path d="M20 7H4"></path><path d="m8 21-4-4 4-4"></path><path d="M4 17h16"></path></svg></div>';
    echo '    <span>Contra Vouchers (CV)</span><strong>৳ ' . number_format($sums['contra'], 2) . '</strong><small style="color:#9333ea;">' . $counts['contra'] . ' Bank/Cash Transfers (Filter)</small>';
    echo '  </a>';
    echo '</div>';

    // Stacked Layout: Post Form is ON TOP, Posted Vouchers is BELOW (Per user instruction)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';
    
    // Top Section: Post Balanced Voucher Form (Full Width & Spacious)
    echo '<section class="card">';
    echo '<div class="card-head"><div><span class="eyebrow">DOUBLE-ENTRY POSTING</span><h3>Post General Ledger Voucher</h3></div></div>';
    echo '<form method="post" action="/index.php?page=financial_vouchers" class="field-grid" style="grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="voucher"><input type="hidden" name="branch_id" value="' . e($branchId) . '">';
    echo '<label class="field">Voucher Type *<select name="voucher_type" required>';
    echo '  <option value="journal"' . ($vType === 'journal' ? ' selected' : '') . '>Journal Voucher (JV) - Accrual / Adjustment</option>';
    echo '  <option value="payment"' . ($vType === 'payment' ? ' selected' : '') . '>Payment Voucher (PV) - Cash / Bank Outflow</option>';
    echo '  <option value="receipt"' . ($vType === 'receipt' ? ' selected' : '') . '>Receipt Voucher (RV) - Patient / Corporate Inflow</option>';
    echo '  <option value="contra"' . ($vType === 'contra' ? ' selected' : '') . '>Contra Voucher (CV) - Vault to Bank / Inter-Bank</option>';
    echo '</select></label>';
    echo '<label class="field">Posting Date *<input type="date" name="voucher_date" value="' . date('Y-m-d') . '" required></label>';
    echo '<label class="field">Debit Account (Dr.) *<select name="debit_account_id" required>';
    foreach ($accounts as $ac) echo '<option value="' . e((string)$ac['id']) . '">' . e($ac['account_code']) . ' - ' . e($ac['name']) . ' (' . strtoupper($ac['account_type']) . ')</option>';
    echo '</select></label>';
    echo '<label class="field">Credit Account (Cr.) *<select name="credit_account_id" required>';
    foreach ($accounts as $ac) echo '<option value="' . e((string)$ac['id']) . '">' . e($ac['account_code']) . ' - ' . e($ac['name']) . ' (' . strtoupper($ac['account_type']) . ')</option>';
    echo '</select></label>';
    echo '<label class="field">Voucher Amount (BDT) *<input type="number" step="0.01" name="amount" value="5000.00" required></label>';
    echo '<label class="field">Reference / Cheque #<input name="reference_no" placeholder="e.g. CHQ-99214, EFT-48210"></label>';
    echo '<label class="field span-2" style="grid-column:1/-1;">Narration / Particulars *<textarea name="narration" rows="2" placeholder="Explain the transaction particulars..." required style="min-height:55px;">Monthly pathology consumable procurement payment voucher.</textarea></label>';
    echo '<div class="form-actions span-2" style="grid-column:1/-1;"><button type="submit" class="button button-primary" style="width:100%;font-weight:700;padding:12px;"><i class="fa-solid fa-stamp" style="margin-right:6px;"></i> Post & Balance Voucher</button></div>';
    echo '</form></section>';

    // Bottom Section: Posted Vouchers Register Table (Full Width, below the post form)
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">AUDIT REGISTER</span><h3>Posted Vouchers (' . count($vouchers) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=financial_vouchers&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=financial_vouchers&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Filters Bar with Instant Live Auto-Search
    echo '<form method="get" action="/index.php" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0 16px;background:#f8fafc;padding:12px 14px;border-radius:10px;border:1px solid #e2e8f0;">';
    echo '  <input type="hidden" name="page" value="financial_vouchers">';
    echo '  <select name="voucher_type" style="padding:8px 12px;border:1px solid #cbd5e1;border-radius:7px;font-size:12.5px;background:#fff;">';
    echo '    <option value="">All Voucher Types</option>';
    echo '    <option value="journal"' . ($vType === 'journal' ? ' selected' : '') . '>Journal (JV)</option>';
    echo '    <option value="payment"' . ($vType === 'payment' ? ' selected' : '') . '>Payment (PV)</option>';
    echo '    <option value="receipt"' . ($vType === 'receipt' ? ' selected' : '') . '>Receipt (RV)</option>';
    echo '    <option value="contra"' . ($vType === 'contra' ? ' selected' : '') . '>Contra (CV)</option>';
    echo '  </select>';
    echo '  <div style="flex:1;min-width:220px;position:relative;">';
    echo '    <input name="q" value="' . e($search) . '" placeholder="Type 1-2 letters to search voucher # or narration..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12.5px;background:#fff;">';
    echo '    <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '  </div>';
    echo '  <input type="date" name="date_from" value="' . e($dateFrom) . '" style="padding:8px 10px;border:1px solid #cbd5e1;border-radius:7px;font-size:12.5px;background:#fff;">';
    echo '  <input type="date" name="date_to" value="' . e($dateTo) . '" style="padding:8px 10px;border:1px solid #cbd5e1;border-radius:7px;font-size:12.5px;background:#fff;">';
    echo '  <button type="submit" class="button button-outline small" style="font-weight:700;"><i class="fa-solid fa-filter"></i> Filter</button>';
    if ($vType !== '' || $search !== '' || $dateFrom !== '' || $dateTo !== '') {
        echo '  <a href="/index.php?page=financial_vouchers" class="button button-outline small" style="color:#64748b;border-color:#cbd5e1;">Reset</a>';
    }
    echo '</form>';

    echo '<div class="table-wrap"><table><thead><tr><th>Voucher #</th><th>Type</th><th>Date</th><th>Narration & Particulars</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
    if (!$vouchers) echo '<tr><td colspan="7"><div class="empty-state">No vouchers posted yet.</div></td></tr>';
    foreach ($vouchers as $v) {
        $vt = strtoupper($v['voucher_type']);
        $typeBadge = match(strtolower($v['voucher_type'])) {
            'journal' => '<span class="status on" style="background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;">JV</span>',
            'payment' => '<span class="status alert" style="background:#fef2f2;color:#b91c1c;border:1px solid #fecaca;">PV</span>',
            'receipt' => '<span class="status on" style="background:#f0fdf4;color:#15803d;border:1px solid #bbf7d0;">RV</span>',
            'contra' => '<span class="status off" style="background:#faf5ff;color:#7e22ce;border:1px solid #e9d5ff;">CV</span>',
            default => '<span class="status on">' . e($vt) . '</span>'
        };

        $vAmt = (float)($v['total_amount'] ?? $v['amount'] ?? 0.0);

        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($v['voucher_no']) . '</span></td>';
        echo '<td>' . $typeBadge . '</td>';
        echo '<td>' . e(date('d-M-Y', strtotime($v['voucher_date']))) . '</td>';
        echo '<td><strong>' . e($v['narration']) . '</strong>' . (!empty($v['reference_no']) ? '<br><small style="color:#64748b;">Ref: ' . e($v['reference_no']) . '</small>' : '') . '</td>';
        echo '<td><strong style="color:#092c36;font-size:13px;">৳ ' . number_format($vAmt, 2) . '</strong></td>';
        echo '<td><span class="status on">POSTED</span></td>';
        echo '<td><div class="table-actions-cell">';
        echo '  <a href="/index.php?page=download_pdf&type=financial_voucher&id=' . e((string)$v['id']) . '" class="btn-action-pdf" title="Download Official Voucher PDF"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg> PDF</a>';
        echo '  <a href="/index.php?page=print_voucher&type=financial_voucher&id=' . e((string)$v['id']) . '" target="_blank" class="btn-action-print" title="Print Official Voucher Slip"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg> Print</a>';
        echo '</div></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_financial_statements(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $tab = strtolower(trim((string)($_GET['tab'] ?? 'trial_balance')));
    if (!in_array($tab, ['trial_balance', 'pnl', 'balance_sheet', 'cash_flow'])) {
        $tab = 'trial_balance';
    }

    $tabTitles = [
        'trial_balance' => 'Statutory Trial Balance (Zero Variance Audited)',
        'pnl' => 'Statement of Profit & Loss (Income Statement)',
        'balance_sheet' => 'Statement of Financial Position (Balance Sheet)',
