    }
    echo '  </div>';
    
    // Print and PDF Actions
    $printType = match($tab) {
        'pnl' => 'income_statement',
        'balance_sheet' => 'balance_sheet',
        default => 'trial_balance'
    };
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=print_voucher&type=' . e($printType) . '" target="_blank" class="button button-outline" style="display:inline-flex;align-items:center;gap:6px;font-weight:750;color:#0f172a;border-color:#94a3b8;background:#f1f5f9;"><i class="fa-solid fa-print"></i> Print Statement</a>';
