}

function render_doctor_commissions(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $summary = \Diagnostic\Accounting::getDoctorCommissionSummary($db);

    $totalReferredTests = 0;
    $totalBilledVolume = 0.0;
    $totalAccrued = 0.0;
    $totalPendingDue = 0.0;

    foreach ($summary as $s) {
        $totalReferredTests += (int)$s['total_referrals'];
        $totalBilledVolume += (float)$s['total_billed'];
        $totalAccrued += (float)$s['total_commission'];
        $totalPendingDue += (float)($s['pending_due'] ?? $s['pending_commission'] ?? 0.0);
