        echo '</div></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_corporate_billing(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $aging = \Diagnostic\Accounting::getCorporateAging($db);

    $totalInvoiced = 0.0;
    $totalCurrent = 0.0;
    $total30_60 = 0.0;
    $totalOver60 = 0.0;
    $totalOutstanding = 0.0;

    foreach ($aging as $a) {
        $totalInvoiced += (float)($a['total_billed'] ?? $a['total_invoiced'] ?? 0.0);
        $totalCurrent += (float)($a['aging_30'] ?? $a['current_due'] ?? 0.0);
        $total30_60 += (float)($a['aging_60'] ?? $a['days_30_60'] ?? 0.0);
        $totalOver60 += (float)($a['aging_90_plus'] ?? $a['days_over_60'] ?? 0.0);
        $totalOutstanding += (float)($a['total_due'] ?? 0.0);
    }

    page_start($db, $user, 'corporate_billing', 'Corporate Client Accounts Receivable (AR) & Aging', 'Credit agreements, corporate health checkup panel billing, collection tracking and aging schedule.');

    // Top Aging KPI Cards (Light styled, professional SVG icons, clickable redirection)
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=corporate_b2b" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"></rect><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path></svg></div>';
    echo '    <span>Corporate Panel Clients</span><strong>' . count($aging) . ' Partners</strong><small style="color:#2563eb;">Total Billed: ৳ ' . number_format($totalInvoiced, 2) . '</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=corporate_billing" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div>';
    echo '    <span>Current Dues (0-30 Days)</span><strong>৳ ' . number_format($totalCurrent, 2) . '</strong><small style="color:#16a34a;">Standard Credit Term</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=corporate_billing" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><path d="M5 22h14"></path><path d="M5 2h14"></path><path d="M17 22v-4.172a2 2 0 0 0-.586-1.414L12 12l-4.414 4.414A2 2 0 0 0 7 17.828V22"></path><path d="M7 2v4.172a2 2 0 0 0 .586 1.414L12 12l4.414-4.414A2 2 0 0 0 17 6.172V2"></path></svg></div>';
    echo '    <span>Aging 31-60 Days</span><strong>৳ ' . number_format($total30_60, 2) . '</strong><small style="color:#b45309;">Follow-up Notice Active</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=corporate_billing" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"></path><line x1="12" y1="9" x2="12" y2="13"></line><line x1="12" y1="17" x2="12.01" y2="17"></line></svg></div>';
    echo '    <span>Overdue &gt; 60 Days</span><strong>৳ ' . number_format($totalOver60, 2) . '</strong><small style="color:#9333ea;">Total Outstanding: ৳ ' . number_format($totalOutstanding, 2) . '</small>';
    echo '  </a>';
    echo '</div>';

    // Corporate AR Aging Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">RECEIVABLES AGING</span><h3>Corporate AR Aging Analysis (' . count($aging) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=corporate_billing&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=corporate_billing&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search for Corporate Partners
    echo '<div style="margin:10px 0 16px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search corporate partner or code..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Client Code</th><th>Corporate Partner</th><th>Contact &amp; Scheme</th><th>Total Invoiced</th><th>0-30 Days (Current)</th><th>31-60 Days</th><th>60+ Days Overdue</th><th>Total Outstanding</th><th>Status</th></tr></thead><tbody>';
    if (!$aging) echo '<tr><td colspan="9"><div class="empty-state">No corporate clients registered.</div></td></tr>';
    foreach ($aging as $c) {
        $stat = ((float)$c['total_due'] > 0) ? '<span class="status alert">PENDING AR</span>' : '<span class="status on">CLEARED</span>';
        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($c['code'] ?? $c['client_code']) . '</span></td>';
        echo '<td><strong>' . e($c['name']) . '</strong></td>';
        echo '<td>' . e($c['phone'] ?? 'N/A') . '</td>';
        echo '<td>৳ ' . number_format((float)($c['total_billed'] ?? $c['total_invoiced'] ?? 0.0), 2) . '</td>';
        echo '<td style="color:#16a34a;font-weight:600;">৳ ' . number_format((float)($c['aging_30'] ?? $c['current_due'] ?? 0.0), 2) . '</td>';
        echo '<td style="color:#d97706;font-weight:600;">৳ ' . number_format((float)($c['aging_60'] ?? $c['days_30_60'] ?? 0.0), 2) . '</td>';
        echo '<td style="color:#dc2626;font-weight:600;">৳ ' . number_format((float)($c['aging_90_plus'] ?? $c['days_over_60'] ?? 0.0), 2) . '</td>';
        echo '<td><strong style="color:#092c36;font-size:13px;">৳ ' . number_format((float)$c['total_due'], 2) . '</strong></td>';
        echo '<td>' . $stat . '</td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section>';
    page_end();
}

function render_accounts_payable(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $suppliers = \Diagnostic\Accounting::getSupplierLedger($db);

    $totalPurchases = 0.0;
    $totalTdsVds = 0.0;
    $totalPaid = 0.0;
    $totalBalanceDue = 0.0;

    foreach ($suppliers as $s) {
        $totalPurchases += (float)($s['total_purchased'] ?? $s['total_purchases'] ?? 0.0);
        $totalTdsVds += (float)($s['tds_vds_deducted'] ?? $s['total_tds_vds'] ?? 0.0);
        $totalPaid += (float)$s['total_paid'];
        $totalBalanceDue += (float)$s['balance_payable'];
    }

    page_start($db, $user, 'accounts_payable', 'Supplier Accounts Payable (AP) & NBR TDS/VDS', 'Reagents, chemicals, lab consumables procurement payables with statutory NBR tax & VAT withholding.');

    // Top KPI Cards (Light styled, professional SVG icons, clickable redirection)
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=procurement" class="stat-card dash-clickable-card card-light-blue" style="text-decoration:none;">';
    echo '    <div class="stat-icon blue"><svg viewBox="0 0 24 24"><path d="M1 3h15v13H1zM16 8h4l3 3v5h-7V8zM5.5 19a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5zM18.5 19a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5z"></path></svg></div>';
    echo '    <span>Enlisted Vendors</span><strong>' . count($suppliers) . ' Suppliers</strong><small style="color:#2563eb;">Total Billed: ৳ ' . number_format($totalPurchases, 2) . '</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=accounts_payable" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg></div>';
    echo '    <span>NBR Statutory TDS/VDS Withheld</span><strong>৳ ' . number_format($totalTdsVds, 2) . '</strong><small style="color:#16a34a;">NBR Challan Ready</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=financial_vouchers&voucher_type=payment" class="stat-card dash-clickable-card card-light-purple" style="text-decoration:none;">';
    echo '    <div class="stat-icon purple"><svg viewBox="0 0 24 24"><rect x="2" y="5" width="20" height="14" rx="2"></rect><line x1="2" y1="10" x2="22" y2="10"></line><path d="M7 15h.01M11 15h2"></path></svg></div>';
    echo '    <span>Disbursed Payments</span><strong>৳ ' . number_format($totalPaid, 2) . '</strong><small style="color:#9333ea;">Cheque / Corporate EFT (View PV)</small>';
    echo '  </a>';
    echo '  <a href="/index.php?page=accounts_payable" class="stat-card dash-clickable-card card-light-amber" style="text-decoration:none;">';
    echo '    <div class="stat-icon amber"><svg viewBox="0 0 24 24"><path d="m16 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z"></path><path d="m2 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z"></path><path d="M7 21h10"></path><path d="M12 3v18"></path></svg></div>';
    echo '    <span>Outstanding Payable Dues</span><strong>৳ ' . number_format($totalBalanceDue, 2) . '</strong><small style="color:#b45309;">Net AP Balance</small>';
    echo '  </a>';
    echo '</div>';

    // Supplier AP Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">VENDOR PAYABLES</span><h3>Diagnostic Supplier Ledger (' . count($suppliers) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=accounts_payable&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=accounts_payable&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search for Suppliers
    echo '<div style="margin:10px 0 16px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search vendor name or code..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Vendor Code</th><th>Distributor / Supplier</th><th>Category / Scope</th><th>Total Purchases</th><th>Statutory TDS/VDS</th><th>Disbursed Payments</th><th>Net Balance Payable</th><th>Status</th></tr></thead><tbody>';
    if (!$suppliers) echo '<tr><td colspan="8"><div class="empty-state">No suppliers registered.</div></td></tr>';
    foreach ($suppliers as $sp) {
        $stat = ((float)$sp['balance_payable'] > 0) ? '<span class="status alert">DUE</span>' : '<span class="status on">SETTLED</span>';
        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($sp['code'] ?? $sp['supplier_code']) . '</span></td>';
        echo '<td><strong>' . e($sp['name']) . '</strong><br><small style="color:#64748b;">Phone: ' . e($sp['phone'] ?? 'N/A') . '</small></td>';
        echo '<td><span class="status off" style="font-size:11px;">' . e(strtoupper($sp['category'] ?? 'REAGENTS')) . '</span></td>';
        echo '<td>৳ ' . number_format((float)($sp['total_purchased'] ?? $sp['total_purchases'] ?? 0.0), 2) . '</td>';
        echo '<td style="color:#2563eb;font-weight:600;">৳ ' . number_format((float)($sp['tds_vds_deducted'] ?? $sp['total_tds_vds'] ?? 0.0), 2) . '</td>';
        echo '<td style="color:#16a34a;font-weight:600;">৳ ' . number_format((float)$sp['total_paid'], 2) . '</td>';
        echo '<td><strong style="color:#dc2626;font-size:13px;">৳ ' . number_format((float)$sp['balance_payable'], 2) . '</strong></td>';
        echo '<td>' . $stat . '</td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section>';
    page_end();
}

function render_cash_bank_books(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $liquidAccounts = \Diagnostic\Accounting::getCashBankBalances($db);

    $totalLiquidity = 0.0;
    foreach ($liquidAccounts as $la) {
        $totalLiquidity += (float)$la['balance'];
    }

    page_start($db, $user, 'cash_bank_books', 'Cash & Bank Books Liquidity Register', 'Physical vault cash, operational commercial bank accounts and digital mobile financial services (MFS).');

    // Top KPI Cards (Light styled, professional SVG icons, clickable redirection)
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=cash_bank_books" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg></div>';
