    echo '    <span>MFS Gateways</span><strong>bKash & Nagad Active</strong><small style="color:#0d9488;">Auto POS Settlement</small>';
    echo '  </a>';
    echo '</div>';

    // Liquidity Matrix Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">LIQUIDITY REGISTRY</span><h3>Cash, Bank &amp; MFS Books (' . count($liquidAccounts) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=cash_bank_books&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=cash_bank_books&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search for Liquid Accounts
    echo '<div style="margin:10px 0 16px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search account title or code..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Account Code</th><th>Liquid Account Title</th><th>Channel Type</th><th style="text-align:right;">Current Available Balance</th><th>Audit Status</th></tr></thead><tbody>';
    if (!$liquidAccounts) echo '<tr><td colspan="5"><div class="empty-state">No liquidity accounts configured.</div></td></tr>';
    foreach ($liquidAccounts as $la) {
        $accCode = $la['account_code'] ?? $la['code'];
        $channel = match(true) {
            str_contains(strtolower($accCode), 'cash') || str_contains(strtolower($accCode), 'petty') => '<span class="status on" style="background:#eff6ff;color:#1d4ed8;">PHYSICAL CASH</span>',
            str_contains(strtolower($accCode), 'mfs') || str_contains(strtolower($accCode), 'bkash') || str_contains(strtolower($la['name']), 'bkash') => '<span class="status on" style="background:#fdf2f8;color:#be185d;">DIGITAL MFS</span>',
            default => '<span class="status on" style="background:#f0fdf4;color:#15803d;">BANK ACCOUNT</span>'
        };

        echo '<tr>';
        echo '<td><span class="code-chip" style="font-weight:700;">' . e($accCode) . '</span></td>';
        echo '<td><strong>' . e($la['name']) . '</strong></td>';
        echo '<td>' . $channel . '</td>';
        echo '<td style="text-align:right;"><strong style="color:#092c36;font-size:14px;">৳ ' . number_format((float)$la['balance'], 2) . '</strong></td>';
        echo '<td><span class="status on">RECONCILED</span></td>';
        echo '</tr>';
    }
    echo '<tr class="summary-total-row" style="background:#f8fafc;font-size:14px;border-top:2px solid #092c36;">';
    echo '<td colspan="3"><strong>TOTAL RECONCILED CASH & BANK BALANCES</strong></td>';
    echo '<td style="text-align:right;"><strong style="color:#0d9488;font-size:16px;">৳ ' . number_format($totalLiquidity, 2) . '</strong></td>';
    echo '<td><span class="status on">VERIFIED</span></td>';
    echo '</tr>';
    echo '</tbody></table></div></section>';
    page_end();
}

