function render_hr_employees(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $employees = \Diagnostic\HR::listEmployees($db);
    $departments = Masters::scoped($db, 'departments', 100);

    $totalStaff = count($employees);
    $activeDocs = 0; $techs = 0; $totalSalary = 0.0;
    foreach ($employees as $e) {
        $totalSalary += (float)($e['basic_salary'] ?? 0);
        if (str_contains(strtolower($e['designation']), 'doctor') || str_contains(strtolower($e['designation']), 'pathologist') || str_contains(strtolower($e['designation']), 'radiologist')) $activeDocs++;
        if (str_contains(strtolower($e['designation']), 'technologist') || str_contains(strtolower($e['designation']), 'radiographer') || str_contains(strtolower($e['designation']), 'biochemist')) $techs++;
    }

    page_start($db, $user, 'hr_employees', 'Employee Profiles & Clinical Credentials', 'Workforce master records, BMDC/license expiry alerts, designation grades and ERP user mapping.');

    // KPI Cards (Light gradient, SVG icons, clickable redirection)
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <a href="/index.php?page=hr_employees" class="stat-card dash-clickable-card card-light-teal" style="text-decoration:none;">';
    echo '    <div class="stat-icon teal"><svg viewBox="0 0 24 24"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M23 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg></div>';
