    echo '  </a>';
    echo '  <a href="/index.php?page=hr_employees" class="stat-card dash-clickable-card card-light-emerald" style="text-decoration:none;">';
    echo '    <div class="stat-icon green"><svg viewBox="0 0 24 24"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg></div>';
    echo '    <span>Monthly Salary Budget</span><strong>৳ ' . number_format($totalSalary, 2) . '</strong><small style="color:#16a34a;">Total Base Payroll</small>';
    echo '  </a>';
    echo '</div>';

    // Stacked Layout: Register Staff Profile Form (Top) + Workforce Master Table (Below)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';
    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">NEW WORKFORCE MEMBER</span><h3>Register Staff Profile</h3></div></div>';
