    echo '<label class="field">Full Name *<input name="name" placeholder="Staff Full Name" required></label>';
    echo '<label class="field">Designation *<input name="designation" placeholder="e.g. Senior Medical Technologist" required></label>';
    echo '<label class="field">Department<select name="department_id">';
    foreach ($departments as $d) echo '<option value="' . e((string)$d['id']) . '">' . e($d['name']) . '</option>';
    echo '</select></label>';
    echo '<label class="field">Mobile Phone *<input name="mobile" placeholder="017xxxxxxxx" required></label>';
    echo '<label class="field">Email Address<input type="email" name="email" placeholder="staff@lutfunnesa.com"></label>';
    echo '<label class="field">BMDC / License No<input name="license_no" placeholder="e.g. BMDC-A-45210 / SMF-1029"></label>';
