    echo '<div class="form-actions span-2"><button class="button button-primary"><i class="fa-solid fa-user-plus" style="margin-right:6px;"></i> Save Staff Profile</button></div></form></section>';

    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">STAFF DIRECTORY</span><h3>Workforce Master (' . $totalStaff . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=hr_employees&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Export PDF</a>';
    echo '    <a href="/index.php?page=print_voucher&type=staff_directory" class="button button-outline small" target="_blank" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-print"></i> Print Directory</a>';
    echo '    <a href="/index.php?page=hr_employees&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar for Employees
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search employee name, code or designation..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Code</th><th>Name &amp; Role</th><th>Department</th><th>License</th><th>Salary</th><th>Action</th></tr></thead><tbody>';
    if (!$employees) echo '<tr><td colspan="6"><div class="empty-state">No workforce records found.</div></td></tr>';
    foreach ($employees as $emp) {
        $hasLicense = !empty($emp['license_no']);
        $isExpiring = $hasLicense && !empty($emp['license_expiry']) && (strtotime($emp['license_expiry']) < strtotime('+90 days'));
        echo '<tr>';
        echo '<td><span class="code-chip">' . e($emp['employee_code']) . '</span></td>';
        echo '<td><strong>' . e($emp['name']) . '</strong><br><small style="color:#64748b;">' . e($emp['designation']) . '</small></td>';
        echo '<td><span class="pill" style="font-size:10px;">' . e($emp['department_name'] ?? 'General') . '</span></td>';
        echo '<td>' . ($hasLicense ? ('<small style="font-weight:700;color:#0f766e;">' . e($emp['license_no']) . '</small>' . ($isExpiring ? ' <span style="background:#fee2e2;color:#dc2626;padding:1px 5px;border-radius:4px;font-size:9px;font-weight:800;">RENEW</span>' : '')) : '<span style="color:#94a3b8;">N/A</span>') . '</td>';
        echo '<td><strong>৳ ' . number_format((float)$emp['basic_salary'], 2) . '</strong></td>';
        echo '<td><div class="table-actions-cell"><a href="/index.php?page=print_voucher&type=staff_directory" target="_blank" class="btn-action-print" title="Print Staff ID Dossier"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg> Print ID</a></div></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_hr_attendance(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $date = (string) ($_GET['date'] ?? date('Y-m-d'));
    $records = \Diagnostic\HR::listAttendance($db, $date);
    $stats = \Diagnostic\HR::getAttendanceStats($db, $date);
    $employees = \Diagnostic\HR::listEmployees($db);

    page_start($db, $user, 'hr_attendance', 'Daily Attendance, Biometrics & Shift Punches', 'Monitor real-time clock-in/out times, late arrivals, shift hours, overtime calculations and biometric logs.');

    // KPI Cards (Light gradient, SVG icons, clickable redirection)
