    echo '<div class="form-actions span-2"><button class="button button-primary"><i class="fa-solid fa-fingerprint" style="margin-right:6px;"></i> Record Attendance</button></div></form></section>';

    // Attendance Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">ATTENDANCE LOG</span><h3>Logs for ' . date('d M Y', strtotime($date)) . '</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <form method="get" action="/index.php" style="margin:0;"><input type="hidden" name="page" value="hr_attendance"><input type="date" name="date" value="' . e($date) . '" onchange="this.form.submit()" style="border:1.5px solid #0d9488;border-radius:6px;padding:4px 8px;font-size:12px;font-weight:700;"></form>';
    echo '    <a href="/index.php?page=hr_attendance&export=pdf&date=' . e($date) . '" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> PDF</a>';
    echo '    <a href="/index.php?page=print_voucher&type=attendance&date=' . e($date) . '" class="button button-outline small" target="_blank" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-print"></i> Print</a>';
    echo '    <a href="/index.php?page=hr_attendance&export=csv&date=' . e($date) . '" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> CSV</a>';
    echo '  </div>';
    echo '</div>';

    // Live Auto-Search Bar for Attendance
    echo '<div style="margin:10px 0 14px;position:relative;max-width:380px;">';
    echo '  <input type="text" placeholder="Type 1-2 letters to search staff name, code or status..." class="table-search" style="width:100%;padding:8px 12px 8px 30px;border:1px solid #cbd5e1;border-radius:7px;font-size:12px;background:#ffffff;">';
    echo '  <span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);color:#94a3b8;font-size:12px;">🔍</span>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Code</th><th>Name</th><th>Dept</th><th>In / Out</th><th>OT</th><th>Status</th></tr></thead><tbody>';
    if (!$records) echo '<tr><td colspan="6"><div class="empty-state">No attendance logs found for this date.</div></td></tr>';
    foreach ($records as $a) {
        $stClass = ($a['status'] === 'present') ? 'color:#15803d;background:#f0fdf4;' : (($a['status'] === 'late') ? 'color:#b45309;background:#fffbeb;' : 'color:#1e40af;background:#eff6ff;');
        echo '<tr>';
        echo '<td><span class="code-chip">' . e($a['employee_code']) . '</span></td>';
        echo '<td><strong>' . e($a['employee_name']) . '</strong></td>';
        echo '<td><small>' . e($a['department_name'] ?? 'General') . '</small></td>';
        echo '<td>' . e(date('h:i A', strtotime($a['clock_in']))) . ' - ' . ($a['clock_out'] ? e(date('h:i A', strtotime($a['clock_out']))) : '<span style="color:#94a3b8;">On Duty</span>') . '</td>';
        echo '<td>' . ($a['overtime_hours'] > 0 ? ('<strong style="color:#0d9488;">+' . (float)$a['overtime_hours'] . 'h</strong>') : '-') . '</td>';
        echo '<td><span class="pill" style="font-size:10px;text-transform:uppercase;' . $stClass . '">' . e($a['status']) . '</span></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_hr_roster_leave(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $branchId = Security::branchIds($db)[0];
    $employees = \Diagnostic\HR::listEmployees($db);
    $rosters = \Diagnostic\HR::listRosters($db, $branchId);

    page_start($db, $user, 'hr_roster_leave', '24/7 Clinical & Diagnostic Duty Rostering', 'Schedule 24/7 shift coverage across Pathology, Radiology, Chamber Nursing, Front Desk and Sample Desks.');

    // Stat Cards
    $morning = 0; $evening = 0; $night = 0;
    foreach ($rosters as $r) {
        if ($r['shift_name'] === 'morning') $morning++;
        if ($r['shift_name'] === 'evening') $evening++;
        if ($r['shift_name'] === 'night') $night++;
    }

    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #f0fdfa, #ccfbf1);border:1px solid #99f6e4;"><div class="stat-icon teal"><i class="fa-solid fa-sun"></i></div><span>Morning Shift</span><strong>' . $morning . ' Duties</strong><small style="color:#0d9488;">08:00 AM - 04:00 PM</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #fffbeb, #fef3c7);border:1px solid #fde68a;"><div class="stat-icon amber"><i class="fa-solid fa-cloud-sun"></i></div><span>Evening Shift</span><strong>' . $evening . ' Duties</strong><small style="color:#b45309;">04:00 PM - 12:00 AM</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #eff6ff, #dbeafe);border:1px solid #bfdbfe;"><div class="stat-icon blue"><i class="fa-solid fa-moon"></i></div><span>Night Duty Shift</span><strong>' . $night . ' Duties</strong><small style="color:#2563eb;">12:00 AM - 08:00 AM</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #faf5ff, #f3e8ff);border:1px solid #e9d5ff;"><div class="stat-icon purple"><i class="fa-solid fa-calendar-check"></i></div><span>Shift Coverage</span><strong>100% Active</strong><small style="color:#9333ea;">24/7 Service Desk</small></div>';
    echo '</div>';

    echo '<div class="two-columns">';
    
    // Assign Roster Form
    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">DUTY ALLOCATION</span><h3>Assign 24/7 Shift Roster</h3></div></div>';
    echo '<form method="post" action="/index.php?page=hr_roster_leave" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="roster"><input type="hidden" name="branch_id" value="' . e((string)$branchId) . '">';
    echo '<label class="field">Select Staff *<select name="employee_id" required>';
    foreach ($employees as $e) echo '<option value="' . e((string)$e['id']) . '">' . e($e['name']) . ' (' . e($e['employee_code']) . ' - ' . e($e['designation']) . ')</option>';
    echo '</select></label>';
    echo '<label class="field">Shift Date *<input type="date" name="shift_date" value="' . date('Y-m-d') . '" required></label>';
    echo '<label class="field span-2">Duty Shift *<select name="shift_name"><option value="morning">Morning Shift (08:00 AM - 04:00 PM)</option><option value="evening">Evening Shift (04:00 PM - 12:00 AM)</option><option value="night">Night Duty Shift (12:00 AM - 08:00 AM)</option></select></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary"><i class="fa-solid fa-calendar-plus" style="margin-right:6px;"></i> Assign Duty Shift</button></div></form></section>';

    // Roster Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">SCHEDULE ROSTER</span><h3>Assigned Shifts (' . count($rosters) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=hr_roster_leave&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=print_voucher&type=roster" class="button button-outline small" target="_blank" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-print"></i> Print 24/7 Roster</a>';
    echo '    <a href="/index.php?page=hr_roster_leave&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Date</th><th>Employee</th><th>Department</th><th>Shift</th><th>Timing</th></tr></thead><tbody>';
    if (!$rosters) echo '<tr><td colspan="5"><div class="empty-state">No shift rosters scheduled.</div></td></tr>';
    foreach ($rosters as $r) {
        $badgeClass = ($r['shift_name'] === 'morning') ? 'color:#047857;background:#ecfdf5;' : (($r['shift_name'] === 'evening') ? 'color:#b45309;background:#fffbeb;' : 'color:#1e40af;background:#eff6ff;');
        $timeStr = ($r['shift_name']==='morning'?'08:00 - 16:00':($r['shift_name']==='evening'?'16:00 - 00:00':'00:00 - 08:00'));
        echo '<tr>';
        echo '<td>' . e($r['shift_date']) . '</td>';
        echo '<td><strong>' . e($r['employee_name']) . '</strong><br><small style="color:#64748b;">' . e($r['designation']) . '</small></td>';
        echo '<td><small>' . e($r['department_name'] ?? 'General') . '</small></td>';
        echo '<td><span class="pill" style="font-size:10px;text-transform:uppercase;' . $badgeClass . '">' . e($r['shift_name']) . '</span></td>';
        echo '<td><small style="font-weight:700;">' . $timeStr . '</small></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_hr_leaves(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $statusFilter = (string) ($_GET['status'] ?? 'all');
    $leaves = \Diagnostic\HR::listLeaves($db, $statusFilter);
    $employees = \Diagnostic\HR::listEmployees($db);

    $pending = 0; $approved = 0;
    foreach ($leaves as $l) {
        if ($l['status'] === 'pending') $pending++;
        if ($l['status'] === 'approved') $approved++;
    }

    page_start($db, $user, 'hr_leaves', 'Leave Desk, Balances & Approvals', 'Employee leave applications, approval workflows, casual/sick/annual leave quotas and duty handovers.');

    // Stat Cards
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #fffbeb, #fef3c7);border:1px solid #fde68a;"><div class="stat-icon amber"><i class="fa-solid fa-hourglass-half"></i></div><span>Pending Approvals</span><strong>' . $pending . ' Applications</strong><small style="color:#b45309;">Awaiting HR Action</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #f0fdf4, #dcfce7);border:1px solid #bbf7d0;"><div class="stat-icon green"><i class="fa-solid fa-circle-check"></i></div><span>Approved Leaves</span><strong>' . $approved . ' Granted</strong><small style="color:#16a34a;">Recorded on Roster</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #eff6ff, #dbeafe);border:1px solid #bfdbfe;"><div class="stat-icon blue"><i class="fa-solid fa-calendar-check"></i></div><span>Annual Leave Quota</span><strong>20 Days / Staff</strong><small style="color:#2563eb;">Standard Medical Staff</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #faf5ff, #f3e8ff);border:1px solid #e9d5ff;"><div class="stat-icon purple"><i class="fa-solid fa-heart-pulse"></i></div><span>Sick &amp; Casual Pool</span><strong>14 Days / Staff</strong><small style="color:#9333ea;">Paid Medical Leave</small></div>';
    echo '</div>';

    echo '<div class="two-columns">';
    
    // Apply Leave Form
    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">APPLICATION FORM</span><h3>Submit Leave Request</h3></div></div>';
    echo '<form method="post" action="/index.php?page=hr_leaves" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="apply_leave">';
    echo '<label class="field">Staff Member *<select name="employee_id" required>';
    foreach ($employees as $e) echo '<option value="' . e((string)$e['id']) . '">' . e($e['name']) . ' (' . e($e['employee_code']) . ')</option>';
    echo '</select></label>';
    echo '<label class="field">Leave Type *<select name="leave_type"><option value="casual">Casual Leave (CL)</option><option value="sick">Sick Leave (Medical)</option><option value="annual">Annual Privilege Leave</option></select></label>';
    echo '<label class="field">Start Date *<input type="date" name="start_date" value="' . date('Y-m-d') . '" required></label>';
    echo '<label class="field">End Date *<input type="date" name="end_date" value="' . date('Y-m-d', strtotime('+2 days')) . '" required></label>';
    echo '<label class="field span-2">Reason for Leave *<input name="reason" placeholder="State reason or medical justification" required></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary"><i class="fa-solid fa-paper-plane" style="margin-right:6px;"></i> Submit Leave Request</button></div></form></section>';

    // Leave Requests Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">LEAVE REGISTER</span><h3>Leave Applications (' . count($leaves) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=hr_leaves&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=hr_leaves&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a>';
    echo '  </div>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Type</th><th>Duration</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody>';
    if (!$leaves) echo '<tr><td colspan="6"><div class="empty-state">No leave applications found.</div></td></tr>';
    foreach ($leaves as $lv) {
        $stBadge = ($lv['status'] === 'approved') ? 'color:#15803d;background:#f0fdf4;' : (($lv['status'] === 'pending') ? 'color:#b45309;background:#fffbeb;' : 'color:#dc2626;background:#fef2f2;');
        echo '<tr>';
        echo '<td><strong>' . e($lv['employee_name']) . '</strong><br><small style="color:#64748b;">' . e($lv['employee_code']) . ' • ' . e($lv['department_name'] ?? 'General') . '</small></td>';
        echo '<td><span class="pill" style="font-size:10px;text-transform:uppercase;">' . e($lv['leave_type']) . '</span></td>';
        echo '<td>' . e(date('d M', strtotime($lv['start_date']))) . ' - ' . e(date('d M', strtotime($lv['end_date']))) . ' <br><strong style="color:#0d9488;">' . (int)$lv['total_days'] . ' Days</strong></td>';
        echo '<td><small>' . e($lv['reason']) . '</small></td>';
        echo '<td><span class="pill" style="font-size:10px;text-transform:uppercase;' . $stBadge . '">' . e($lv['status']) . '</span></td>';
        echo '<td>';
        if ($lv['status'] === 'pending') {
            echo '<form method="post" action="/index.php?page=hr_leaves" style="display:inline-flex;gap:4px;margin:0;">';
            echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="update_leave"><input type="hidden" name="leave_id" value="' . e((string)$lv['id']) . '">';
            echo '<button type="submit" name="status" value="approved" class="button small" style="background:#16a34a;color:white;border:none;padding:2px 8px;font-size:11px;" title="Approve Leave">✓</button>';
            echo '<button type="submit" name="status" value="rejected" class="button small" style="background:#dc2626;color:white;border:none;padding:2px 8px;font-size:11px;" title="Reject Leave">✕</button>';
            echo '</form>';
        } else {
            echo '<small style="color:#94a3b8;">Closed</small>';
        }
        echo '</td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_hr_payroll(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $employees = \Diagnostic\HR::listEmployees($db);
    $payrolls = \Diagnostic\HR::listPayrolls($db);

    $totalDisbursed = 0.0; $totalDeductions = 0.0;
    foreach ($payrolls as $p) {
        $totalDisbursed += (float)$p['net_salary'];
        $totalDeductions += (float)($p['deductions'] ?? 0);
    }

    page_start($db, $user, 'hr_payroll', 'Payroll & Corporate Salary Payslips', 'Process monthly salary payouts, allowances (HRA/Medical), PF deductions, corporate payslips and tax registers.');

    // Stat Cards
    echo '<div class="stats-grid" style="margin-bottom:20px;">';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #f0fdf4, #dcfce7);border:1px solid #bbf7d0;"><div class="stat-icon green"><i class="fa-solid fa-wallet"></i></div><span>Total Net Disbursed</span><strong>৳ ' . number_format($totalDisbursed, 2) . '</strong><small style="color:#16a34a;">' . count($payrolls) . ' Slips Processed</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #eff6ff, #dbeafe);border:1px solid #bfdbfe;"><div class="stat-icon blue"><i class="fa-solid fa-piggy-bank"></i></div><span>PF &amp; Tax Deductions</span><strong>৳ ' . number_format($totalDeductions, 2) . '</strong><small style="color:#2563eb;">Statutory Compliance</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #faf5ff, #f3e8ff);border:1px solid #e9d5ff;"><div class="stat-icon purple"><i class="fa-solid fa-money-check-dollar"></i></div><span>Payment Channel</span><strong>100% Bank Transfer</strong><small style="color:#9333ea;">City Bank Corporate</small></div>';
    echo '  <div class="stat-card" style="background:linear-gradient(135deg, #f0fdfa, #ccfbf1);border:1px solid #99f6e4;"><div class="stat-icon teal"><i class="fa-solid fa-file-invoice-dollar"></i></div><span>Salary Cycle</span><strong>Monthly (1st-5th)</strong><small style="color:#0d9488;">On-Time SLA</small></div>';
    echo '</div>';

    echo '<div class="two-columns">';
    
    // Single Run Form & Batch Trigger
    echo '<section class="card">';
    echo '<div class="card-head"><div><span class="eyebrow">SALARY RUN</span><h3>Disburse Staff Salary</h3></div></div>';
    echo '<form method="post" action="/index.php?page=hr_payroll" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="payroll">';
    echo '<label class="field">Payroll Period *<input name="payroll_period" value="' . date('F Y') . '" required></label>';
    echo '<label class="field">Select Employee *<select name="employee_id" required>';
    foreach ($employees as $e) echo '<option value="' . e((string)$e['id']) . '">' . e($e['name']) . ' (' . e($e['employee_code']) . ' - ৳' . number_format((float)$e['basic_salary']) . ')</option>';
    echo '</select></label>';
    echo '<label class="field">Basic Salary (BDT)<input type="number" step="0.01" name="basic_salary" value="45000.00"></label>';
    echo '<label class="field">Allowances (HRA+Med)<input type="number" step="0.01" name="allowances" value="21000.00"></label>';
    echo '<label class="field">Deductions (PF+Tax)<input type="number" step="0.01" name="deductions" value="4600.00"></label>';
    echo '<label class="field">Disbursement Channel<select name="payment_method"><option value="Bank Transfer">Bank Transfer (Corporate EFT)</option><option value="Cheque">Account Payee Cheque</option><option value="Cash">Cash Voucher</option></select></label>';
