    echo '  <strong style="display:block;font-size:12px;color:#092c36;margin-bottom:4px;">⚡ 1-Click Batch Payroll Generation</strong>';
    echo '  <p style="margin:0 0 10px;font-size:11.5px;color:#64748b;">Automatically generate salary payslips for all active workforce members for ' . date('F Y') . '.</p>';
    echo '  <form method="post" action="/index.php?page=hr_payroll"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="batch_payroll"><input type="hidden" name="payroll_period" value="' . date('F Y') . '">';
    echo '  <button type="submit" class="button button-outline" style="width:100%;font-weight:750;color:#0d9488;border-color:#0d9488;"><i class="fa-solid fa-bolt"></i> Generate Batch Payroll For All Staff</button></form>';
    echo '</div></section>';

    // Payroll History Table
    echo '<section class="card">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
    echo '  <div><span class="eyebrow">SALARY SLIPS</span><h3>Disbursed Slips (' . count($payrolls) . ')</h3></div>';
    echo '  <div style="display:flex;gap:8px;">';
    echo '    <a href="/index.php?page=hr_payroll&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a>';
    echo '    <a href="/index.php?page=hr_payroll&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export Ledger CSV</a>';
    echo '  </div>';
    echo '</div>';

    echo '<div class="table-wrap"><table><thead><tr><th>Period</th><th>Employee</th><th>Basic</th><th>Net Salary</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
    if (!$payrolls) echo '<tr><td colspan="6"><div class="empty-state">No payroll runs processed.</div></td></tr>';
    foreach ($payrolls as $p) {
        echo '<tr>';
        echo '<td><strong style="color:#092c36;">' . e($p['payroll_period']) . '</strong><br><small style="color:#64748b;">' . e($p['transaction_ref'] ?? '') . '</small></td>';
        echo '<td><strong>' . e($p['employee_name']) . '</strong><br><small style="color:#64748b;">' . e($p['employee_code']) . '</small></td>';
        echo '<td>৳ ' . number_format((float)$p['basic_salary'], 2) . '</td>';
        echo '<td><strong style="color:#0d9488;font-size:13px;">৳ ' . number_format((float)$p['net_salary'], 2) . '</strong></td>';
        echo '<td><span class="status on">PAID</span></td>';
        echo '<td><div class="table-actions-cell"><a href="/index.php?page=download_pdf&type=payslip&id=' . e((string)$p['id']) . '" class="btn-action-pdf" title="Download Payslip PDF"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg> PDF</a><a href="/index.php?page=print_voucher&type=payslip&id=' . e((string)$p['id']) . '" target="_blank" class="btn-action-print" title="Print Official Payslip"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg> Print</a></div></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

