    echo '<label class="field">Application Deadline<input type="date" name="deadline" value="' . date('Y-m-d', strtotime('+30 days')) . '"></label>';
    echo '<label class="field">Employment Type<select name="job_type"><option value="full_time">Full Time</option><option value="part_time">Part Time</option><option value="visiting">Visiting Specialist</option></select></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary"><i class="fa-solid fa-bullhorn" style="margin-right:6px;"></i> Publish Opening</button></div></form></section>';

    // Active Openings Table
    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">OPEN POSITIONS</span><h3>Active Clinical Vacancies (' . count($recruitments) . ')</h3></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Job Title</th><th>Dept</th><th>Vacancies</th><th>Applicants</th><th>Status</th></tr></thead><tbody>';
    if (!$recruitments) echo '<tr><td colspan="5"><div class="empty-state">No open vacancies.</div></td></tr>';
    foreach ($recruitments as $rc) {
        echo '<tr>';
        echo '<td><strong>' . e($rc['job_title']) . '</strong><br><small style="color:#64748b;">Exp: ' . e($rc['experience_required']) . '</small></td>';
        echo '<td><small>' . e($rc['department_name'] ?? 'General') . '</small></td>';
        echo '<td>' . (int)$rc['vacancy_count'] . ' Post</td>';
        echo '<td><strong style="color:#0d9488;">' . (int)$rc['total_candidates'] . ' Candidates</strong></td>';
        echo '<td><span class="pill" style="font-size:10px;text-transform:uppercase;">' . e($rc['status']) . '</span></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section></div>';

    // Candidate Pipeline Table
    echo '<section class="card" style="margin-top:24px;">';
    echo '<div class="card-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;"><div><span class="eyebrow">CANDIDATE PIPELINE</span><h3>Applicant Screening &amp; Interviews (' . count($candidates) . ')</h3></div><div style="display:flex;gap:8px;"><a href="/index.php?page=hr_recruitment&export=pdf" class="button button-outline small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#0284c7;border-color:#bae6fd;"><i class="fa-solid fa-file-pdf"></i> Download PDF</a><a href="/index.php?page=hr_recruitment&export=csv" class="button button-primary small" style="display:inline-flex;align-items:center;gap:6px;font-weight:700;"><i class="fa-solid fa-file-excel"></i> Export CSV</a></div></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Applicant Name</th><th>Position</th><th>Contact</th><th>Experience</th><th>Expected Salary</th><th>Interview</th><th>Status</th></tr></thead><tbody>';
    if (!$candidates) echo '<tr><td colspan="7"><div class="empty-state">No candidate applications in pipeline.</div></td></tr>';
    foreach ($candidates as $cd) {
        $stCol = ($cd['status'] === 'shortlisted' || $cd['status'] === 'hired') ? 'color:#15803d;background:#f0fdf4;' : 'color:#475569;background:#f1f5f9;';
        echo '<tr>';
        echo '<td><strong>' . e($cd['name']) . '</strong></td>';
        echo '<td>' . e($cd['job_title']) . '</td>';
        echo '<td>' . e($cd['mobile']) . '<br><small style="color:#64748b;">' . e($cd['email'] ?? '') . '</small></td>';
        echo '<td>' . (int)$cd['experience_years'] . ' Years</td>';
        echo '<td>' . ($cd['expected_salary'] ? ('৳ ' . number_format((float)$cd['expected_salary'])) : 'Negotiable') . '</td>';
        echo '<td>' . ($cd['interview_date'] ? e(date('d M Y', strtotime($cd['interview_date']))) : '<span style="color:#94a3b8;">Not scheduled</span>') . '</td>';
        echo '<td><span class="pill" style="font-size:10px;text-transform:uppercase;' . $stCol . '">' . e($cd['status']) . '</span></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></section>';
    page_end();
}

