function render_quality_qc_tat(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $qcLogs = \Diagnostic\Quality::listQCLogs($db);

    page_start($db, $user, 'quality_qc_tat', 'Quality Control (QC) & TAT Monitoring', 'Internal quality control (Level 1/2/3) Westgard rules, TAT target breaches, and rejection metrics.');

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">QUALITY CONTROL</span><h3>Log Lab QC Observation</h3></div></div>';
    echo '<form method="post" action="/index.php?page=quality_qc_tat" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="qc">';
    echo '<label class="field">Lab Section<select name="section_name"><option value="Biochemistry">Biochemistry</option><option value="Hematology">Hematology</option><option value="Immunology">Immunology</option><option value="Microbiology">Microbiology</option></select></label>';
    echo '<label class="field">QC Control Level<select name="qc_level"><option value="level_1">Level 1 (Normal)</option><option value="level_2">Level 2 (Abnormal High)</option><option value="level_3">Level 3 (Abnormal Low)</option></select></label>';
    echo '<label class="field">Target Mean Value<input type="number" step="0.0001" name="target_value" value="100.0000" required></label>';
    echo '<label class="field">Observed Value<input type="number" step="0.0001" name="observed_value" value="101.2000" required></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Log QC Result</button></div></form></section>';

    echo '<section class="card" style="margin-top:20px;"><div class="card-head"><div><span class="eyebrow">WESTGARD WATCH</span><h3>Recent QC Logs & Status</h3></div><span class="pill">' . count($qcLogs) . ' logs</span></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Section</th><th>QC Level</th><th>Target</th><th>Observed</th><th>Westgard Status</th></tr></thead><tbody>';
    if (!$qcLogs) echo '<tr><td colspan="5"><div class="empty-state">No QC runs recorded.</div></td></tr>';
    foreach ($qcLogs as $q) {
        echo '<tr><td><span class="code-chip">' . e($q['section_name']) . '</span></td><td>' . e(strtoupper($q['qc_level'])) . '</td><td>' . e($q['target_value']) . '</td><td>' . e($q['observed_value']) . '</td><td><span class="status ' . ($q['status']==='passed'?'on':'off') . '">' . e(strtoupper($q['status'])) . '</span></td></tr>';
    }
    echo '</tbody></table></div></section>';
    page_end();
}

