function render_executive_dashboard(PDO $db, array $user): void
{
    Security::requirePermission($db, 'intelligence.view');

    $filters = [
        'branch_filter' => $_GET['branch_filter'] ?? 'all',
        'dept_filter' => $_GET['dept_filter'] ?? 'all',
        'doc_filter' => $_GET['doc_filter'] ?? 'all',
        'status_filter' => $_GET['status_filter'] ?? 'all',
        'start_date' => $_GET['start_date'] ?? date('Y-m-01'),
        'end_date' => $_GET['end_date'] ?? date('Y-m-d'),
        'horizon' => $_GET['horizon'] ?? 'daily',
    ];

    $data = \Diagnostic\Intelligence::getRealtimeCockpitData($db, $filters);

    $branches = $db->query('SELECT id, name FROM branches WHERE active = 1 ORDER BY id ASC')->fetchAll() ?: [];
    $departments = $db->query('SELECT id, name FROM departments WHERE active = 1 ORDER BY name ASC')->fetchAll() ?: [];
    $doctors = $db->query('SELECT id, name FROM doctors WHERE active = 1 ORDER BY name ASC')->fetchAll() ?: [];

    $isFiltered = (!empty($_GET['start_date']) && $_GET['start_date'] !== date('Y-m-01')) ||
                  (!empty($_GET['end_date']) && $_GET['end_date'] !== date('Y-m-d')) ||
                  (($filters['branch_filter'] ?? 'all') !== 'all') ||
                  (($filters['dept_filter'] ?? 'all') !== 'all') ||
                  (($filters['doc_filter'] ?? 'all') !== 'all') ||
                  (($filters['status_filter'] ?? 'all') !== 'all');

    page_start($db, $user, 'executive_dashboard', 'Executive & Operational Cockpit', 'Real-time revenue, MTD/YTD growth, TAT performance, critical alerts, stock risk, and cash collection breakdown.');

    // 1. Spaciously Designed Header Banner (Clean Vertical Rhythm & Uncluttered Layout)
    echo '<div style="background:linear-gradient(135deg,#092c36 0%,#134c59 50%,#0c928c 100%);color:white;border-radius:16px;padding:26px 32px;margin-bottom:24px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:20px;box-shadow:0 10px 30px rgba(9,44,54,0.25);border:1px solid #1c5f6e;">';
    echo '<a href="/index.php?page=billing" style="color:inherit;text-decoration:none;display:block;flex:1;min-width:320px;" title="Click to view Billing Overview">';
    echo '<span style="display:inline-block;background:rgba(50,215,193,0.18);color:#32d7c1;border:1px solid rgba(50,215,193,0.35);padding:5px 14px;border-radius:20px;font-weight:800;font-size:10px;letter-spacing:0.12em;text-transform:uppercase;margin-bottom:12px;">● LIVE TODAY PERFORMANCE SUMMARY · ' . date('d M Y') . '</span>';
    echo '<h2 style="margin:0 0 10px;font-size:26px;color:white;font-weight:800;line-height:1.25;letter-spacing:-0.03em;">Today\'s Center Revenue & Operational Velocity →</h2>';
    echo '<p style="margin:0;color:#c2e4e8;font-size:13px;line-height:1.6;max-width:640px;">Real-time billing, patient queue arrivals, lab TAT status, and cashier collection summary.</p></a>';
    echo '<div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;">';
    echo '<a href="/index.php?page=billing" style="text-align:right;text-decoration:none;color:inherit;display:block;padding:12px 18px;background:rgba(255,255,255,0.12);border-radius:12px;border:1px solid rgba(255,255,255,0.3);transition:all 0.2s;" title="Click to view Cash Collections"><span style="display:block;font-size:10px;color:#c2e4e8;text-transform:uppercase;font-weight:800;letter-spacing:0.06em;margin-bottom:4px;">Today Cash Collected</span><strong style="font-size:22px;color:#ffffff;font-weight:900;text-shadow:0 1px 3px rgba(0,0,0,0.3);">৳ ' . number_format($data['today_paid'], 2) . ' →</strong></a>';
    echo '<a href="/index.php?page=patients" style="text-align:right;text-decoration:none;color:inherit;display:block;padding:12px 18px;background:rgba(255,255,255,0.08);border-radius:12px;border:1px solid rgba(255,255,255,0.25);transition:all 0.2s;" title="Click to view Patients List"><span style="display:block;font-size:10px;color:#95c1c8;text-transform:uppercase;font-weight:800;letter-spacing:0.06em;margin-bottom:4px;">Today Patients</span><strong style="font-size:22px;color:white;font-weight:800;">' . $data['patient_count'] . ' Patients →</strong></a>';
    echo '</div></div>';

    // 2. Unified Executive Analytics Filter & Horizon Bar (Merged into single clean section)
    echo '<div class="dashboard-filter-bar exec-cockpit-filter-bar" style="background:#ffffff;border:1px solid #e2e8f0;border-radius:14px;padding:20px 24px;box-shadow:0 4px 20px rgba(15,23,42,0.04);margin-bottom:24px;">';
    echo '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid #f1f5f9;flex-wrap:wrap;gap:12px;">';
    echo '<div style="display:flex;gap:6px;align-items:center;"><span style="font-size:11px;font-weight:800;color:#475569;letter-spacing:0.12em;text-transform:uppercase;">Analytics Horizon View:</span></div>';
    echo '<div class="cockpit-tab-bar" style="margin:0;padding:4px;background:#f1f5f9;border:1px solid #e2e8f0;border-radius:10px;">';
    echo '<button type="button" class="cockpit-tab-btn ' . ($filters['horizon'] === 'daily' ? 'active' : '') . '" id="tab-btn-daily" onclick="switchCockpitTab(\'daily\')"><span style="font-size:13px;">☀️</span> Daily Pulse</button>';
    echo '<button type="button" class="cockpit-tab-btn ' . ($filters['horizon'] === 'monthly' ? 'active' : '') . '" id="tab-btn-monthly" onclick="switchCockpitTab(\'monthly\')"><span style="font-size:13px;">📅</span> Monthly (MTD)</button>';
    echo '<button type="button" class="cockpit-tab-btn ' . ($filters['horizon'] === 'yearly' ? 'active' : '') . '" id="tab-btn-yearly" onclick="switchCockpitTab(\'yearly\')"><span style="font-size:13px;">📈</span> Yearly (YTD)</button>';
    echo '</div></div>';

    echo '<form method="get" action="/index.php" style="display:flex;flex-wrap:wrap;gap:12px;align-items:center;">';
    echo '<input type="hidden" name="page" value="executive_dashboard">';
    echo '<input type="hidden" name="horizon" id="horizonInput" value="' . e($filters['horizon']) . '">';
    
    // Branch Filter
