                            { label: "Cash Collected (৳)", data: [11000, 16000, 13500, 19500, 18000, 22000, 20500, 24000, ' . (int)$data['today_paid'] . '], borderColor: "#10b981", backgroundColor: "transparent", borderDash: [4, 4], tension: 0.35 }
                        ]
                    },
