                });
            }

            // 6. Department Revenue Horizontal Bar Chart
            var c4 = document.getElementById("deptRevenueChart");
            if (c4) {
                new Chart(c4, {
                    type: "bar",
                    data: {
                        labels: ["Biochemistry", "Hematology", "Radiology", "Ultrasonography", "Microbiology", "Cardiology"],
                        datasets: [{ label: "Revenue (BDT ৳)", data: [68500, 42000, 38500, 24000, 18000, 9500], backgroundColor: ["#0c928c", "#0ea5e9", "#10b981", "#f59e0b", "#8b5cf6", "#ec4899"], borderRadius: 6 }]
