                        datasets: [
                            { label: "2026 Monthly Revenue (৳)", data: [210000, 235000, 260000, 280000, 310000, 340000, 365000, 390000, ' . (int)$data['mtd_revenue'] . ', 0, 0, 0], borderColor: "#10b981", backgroundColor: "rgba(16,185,129,0.1)", fill: true, tension: 0.3 },
                            { label: "2025 Historic Baseline (৳)", data: [180000, 195000, 215000, 230000, 250000, 275000, 290000, 310000, 325000, 340000, 350000, 365000], borderColor: "#94a3b8", borderDash: [5, 5], backgroundColor: "transparent", tension: 0.3 }
                        ]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: "top" } }, scales: { y: { beginAtZero: true } } }
                });
            }

            // 8. Yearly Margin Bar Chart
            var c6 = document.getElementById("yearlyMarginChart");
            if (c6) {
                new Chart(c6, {
                    type: "bar",
                    data: {
                        labels: ["Gross Revenue", "Discounts", "Reagent Expenses", "Doctor Commissions", "Net Surplus"],
                        datasets: [{ label: "Amount (BDT ৳)", data: [' . (int)$data['ytd_revenue'] . ', ' . (int)($data['ytd_revenue'] * 0.08) . ', ' . (int)($data['ytd_revenue'] * 0.18) . ', ' . (int)($data['ytd_revenue'] * 0.12) . ', ' . (int)($data['ytd_revenue'] * 0.62) . '], backgroundColor: ["#0ea5e9", "#ef4444", "#f59e0b", "#8b5cf6", "#10b981"], borderRadius: 6 }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } }
                });
            }
        }
        if (document.readyState === "complete" || document.readyState === "interactive") renderCharts();
        else document.addEventListener("DOMContentLoaded", renderCharts);
    })();
    </script>';

    page_end();
}

