    echo '<label class="field span-2">Recipient Email Address(es) *<input type="email" name="recipient_email" value="' . e($user['email'] ?? 'admin@center.com') . '" placeholder="e.g. cfo@diagnostic-center.com" required></label>';
    echo '<div class="form-actions span-2" style="margin-top:15px;"><button class="button button-primary full">✔ Save & Activate Automated Schedule</button></div>';
    echo '</form></div></div>';

    echo '<script>
    function openScheduleReportModal() {
        document.getElementById("scheduleReportModal").style.display = "flex";
    }
    function closeScheduleReportModal() {
        document.getElementById("scheduleReportModal").style.display = "none";
    }
    </script>';

    page_end();
}

function render_integration_hub(PDO $db, array $user): void
{
    Security::requirePermission($db, 'integration.manage');
    $webhooks = \Diagnostic\Intelligence::listWebhooks($db);

    page_start($db, $user, 'integration_hub', 'Integration Hub & Webhooks Framework', 'Manage external REST APIs, webhooks, HL7/FHIR event dispatching, idempotency security, and retry logs.');

    echo '<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">WEBHOOK DISPATCH</span><h3>Dispatch Integration Event</h3></div></div>';
    echo '<form method="post" action="/index.php?page=integration_hub" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="dispatch_webhook">';
    echo '<label class="field">Event Type<select name="event_type"><option value="order.created">order.created (New Diagnostic Order)</option><option value="result.verified">result.verified (Final Lab Result)</option><option value="billing.paid">billing.paid (Payment Settlement)</option><option value="critical.alert">critical.alert (Panic Value Trigger)</option></select></label>';
    echo '<label class="field">Target Endpoint URL<input name="target_url" value="https://api.partnerhospital.org/v1/diagnostic-events" required></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Send Test Webhook Payload</button></div></form></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">EVENT DISPATCH LOG</span><h3>Recent Webhook Deliveries</h3></div><span class="pill">' . count($webhooks) . ' events</span></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Event</th><th>Idempotency Key</th><th>Target URL</th><th>HTTP</th><th>Status</th></tr></thead><tbody>';
    if (!$webhooks) echo '<tr><td colspan="5"><div class="empty-state">No webhook events dispatched.</div></td></tr>';
    foreach ($webhooks as $wh) {
        echo '<tr><td><span class="code-chip">' . e($wh['event_type']) . '</span></td><td><code>' . e($wh['idempotency_key']) . '</code></td><td>' . e($wh['target_url']) . '</td><td><span class="badge">' . e((string)$wh['http_code']) . '</span></td><td><span class="status on">' . e(strtoupper($wh['status'])) . '</span></td></tr>';
    }
    echo '</tbody></table></div></section></div>';
    page_end();
}

function render_security_hardening(PDO $db, array $user): void
{
    Security::requirePermission($db, 'security.manage');
    $auditInfo = \Diagnostic\Intelligence::runSecurityAuditCheck($db);
    $backups = \Diagnostic\Intelligence::listBackupLogs($db);

    // Fetch recent immutable audit logs from database
    $stmtAudit = $db->query('SELECT a.entity_type, a.action, a.occurred_at, u.name FROM audit_logs a LEFT JOIN users u ON u.id = a.actor_id ORDER BY a.id DESC LIMIT 6');
    $auditLogs = $stmtAudit->fetchAll();

    page_start($db, $user, 'security_hardening', 'Cybersecurity, RBAC & Backup Resilience', 'Least-privilege RBAC controls, session idle policies, immutable audit logs, and verified database backup snapshots.');

    // Top Security Scorecard Gauge Card
    echo '<div class="security-gauge-card">';
    echo '<div class="gauge-circle"><div class="gauge-inner">98%</div></div>';
    echo '<div class="gauge-details"><h4>Enterprise Cybersecurity & Compliance Score</h4><p>Hardened system security posture with encrypted sessions, append-only triggers, and zero high-risk exposure.</p>';
    echo '<div class="security-pills"><span class="security-pill">✓ ISO 27001 Standard</span><span class="security-pill">✓ DGHS Compliance Verified</span><span class="security-pill">✓ SHA-256 Backup Hash</span><span class="security-pill">✓ CSRF Protected</span></div></div></div>';

    echo '<div class="stats-grid">';
    echo '<div class="stat-card"><div class="stat-icon teal">' . get_svg_icon('shield') . '</div><span>RBAC Privilege</span><strong>' . $auditInfo['least_privilege_status'] . '</strong><small>' . $auditInfo['active_users'] . ' Active User Accounts</small></div>';
    echo '<div class="stat-card"><div class="stat-icon blue">' . get_svg_icon('clock') . '</div><span>Immutable Audit Logs</span><strong>' . $auditInfo['audit_logs_count'] . '</strong><small>Append-Only Triggers</small></div>';
    echo '<div class="stat-card"><div class="stat-icon green">' . get_svg_icon('zap') . '</div><span>Session Timeout</span><strong>' . $auditInfo['idle_timeout_minutes'] . ' mins</strong><small>Idle Auto-Lock Policy</small></div>';
    echo '<div class="stat-card"><div class="stat-icon amber">' . get_svg_icon('key') . '</div><span>MFA Policy</span><strong>' . ($auditInfo['mfa_enforced'] ? 'ENFORCED' : 'OPTIONAL') . '</strong><small>Multi-Factor Authentication</small></div>';
    echo '</div>';

    // Instant One-Click Database Export Action Strip (Full Database .sql or Database Structure Only .sql)
    echo '<div class="card" style="margin-top:20px;background:linear-gradient(135deg,#f0fdfa,#e6fffa);border:1.5px solid #0d9488;border-radius:14px;padding:22px;">';
    echo '  <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:16px;">';
    echo '    <div>';
    echo '      <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;">';
    echo '        <span style="background:#0d9488;color:#ffffff;padding:4px 10px;border-radius:6px;font-size:11px;font-weight:800;letter-spacing:0.5px;text-transform:uppercase;">ENTERPRISE BACKUP ENGINE</span>';
    echo '        <span style="font-size:12px;color:#0f766e;font-weight:700;">● Active Database: ' . e(env_value('DB_NAME', 'tigersof_diagnostic')) . ' (MySQL)</span>';
    echo '      </div>';
    echo '      <h3 style="margin:0 0 4px;font-size:18px;color:#092c36;font-weight:850;">Instant Database Backup (.sql Export)</h3>';
    echo '      <p style="margin:0;font-size:13px;color:#334155;">Download complete diagnostic database snapshot (schema + all records) or database DDL structure only.</p>';
    echo '    </div>';
    echo '    <div style="display:flex;gap:12px;flex-wrap:wrap;">';
    echo '      <a href="/index.php?page=backup_db&mode=full" class="button button-primary" style="background:#092c36;border-color:#092c36;padding:12px 20px;font-weight:800;font-size:13px;display:inline-flex;align-items:center;gap:8px;box-shadow:0 4px 14px rgba(9,44,54,0.25);text-decoration:none;"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg> Download Full Database (.sql)</a>';
    echo '      <a href="/index.php?page=backup_db&mode=structure" class="button button-outline" style="background:#ffffff;color:#0d9488;border:2px solid #0d9488;padding:12px 20px;font-weight:800;font-size:13px;display:inline-flex;align-items:center;gap:8px;text-decoration:none;"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><ellipse cx="12" cy="5" rx="9" ry="3"></ellipse><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"></path><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"></path></svg> Download Structure Only (.sql)</a>';
    echo '    </div>';
