    echo '</div>';

    echo '<div class="two-columns" style="margin-top:20px;"><section class="card"><div class="card-head"><div><span class="eyebrow">DISASTER RECOVERY</span><h3>Trigger Automated Backup</h3></div></div>';
    echo '<form method="post" action="/index.php?page=security_hardening" class="field-grid"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="trigger_backup">';
    echo '<label class="field">Backup Type<select name="backup_type"><option value="full_db">Full Database Snapshot (.sql.gz)</option><option value="schema_only">Schema DDL Dump</option><option value="audit_export">Immutable Audit Logs Archive</option></select></label>';
    echo '<div class="form-actions span-2"><button class="button button-primary">Execute Backup & Verification</button></div></form></section>';

    echo '<section class="card"><div class="card-head"><div><span class="eyebrow">BACKUP REPOSITORY</span><h3>Verified Backup Snapshots</h3></div><span class="pill">' . count($backups) . ' backups</span></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Backup #</th><th>Type</th><th>Size</th><th>SHA-256 Hash</th><th>Status</th></tr></thead><tbody>';
    if (!$backups) echo '<tr><td colspan="5"><div class="empty-state">No backup snapshots logged.</div></td></tr>';
    foreach ($backups as $bk) {
        echo '<tr><td><span class="code-chip">' . e($bk['backup_no']) . '</span></td><td>' . e($bk['backup_type']) . '</td><td>' . number_format($bk['file_size_bytes'] / 1024 / 1024, 2) . ' MB</td><td><code>' . e(substr($bk['file_hash_sha256'], 0, 12)) . '...</code></td><td><span class="status on">' . e(strtoupper($bk['status'])) . '</span></td></tr>';
    }
    echo '</tbody></table></div></section></div>';

    // System Audit Trail Stream Table
    echo '<div class="card" style="margin-top:20px;"><div class="card-head"><div><span class="eyebrow">IMMUTABLE AUDIT TRAIL</span><h3>Recent Security & Access Logs</h3></div><span class="pill">' . count($auditLogs) . ' events</span></div>';
    echo '<div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Actor</th><th>Entity Type</th><th>Action Executed</th><th>Security Status</th></tr></thead><tbody>';
    if (!$auditLogs) echo '<tr><td colspan="5"><div class="empty-state">No security audit logs recorded.</div></td></tr>';
    foreach ($auditLogs as $al) {
        echo '<tr><td>' . e($al['occurred_at']) . '</td><td><strong>' . e($al['name'] ?? 'System Process') . '</strong></td><td><span class="code-chip">' . e(strtoupper($al['entity_type'])) . '</span></td><td>' . e(ucwords(str_replace('_', ' ', $al['action']))) . '</td><td><span class="status on">AUDITED & SECURE</span></td></tr>';
    }
    echo '</tbody></table></div></div>';

    page_end();
}

function render_payment_gateway(PDO $db, array $user): void
{
    Security::requirePermission($db, 'dashboard.view');
    $invoiceId = (int) ($_GET['invoice_id'] ?? 0);
    $methodId = (int) ($_GET['method_id'] ?? 2);
    $amount = (float) ($_GET['amount'] ?? 0.00);

    $inv = $invoiceId ? \Diagnostic\Billing::getInvoice($db, $invoiceId) : null;
    if (!$inv) {
        flash('error', 'Select a valid unpaid invoice to initiate gateway payment.');
        redirect('index.php?page=billing');
    }

    $stmt = $db->prepare('SELECT * FROM payment_methods WHERE id=?');
    $stmt->execute([$methodId]);
    $pm = $stmt->fetch() ?: ['name' => 'SSLCommerz Gateway', 'code' => 'SSLCOMMERZ'];

    $isBkash = strtoupper((string)($pm['code'] ?? '')) === 'BKASH';
    $isNagad = strtoupper((string)($pm['code'] ?? '')) === 'NAGAD';
    $isHandCash = strtoupper((string)($pm['code'] ?? '')) === 'CASH';
    $isCard = strtoupper((string)($pm['code'] ?? '')) === 'VISA_MC';
    $isBank = strtoupper((string)($pm['code'] ?? '')) === 'NET_BANK';
    $dueVal = $amount > 0 ? $amount : (float)$inv['due_amount'];
    $dueFormatted = number_format($dueVal, 2);

    page_start($db, $user, 'payment_gateway', 'Online Payment Gateway Checkout', 'Secure 256-Bit Encrypted Multi-Channel Payment Processing');

    echo '<div style="max-width:960px;margin:20px auto;">';
    echo '<div style="background:#ffffff;border:1px solid #e2e8f0;border-radius:24px;box-shadow:0 12px 40px rgba(15,23,42,0.06);overflow:hidden;position:relative;">';
    
    // Top Close Button
    echo '<div style="display:flex;justify-content:flex-end;padding:16px 20px 0;">';
    echo '<a href="/index.php?page=billing&view=' . e($inv['id']) . '" style="color:#94a3b8;font-size:20px;text-decoration:none;font-weight:700;line-height:1;">✕</a>';
    echo '</div>';

    echo '<div style="display:grid;grid-template-columns:1.1fr 1.4fr;gap:32px;padding:10px 36px 36px;">';

    // LEFT COLUMN: Summary & Payment Channel Selector
    echo '<div style="display:flex;flex-direction:column;gap:18px;">';
    
    // Header with cute 3D wallet illustration
    echo '<div>';
    echo '<div style="width:56px;height:56px;border-radius:16px;background:linear-gradient(135deg,#f0fdf4,#dcfce7);display:flex;align-items:center;justify-content:center;margin-bottom:12px;box-shadow:0 4px 12px rgba(16,185,129,0.15);font-size:28px;">';
    echo '💳';
    echo '</div>';
    echo '<h2 style="margin:0 0 4px;font-size:24px;font-weight:800;color:#0f172a;">Checkout</h2>';
    echo '<p style="margin:0;font-size:13px;color:#64748b;">You\'re one more step to go...</p>';
    echo '</div>';

    // Invoice Summary Box
    echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:16px;padding:18px;display:flex;flex-direction:column;gap:8px;">';
    echo '<div style="display:flex;justify-content:space-between;font-size:12px;color:#64748b;"><span>Invoice Ref:</span><strong style="color:#092c36;">#' . e($inv['invoice_no']) . '</strong></div>';
    echo '<div style="display:flex;justify-content:space-between;font-size:12px;color:#64748b;"><span>Patient Name:</span><strong style="color:#092c36;">' . e($inv['patient_name']) . '</strong></div>';
    echo '<div style="display:flex;justify-content:space-between;font-size:12px;color:#64748b;"><span>MRN:</span><strong style="color:#092c36;">' . e($inv['mrn']) . '</strong></div>';
    echo '<div style="display:flex;justify-content:space-between;align-items:center;border-top:1px dashed #cbd5e1;padding-top:10px;margin-top:4px;">';
    echo '<span style="font-size:13px;font-weight:700;color:#334155;">Total Charge:</span>';
    echo '<span style="font-size:20px;font-weight:800;color:#0c928c;">৳ ' . $dueFormatted . '</span>';
    echo '</div></div>';

    // 4 Payment Mode Selection Tabs (SSLCommerz, Cards, Online Banking, Hand Cash)
    echo '<div style="display:flex;flex-direction:column;gap:8px;">';
    echo '<span style="font-size:12px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:0.5px;">Select Payment Option:</span>';
    
    $modes = [
        ['id' => 'card', 'label' => 'Cards (Visa/Master/Amex)', 'badge' => 'VISA · MC · AMEX', 'icon' => '💳'],
        ['id' => 'ssl', 'label' => 'SSLCommerz (All Gateways)', 'badge' => 'bKash · Nagad · DBBL', 'icon' => '🚀'],
        ['id' => 'bank', 'label' => 'Online & Net Banking', 'badge' => 'CityTouch · EBL · IBBL', 'icon' => '🏦'],
        ['id' => 'cash', 'label' => 'Hand Cash (Counter Desk)', 'badge' => 'Instant Receipt', 'icon' => '💵'],
    ];

    $defaultTab = $isHandCash ? 'cash' : ($isBkash || $isNagad ? 'ssl' : ($isBank ? 'bank' : 'card'));

    foreach ($modes as $m) {
        $isActive = ($defaultTab === $m['id']);
        $tabBg = $isActive ? '#f0fdfa' : '#ffffff';
        $tabBorder = $isActive ? '#0c928c' : '#e2e8f0';
        $tabColor = $isActive ? '#0c928c' : '#334155';
        echo '<div onclick="switchCheckoutTab(\'' . $m['id'] . '\')" id="tab_btn_' . $m['id'] . '" style="display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border:1.5px solid ' . $tabBorder . ';background:' . $tabBg . ';border-radius:12px;cursor:pointer;transition:all 0.2s ease;">';
        echo '<div style="display:flex;align-items:center;gap:10px;">';
        echo '<span style="font-size:18px;">' . $m['icon'] . '</span>';
        echo '<div><strong style="font-size:13px;display:block;color:' . $tabColor . ';">' . $m['label'] . '</strong><small style="color:#64748b;font-size:10.5px;">' . $m['badge'] . '</small></div>';
        echo '</div>';
        echo '<div class="tab-radio-dot" style="width:16px;height:16px;border-radius:50%;border:2px solid ' . ($isActive ? '#0c928c' : '#cbd5e1') . ';background:' . ($isActive ? '#0c928c' : '#ffffff') . ';"></div>';
        echo '</div>';
    }
    echo '</div>';

    // Trust badge info
    echo '<div style="font-size:11.5px;color:#64748b;line-height:1.5;background:#f8fafc;padding:12px;border-radius:10px;border:1px solid #e2e8f0;">';
    echo '🛡️ <strong>256-Bit SSL Encrypted:</strong> We won\'t share your payment details with third parties. Compliant with Bangladesh Bank & PCI-DSS security guidelines.';
    echo '</div>';

    echo '</div>'; // End Left Column

    // RIGHT COLUMN: Dynamic Payment Entry Form
    echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:20px;padding:24px;display:flex;flex-direction:column;justify-content:space-between;">';

    echo '<form method="post" action="/index.php?page=payment_gateway" id="unifiedCheckoutForm">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<input type="hidden" name="invoice_id" value="' . e($inv['id']) . '">';
    echo '<input type="hidden" name="payment_method_id" id="selectedMethodInput" value="' . e($methodId) . '">';
    echo '<input type="hidden" name="amount" value="' . e($dueVal) . '">';
    echo '<input type="hidden" name="reference_no" id="finalRefNo" value="TXN-' . strtoupper(substr(md5((string)time()), 0, 8)) . '">';
    echo '<input type="hidden" name="payment_channel_type" id="paymentChannelInput" value="' . $defaultTab . '">';

    // TAB 1: CARDS
    echo '<div id="pane_card" style="display:' . ($defaultTab === 'card' ? 'block' : 'none') . ';">';
    echo '<h4 style="margin:0 0 16px;font-size:15px;color:#0f172a;font-weight:800;">Debit / Credit Card Details</h4>';
    echo '<div style="display:flex;gap:8px;margin-bottom:16px;">';
    echo '<span style="padding:4px 10px;border-radius:6px;background:#1e3a8a;color:white;font-size:10px;font-weight:800;">VISA</span>';
    echo '<span style="padding:4px 10px;border-radius:6px;background:#ea580c;color:white;font-size:10px;font-weight:800;">Mastercard</span>';
    echo '<span style="padding:4px 10px;border-radius:6px;background:#0284c7;color:white;font-size:10px;font-weight:800;">AMEX</span>';
    echo '<span style="padding:4px 10px;border-radius:6px;background:#059669;color:white;font-size:10px;font-weight:800;">UnionPay</span>';
    echo '</div>';
    echo '<div class="field" style="margin-bottom:12px;"><label style="font-weight:700;color:#334155;font-size:12px;">Name on Card *</label><input name="card_name" placeholder="e.g. ' . e($inv['patient_name']) . '" value="' . e($inv['patient_name']) . '" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;"></div>';
    echo '<div class="field" style="margin-bottom:12px;"><label style="font-weight:700;color:#334155;font-size:12px;">Card Number *</label><input name="card_number" placeholder="4111 2222 3333 4444" value="4111 2222 3333 4444" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;"></div>';
    echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px;">';
    echo '<div class="field"><label style="font-weight:700;color:#334155;font-size:12px;">Card Expiration Date *</label><input name="expiry" placeholder="12/28" value="12/28" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;"></div>';
    echo '<div class="field"><label style="font-weight:700;color:#334155;font-size:12px;">CVV / Security Code *</label><input type="password" name="cvv" placeholder="123" value="123" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;"></div>';
    echo '</div>'; // End grid
    echo '</div>'; // End pane_card

    // TAB 2: SSLCOMMERZ / MFS
    echo '<div id="pane_ssl" style="display:' . ($defaultTab === 'ssl' ? 'block' : 'none') . ';">';
    echo '<h4 style="margin:0 0 16px;font-size:15px;color:#0f172a;font-weight:800;">SSLCommerz & Mobile Banking Gateway</h4>';
    echo '<div style="background:#fff0f5;border:1px solid #fbcfe8;border-radius:10px;padding:12px 16px;margin-bottom:16px;">';
    echo '<strong style="color:#9d174d;font-size:13px;">Selected Gateway: bKash / Nagad / Rocket</strong>';
    echo '<p style="margin:2px 0 0;font-size:11.5px;color:#701a75;">Instant PIN/OTP verification with real-time settlement.</p>';
    echo '</div>';
    echo '<div class="field" style="margin-bottom:12px;"><label style="font-weight:700;color:#334155;font-size:12px;">Wallet / Account Number *</label><input name="wallet_number" placeholder="017XXXXXXXX" value="' . e($inv['patient_mobile'] ?? '01711223344') . '" style="background:#fff;border:1.5px solid #e2136e;padding:10px 14px;border-radius:8px;width:100%;"></div>';
    echo '<div class="field" style="margin-bottom:16px;"><label style="font-weight:700;color:#334155;font-size:12px;">Secret PIN / OTP *</label><input type="password" name="pin" placeholder="Enter 5-digit PIN (Demo: 12345)" value="12345" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;"></div>';
    echo '</div>';

    // TAB 3: ONLINE / INTERNET BANKING
    echo '<div id="pane_bank" style="display:' . ($defaultTab === 'bank' ? 'block' : 'none') . ';">';
    echo '<h4 style="margin:0 0 16px;font-size:15px;color:#0f172a;font-weight:800;">Internet Banking / IBFT Transfer</h4>';
    echo '<div class="field" style="margin-bottom:14px;"><label style="font-weight:700;color:#334155;font-size:12px;">Select Bank Portal *</label><select name="bank_name" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;"><option value="CityTouch">City Bank (CityTouch)</option><option value="EBL">Eastern Bank Ltd (EBL Skybanking)</option><option value="IBBL">Islami Bank Bangladesh (CellFin / iBanking)</option><option value="BRAC">BRAC Bank (Astha)</option><option value="DutchBangla">Dutch-Bangla Bank (NexusPay)</option></select></div>';
    echo '<div class="field" style="margin-bottom:16px;"><label style="font-weight:700;color:#334155;font-size:12px;">Bank Account / User ID *</label><input name="bank_user_id" placeholder="Online User ID or Account #" value="ACC-8921-99214" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;"></div>';
    echo '</div>';

    // TAB 4: HAND CASH PAYMENT
    echo '<div id="pane_cash" style="display:' . ($defaultTab === 'cash' ? 'block' : 'none') . ';">';
    echo '<h4 style="margin:0 0 16px;font-size:15px;color:#0f172a;font-weight:800;">Hand Cash Collection (Counter Desk)</h4>';
    echo '<div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;padding:14px;margin-bottom:16px;">';
    echo '<strong style="color:#15803d;font-size:13px;">✔ Physical Cash Counter Receipt</strong>';
    echo '<p style="margin:3px 0 0;font-size:11.5px;color:#166534;">Cash received by duty cashier and money receipt generated directly.</p>';
    echo '</div>';
    echo '<div class="field" style="margin-bottom:12px;"><label style="font-weight:700;color:#334155;font-size:12px;">Cash Collected (BDT) *</label><input type="number" step="0.01" name="cash_tendered" value="' . e($dueVal) . '" style="background:#fff;border:1.5px solid #059669;padding:10px 14px;border-radius:8px;width:100%;font-weight:750;"></div>';
    echo '<div class="field" style="margin-bottom:16px;"><label style="font-weight:700;color:#334155;font-size:12px;">Duty Collector Desk</label><input value="Main Cash Counter Desk #1 (Auto-logged)" readonly style="background:#e2e8f0;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;color:#475569;"></div>';
    echo '</div>';

    // Primary Phone & Optional Email for Instant Receipt / SMS / Confirmation (Universal across all categories)
    echo '<div style="background:#f1f5f9;border:1px solid #e2e8f0;border-radius:12px;padding:14px;margin-top:16px;">';
    echo '<div style="font-size:12px;font-weight:800;color:#0f172a;margin-bottom:10px;display:flex;align-items:center;gap:6px;">';
    echo '<span>📱</span> Receipt & Payment Confirmation Notification:';
    echo '</div>';
    echo '<div class="field" style="margin-bottom:10px;">';
    echo '<label style="font-weight:700;color:#334155;font-size:12px;">Mobile Number (Primary SMS & WhatsApp Confirmation) *</label>';
    echo '<input type="tel" name="receipt_phone" required placeholder="017XXXXXXXX" value="' . e($inv['patient_mobile'] ?? '01711223344') . '" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;font-weight:600;">';
    echo '</div>';
    echo '<div class="field">';
    echo '<label style="font-weight:700;color:#334155;font-size:12px;">Email Address <small style="color:#64748b;font-weight:500;">(Optional - for digital e-Receipt copy)</small></label>';
    echo '<input type="email" name="receipt_email" placeholder="patient@example.com (optional)" value="' . e($inv['patient_email'] ?? '') . '" style="background:#fff;border:1px solid #cbd5e1;padding:10px 14px;border-radius:8px;width:100%;">';
    echo '</div>';
    echo '</div>';

    // Submit Button
    echo '<div style="margin-top:20px;">';
    echo '<button type="submit" id="checkoutSubmitBtn" class="button button-primary" style="width:100%;padding:14px;font-size:15px;font-weight:800;border-radius:12px;background:linear-gradient(135deg,#0c928c,#08756f);box-shadow:0 6px 20px rgba(12,146,140,0.3);">';
    echo 'Continue payment ❯';
    echo '</button>';
    echo '</div>';

    echo '<div style="text-align:center;margin-top:14px;">';
    echo '<a href="/index.php?page=billing&view=' . e($inv['id']) . '" style="color:#64748b;font-size:12px;text-decoration:none;font-weight:600;">← Go back</a>';
    echo '</div>';

    echo '</form>';
    echo '</div>'; // End Right Column

    echo '</div></div></div>'; // End Outer Card & Container

    echo '<script>
    function switchCheckoutTab(mode) {
        var modes = ["card", "ssl", "bank", "cash"];
        modes.forEach(function(m) {
            var pane = document.getElementById("pane_" + m);
            var btn = document.getElementById("tab_btn_" + m);
            if (pane) pane.style.display = (m === mode ? "block" : "none");
            if (btn) {
                var dot = btn.querySelector(".tab-radio-dot");
                var label = btn.querySelector("strong");
                if (m === mode) {
                    btn.style.borderColor = "#0c928c";
                    btn.style.backgroundColor = "#f0fdfa";
                    if (label) label.style.color = "#0c928c";
                    if (dot) {
                        dot.style.borderColor = "#0c928c";
                        dot.style.backgroundColor = "#0c928c";
                    }
                } else {
                    btn.style.borderColor = "#e2e8f0";
                    btn.style.backgroundColor = "#ffffff";
                    if (label) label.style.color = "#334155";
                    if (dot) {
                        dot.style.borderColor = "#cbd5e1";
                        dot.style.backgroundColor = "#ffffff";
                    }
                }
            }
        });
        document.getElementById("paymentChannelInput").value = mode;
        var submitBtn = document.getElementById("checkoutSubmitBtn");
        if (mode === "cash") {
            submitBtn.textContent = "Confirm Cash Payment ৳ ' . $dueFormatted . ' ❯";
            submitBtn.style.background = "linear-gradient(135deg, #059669, #047857)";
        } else if (mode === "ssl") {
            submitBtn.textContent = "Pay via SSLCommerz ৳ ' . $dueFormatted . ' ❯";
            submitBtn.style.background = "linear-gradient(135deg, #e2136e, #be123c)";
        } else {
            submitBtn.textContent = "Continue payment ❯";
            submitBtn.style.background = "linear-gradient(135deg, #0c928c, #08756f)";
        }
    }
    </script>';

    page_end();
}

function render_pharmacy_catalog(PDO $db, array $user): void
{
    Security::requirePermission($db, 'pharmacy.view');
    page_start($db, $user, 'pharmacy_catalog', 'Global Drug Catalog & Master Repository', 'National DGDA Bangladesh & WHO-ATC Drug Master Repository with <50ms Fuzzy Search');

    $q = trim((string) ($_GET['q'] ?? ''));
    $medicines = \Diagnostic\Pharmacy::searchGlobalMedicines($db, $q, 50);

    echo '<div style="display:flex;flex-direction:column;gap:20px;">';

    // Summary banner
    echo '<div style="background:linear-gradient(135deg,#047857,#065f46);color:white;border-radius:12px;padding:20px;box-shadow:0 8px 20px rgba(4,120,87,0.2);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:15px;">';
    echo '<div>';
    echo '<h3 style="margin:0 0 4px;font-size:18px;font-weight:800;">💊 DGDA National & Global Master Repository</h3>';
    echo '<p style="margin:0;font-size:13px;opacity:0.9;">Ingested 25,000+ Bangladesh approved drug brands with WHO-ATC taxonomy & cold-chain specs.</p>';
    echo '</div>';
    echo '<div style="display:flex;gap:12px;">';
    echo '<span style="background:rgba(255,255,255,0.2);padding:6px 14px;border-radius:20px;font-size:12px;font-weight:700;">⚡ Search Latency: < 50ms</span>';
    echo '<span style="background:rgba(255,255,255,0.2);padding:6px 14px;border-radius:20px;font-size:12px;font-weight:700;">🏷️ Auto-SKU Generator Active</span>';
    echo '</div></div>';

    // Search bar
    echo '<div class="card" style="padding:16px;">';
    echo '<form method="get" action="/index.php" style="display:flex;gap:12px;align-items:center;">';
    echo '<input type="hidden" name="page" value="pharmacy_catalog">';
    echo '<div class="field" style="flex:1;margin:0;">';
    echo '<input type="text" name="q" value="' . e($q) . '" placeholder="⚡ Fuzzy Search by Brand Name, Generic Name, Manufacturer, DAR No, or WHO-ATC Code..." style="font-size:15px;padding:10px 14px;border-radius:8px;">';
    echo '</div>';
    echo '<button class="button button-primary" style="padding:10px 20px;">🔍 Fuzzy Search</button>';
    if ($q !== '') {
        echo '<a href="/index.php?page=pharmacy_catalog" class="button button-secondary">Clear</a>';
    }
    echo '</form></div>';

    // Catalog Table
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:16px 20px;border-bottom:1px solid var(--border-color);display:flex;justify-content:space-between;align-items:center;background:#f9fafb;">';
    echo '<h4 style="margin:0;font-size:15px;color:#111827;">Global Master Medicines Catalog (' . count($medicines) . ' entries displayed)</h4>';
    echo '<small style="color:#6b7280;">Click "1-Click Clone to Stock" to immediately map medicine into Lutfunnesa Center Stock</small>';
    echo '</div>';

    echo '<div style="overflow-x:auto;"><table class="data-table" style="width:100%;margin:0;">';
    echo '<thead><tr>';
    echo '<th>Brand & Form</th>';
    echo '<th>Generic Name</th>';
    echo '<th>Strength</th>';
    echo '<th>Manufacturer</th>';
    echo '<th>DGDA DAR No</th>';
    echo '<th>WHO-ATC Code</th>';
    echo '<th>Storage Temp</th>';
    echo '<th>Indicative MRP</th>';
    echo '<th style="text-align:right;">Action</th>';
    echo '</tr></thead><tbody>';

    if (empty($medicines)) {
        echo '<tr><td colspan="9" style="text-align:center;padding:30px;color:#6b7280;">No medicines found matching "' . e($q) . '". Try a different search term.</td></tr>';
    } else {
        foreach ($medicines as $m) {
            $isColdChain = ($m['storage_temp'] ?? '') === '2°C - 8°C';
            echo '<tr>';
            echo '<td><strong style="color:#0f172a;font-size:14px;">' . e($m['brand_name']) . '</strong><br><small style="color:#64748b;">' . e($m['dosage_form'] ?? 'Tablet') . '</small></td>';
            echo '<td style="font-weight:600;color:#334155;">' . e($m['generic_name']) . '</td>';
            echo '<td>' . e($m['strength'] ?? '-') . '</td>';
            echo '<td style="color:#475569;">' . e($m['manufacturer']) . '</td>';
            echo '<td><span style="font-family:monospace;background:#f1f5f9;padding:2px 6px;border-radius:4px;font-size:12px;">' . e($m['dgda_dar_no'] ?? 'N/A') . '</span></td>';
            echo '<td><span style="font-family:monospace;background:#e0f2fe;color:#0369a1;padding:2px 6px;border-radius:4px;font-size:12px;">' . e($m['who_atc_code'] ?? 'N/A') . '</span></td>';
            echo '<td>';
            if ($isColdChain) {
                echo '<span style="background:#fef2f2;color:#dc2626;border:1px solid #fecaca;padding:3px 8px;border-radius:12px;font-size:11px;font-weight:700;">❄️ 2°C - 8°C Cold Chain</span>';
            } else {
                echo '<span style="color:#64748b;font-size:12px;">' . e($m['storage_temp'] ?? '25°C') . '</span>';
            }
            echo '</td>';
            echo '<td style="font-weight:700;color:#047857;">৳ ' . number_format((float)$m['indicative_mrp'], 2) . '</td>';
            echo '<td style="text-align:right;">';
            echo '<button class="button button-primary" style="padding:5px 12px;font-size:12px;background:#059669;border-color:#059669;" onclick="document.getElementById(\'clone_modal_' . $m['id'] . '\').style.display=\'flex\'">➕ 1-Click Clone to Stock</button>';

            // Modal for rack location setup on clone
            echo '<div id="clone_modal_' . $m['id'] . '" style="display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:9999;align-items:center;justify-content:center;">';
            echo '<div style="background:white;border-radius:12px;width:450px;padding:20px;text-align:left;box-shadow:0 20px 25px -5px rgba(0,0,0,0.2);">';
            echo '<h4 style="margin:0 0 10px;font-size:16px;color:#0f172a;">📍 Configure Stock Location for ' . e($m['brand_name']) . '</h4>';
            echo '<form method="post" action="/index.php?page=pharmacy_catalog">';
            echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
            echo '<input type="hidden" name="action" value="clone">';
            echo '<input type="hidden" name="global_medicine_id" value="' . e($m['id']) . '">';
            
            echo '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:10px;">';
            echo '<div><label style="font-size:11px;font-weight:700;">Rack No</label><input type="text" name="rack_number" value="R-01" style="padding:6px;font-size:13px;width:100%;"></div>';
            echo '<div><label style="font-size:11px;font-weight:700;">Shelf ID</label><input type="text" name="shelf_id" value="S-01" style="padding:6px;font-size:13px;width:100%;"></div>';
            echo '<div><label style="font-size:11px;font-weight:700;">Bin No</label><input type="text" name="bin_number" value="B-01" style="padding:6px;font-size:13px;width:100%;"></div>';
            echo '</div>';

            echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px;">';
            echo '<div><label style="font-size:11px;font-weight:700;">Reorder Level (ROL)</label><input type="number" name="reorder_level" value="50" style="padding:6px;font-size:13px;width:100%;"></div>';
            echo '<div><label style="font-size:11px;font-weight:700;">Unit Type</label><input type="text" name="unit_type" value="' . e($m['dosage_form'] ?? 'Box') . '" style="padding:6px;font-size:13px;width:100%;"></div>';
            echo '</div>';

            echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px;">';
            echo '<div><label style="font-size:11px;font-weight:700;">Purchase Price (৳)</label><input type="number" step="0.01" name="purchase_price" value="' . number_format((float)$m['indicative_mrp'] * 0.85, 2, '.', '') . '" style="padding:6px;font-size:13px;width:100%;"></div>';
            echo '<div><label style="font-size:11px;font-weight:700;">MRP Price (৳)</label><input type="number" step="0.01" name="mrp" value="' . number_format((float)$m['indicative_mrp'], 2, '.', '') . '" style="padding:6px;font-size:13px;width:100%;"></div>';
            echo '</div>';

            echo '<div style="display:flex;justify-content:flex-end;gap:8px;">';
            echo '<button type="button" class="button button-secondary" onclick="document.getElementById(\'clone_modal_' . $m['id'] . '\').style.display=\'none\'">Cancel</button>';
            echo '<button type="submit" class="button button-primary" style="background:#059669;border-color:#059669;">Confirm & Clone Item</button>';
            echo '</div>';
            echo '</form></div></div>';
            echo '</td>';
            echo '</tr>';
        }
    }

    echo '</tbody></table></div></div></div>';
    page_end();
}

