function render_pharmacy_pos(PDO $db, array $user): void
{
    Security::requirePermission($db, 'pharmacy.pos');
    page_start($db, $user, 'pharmacy_pos', 'Rapid POS Billing & Dispensing Counter', 'Keyboard-First Lightning Billing, 1D/2D Barcode Scanning, Strip/Piece Breakdown & Dual Cash Memos');

    $localItems = \Diagnostic\Pharmacy::listLocalItems($db);
    $diagTests = \Diagnostic\Pharmacy::listAvailableDiagnosticTests($db);
    $scheduleGLogs = \Diagnostic\Pharmacy::listScheduleGLogs($db);

    $prefilledName = trim((string)($_GET['patient_name'] ?? 'Walk-in Customer'));
    $prefilledUhid = trim((string)($_GET['patient_uhid'] ?? ''));
    $prefilledRxId = trim((string)($_GET['rx_id'] ?? ''));
    $prefilledDoctor = trim((string)($_GET['doctor_name'] ?? 'Dr. Chamber Specialist'));
    $prefilledBmdc = trim((string)($_GET['doctor_bmdc_no'] ?? 'A-55412'));

    $prefilledRxItems = [];
    if ($prefilledRxId !== '') {
        $rxDetails = \Diagnostic\Pharmacy::getPrescriptionDetails($db, (int)$prefilledRxId);
        if (!empty($rxDetails)) {
            if (!empty($rxDetails['patient_name'])) $prefilledName = $rxDetails['patient_name'];
            if (!empty($rxDetails['patient_uhid'])) $prefilledUhid = $rxDetails['patient_uhid'];
            if (!empty($rxDetails['doctor_name'])) $prefilledDoctor = $rxDetails['doctor_name'];
            if (!empty($rxDetails['doctor_reg_no'])) $prefilledBmdc = $rxDetails['doctor_reg_no'];
            $prefilledRxItems = $rxDetails['items'] ?? [];
        }
    }

    // Separate in-stock vs out-of-stock medicines
    $inStockMedicines = array_filter($localItems, fn($i) => (float)$i['total_stock'] > 0);
    $outOfStockMedicines = array_filter($localItems, fn($i) => (float)$i['total_stock'] <= 0);

    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Banner: Customer Type & Keyboard Shortcuts & Offline Mode Indicator
    echo '<div style="background:linear-gradient(135deg, #092c36 0%, #0f4854 50%, #0c928c 100%);color:white;border-radius:16px;padding:24px 28px;box-shadow:0 10px 30px rgba(9,44,54,0.3);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:18px;">';
    echo '<div>';
    echo '<h3 style="margin:0 0 6px;font-size:22px;font-weight:900;color:#ffffff;letter-spacing:-0.02em;">🛒 Rapid POS Billing & Dispensing Desk</h3>';
    echo '<p style="margin:0;font-size:13.5px;color:#c2e4e8;font-weight:500;line-height:1.5;">Supports Walk-in Local Customer OTC Purchases, Direct Diagnostic Lab Test Orders, Chamber E-Rx Dispensing & Split Cash Memos.</p>';
    echo '</div>';
    echo '<div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;">';
    echo '<a href="/index.php?page=pharmacy_receipt" class="button" style="background:#0284c7;color:#ffffff;border-radius:10px;font-weight:800;padding:11px 20px;display:inline-flex;align-items:center;gap:8px;box-shadow:0 4px 14px rgba(2,132,199,0.4);border:1px solid rgba(255,255,255,0.25);">📜 POS Vouchers Archive Register ↗</a>';
    echo '<span id="offline_status_badge" style="background:#10b981;color:#ffffff;padding:9px 18px;border-radius:20px;font-size:12.5px;font-weight:800;box-shadow:0 2px 8px rgba(0,0,0,0.25);border:1px solid rgba(255,255,255,0.3);">🟢 Online Central Sync</span>';
    if ($prefilledRxId !== '') {
        echo '<span style="background:#4338ca;color:#ffffff;padding:9px 18px;border-radius:20px;font-size:12.5px;font-weight:800;border:1.5px solid rgba(255,255,255,0.35);">🩺 Chamber E-Rx Dispense (Rx #' . e($prefilledRxId) . ')</span>';
    } else {
        echo '<span style="background:rgba(255,255,255,0.18);color:#ffffff;padding:9px 18px;border-radius:20px;font-size:12.5px;font-weight:800;border:1.5px solid rgba(255,255,255,0.35);backdrop-filter:blur(6px);">🚶 Direct Walk-in Local Customer (No Appt. Needed)</span>';
    }
    echo '</div></div>';

    // Walk-in Customer OTC & Direct Lab Test Notice Card
    echo '<div style="background:linear-gradient(135deg,#ecfdf5,#f0fdf4);border:1.5px solid #a7f3d0;border-radius:14px;padding:16px 20px;display:flex;align-items:center;justify-content:space-between;gap:16px;box-shadow:0 2px 10px rgba(16,185,129,0.06);">';
    echo '<div style="display:flex;gap:12px;align-items:center;">';
    echo '<div style="font-size:28px;">🏥</div>';
    echo '<div>';
    echo '<strong style="color:#065f46;font-size:14px;display:block;margin-bottom:2px;">Walk-in Local Customer Purchase & Direct Diagnostic Test Counter</strong>';
    echo '<span style="font-size:12px;color:#047857;">Local customers can buy medicines and order diagnostic lab tests directly at this counter without needing a doctor appointment. Separate cash memos (Pharmacy Cash Memo & Diagnostic Lab Cash Memo) are automatically issued upon billing.</span>';
    echo '</div></div>';
    echo '<span style="background:#10b981;color:white;padding:6px 12px;border-radius:8px;font-size:11px;font-weight:800;white-space:nowrap;">DIRECT OTC & LAB MODE ACTIVE</span>';
    echo '</div>';

    // Keyboard Shortcut Legend Bar
    echo '<div style="background:#1e293b;color:white;border-radius:12px;padding:14px 20px;display:flex;gap:16px;align-items:center;font-family:monospace;font-size:12px;overflow-x:auto;box-shadow:0 4px 12px rgba(30,41,59,0.15);">';
    echo '<strong style="color:#38bdf8;font-size:13px;">⌨️ KEYBOARD SHORTCUTS:</strong>';
    echo '<span style="background:#334155;padding:4px 10px;border-radius:6px;"><strong style="color:#facc15;">F1</strong> Search</span>';
    echo '<span style="background:#334155;padding:4px 10px;border-radius:6px;"><strong style="color:#facc15;">F2</strong> Add Item</span>';
    echo '<span style="background:#334155;padding:4px 10px;border-radius:6px;"><strong style="color:#facc15;">F4</strong> Discount</span>';
    echo '<span style="background:#334155;padding:4px 10px;border-radius:6px;"><strong style="color:#facc15;">F8</strong> Cash Pay</span>';
    echo '<span style="background:#334155;padding:4px 10px;border-radius:6px;"><strong style="color:#facc15;">F9</strong> bKash/Split</span>';
    echo '<span style="background:#059669;padding:4px 12px;border-radius:6px;box-shadow:0 2px 6px rgba(5,150,105,0.4);"><strong style="color:#ffffff;">F12</strong> Confirm & Print (10s)</span>';
    echo '</div>';

    // Main POS Container (Full Width Stack)
    echo '<div style="display:flex;flex-direction:column;gap:24px;">';

    // Datalist for autocomplete search (Medicines + Diagnostic Tests)
    echo '<datalist id="pos_items_datalist">';
    foreach ($localItems as $itm) {
        $stkStr = (float)$itm['total_stock'] > 0 ? ('Stock: ' . (float)$itm['total_stock'] . ' ' . $itm['unit_type']) : '❌ OUT OF STOCK';
        $strengthVal = !empty($itm['strength']) ? $itm['strength'] : '500mg';
        $schedGFlag = !empty($itm['is_schedule_g']) ? ' 🛑 [Schedule-G Narcotic]' : '';
        echo '<option value="' . e($itm['custom_name']) . ' [' . e($itm['sku_code']) . ']' . $schedGFlag . '" data-id="' . $itm['id'] . '" data-name="' . e(addslashes($itm['custom_name'])) . '" data-unit="' . e($itm['unit_type']) . '" data-mrp="' . $itm['mrp'] . '" data-stock="' . (float)$itm['total_stock'] . '" data-type="medicine" data-schedg="' . (!empty($itm['is_schedule_g']) ? 1 : 0) . '" data-pcsstrip="' . e((string)($itm['pieces_per_strip'] ?? 10)) . '">' . $stkStr . '</option>';
    }
    foreach ($diagTests as $t) {
        echo '<option value="[TEST] ' . e($t['name']) . ' (' . e($t['code']) . ')" data-id="' . $t['id'] . '" data-name="' . e(addslashes($t['name'])) . '" data-unit="Test" data-mrp="' . $t['price'] . '" data-stock="9999" data-type="diagnostic_test">🧪 Diagnostic Test @ ৳' . $t['price'] . '</option>';
    }
    echo '</datalist>';

    // Card 1: Search Medicines & Diagnostic Lab Tests Card
    echo '<div class="card" style="padding:24px;border-radius:16px;box-shadow:0 4px 20px rgba(0,0,0,0.03);margin:0;position:relative;">';
    echo '<h4 style="margin:0 0 14px;font-size:16px;color:#0f172a;display:flex;justify-content:space-between;align-items:center;"><span>⚡ Search Medicines & Diagnostic Lab Tests</span><span style="font-size:12px;color:#059669;font-weight:700;">Instant Live Search & 1D/2D Barcode Ready</span></h4>';
    echo '<div style="display:flex;gap:12px;position:relative;">';
    echo '<input type="text" id="pos_search" autocomplete="off" placeholder="Type medicine or test name (e.g. Napa, Ace, Sergel, CBC, X-Ray) or scan barcode..." style="font-size:15px;padding:12px 14px;border-radius:10px;flex:1;border:2px solid #059669;box-shadow:0 2px 8px rgba(5,150,105,0.08);" onkeydown="handlePosSearchKeydown(event)" oninput="handlePosLiveSearch(this.value)">';
    echo '<button type="button" class="button button-primary" style="padding:12px 20px;background:#059669;border-color:#059669;font-weight:700;border-radius:10px;box-shadow:0 4px 12px rgba(5,150,105,0.2);" onclick="addSelectedPosItem(true)">➕ Add Cart (F2)</button>';
