    // JavaScript logic for F1-F12 shortcuts, barcode scanner, unit breakdown & offline sync
    echo '<script>
    var posRowIndex = 100;
    var allLocalItems = ' . json_encode(array_values($localItems), JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) . ';
    var allDiagTests = ' . json_encode($diagTests, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) . ';

    // 16.1 F1-F12 Keyboard Shortcut Listener
    document.addEventListener("keydown", function(e) {
        var k = (e.key || "").toUpperCase();
        var code = (e.code || "").toUpperCase();
        if (k === "F1" || code === "F1") {
            e.preventDefault();
            var search = document.getElementById("pos_search");
            if (search) { search.focus(); search.select(); }
        } else if (k === "F2" || code === "F2") {
            e.preventDefault();
            addSelectedPosItem(true);
        } else if (k === "F4" || code === "F4") {
            e.preventDefault();
            var disc = document.getElementById("discount_amount_input");
            if (disc) { disc.focus(); disc.select(); }
        } else if (k === "F8" || code === "F8") {
            e.preventDefault();
            var sel = document.getElementById("payment_method_select");
            if (sel) sel.value = "CASH";
            var paid = document.getElementById("paid_amount_input");
            if (paid) { paid.focus(); paid.select(); }
        } else if (k === "F9" || code === "F9") {
            e.preventDefault();
            var sel = document.getElementById("payment_method_select");
            if (sel) sel.value = "BKASH";
            var paid = document.getElementById("paid_amount_input");
            if (paid) { paid.focus(); paid.select(); }
        } else if (k === "F12" || code === "F12") {
            e.preventDefault();
            var btn = document.getElementById("pos_submit_btn");
            if (btn) btn.click();
        }
    });

    // 16.4 Offline Mode Network Detector
    window.addEventListener("online", function() {
        var badge = document.getElementById("offline_status_badge");
        if (badge) {
            badge.innerText = "🟢 Online Central Sync";
            badge.style.background = "#dcfce7";
            badge.style.color = "#15803d";
        }
    });
    window.addEventListener("offline", function() {
        var badge = document.getElementById("offline_status_badge");
        if (badge) {
            badge.innerText = "🔴 Offline Mode (Local Cache Active)";
            badge.style.background = "#fef2f2";
            badge.style.color = "#dc2626";
        }
    });

    function escapeHtml(str) {
        if (!str) return "";
        return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
    }

    function triggerOosAlert(id, name) {
        var box = document.getElementById("oos_alert_box");
        var content = document.getElementById("oos_alert_content");
        if (!box || !content) return;

        var itemName = name || "Requested Item";
        var alts = allLocalItems.filter(function(i) {
            return i.id != id && parseFloat(i.total_stock) > 0;
        }).slice(0, 3);

        var html = "<div style=\"margin-bottom:8px;padding-bottom:6px;border-bottom:1px dashed #fde68a;\">";
        html += "<span style=\"background:#fef2f2;color:#dc2626;padding:3px 8px;border-radius:6px;font-weight:700;font-size:11px;\">❌ " + escapeHtml(itemName) + " (0 Pcs / OUT OF STOCK)</span>";
        if (alts.length > 0) {
            html += "<span style=\"margin-left:8px;font-size:11px;color:#15803d;font-weight:700;\">➔ Recommended In-Stock Alternatives:</span>";
            html += "<div style=\"display:flex;gap:6px;flex-wrap:wrap;margin-top:6px;\">";
            alts.forEach(function(alt) {
                html += "<button type=\"button\" class=\"button button-light\" style=\"font-size:11px;padding:4px 10px;border:1px solid #86efac;color:#166534;background:#ffffff;font-weight:700;border-radius:6px;cursor:pointer;\" onclick=\"addPosItemById(" + alt.id + ", \\\'medicine\\\')\">➕ Substitute with " + escapeHtml(alt.custom_name) + " [Stock: " + parseFloat(alt.total_stock) + " Pcs @ ৳" + parseFloat(alt.mrp).toFixed(2) + "]</button>";
            });
            html += "</div>";
        } else {
            html += "<span style=\"margin-left:8px;font-size:11px;color:#6b7280;\">No alternative mapped brands currently in stock.</span>";
        }
        html += "</div>";

        content.innerHTML = html;
        box.style.display = "block";
    }

    function addPosItemById(id, type) {
        if (type === "medicine") {
            var item = allLocalItems.find(function(i) { return i.id == id; });
            if (item) {
                addPosItem(item.id, item.custom_name, item.unit_type || "Strip", parseFloat(item.mrp || 0), "medicine", parseFloat(item.total_stock || 0), parseInt(item.is_schedule_g || 0), item.strength || "500mg");
            }
        } else if (type === "diagnostic_test") {
            var test = allDiagTests.find(function(t) { return t.id == id; });
            if (test) {
                addPosItem(test.id, test.name, "Test", parseFloat(test.price || 0), "diagnostic_test", 9999, 0, "N/A");
            }
        }
    }

    function addPosItem(id, name, unitType, mrp, type, stock, isSchedG, strength) {
        var body = document.getElementById("pos_cart_body");
        if (!body) return;

        if (type === "medicine" && stock !== undefined && stock <= 0) {
            triggerOosAlert(id, name);
            alert("⚠️ OUT OF STOCK ALERT: " + name + " (0 Pcs available).\nSubstitute in-stock alternatives have been loaded in the yellow recommendations box above.");
            return;
        }

        if (isSchedG) {
            alert("🛑 SCHEDULE-G NARCOTIC ALERT: " + name + " is a controlled sedative/narcotic!\nPlease ensure Doctor Name and BMDC Registration Number are verified.");
        }

        var stVal = strength || "500mg";
        var typeBadge = type === "diagnostic_test" ? "<span style=\"background:#e0e7ff;color:#3730a3;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;\">🧪 Test</span>" : "<span style=\"background:#e0f2fe;color:#0369a1;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;\">💊 Medicine</span>";
        var hiddenInputs = type === "diagnostic_test" ? 
            "<input type=\"hidden\" name=\"items[" + posRowIndex + "][type]\" value=\"diagnostic_test\"><input type=\"hidden\" name=\"items[" + posRowIndex + "][test_id]\" value=\"" + id + "\">" : 
            "<input type=\"hidden\" name=\"items[" + posRowIndex + "][type]\" value=\"medicine\"><input type=\"hidden\" name=\"items[" + posRowIndex + "][pharmacy_item_id]\" value=\"" + id + "\">";

        var strengthCol = type === "diagnostic_test" ? "<td><span style=\"color:#64748b;font-size:12px;\">N/A</span></td>" : "<td><select name=\"items[" + posRowIndex + "][strength]\" style=\"padding:6px;font-size:12px;border-radius:6px;border:1px solid #cbd5e1;\"><option value=\"" + stVal + "\" selected>" + stVal + "</option><option value=\"500mg\">500mg</option><option value=\"665mg\">665mg</option><option value=\"250mg\">250mg</option><option value=\"125mg\">125mg</option><option value=\"20mg\">20mg</option><option value=\"40mg\">40mg</option><option value=\"10mg\">10mg</option></select></td>";

        var unitCol = type === "diagnostic_test" ? "<td><span style=\"color:#64748b;font-size:12px;\">Test Order</span><input type=\"hidden\" name=\"items[" + posRowIndex + "][unit_type]\" value=\"Test\"></td>" : "<td><select name=\"items[" + posRowIndex + "][unit_type]\" style=\"padding:6px;font-size:13px;border-radius:6px;\" onchange=\"recalculatePosTotal()\"><option value=\"Strip\">Strip</option><option value=\"Box\">Box</option><option value=\"Pcs\">Pcs / Tablet</option></select></td>";

        var tr = document.createElement("tr");
        tr.id = "pos_row_" + posRowIndex;
        tr.innerHTML = "<td>" + typeBadge + "</td>" +
            "<td>" + hiddenInputs + "<strong>" + escapeHtml(name) + "</strong></td>" +
            strengthCol +
            unitCol +
            "<td><input type=\"number\" name=\"items[" + posRowIndex + "][quantity]\" value=\"1\" min=\"1\" class=\"pos-qty\" style=\"width:75px;padding:6px;font-size:14px;border-radius:6px;\" oninput=\"recalculatePosTotal()\"></td>" +
            "<td><div style=\"display:inline-flex;align-items:center;gap:4px;\"><span style=\"font-weight:700;color:#0f172a;\">৳</span><input type=\"number\" step=\"0.01\" name=\"items[" + posRowIndex + "][unit_price]\" value=\"" + mrp + "\" class=\"pos-price\" style=\"width:80px;padding:6px;font-size:14px;border-radius:6px;border:1px solid #cbd5e1;\" oninput=\"recalculatePosTotal()\"></div></td>" +
            "<td style=\"font-weight:700;color:#059669;vertical-align:middle;\"><div style=\"display:inline-flex;align-items:center;gap:4px;\"><span>৳</span><span class=\"pos-line-subtotal\">" + parseFloat(mrp).toFixed(2) + "</span></div></td>" +
            "<td><button type=\"button\" class=\"button button-secondary\" style=\"padding:4px 10px;color:#dc2626;border-radius:6px;\" onclick=\"this.closest(\'tr\').remove();recalculatePosTotal();\">✕</button></td>";
        body.appendChild(tr);
        posRowIndex++;
        recalculatePosTotal();
    }

    function handlePosSearchKeydown(e) {
        var box = document.getElementById("pos_autosuggest_box");
        var items = box ? box.querySelectorAll(".pos-suggest-item") : [];
        if (e.key === "ArrowDown") {
            e.preventDefault();
            if (items.length > 0) {
                var active = box.querySelector(".pos-suggest-item.active");
                var idx = -1;
                for (var i = 0; i < items.length; i++) {
                    if (items[i] === active) { idx = i; break; }
                }
                if (active) active.classList.remove("active");
                var nextIdx = (idx + 1) % items.length;
                items[nextIdx].classList.add("active");
                items[nextIdx].style.background = "#f0fdf4";
                items[nextIdx].scrollIntoView({ block: "nearest" });
            }
        } else if (e.key === "ArrowUp") {
            e.preventDefault();
            if (items.length > 0) {
                var active = box.querySelector(".pos-suggest-item.active");
                var idx = 0;
                for (var i = 0; i < items.length; i++) {
                    if (items[i] === active) { idx = i; break; }
                }
                if (active) active.classList.remove("active");
                var prevIdx = (idx - 1 + items.length) % items.length;
                items[prevIdx].classList.add("active");
                items[prevIdx].style.background = "#f0fdf4";
                items[prevIdx].scrollIntoView({ block: "nearest" });
            }
        } else if (e.key === "Enter") {
            e.preventDefault();
            var active = box ? box.querySelector(".pos-suggest-item.active") : null;
            if (active) {
                active.click();
            } else {
                addSelectedPosItem(true);
            }
        } else if (e.key === "Escape") {
            if (box) box.style.display = "none";
        }
    }

    function handlePosLiveSearch(val) {
        var box = document.getElementById("pos_autosuggest_box");
        if (!box) return;
        var query = (val || "").trim().toLowerCase();
        if (query.length === 0) {
            box.style.display = "none";
            box.innerHTML = "";
            return;
        }

        var results = [];

        // 1. Search Medicines
        for (var i = 0; i < allLocalItems.length; i++) {
            var m = allLocalItems[i];
            var cName = (m.custom_name || "").toLowerCase();
            var sku = (m.sku_code || "").toLowerCase();
            var gen = (m.generic_name || "").toLowerCase();
            var stk = parseFloat(m.total_stock || 0);

            if (cName.indexOf(query) !== -1 || sku.indexOf(query) !== -1 || gen.indexOf(query) !== -1) {
                results.push({
                    type: "medicine",
                    id: m.id,
                    name: m.custom_name,
                    subtext: (m.sku_code || "") + (gen ? " • " + gen : "") + " • Rack: " + (m.rack_number || "R-01"),
                    mrp: parseFloat(m.mrp || 0),
                    stock: stk,
                    unit: m.unit_type || "Strip",
                    isSchedG: parseInt(m.is_schedule_g || 0)
                });
            }
            if (results.length >= 10) break;
        }

        // 2. Search Diagnostic Tests
        for (var j = 0; j < allDiagTests.length; j++) {
            var t = allDiagTests[j];
            var tName = (t.name || "").toLowerCase();
            var tCode = (t.code || "").toLowerCase();

            if (tName.indexOf(query) !== -1 || tCode.indexOf(query) !== -1) {
                results.push({
                    type: "diagnostic_test",
                    id: t.id,
                    name: t.name,
                    subtext: "Code: " + t.code + " • Pathology LIS / Radiology Desk",
                    mrp: parseFloat(t.price || 0),
                    stock: 9999,
                    unit: "Test",
                    isSchedG: 0
                });
            }
            if (results.length >= 15) break;
        }

        if (results.length === 0) {
            box.innerHTML = "<div style=\"padding:14px 18px;color:#94a3b8;font-size:13px;text-align:center;\">🔍 No medicine or diagnostic test matching <strong>\"" + escapeHtml(val) + "\"</strong>.</div>";
            box.style.display = "block";
            return;
        }

        var html = "";
        for (var k = 0; k < results.length; k++) {
            var r = results[k];
            var isOos = (r.type === "medicine" && r.stock <= 0);
            var isG = r.isSchedG === 1;

            var tagBadge = r.type === "diagnostic_test" ? 
                "<span style=\"background:#e0e7ff;color:#3730a3;font-size:11px;font-weight:800;padding:2px 8px;border-radius:6px;\">🧪 TEST</span>" : 
                "<span style=\"background:#ecfdf5;color:#047857;font-size:11px;font-weight:800;padding:2px 8px;border-radius:6px;\">💊 MEDICINE</span>";

            var stockBadge = "";
            if (r.type === "medicine") {
                if (isOos) {
                    stockBadge = "<span style=\"background:#fef2f2;color:#dc2626;font-size:11px;font-weight:800;padding:2px 8px;border-radius:6px;\">❌ OUT OF STOCK</span>";
                } else {
                    stockBadge = "<span style=\"background:#f0fdf4;color:#166534;font-size:11px;font-weight:800;padding:2px 8px;border-radius:6px;\">Stock: " + r.stock + " " + escapeHtml(r.unit) + "</span>";
                }
            } else {
                stockBadge = "<span style=\"background:#eff6ff;color:#1d4ed8;font-size:11px;font-weight:800;padding:2px 8px;border-radius:6px;\">Instant Lab Order</span>";
            }

            var schedBadge = isG ? "<span style=\"background:#fef2f2;color:#991b1b;font-size:10px;font-weight:800;padding:2px 6px;border-radius:4px;margin-left:6px;\">🛑 SCHEDULE-G</span>" : "";

            html += "<div class=\"pos-suggest-item\" data-id=\"" + r.id + "\" data-type=\"" + r.type + "\" style=\"display:flex;justify-content:space-between;align-items:center;padding:12px 18px;border-bottom:1px solid #f1f5f9;cursor:pointer;transition:background 0.15s;\" onclick=\"selectPosSuggestItem(" + r.id + ", \'" + r.type + "\')\" onmouseover=\"this.style.background=\'#f8fafc\'\" onmouseout=\"if(!this.classList.contains(\'active\'))this.style.background=\'#ffffff\'\">";
            html += "<div>";
            html += "<div style=\"display:flex;align-items:center;gap:8px;margin-bottom:3px;\">" + tagBadge + "<strong style=\"font-size:14.5px;color:#0f172a;\">" + escapeHtml(r.name) + "</strong>" + schedBadge + "</div>";
            html += "<div style=\"font-size:12px;color:#64748b;\">" + escapeHtml(r.subtext) + "</div>";
            html += "</div>";
            html += "<div style=\"display:flex;align-items:center;gap:12px;\">";
            html += stockBadge;
            html += "<div style=\"font-weight:800;color:#059669;font-size:15px;min-width:70px;text-align:right;\">৳ " + r.mrp.toFixed(2) + "</div>";
            html += "</div>";
            html += "</div>";
        }

        box.innerHTML = html;
        box.style.display = "block";
    }

    function selectPosSuggestItem(id, type) {
        addPosItemById(id, type);
        var input = document.getElementById("pos_search");
        if (input) {
            input.value = "";
            input.focus();
        }
        var box = document.getElementById("pos_autosuggest_box");
        if (box) box.style.display = "none";
    }

    document.addEventListener("click", function(e) {
        var box = document.getElementById("pos_autosuggest_box");
        var search = document.getElementById("pos_search");
        if (box && search && !box.contains(e.target) && e.target !== search) {
            box.style.display = "none";
        }
    });

    function checkDatalistAutoAdd() {
        var input = document.getElementById("pos_search");
        if (!input || !input.value.trim()) return;
        var val = input.value.trim();
        
        var datalist = document.getElementById("pos_items_datalist");
        if (datalist && datalist.options) {
            for (var k = 0; k < datalist.options.length; k++) {
                if (datalist.options[k].value === val) {
                    addSelectedPosItem(false);
                    return;
                }
            }
        }
    }

    function addSelectedPosItem(isExplicit) {
        var input = document.getElementById("pos_search");
        if (!input || !input.value.trim()) return;
        var rawQuery = input.value.trim();
        var query = rawQuery.toLowerCase();
        
        // 1. Exact match against datalist options
        var datalist = document.getElementById("pos_items_datalist");
        if (datalist && datalist.options) {
            for (var k = 0; k < datalist.options.length; k++) {
                var opt = datalist.options[k];
                var optVal = (opt.value || "").toLowerCase();
                if (optVal === query || optVal.indexOf(query) !== -1 || query.indexOf(optVal) !== -1) {
                    var ds = opt.dataset;
                    if (ds && ds.id) {
                        addPosItemById(parseInt(ds.id), ds.type);
                        input.value = "";
                        input.focus();
                        return;
                    }
                }
            }
        }

        // 2. Search in allLocalItems (Medicines)
        var foundMed = allLocalItems.find(function(i) {
            var cName = (i.custom_name || "").toLowerCase();
            var sku = (i.sku_code || "").toLowerCase();
            return cName === query || sku === query || (rawQuery.indexOf("[" + i.sku_code + "]") !== -1);
        });

        if (!foundMed) {
            var cleanQuery = query.replace(/\[.*?\]/g, "").replace(/[^\w\s]/gi, "").trim();
            foundMed = allLocalItems.find(function(i) {
                var cName = (i.custom_name || "").toLowerCase();
                var sku = (i.sku_code || "").toLowerCase();
                var gen = (i.generic_name || "").toLowerCase();
                return (cName && cName.includes(query)) || (sku && sku.includes(query)) || (gen && gen.includes(query)) ||
                       (cleanQuery && cName && cName.includes(cleanQuery));
            });
        }

        if (foundMed) {
            addPosItemById(foundMed.id, "medicine");
            input.value = "";
            input.focus();
            return;
        }

        // 3. Search in allDiagTests (Diagnostic Tests)
        var foundTest = allDiagTests.find(function(t) {
            var tName = (t.name || "").toLowerCase();
            var tCode = (t.code || "").toLowerCase();
            return tName === query || tCode === query || query.includes(tName) || tName.includes(query) || (rawQuery.indexOf("(" + tCode + ")") !== -1);
        });

        if (!foundTest) {
            var cleanQueryTest = query.replace(/\[.*?\]/g, "").replace(/[^\w\s]/gi, "").trim();
            foundTest = allDiagTests.find(function(t) {
                var tName = (t.name || "").toLowerCase();
                var tCode = (t.code || "").toLowerCase();
                return (tName && tName.includes(cleanQueryTest)) || (tCode && tCode.includes(cleanQueryTest));
            });
        }

        if (foundTest) {
            addPosItemById(foundTest.id, "diagnostic_test");
            input.value = "";
            input.focus();
            return;
        }

        if (isExplicit) {
            alert("⚠️ No matching medicine or diagnostic test found for: \"" + rawQuery + "\".\nPlease select from the dropdown or search by medicine/test name.");
        }
    }

    function recalculatePosTotal() {
        var rows = document.querySelectorAll("#pos_cart_body tr");
        var grandTotal = 0;
        rows.forEach(function(r) {
            var qtyInput = r.querySelector(".pos-qty");
            var priceInput = r.querySelector(".pos-price");
            var subSpan = r.querySelector(".pos-line-subtotal");
            if (qtyInput && priceInput && subSpan) {
                var q = parseFloat(qtyInput.value) || 0;
                var p = parseFloat(priceInput.value) || 0;
                var sub = q * p;
                subSpan.innerText = sub.toFixed(2);
                grandTotal += sub;
            }
        });

        var discountInput = document.getElementById("discount_amount_input");
        var discount = discountInput ? (parseFloat(discountInput.value) || 0) : 0;
        var payable = Math.max(0, grandTotal - discount);

        var subText = document.getElementById("cart_subtotal_text");
        if (subText) subText.innerText = grandTotal.toFixed(2);

        var paidInput = document.getElementById("paid_amount_input");
        if (paidInput) paidInput.value = payable.toFixed(2);

        document.querySelectorAll(".pharm_receipt_total, .pharm_receipt_paid").forEach(function(el) {
            el.innerText = payable.toFixed(2);
        });
    }
    </script>';

    page_end();
}

function render_pharmacy_chamber_queue(PDO $db, array $user): void
{
    Security::requirePermission($db, 'pharmacy.view');
    page_start($db, $user, 'pharmacy_chamber_queue', 'Doctor Chamber E-Prescription Queue', 'Automatic E-Prescription Sync, UHID Queue & Schedule-G Narcotics Validation');

    $q = trim((string)($_GET['q'] ?? ''));
    $prescriptions = \Diagnostic\Pharmacy::listUnfulfilledPrescriptions($db, $q);

    echo '<div style="display:flex;flex-direction:column;gap:20px;">';

    // Banner
    echo '<div style="background:linear-gradient(135deg,#059669,#047857);color:white;border-radius:12px;padding:20px;box-shadow:0 8px 20px rgba(5,150,105,0.2);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:15px;">';
    echo '<div>';
    echo '<h3 style="margin:0 0 4px;font-size:18px;font-weight:800;">🩺 Chamber Doctor E-Prescription Live Feed</h3>';
    echo '<p style="margin:0;font-size:13px;opacity:0.9;">Unfulfilled chamber prescriptions automatically linked to patient UHID for immediate POS dispensing.</p>';
    echo '</div>';
    echo '<div><span style="background:rgba(255,255,255,0.2);padding:6px 14px;border-radius:20px;font-size:12px;font-weight:700;">🟢 Live Queue Active</span></div>';
    echo '</div>';

    // Search Box
    echo '<div class="card" style="padding:16px;">';
    echo '<form method="get" action="/index.php" style="display:flex;gap:12px;align-items:center;">';
    echo '<input type="hidden" name="page" value="pharmacy_chamber_queue">';
    echo '<div style="flex:1;margin:0;">';
    echo '<input type="text" name="q" value="' . e($q) . '" placeholder="🔍 Search E-Prescriptions by Patient Name, Patient UHID, Rx Number (e.g. RX-LUDC-2026-0001), or Doctor Name..." style="font-size:15px;padding:10px 14px;border-radius:8px;width:100%;border:1px solid #cbd5e1;">';
    echo '</div>';
    echo '<button class="button button-primary" style="padding:10px 20px;background:#059669;border-color:#059669;font-weight:700;">🔍 Search Queue</button>';
    if ($q !== '') {
        echo '<a href="/index.php?page=pharmacy_chamber_queue" class="button button-secondary" style="padding:10px 16px;">Clear Search</a>';
    }
    echo '</form></div>';

    // Unfulfilled E-Prescriptions Cards / Table
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:16px 20px;background:#f9fafb;border-bottom:1px solid #e5e7eb;display:flex;justify-content:space-between;align-items:center;">';
    echo '<h4 style="margin:0;font-size:15px;color:#111827;">Unfulfilled Chamber Prescriptions (' . count($prescriptions) . ' pending)</h4>';
    if ($q !== '') {
        echo '<small style="color:#059669;font-weight:700;">Filtered by: "' . e($q) . '"</small>';
    }
    echo '</div>';

    if (empty($prescriptions)) {
        echo '<div style="text-align:center;padding:40px;color:#6b7280;">No unfulfilled chamber prescriptions matching search query.</div>';
    } else {
        foreach ($prescriptions as $rx) {
            echo '<div style="padding:20px;border-bottom:1px solid #f1f5f9;display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:15px;">';
            echo '<div style="flex:1;min-width:300px;">';
            echo '<div style="display:flex;gap:10px;align-items:center;margin-bottom:6px;flex-wrap:wrap;">';
            echo '<span style="font-family:monospace;font-weight:700;color:#059669;background:#ecfdf5;padding:3px 8px;border-radius:6px;border:1px solid #a7f3d0;">' . e($rx['rx_no']) . '</span>';
            echo '<span style="font-weight:800;color:#0f172a;font-size:16px;">' . e($rx['patient_name']) . '</span>';
            echo '<span style="background:#f1f5f9;color:#475569;padding:2px 8px;border-radius:4px;font-size:12px;font-weight:700;">UHID: ' . e($rx['patient_uhid']) . '</span>';
            echo '</div>';
            echo '<div style="font-size:13px;color:#64748b;margin-bottom:14px;">Prescribed by: <strong style="color:#334155;">' . e($rx['doctor_name']) . '</strong> (BMDC Reg: ' . e($rx['doctor_reg_no']) . ')</div>';

            echo '<table style="width:100%;font-size:13px;border-collapse:collapse;margin-bottom:10px;">';
            echo '<tr style="background:#f8fafc;color:#475569;text-align:left;"><th style="padding:8px;">Prescribed Medicine Item</th><th style="padding:8px;">Dosage Instruction</th><th style="padding:8px;">Duration</th><th style="padding:8px;">Prescribed Qty</th><th style="padding:8px;">Stock Status & Alternative Suggestion</th></tr>';
            foreach ($rx['items'] as $item) {
                $stock = (float)($item['available_stock'] ?? 0);
                $isAvailable = $stock > 0;

                echo '<tr style="border-bottom:1px solid #f1f5f9;">';
                echo '<td style="padding:8px;font-weight:600;color:#0f172a;">' . e($item['custom_name']) . '<br><small style="color:#64748b;">Generic: ' . e($item['generic_name'] ?? 'N/A') . '</small></td>';
                echo '<td style="padding:8px;color:#475569;">' . e($item['dosage_instruction']) . '</td>';
                echo '<td style="padding:8px;">' . e((string)$item['duration_days']) . ' days</td>';
                echo '<td style="padding:8px;font-weight:700;color:#0f172a;">' . e((string)$item['quantity']) . ' Pcs</td>';
                echo '<td style="padding:8px;">';
                if ($isAvailable) {
                    echo '<span style="background:#dcfce7;color:#15803d;padding:4px 10px;border-radius:12px;font-weight:700;font-size:12px;display:inline-block;">✅ In Stock (' . $stock . ' Pcs)</span>';
                } else {
                    echo '<span style="background:#fef2f2;color:#dc2626;border:1px solid #fecaca;padding:4px 10px;border-radius:12px;font-weight:800;font-size:12px;display:inline-block;">❌ Out of Stock (0 Pcs)</span>';
                    if (!empty($item['alternatives'])) {
                        echo '<div style="margin-top:6px;background:#f0fdf4;border:1px solid #bbf7d0;padding:8px 10px;border-radius:8px;font-size:12px;color:#166534;">';
                        echo '<strong style="display:block;margin-bottom:4px;">💡 Recommended In-Stock Alternatives:</strong>';
                        echo '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
                        foreach ($item['alternatives'] as $alt) {
                            echo '<span style="background:white;border:1px solid #86efac;padding:3px 8px;border-radius:6px;font-weight:700;color:#15803d;">➕ ' . e($alt['custom_name']) . ' (' . e($alt['manufacturer'] ?? 'Square') . ') — Stock: ' . (float)$alt['total_stock'] . ' Pcs @ ৳' . number_format((float)$alt['mrp'], 2) . '</span>';
                        }
                        echo '</div></div>';
                    }
                }
                echo '</td>';
                echo '</tr>';
            }
            echo '</table></div>';

            echo '<div style="text-align:right;align-self:flex-start;">';
            echo '<form method="get" action="/index.php">';
            echo '<input type="hidden" name="page" value="pharmacy_pos">';
            echo '<input type="hidden" name="rx_id" value="' . e($rx['id']) . '">';
            echo '<input type="hidden" name="patient_name" value="' . e($rx['patient_name']) . '">';
            echo '<input type="hidden" name="patient_uhid" value="' . e($rx['patient_uhid']) . '">';
            echo '<button class="button button-primary" style="padding:12px 20px;background:#059669;border-color:#059669;font-weight:800;font-size:14px;box-shadow:0 4px 14px rgba(5,150,105,0.3);">⚡ Dispense via POS Billing</button>';
            echo '</form>';
            echo '</div></div>';
        }
    }

    echo '</div></div>';
    page_end();
}

