    echo '</form></div>';

    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:14px 18px;background:#f8fafc;border-bottom:1px solid #e2e8f0;"><strong style="color:#0f172a;">🏢 Approved Pharma Suppliers Directory</strong></div>';
