        echo '<td>' . e($sup['contact_person']) . '</td>';
        echo '<td>' . e($sup['phone']) . '</td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></div>';

    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:14px 18px;background:#f8fafc;border-bottom:1px solid #e2e8f0;"><strong style="color:#0f172a;">📋 Issued Purchase Orders & Goods Received Notes (GRN)</strong></div>';
