    echo '<div class="card" style="padding:20px;">';
    echo '<h4 style="margin:0 0 14px;font-size:16px;color:#0f172a;">🌡️ Morning & Evening Temperature Log Checklist</h4>';
    echo '<form method="post" action="/index.php?page=pharmacy_coldchain">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<input type="hidden" name="action" value="log_temp">';

    echo '<div class="field" style="margin-bottom:12px;"><label style="font-weight:600;">Storage Refrigerator Bay *</label><select name="storage_unit" style="padding:8px;font-size:14px;"><option>Main Insulin Cold-Bay Ref-01</option><option>Insulin Deep-Freeze Bay-02</option><option>Vaccine Storage Bay-03</option></select></div>';
    echo '<div class="field" style="margin-bottom:12px;"><label style="font-weight:600;">Log Shift Checklist *</label><select name="shift" style="padding:8px;font-size:14px;"><option value="AM_CHECKLIST">🌅 Morning AM Checklist (09:00 AM)</option><option value="PM_CHECKLIST">🌆 Evening PM Checklist (06:00 PM)</option></select></div>';
    echo '<div class="field" style="margin-bottom:16px;"><label style="font-weight:600;">Recorded Temperature (°C) *</label><input type="number" step="0.1" name="temperature" value="4.2" required style="padding:8px;font-size:16px;font-weight:700;color:#0284c7;"></div>';

    echo '<button class="button button-primary" style="width:100%;padding:10px;background:#0284c7;border-color:#0284c7;font-weight:800;">💾 Submit Temperature Log Checklist</button>';
    echo '</form></div>';

    // Quarantine & Return-To-Vendor (RTV) Workflow
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:14px 18px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;">';
    echo '<strong style="color:#0f172a;font-size:15px;">⚠️ Quarantine Register & Maker-Checker Workflow</strong>';
    echo '<span style="font-size:11px;color:#dc2626;font-weight:700;">Auditable Isolation & RTV Debit Notes</span>';
    echo '</div>';

    echo '<table class="data-table" style="width:100%;margin:0;">';
    echo '<thead><tr><th>Ticket No</th><th>Medicine Item</th><th>Qty</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody>';
    if (empty($quarantines)) {
        echo '<tr><td colspan="6" style="text-align:center;padding:20px;color:#6b7280;">No items currently in quarantine register.</td></tr>';
    } else {
        foreach ($quarantines as $q) {
            echo '<tr>';
            echo '<td><span style="font-family:monospace;font-weight:700;color:#dc2626;">' . e($q['ticket_no']) . '</span></td>';
            echo '<td>' . e($q['custom_name']) . '</td>';
            echo '<td>' . e((string)$q['quantity']) . ' Pcs</td>';
            echo '<td><span style="background:#fef2f2;color:#dc2626;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:700;">' . e(strtoupper($q['reason'])) . '</span></td>';
            echo '<td><span style="background:#f1f5f9;color:#475569;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;">' . e(strtoupper($q['status'])) . '</span></td>';
            echo '<td>';
            if ($q['status'] === 'pending') {
                echo '<form method="post" action="/index.php?page=pharmacy_coldchain" style="display:inline;">';
                echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
                echo '<input type="hidden" name="action" value="approve_quarantine">';
                echo '<input type="hidden" name="ticket_id" value="' . e($q['id']) . '">';
                echo '<input type="hidden" name="decision" value="returned_to_vendor">';
                echo '<button class="button button-primary" style="padding:4px 8px;font-size:11px;background:#dc2626;border-color:#dc2626;">Approve & Issue RTV Debit Note</button>';
                echo '</form>';
            } else {
                echo '<span style="color:#059669;font-weight:700;font-size:12px;">✅ Processed</span>';
            }
            echo '</td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div></div>';

    // RTV Debit Notes Table
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:14px 18px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;">';
    echo '<strong style="color:#0f172a;font-size:15px;">📜 Return-To-Vendor (RTV) Debit Notes Register</strong>';
    echo '<span style="font-size:12px;color:#059669;font-weight:700;">Formal Vendor Debit Adjustment Vouchers</span>';
    echo '</div>';
    echo '<div style="overflow-x:auto;"><table class="data-table" style="width:100%;margin:0;">';
    echo '<thead><tr><th>RTV Voucher No</th><th>Supplier</th><th>Item Custom Name</th><th>Batch No</th><th>Quantity</th><th>Unit Cost</th><th>Total Debit Amount</th><th>Issued Date</th></tr></thead><tbody>';
    if (empty($rtvNotes)) {
        echo '<tr><td colspan="8" style="text-align:center;padding:25px;color:#6b7280;">No Return-to-Vendor Debit Notes issued yet. Approved quarantine tickets automatically generate RTV Debit Notes.</td></tr>';
    } else {
        foreach ($rtvNotes as $rtv) {
            echo '<tr>';
            echo '<td><span style="font-family:monospace;font-weight:700;color:#dc2626;background:#fef2f2;padding:3px 8px;border-radius:4px;border:1px solid #fecaca;">' . e($rtv['rtv_no']) . '</span></td>';
            echo '<td><strong>' . e($rtv['supplier_name']) . '</strong></td>';
            echo '<td>' . e($rtv['custom_name']) . '</td>';
            echo '<td><span style="font-family:monospace;">' . e($rtv['batch_number']) . '</span></td>';
            echo '<td>' . e((string)$rtv['quantity']) . ' Pcs</td>';
            echo '<td>৳ ' . number_format((float)$rtv['unit_cost'], 2) . '</td>';
            echo '<td style="font-weight:800;color:#dc2626;">৳ ' . number_format((float)$rtv['total_debit_amount'], 2) . '</td>';
            echo '<td>' . e(substr($rtv['created_at'], 0, 10)) . '</td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div></div></div>';

    page_end();
}

