            echo '<td>' . e(substr($ret['created_at'], 0, 16)) . '</td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div></div>';

    page_end();
}

/**
 * PHASE 18 Views: Hypercare Dashboard, Concurrency Audit, Cost Security & Physical Stock Cutover
 */
function render_pharmacy_hypercare(PDO $db, array $user): void
{
    Security::requirePermission($db, 'pharmacy.view');
    page_start($db, $user, 'pharmacy_hypercare', '14-Day Hypercare, Concurrency & Security Desk', 'Live Multi-Counter Stress Audit, Cost Margin Security & SOP Training Dashboard');

    $hypercare = \Diagnostic\Pharmacy::getHypercareDashboardMetrics($db);
    $canViewCost = \Diagnostic\Security::canViewFinancialCosts($db);

    $concurrencyResult = null;
    if (!empty($_POST['action']) && $_POST['action'] === 'run_concurrency_test') {
        $sku = trim((string)($_POST['sku'] ?? 'MED-NAPA-500'));
        $counters = (int)($_POST['counters'] ?? 5);
        $concurrencyResult = \Diagnostic\Pharmacy::runConcurrencyStressTest($db, $sku, $counters);
    }

    echo '<div style="display:flex;flex-direction:column;gap:20px;">';

    // Banner
    echo '<div style="background:linear-gradient(135deg,#0f172a,#1e293b);color:white;border-radius:12px;padding:20px;box-shadow:0 8px 20px rgba(15,23,42,0.2);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:15px;">';
    echo '<div>';
    echo '<h3 style="margin:0 0 4px;font-size:18px;font-weight:800;">🛡️ 14-Day On-Site Hypercare & Security Operations Hub</h3>';
    echo '<p style="margin:0;font-size:13px;opacity:0.9;">Real-time multi-counter stress lock checks, cashier cost margin masking, SOP training cheat sheets & live daily audits.</p>';
    echo '</div>';
    echo '<div style="display:flex;gap:10px;align-items:center;">';
    echo '<span style="background:#10b981;color:white;padding:6px 14px;border-radius:20px;font-size:12px;font-weight:800;">🟢 HYPERCARE ACTIVE: DAY ' . $hypercare['current_day'] . ' OF 14</span>';
    echo '</div></div>';

    // Dashboard Metrics Cards
    echo '<div style="display:grid;grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));gap:16px;">';
    echo '<div style="background:#f0f9ff;border:1px solid #bae6fd;padding:16px;border-radius:12px;">';
    echo '<small style="color:#0284c7;font-weight:800;">TODAY POS TRANSACTIONS</small>';
    echo '<div style="font-size:26px;font-weight:900;color:#0369a1;margin:4px 0;">' . $hypercare['today_sales_count'] . ' Receipts</div>';
    echo '<small style="color:#0369a1;">Live Counter Activity</small>';
    echo '</div>';

    echo '<div style="background:#f0fdf4;border:1px solid #bbf7d0;padding:16px;border-radius:12px;">';
    echo '<small style="color:#166534;font-weight:800;">TODAY COUNTER SALES</small>';
    echo '<div style="font-size:26px;font-weight:900;color:#15803d;margin:4px 0;">৳ ' . number_format($hypercare['today_sales_revenue'], 2) . '</div>';
    echo '<small style="color:#166534;">Verified Shift Cash</small>';
    echo '</div>';

    echo '<div style="background:#fefce8;border:1px solid #fef9c3;padding:16px;border-radius:12px;">';
    echo '<small style="color:#ca8a04;font-weight:800;">ACTIVE POS COUNTERS</small>';
    echo '<div style="font-size:26px;font-weight:900;color:#a16207;margin:4px 0;">' . $hypercare['active_counters'] . ' Counters Online</div>';
    echo '<small style="color:#854d0e;">Central DB Sync Active</small>';
    echo '</div>';

    echo '<div style="background:#faf5ff;border:1px solid #e9d5ff;padding:16px;border-radius:12px;">';
    echo '<small style="color:#7e22ce;font-weight:800;">ZERO-OVERSELL STOCK LOCK</small>';
    echo '<div style="font-size:22px;font-weight:900;color:#6b21a8;margin:4px 0;">' . $hypercare['zero_oversell_lock'] . '</div>';
    echo '<small style="color:#6b21a8;">Isolation: FOR UPDATE</small>';
    echo '</div>';
    echo '</div>';

    // Concurrency & Multi-Counter Stress Testing Widget
    echo '<div style="display:grid;grid-template-columns: 1fr 1fr;gap:20px;">';
    echo '<div class="card" style="padding:20px;">';
    echo '<h4 style="margin:0 0 8px;font-size:16px;color:#0f172a;">⚡ Concurrency & Multi-Counter Stress Test Engine</h4>';
    echo '<p style="font-size:12px;color:#64748b;margin-bottom:14px;">Simulate simultaneous multi-counter checkout attempts on identical stock batches to verify atomic zero-oversell locks.</p>';
    echo '<form method="post" action="/index.php?page=pharmacy_hypercare">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<input type="hidden" name="action" value="run_concurrency_test">';

    echo '<div class="field" style="margin-bottom:10px;"><label style="font-weight:600;">Target Stock Item / SKU Code *</label><input type="text" name="sku" value="Napa 500mg" required style="padding:8px;font-size:13px;"></div>';
    echo '<div class="field" style="margin-bottom:14px;"><label style="font-weight:600;">Simulated POS Counters</label><select name="counters" style="padding:8px;font-size:13px;"><option value="3">3 Concurrent Counters</option><option value="5" selected>5 Concurrent Counters</option><option value="10">10 Concurrent Counters</option></select></div>';

    echo '<button class="button button-primary" style="width:100%;padding:10px;background:#0f172a;border-color:#0f172a;font-weight:800;">🚀 Execute Atomic Stock Lock Stress Audit</button>';
    echo '</form>';

    if ($concurrencyResult) {
        echo '<div style="margin-top:14px;background:#ecfdf5;border:1px solid #a7f3d0;padding:12px 14px;border-radius:8px;font-size:13px;">';
        echo '<strong style="color:#065f46;display:block;">✅ Audit Result: ' . e($concurrencyResult['result_status']) . '</strong>';
        echo '<span style="color:#047857;font-size:12px;">Item: ' . e($concurrencyResult['item_name']) . ' | Available Stock: ' . $concurrencyResult['available_qty'] . ' Pcs | Attempted: ' . $concurrencyResult['total_attempted_qty'] . ' Pcs across ' . $concurrencyResult['simulated_counters'] . ' counters. Hard lock active!</span>';
        echo '</div>';
    }
    echo '</div>';

    // Role-Based Security & Cost Margin Masking Status Card
    echo '<div class="card" style="padding:20px;">';
    echo '<h4 style="margin:0 0 8px;font-size:16px;color:#0f172a;">🔐 Role-Based Cost Margin Masking Security</h4>';
    echo '<p style="font-size:12px;color:#64748b;margin-bottom:14px;">Ensures counter cashiers and junior staff cannot view supplier purchase costs or gross margins on POS screens.</p>';

    echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;padding:14px;border-radius:8px;margin-bottom:12px;">';
    echo '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
    echo '<span style="font-size:13px;font-weight:700;color:#334155;">Active User Account:</span>';
    echo '<strong style="color:#0f172a;">' . e($user['name']) . '</strong>';
    echo '</div>';
    echo '<div style="display:flex;justify-content:space-between;align-items:center;">';
    echo '<span style="font-size:13px;font-weight:700;color:#334155;">Cost Margin Access Permission:</span>';
    if ($canViewCost) {
        echo '<span style="background:#dcfce7;color:#15803d;padding:4px 10px;border-radius:12px;font-size:12px;font-weight:800;">🔓 Authorized (Admin / Manager)</span>';
    } else {
        echo '<span style="background:#fef2f2;color:#dc2626;padding:4px 10px;border-radius:12px;font-size:12px;font-weight:800;">🔒 Restricted (Cashier Masked)</span>';
    }
    echo '</div></div>';

    echo '<table style="width:100%;font-size:12px;border-collapse:collapse;" border="1" borderColor="#e2e8f0">';
    echo '<tr style="background:#f1f5f9;"><th style="padding:6px;">Role</th><th style="padding:6px;">Purchase Rate</th><th style="padding:6px;">Gross Margin</th><th style="padding:6px;">MRP Price</th></tr>';
    echo '<tr><td style="padding:6px;">👨‍💼 Administrator / Store Manager</td><td style="padding:6px;color:#059669;font-weight:700;">Visible (৳ 42.50)</td><td style="padding:6px;color:#059669;font-weight:700;">Visible (15.0%)</td><td style="padding:6px;font-weight:700;">Visible (৳ 50.00)</td></tr>';
    echo '<tr><td style="padding:6px;">🧑‍💻 Counter Cashier / Pharmacist</td><td style="padding:6px;color:#dc2626;font-weight:700;">🔒 Restricted</td><td style="padding:6px;color:#dc2626;font-weight:700;">🔒 Restricted</td><td style="padding:6px;font-weight:700;">Visible (৳ 50.00)</td></tr>';
    echo '</table>';
    echo '</div></div>';

    // Pharmacist & Cashier Training SOP Guide & Cheat Sheet
    echo '<div class="card" style="padding:20px;">';
    echo '<h4 style="margin:0 0 12px;font-size:16px;color:#0f172a;">🎓 Pharmacist & Cashier Hands-On Training SOP Guide</h4>';
    echo '<div style="display:grid;grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));gap:14px;">';

    echo '<div style="background:#f8fafc;border:1px solid #cbd5e1;padding:14px;border-radius:8px;">';
    echo '<strong style="color:#0f172a;font-size:13px;display:block;margin-bottom:6px;">⌨️ Keyboard POS Shortcuts</strong>';
    echo '<ul style="margin:0;padding-left:18px;font-size:12px;color:#334155;line-height:1.6;">';
    echo '<li><strong style="color:#0284c7;">F1</strong>: Search Medicine Focus</li>';
    echo '<li><strong style="color:#059669;">F2</strong>: Quick Cash Payment</li>';
    echo '<li><strong style="color:#d97706;">F3</strong>: Discount Field Focus</li>';
    echo '<li><strong style="color:#7c3aed;">F8</strong>: Load Chamber E-Rx Queue</li>';
    echo '<li><strong style="color:#2563eb;">F9</strong>: Split Card/MFS Payment</li>';
    echo '<li><strong style="color:#dc2626;">F12</strong>: Clear Current Cart</li>';
    echo '</ul></div>';

    echo '<div style="background:#f8fafc;border:1px solid #cbd5e1;padding:14px;border-radius:8px;">';
    echo '<strong style="color:#0f172a;font-size:13px;display:block;margin-bottom:6px;">📦 Strip vs Piece Calculation SOP</strong>';
    echo '<p style="font-size:12px;color:#334155;margin:0;line-height:1.5;">When selling single tablets or strips cut from a box, select "Strip" or "Piece" in cart dropdown. System converts stock deduction automatically based on master strip ratio.</p>';
    echo '</div>';

    echo '<div style="background:#f8fafc;border:1px solid #cbd5e1;padding:14px;border-radius:8px;">';
    echo '<strong style="color:#0f172a;font-size:13px;display:block;margin-bottom:6px;">📝 Shift Closing SOP Checklist</strong>';
    echo '<ol style="margin:0;padding-left:18px;font-size:12px;color:#334155;line-height:1.6;">';
    echo '<li>Count physical cash drawer</li>';
    echo '<li>Enter declared count in Shift Desk</li>';
    echo '<li>Check variance against expected</li>';
    echo '<li>Request Supervisor Sign-Off</li>';
    echo '</ol></div>';

    echo '</div></div>';

    // Hypercare Daily Monitoring Log Table
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:14px 18px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;">';
    echo '<strong style="color:#0f172a;font-size:15px;">📜 14-Day Hypercare On-Site Audit Trail Log</strong>';
    echo '<span style="font-size:12px;color:#059669;font-weight:700;">Daily Shift Reconciliation & System Integrity</span>';
    echo '</div>';
    echo '<div style="overflow-x:auto;"><table class="data-table" style="width:100%;margin:0;">';
    echo '<thead><tr><th>Date</th><th>Day #</th><th>Daily Sales Count</th><th>Daily Total</th><th>Cash Variance</th><th>Stock Sync</th><th>Auditor</th><th>Notes</th></tr></thead><tbody>';
    if (empty($hypercare['recent_logs'])) {
        echo '<tr><td colspan="8" style="text-align:center;padding:20px;color:#6b7280;">No hypercare audit entries logged yet.</td></tr>';
    } else {
        foreach ($hypercare['recent_logs'] as $lg) {
            echo '<tr>';
            echo '<td>' . e($lg['log_date']) . '</td>';
            echo '<td><span style="background:#e0e7ff;color:#3730a3;padding:2px 8px;border-radius:10px;font-weight:800;">Day ' . e((string)$lg['hypercare_day']) . '</span></td>';
            echo '<td>' . e((string)$lg['daily_sales_count']) . ' Orders</td>';
            echo '<td><strong>৳ ' . number_format((float)$lg['daily_sales_total'], 2) . '</strong></td>';
            echo '<td><span style="background:#dcfce7;color:#15803d;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:800;">' . e($lg['cash_variance_status']) . '</span></td>';
            echo '<td><span style="background:#d0f4de;color:#0b6623;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:800;">' . e($lg['inventory_sync_status']) . '</span></td>';
            echo '<td>' . e($lg['auditor_name']) . '</td>';
            echo '<td>' . e($lg['notes']) . '</td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div></div>';

    echo '</div>';
    page_end();
}

function render_pharmacy_cutover(PDO $db, array $user): void
{
    Security::requirePermission($db, 'pharmacy.manage');
    page_start($db, $user, 'pharmacy_cutover', 'Physical Stock Migration & Barcode Sticker Printing Desk', 'Bulk Cutover Opening Stock Import & Customized Thermal Barcode Sticker Generator');

    $sampleItem = \Diagnostic\Pharmacy::getBarcodeStickerData($db, 1);

