/**
 * Phase 19 Clinical Decision Support (CDSS) & Safety Desk View
 */
function render_pharmacy_clinical_cdss(PDO $db, array $user): void
{
    Security::requirePermission($db, 'pharmacy.view');
    page_start($db, $user, 'pharmacy_clinical_cdss', 'Clinical Safety, CDSS & Laboratory Interoperability Desk', 'Drug-Drug Interactions (DDI), Duplicate Class Flags, Patient Allergy Blocks, LIS Lab Binding & Pediatric Calculator');

    $testGenerics = isset($_POST['generics']) ? explode(',', (string)$_POST['generics']) : ['Warfarin', 'Aspirin'];
    $uhid = trim((string)($_POST['uhid'] ?? 'UHID-10001'));
    $pediatricDrug = trim((string)($_POST['pediatric_drug'] ?? 'Paracetamol Syrup'));
    $weightKg = (float)($_POST['weight_kg'] ?? 12.5);
    $ageMonths = (int)($_POST['age_months'] ?? 24);

    $ddiInteractions = \Diagnostic\Pharmacy::checkDrugInteractions($db, $testGenerics);
    $allergyAlerts = \Diagnostic\Pharmacy::checkPatientAllergies($db, $uhid, $testGenerics);
    $lisLabAlerts = \Diagnostic\Pharmacy::checkPatientLISLabBindings($db, $uhid, $testGenerics);
    $pediatricCalc = \Diagnostic\Pharmacy::calculatePediatricDosage($pediatricDrug, $weightKg, $ageMonths);

    $stmtItems = $db->query('SELECT id FROM pharmacy_items LIMIT 5');
    $sampleItemIds = $stmtItems->fetchAll(PDO::FETCH_COLUMN);
    $duplicateClassAlerts = \Diagnostic\Pharmacy::checkDuplicateTherapyClass($db, $sampleItemIds);

    echo '<div style="display:flex;flex-direction:column;gap:20px;">';

    // Banner
    echo '<div style="background:linear-gradient(135deg,#059669,#047857);color:white;border-radius:12px;padding:20px;box-shadow:0 8px 20px rgba(5,150,105,0.2);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:15px;">';
    echo '<div>';
    echo '<h3 style="margin:0 0 4px;font-size:18px;font-weight:800;">🧬 Clinical Decision Support System (CDSS) & LIS Interoperability Hub</h3>';
    echo '<p style="margin:0;font-size:13px;opacity:0.9;">Real-time Drug Interactions (DDI), Duplicate Therapy Flags, Patient Allergy Hard-Blocks, LIS Creatinine Lab Dose Adjustment & Pediatric Weight Calculator.</p>';
    echo '</div>';
    echo '<div style="display:flex;gap:10px;">';
    echo '<span style="background:rgba(255,255,255,0.2);padding:6px 14px;border-radius:20px;font-size:12px;font-weight:800;">🛡️ Clinical Safety Grade A+</span>';
    echo '</div></div>';

    // Section 1: Automated DDI & Duplicate Class Engine
    echo '<div style="display:grid;grid-template-columns: 1.2fr 1fr;gap:20px;">';

    echo '<div class="card" style="padding:20px;">';
    echo '<h4 style="margin:0 0 8px;font-size:16px;color:#0f172a;">🧪 Drug-Drug Interaction (DDI) & Duplicate Class Simulator</h4>';
    echo '<p style="font-size:12px;color:#64748b;margin-bottom:14px;">Enter multi-drug generic combinations to test instant clinical alert triggers:</p>';
    echo '<form method="post" action="/index.php?page=pharmacy_clinical_cdss">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';

    echo '<div class="field" style="margin-bottom:12px;"><label style="font-weight:600;">Generic Drug Names (Comma-Separated) *</label><input type="text" name="generics" value="' . e(implode(', ', $testGenerics)) . '" placeholder="Warfarin, Aspirin" style="padding:8px;font-size:13px;"></div>';
    echo '<div class="field" style="margin-bottom:14px;"><label style="font-weight:600;">Patient UHID Code *</label><input type="text" name="uhid" value="' . e($uhid) . '" placeholder="UHID-10001" style="padding:8px;font-size:13px;"></div>';

    echo '<button class="button button-primary" style="width:100%;padding:10px;background:#059669;border-color:#059669;font-weight:800;">🧪 Run Clinical CDSS Safety Audit</button>';
    echo '</form>';

    // Display DDI Results
    if (!empty($ddiInteractions)) {
        echo '<div style="margin-top:16px;">';
        echo '<strong style="color:#7c3aed;font-size:14px;display:block;margin-bottom:8px;">⚠️ Detected Drug-Drug Interactions (' . count($ddiInteractions) . ')</strong>';
        foreach ($ddiInteractions as $ddi) {
            $isContra = $ddi['severity_level'] === 'CONTRAINDICATED';
            $bgColor = $isContra ? '#fef2f2' : '#fff7ed';
            $bdColor = $isContra ? '#fecaca' : '#ffedd5';
            $textColor = $isContra ? '#991b1b' : '#c2410c';

            echo '<div style="background:' . $bgColor . ';border:1px solid ' . $bdColor . ';padding:14px;border-radius:10px;margin-bottom:10px;">';
            echo '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">';
            echo '<strong style="color:' . $textColor . ';font-size:13px;">⚡ ' . e($ddi['generic_a']) . ' + ' . e($ddi['generic_b']) . '</strong>';
            echo '<span style="background:' . ($isContra ? '#dc2626' : '#ea580c') . ';color:white;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:800;">' . e($ddi['severity_level']) . '</span>';
            echo '</div>';
            echo '<div style="font-size:12px;color:#334155;margin-bottom:4px;"><strong>Clinical Effect:</strong> ' . e($ddi['clinical_effect']) . '</div>';
            echo '<div style="font-size:11px;color:#047857;background:white;padding:6px 10px;border-radius:6px;border:1px solid #cbd5e1;"><strong>Pharmacist Advice:</strong> ' . e($ddi['management_advice']) . '</div>';
            echo '</div>';
        }
        echo '</div>';
    } else {
        echo '<div style="margin-top:14px;background:#f0fdf4;border:1px solid #bbf7d0;padding:12px;border-radius:8px;font-size:12px;color:#15803d;font-weight:700;">✅ No Contraindicated Drug-Drug Interactions Detected in Cart.</div>';
    }

    echo '</div>';

    // Duplicate Class & Patient Allergy Box
    echo '<div style="display:flex;flex-direction:column;gap:16px;">';

    // Patient Allergy Cross-Check Panel
    echo '<div class="card" style="padding:18px;">';
    echo '<h4 style="margin:0 0 8px;font-size:15px;color:#0f172a;">🚫 Patient Allergy Profile & Hard-Block</h4>';
    if (!empty($allergyAlerts)) {
        foreach ($allergyAlerts as $alg) {
            echo '<div style="background:#fef2f2;border:1px solid #fecaca;color:#991b1b;padding:12px;border-radius:8px;font-size:12px;margin-bottom:8px;">';
            echo '<strong style="display:block;font-size:13px;">' . e($alg['warning']) . '</strong>';
            echo '<span>Category: ' . e($alg['allergen_category']) . ' | Allergen: ' . e($alg['specific_allergen']) . ' | Reaction: ' . e($alg['reaction_severity']) . '</span>';
            echo '</div>';
        }
    } else {
        echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;padding:10px;border-radius:8px;font-size:12px;color:#64748b;">No documented allergies matching selected drugs for UHID: <strong>' . e($uhid) . '</strong>.</div>';
    }
    echo '</div>';

    // Diagnostic LIS Lab Result Binding Panel
    echo '<div class="card" style="padding:18px;">';
    echo '<h4 style="margin:0 0 8px;font-size:15px;color:#0f172a;">🩸 Diagnostic LIS Lab Binding (Renal Dose Alert)</h4>';
    if (!empty($lisLabAlerts)) {
        foreach ($lisLabAlerts as $lis) {
            echo '<div style="background:#fff7ed;border:1px solid #ffedd5;color:#c2410c;padding:12px;border-radius:8px;font-size:12px;margin-bottom:8px;">';
            echo '<strong style="display:block;font-size:13px;">' . e($lis['warning']) . '</strong>';
            echo '<span>Serum Creatinine: ' . e($lis['creatinine']) . ' | eGFR: ' . e($lis['eGFR']) . ' | Target Drug: ' . e($lis['drug']) . '</span>';
            echo '</div>';
        }
    } else {
        echo '<div style="background:#f8fafc;border:1px solid #e2e8f0;padding:10px;border-radius:8px;font-size:12px;color:#64748b;">LIS Lab Check: Renal function parameters within normal limits (Creatinine < 1.4 mg/dL).</div>';
    }
    echo '</div>';

    echo '</div></div>';

    // Section 3: Pediatric Weight-Based Dosage Calculator
    echo '<div class="card" style="padding:20px;">';
    echo '<h4 style="margin:0 0 10px;font-size:16px;color:#0f172a;">👶 Pediatric Weight-Based Dosage Calculator</h4>';
    echo '<p style="font-size:12px;color:#64748b;margin-bottom:14px;">Calculates exact mL dose based on child body weight (kg) and concentration specs:</p>';

    echo '<form method="post" action="/index.php?page=pharmacy_clinical_cdss" style="display:grid;grid-template-columns: 1.5fr 1fr 1fr 1fr;gap:12px;align-items:end;margin-bottom:14px;">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<div class="field"><label style="font-weight:600;">Pediatric Suspension / Drop *</label><select name="pediatric_drug" style="padding:8px;font-size:13px;"><option value="Paracetamol Syrup"' . ($pediatricDrug === 'Paracetamol Syrup' ? ' selected' : '') . '>Paracetamol Syrup (125mg/5mL)</option><option value="Amoxicillin Suspension"' . ($pediatricDrug === 'Amoxicillin Suspension' ? ' selected' : '') . '>Amoxicillin Suspension (125mg/5mL)</option><option value="Cetirizine Syrup"' . ($pediatricDrug === 'Cetirizine Syrup' ? ' selected' : '') . '>Cetirizine Syrup (5mg/5mL)</option></select></div>';
    echo '<div class="field"><label style="font-weight:600;">Child Weight (kg) *</label><input type="number" step="0.5" name="weight_kg" value="' . e((string)$weightKg) . '" required style="padding:8px;font-size:13px;"></div>';
    echo '<div class="field"><label style="font-weight:600;">Child Age (Months)</label><input type="number" name="age_months" value="' . e((string)$ageMonths) . '" style="padding:8px;font-size:13px;"></div>';
    echo '<button class="button button-primary" style="padding:9px;background:#059669;border-color:#059669;font-weight:800;">⚖️ Calculate Safe Dose</button>';
    echo '</form>';

    if ($pediatricCalc) {
        echo '<div style="background:#f5f3ff;border:1px solid #ddd6fe;padding:16px;border-radius:10px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">';
        echo '<div>';
        echo '<strong style="color:#6d28d9;font-size:15px;">' . e($pediatricCalc['drug']) . '</strong><br>';
        echo '<span style="color:#5b21b6;font-size:12px;">Target Body Weight: ' . e((string)$pediatricCalc['weight_kg']) . ' kg | Dosing Standard: ' . e($pediatricCalc['dosage_mg_kg_day']) . '</span>';
        echo '</div>';
        echo '<div style="display:flex;gap:16px;align-items:center;">';
        echo '<div style="text-align:right;"><small style="color:#6d28d9;font-size:11px;font-weight:700;">RECOMMENDED SINGLE DOSE</small><div style="font-size:22px;font-weight:900;color:#5b21b6;">' . e($pediatricCalc['single_dose']) . '</div></div>';
        echo '<div style="text-align:right;"><small style="color:#6d28d9;font-size:11px;font-weight:700;">FREQUENCY</small><div style="font-size:16px;font-weight:800;color:#4c1d95;">' . e($pediatricCalc['frequency']) . '</div></div>';
        echo '<span style="background:#dcfce7;color:#15803d;padding:6px 12px;border-radius:20px;font-size:12px;font-weight:800;">✅ SAFE DOSE VERIFIED</span>';
        echo '</div></div>';
    }
    echo '</div>';

    // Section 4: Clinical Safety Rules Matrix Reference Table
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:14px 18px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;">';
    echo '<strong style="color:#0f172a;font-size:15px;">📜 Clinical Decision Support System (CDSS) Rule Matrix Repository</strong>';
    echo '<span style="font-size:11px;color:#7c3aed;font-weight:700;">Automated Hospital Drug Matrix</span>';
    echo '</div>';
    echo '<div style="overflow-x:auto;"><table class="data-table" style="width:100%;margin:0;">';
    echo '<thead><tr><th>Generic Drug A</th><th>Generic Drug B</th><th>Severity Level</th><th>Clinical Risk Effect</th><th>Management Advice</th></tr></thead><tbody>';
    $allRules = $db->query('SELECT * FROM pharmacy_drug_interactions ORDER BY id ASC')->fetchAll();
    foreach ($allRules as $rl) {
        $isContra = $rl['severity_level'] === 'CONTRAINDICATED';
        echo '<tr>';
        echo '<td><strong style="color:#0f172a;">' . e($rl['generic_a']) . '</strong></td>';
        echo '<td><strong style="color:#0f172a;">' . e($rl['generic_b']) . '</strong></td>';
        echo '<td><span style="background:' . ($isContra ? '#fef2f2' : '#fff7ed') . ';color:' . ($isContra ? '#dc2626' : '#ea580c') . ';border:1px solid ' . ($isContra ? '#fecaca' : '#ffedd5') . ';padding:2px 8px;border-radius:10px;font-size:11px;font-weight:800;">' . e($rl['severity_level']) . '</span></td>';
        echo '<td>' . e($rl['clinical_effect']) . '</td>';
        echo '<td>' . e($rl['management_advice']) . '</td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></div>';

    echo '</div>';
    page_end();
}

/**
 * Phase 20 AI & Predictive Inventory Optimization Desk View
 */
function render_pharmacy_ai_optimization(PDO $db, array $user): void
{
    Security::requirePermission($db, 'pharmacy.view');
    page_start($db, $user, 'pharmacy_ai_optimization', 'AI & Predictive Inventory Optimization Desk', 'ABC-FSN Matrix Classification, Seasonal Demand Predictor, Scheme Bonus Cost Recalculator & Vendor TTR Rebates');

    $matrixData = \Diagnostic\Pharmacy::getABCFSNClassificationMatrix($db);
    $selectedSeason = trim((string)($_GET['season'] ?? 'monsoon'));
    $seasonForecast = \Diagnostic\Pharmacy::getSeasonalDemandForecast($db, $selectedSeason);

    $schemePrice = (float)($_POST['purchase_price'] ?? 100.00);
    $purchasedQty = (int)($_POST['purchased_qty'] ?? 10);
    $bonusQty = (int)($_POST['bonus_qty'] ?? 1);
    $schemeCalc = \Diagnostic\Pharmacy::recalculateSchemeBonusUnitCost($schemePrice, $purchasedQty, $bonusQty);

    $ttrLedger = \Diagnostic\Pharmacy::getVendorTTRLedger($db);

    echo '<div style="display:flex;flex-direction:column;gap:20px;">';

    // Banner
    echo '<div style="background:linear-gradient(135deg,#2563eb,#1d4ed8);color:white;border-radius:12px;padding:20px;box-shadow:0 8px 20px rgba(37,99,235,0.2);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:15px;">';
    echo '<div>';
    echo '<h3 style="margin:0 0 4px;font-size:18px;font-weight:800;">📊 AI Predictive Inventory & Pharma Scheme Accounting Hub</h3>';
    echo '<p style="margin:0;font-size:13px;opacity:0.9;">ABC-FSN Capital Matrix, Monsoon/Winter Demand Forecasts, Bonus Scheme Effective Cost Recalculator & Target Turnover Rebates (TTR).</p>';
    echo '</div>';
    echo '<div style="display:flex;gap:10px;">';
    echo '<span style="background:rgba(255,255,255,0.2);padding:6px 14px;border-radius:20px;font-size:12px;font-weight:800;">💡 Capital Efficiency Matrix Active</span>';
    echo '</div></div>';

    // Section 1: ABC-FSN Classification Matrix (3x3 Grid)
    echo '<div class="card" style="padding:20px;">';
    echo '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">';
    echo '<h4 style="margin:0;font-size:16px;color:#0f172a;">🧩 ABC-FSN Capital & Movement Classification Matrix</h4>';
    echo '<span style="font-size:12px;color:#2563eb;font-weight:700;">Total Evaluated Inventory: ' . $matrixData['total_items'] . ' SKUs (Total Revenue: ৳ ' . number_format($matrixData['total_revenue'], 2) . ')</span>';
    echo '</div>';

    $grid = [
        ['AF', 'High Value · Fast Moving', '🟢 Top Capital Priority', '#dcfce7', '#15803d', '#bbf7d0'],
        ['AS', 'High Value · Slow Moving', '🟡 Over-Capitalization Risk', '#fefce8', '#a16207', '#fef9c3'],
        ['AN', 'High Value · Non Moving', '🔴 Dead Capital Block', '#fef2f2', '#991b1b', '#fecaca'],
        ['BF', 'Medium Value · Fast Moving', '🔵 Optimal Replenishment', '#eff6ff', '#1d4ed8', '#bfdbfe'],
        ['BS', 'Medium Value · Slow Moving', '⚪ Moderate Velocity', '#f8fafc', '#475569', '#e2e8f0'],
        ['BN', 'Medium Value · Non Moving', '🟠 Liquidation Candidate', '#fff7ed', '#c2410c', '#ffedd5'],
        ['CF', 'Low Value · Fast Moving', '🟣 Bulk Shelf Stock', '#faf5ff', '#6b21a8', '#e9d5ff'],
        ['CS', 'Low Value · Slow Moving', '⚪ Low Priority', '#f8fafc', '#475569', '#cbd5e1'],
        ['CN', 'Low Value · Non Moving', '⚫ Rationalization Target', '#f1f5f9', '#334155', '#cbd5e1']
    ];

    echo '<div style="display:grid;grid-template-columns: repeat(3, 1fr);gap:12px;">';
    foreach ($grid as $cell) {
        $code = $cell[0];
        $itemsInCell = $matrixData['matrix'][$code] ?? [];
        $count = count($itemsInCell);

        echo '<div style="background:' . $cell[3] . ';border:1px solid ' . $cell[5] . ';padding:14px;border-radius:10px;">';
        echo '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">';
        echo '<strong style="color:' . $cell[4] . ';font-size:16px;">[' . $code . '] ' . $cell[0] . '</strong>';
        echo '<span style="background:white;color:' . $cell[4] . ';padding:2px 8px;border-radius:12px;font-size:12px;font-weight:900;">' . $count . ' SKUs</span>';
        echo '</div>';
        echo '<small style="color:' . $cell[4] . ';font-weight:700;display:block;margin-bottom:4px;">' . e($cell[1]) . '</small>';
        echo '<span style="font-size:11px;color:' . $cell[4] . ';">' . e($cell[2]) . '</span>';
        echo '</div>';
    }
    echo '</div></div>';

    // Section 2: Seasonal Demand Forecasting & ROL Adjuster
    echo '<div style="display:grid;grid-template-columns: 1.3fr 1fr;gap:20px;">';

    echo '<div class="card" style="padding:20px;">';
    echo '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">';
    echo '<h4 style="margin:0;font-size:16px;color:#0f172a;">🌩️ Seasonal Demand Forecast & ROL Multiplier</h4>';
    echo '<div style="display:flex;gap:6px;">';
    echo '<a href="/index.php?page=pharmacy_ai_optimization&season=monsoon" class="button" style="padding:4px 10px;font-size:12px;' . ($selectedSeason === 'monsoon' ? 'background:#2563eb;color:white;' : 'background:#f1f5f9;color:#334155;') . '">🌧️ Monsoon / Dengue</a>';
    echo '<a href="/index.php?page=pharmacy_ai_optimization&season=winter" class="button" style="padding:4px 10px;font-size:12px;' . ($selectedSeason === 'winter' ? 'background:#2563eb;color:white;' : 'background:#f1f5f9;color:#334155;') . '">❄️ Winter Respiratory</a>';
