    echo '<button class="button button-primary" style="width:100%;padding:9px;background:#2563eb;border-color:#2563eb;font-weight:800;">🧮 Recalculate Effective Unit Cost</button>';
    echo '</form>';

    if ($schemeCalc) {
        echo '<div style="background:#f0fdf4;border:1px solid #bbf7d0;padding:14px;border-radius:10px;">';
        echo '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">';
        echo '<small style="color:#166534;font-weight:800;">EFFECTIVE UNIT COST</small>';
        echo '<span style="background:#10b981;color:white;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:800;">-' . $schemeCalc['scheme_savings_pct'] . '% COST REDUCTION</span>';
        echo '</div>';
