    foreach ($ttrLedger as $ttr) {
        $isAchieved = $ttr['status'] === 'TARGET_ACHIEVED';
        echo '<tr>';
        echo '<td><strong style="color:#0f172a;">' . e($ttr['supplier_name']) . '</strong></td>';
