        echo '<td style="color:#059669;font-weight:700;">৳ ' . number_format((float)$ttr['estimated_rebate_amount'], 2) . '</td>';
        echo '<td><span style="background:' . ($isAchieved ? '#dcfce7' : '#eff6ff') . ';color:' . ($isAchieved ? '#15803d' : '#1d4ed8') . ';padding:2px 8px;border-radius:10px;font-size:11px;font-weight:800;">' . e($ttr['status']) . '</span></td>';
        echo '</tr>';
