    echo '<span style="font-size:11px;color:#dc2626;font-weight:700;">Critical Drug Checklist</span>';
    echo '</div>';
    echo '<div style="overflow-x:auto;"><table class="data-table" style="width:100%;margin:0;">';
    echo '<thead><tr><th>Location</th><th>Seal No</th><th>Audited By</th><th>Checklist Status</th></tr></thead><tbody>';
    foreach ($crashCarts as $cc) {
        $isPassed = $cc['checklist_status'] === 'PASSED';
        echo '<tr>';
        echo '<td><strong style="color:#0f172a;">' . e($cc['cart_location']) . '</strong></td>';
        echo '<td><span style="font-family:monospace;font-weight:700;color:#0284c7;">' . e($cc['seal_number']) . '</span></td>';
