        echo '<td><span style="background:' . ($isPassed ? '#dcfce7' : '#fef2f2') . ';color:' . ($isPassed ? '#15803d' : '#dc2626') . ';padding:2px 8px;border-radius:10px;font-size:11px;font-weight:800;">' . e($cc['checklist_status']) . '</span></td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></div>';

    // Perpetual Cycle Counting
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:14px 18px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;">';
    echo '<strong style="color:#0f172a;font-size:15px;">🔍 Daily Perpetual Cycle Counting (2 Shelves/Day)</strong>';
    echo '<span style="font-size:11px;color:#059669;font-weight:700;">No Shop Freeze Audit</span>';
    echo '</div>';
    echo '<div style="overflow-x:auto;"><table class="data-table" style="width:100%;margin:0;">';
    echo '<thead><tr><th>Shelf Location</th><th>Medicine Item</th><th>System Qty</th><th>Physical Count</th><th>Variance</th></tr></thead><tbody>';
    foreach ($cycleCounts as $cy) {
        $var = (float)$cy['variance_qty'];
        echo '<tr>';
        echo '<td><span style="background:#fef3c7;color:#92400e;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:700;">' . e($cy['rack_location']) . '</span></td>';
        echo '<td><strong style="color:#0f172a;">' . e($cy['item_name']) . '</strong></td>';
        echo '<td>' . number_format((float)$cy['system_expected_qty'], 0) . ' Pcs</td>';
        echo '<td>' . number_format((float)$cy['physical_counted_qty'], 0) . ' Pcs</td>';
        echo '<td>' . ($var === 0.0 ? '<span style="color:#059669;font-weight:800;">0 (Matched)</span>' : '<span style="color:#dc2626;font-weight:800;">' . $var . ' Pcs</span>') . '</td>';
        echo '</tr>';
    }
    echo '</tbody></table></div></div>';

    echo '</div>';

    // Anti-Theft Blind-Count Cashier Handover Desk
    echo '<div class="card" style="padding:20px;">';
    echo '<h4 style="margin:0 0 10px;font-size:16px;color:#0f172a;">🔐 Anti-Theft Blind-Count Cashier Shift Handover Desk</h4>';
    echo '<p style="font-size:12px;color:#64748b;margin-bottom:14px;">Cashiers enter physical cash drawer count without seeing expected system sales total to prevent theft mismatch:</p>';

    echo '<form method="post" action="/index.php?page=pharmacy_multistore_theft" style="display:grid;grid-template-columns: 1.5fr 1fr;gap:16px;align-items:end;margin-bottom:14px;">';
    echo '<input type="hidden" name="_csrf" value="' . e(csrf_token()) . '">';
    echo '<input type="hidden" name="action" value="blind_handover">';

    echo '<div class="field"><label style="font-weight:600;">Physical Cash Drawer Count (৳) *</label><input type="number" step="0.01" name="declared_cash" value="' . e((string)$declaredCash) . '" required style="padding:10px;font-size:16px;font-weight:800;color:#059669;"></div>';
    echo '<button class="button button-primary" style="padding:11px;background:#0f172a;border-color:#0f172a;font-weight:800;">🔒 Verify Blind-Count Shift Collection</button>';
    echo '</form>';

    if ($blindHandover) {
        $isExact = $blindHandover['handover_status'] === 'EXACT_MATCH';
        echo '<div style="background:' . ($isExact ? '#ecfdf5' : '#fff7ed') . ';border:1px solid ' . ($isExact ? '#a7f3d0' : '#ffedd5') . ';padding:16px;border-radius:10px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">';
        echo '<div>';
        echo '<strong style="color:' . ($isExact ? '#065f46' : '#c2410c') . ';font-size:15px;">Shift Handover Status: ' . e($blindHandover['handover_status']) . '</strong><br>';
        echo '<span style="color:#334155;font-size:12px;">Declared Cash: ৳ ' . number_format($blindHandover['declared_physical_cash'], 2) . ' | System Expected Sales: ৳ ' . number_format($blindHandover['expected_system_cash'], 2) . '</span>';
        echo '</div>';
        echo '<div>';
        echo '<div style="text-align:right;"><small style="color:#64748b;font-weight:700;">CASH VARIANCE</small><div style="font-size:20px;font-weight:900;color:' . ($isExact ? '#059669' : '#dc2626') . ';">৳ ' . number_format($blindHandover['variance_amount'], 2) . '</div></div>';
        echo '</div></div>';
    }
    echo '</div>';

    echo '</div>';
    page_end();
}

