        echo '<span style="font-size:12px;color:#047857;">Recipient: ' . e($smartReceipt['patient_mobile']) . ' | Memo URL: <a href="' . e($smartReceipt['receipt_url']) . '" target="_blank" style="color:#0284c7;font-weight:700;">' . e($smartReceipt['receipt_url']) . '</a></span>';
