    }
    // Diabetic & Chronic Care Refill CRM Feed
    echo '<div class="card" style="padding:0;overflow:hidden;">';
    echo '<div style="padding:14px 18px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;">';
    echo '<strong style="color:#0f172a;font-size:15px;">📱 Diabetic & Chronic Care Refill CRM (Automated 3-Day SMS Trigger)</strong>';
    echo '<span style="font-size:11px;color:#0284c7;font-weight:700;">Repeat Patient Sales Engine</span>';
    echo '</div>';
    echo '<div style="overflow-x:auto;"><table class="data-table" style="width:100%;margin:0;">';
    echo '<thead><tr><th>Patient Name</th><th>Mobile</th><th>Chronic Condition</th><th>Prescribed Medicine</th><th>Last Refill</th><th>Next Due Date</th><th>SMS Status</th></tr></thead><tbody>';
    if (empty($refillReminders)) {
        echo '<tr><td colspan="7" style="text-align:center;padding:25px;color:#6b7280;">No chronic refill reminders generated yet. Click "Trigger Diabetic 3-Day SMS Refill Cycle" above to analyze sales history.</td></tr>';
    } else {
        foreach (array_slice($refillReminders, 0, 10) as $ref) {
            echo '<tr>';
            echo '<td><strong>' . e($ref['patient_name']) . '</strong><br><small style="color:#64748b;">UHID: ' . e($ref['patient_uhid']) . '</small></td>';
            echo '<td>' . e($ref['patient_mobile']) . '</td>';
            echo '<td><span style="background:#e0f2fe;color:#0369a1;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:700;">' . e($ref['chronic_condition']) . '</span></td>';
            echo '<td>' . e($ref['medicine_name']) . '</td>';
            echo '<td>' . e($ref['last_refill_date']) . '</td>';
            echo '<td><strong style="color:#059669;">' . e($ref['next_refill_due_date']) . '</strong></td>';
            echo '<td><span style="background:#dcfce7;color:#15803d;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;">📲 SMS QUEUED</span></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div></div>';

    echo '</div>';
    page_end();
}

