function render_pharmacy_receipt(PDO $db, array $user): void
{
    Security::requirePermission($db, 'pharmacy.pos');

    $pharmacyInvId = (int)($_GET['pharmacy_inv_id'] ?? 0);
    $diagInvId = (int)($_GET['diag_inv_id'] ?? 0);
    $autoPrint = !empty($_GET['auto_print']);
    $isReissued = !empty($_GET['reissued']);

    // MODE 1: ISOLATED PRINT VIEW FOR SPECIFIC VOUCHER / MEMO SALE
    if ($pharmacyInvId > 0 || $diagInvId > 0) {
        page_start($db, $user, 'pharmacy_receipt', 'Corporate Dual Cash Memos Print Page', 'Official Corporate Printable Invoices & Memos for Pharmacy OTC Sales and Diagnostic Lab Tests');

        $pharmacyInvoice = $pharmacyInvId ? \Diagnostic\Pharmacy::getPharmacyInvoiceDetails($db, $pharmacyInvId) : null;
        $diagInvoice = $diagInvId ? \Diagnostic\Pharmacy::getDiagnosticInvoiceDetails($db, $diagInvId) : null;

        $discountMeta = $_SESSION['last_discount_meta'] ?? [];
        $dType = $discountMeta['discount_type'] ?? ($discountMeta['type'] ?? 'SPECIAL_PROMO');
        $dRefBy = $discountMeta['discount_referred_by'] ?? ($discountMeta['referred_by'] ?? 'Doctor');
        $dRefName = $discountMeta['discount_referrer_name'] ?? ($discountMeta['referrer_name'] ?? 'Prof. Dr. M. Rahman');
        $dDate = $discountMeta['discount_date'] ?? ($discountMeta['date'] ?? date('Y-m-d'));

        echo '<style>
        @media print {
            header, footer, nav, .sidebar, .header-banner, .button, .no-print, .app-header, .app-sidebar, .page-heading, .topbar, .topbar-right {
                display: none !important;
            }
            body {
                background: white !important;
                color: black !important;
                margin: 0 !important;
                padding: 0 !important;
            }
            .main-area, .content {
                margin: 0 !important;
                padding: 0 !important;
                width: 100% !important;
            }
            .print-container {
                display: block !important;
                width: 100% !important;
                margin: 0 !important;
                padding: 0 !important;
            }
            .receipt-card {
                page-break-inside: avoid !important;
                page-break-after: always !important;
                break-after: page !important;
                border: 1.5px solid #0f172a !important;
                margin-bottom: 0 !important;
                padding: 16px !important;
                box-shadow: none !important;
            }
            .receipt-card:last-child {
                page-break-after: avoid !important;
                break-after: avoid !important;
            }
        }
        .receipt-card {
            background: #ffffff;
            border: 1px solid #cbd5e1;
            border-radius: 12px;
            padding: 24px;
            box-shadow: 0 4px 16px rgba(0,0,0,0.04);
            font-family: "Segoe UI", Roboto, Arial, sans-serif;
            box-sizing: border-box;
            overflow: hidden;
            width: 100%;
        }
        .receipt-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            border-bottom: 2px solid #0f172a;
            padding-bottom: 12px;
            margin-bottom: 16px;
        }
        .receipt-table {
            width: 100%;
            border-collapse: collapse;
            margin: 12px 0;
        }
        .receipt-table th {
            background: #f1f5f9;
            color: #0f172a;
            font-size: 11px;
            font-weight: 800;
            text-transform: uppercase;
            padding: 8px 10px;
            text-align: left;
            border-bottom: 1.5px solid #cbd5e1;
        }
        .receipt-table td {
            padding: 8px 10px;
            font-size: 12.5px;
            border-bottom: 1px solid #e2e8f0;
        }
        </style>';

        echo '<div class="no-print" style="margin-bottom:20px;display:flex;justify-content:space-between;align-items:center;background:#1e293b;color:white;padding:16px 24px;border-radius:14px;box-shadow:0 6px 18px rgba(30,41,59,0.15);">';
