            $isPharm = $v['voucher_type'] === 'PHARMACY';
            $catBadge = $isPharm ? '<span style="background:#e0f2fe;color:#0369a1;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;">💊 Pharmacy Memo</span>' : '<span style="background:#e0e7ff;color:#3730a3;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;">🧪 Diagnostic Memo</span>';
            $custBadge = $v['customer_type'] === 'CHAMBER_E_RX_PATIENT' ? '<span style="background:#f3e8ff;color:#6b21a8;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;">🩺 Chamber Patient</span>' : '<span style="background:#ecfdf5;color:#047857;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;">🚶 Walk-in Local</span>';
            $statusBadge = strcasecmp((string)$v['status'], 'REISSUED') === 0 ? '<span style="background:#e0f2fe;color:#0284c7;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:800;">RE-ISSUED</span>' : '<span style="background:#dcfce7;color:#15803d;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:800;">ISSUED</span>';

            $linkUrl = $isPharm ? "/index.php?page=pharmacy_receipt&pharmacy_inv_id={$v['id']}&auto_print=1" : "/index.php?page=pharmacy_receipt&diag_inv_id={$v['id']}&auto_print=1";

            echo '<tr>';
            echo '<td><span style="font-size:12px;color:#475569;">' . date('Y-m-d H:i', strtotime($v['created_at'])) . '</span></td>';
            echo '<td><span style="font-family:monospace;font-weight:800;color:#0284c7;">' . e($v['invoice_no']) . '</span></td>';
            echo '<td>' . $catBadge . '</td>';
            echo '<td>' . $custBadge . '</td>';
            echo '<td><strong>' . e($v['patient_name']) . '</strong><br><small style="color:#64748b;">📞 ' . e($v['patient_mobile'] ?: 'N/A') . '</small></td>';
            echo '<td><strong style="color:#059669;">৳ ' . number_format((float)$v['payable_amount'], 2) . '</strong></td>';
            echo '<td><span style="font-weight:700;font-size:11px;background:#f1f5f9;padding:2px 6px;border-radius:4px;">' . e($v['payment_method']) . '</span></td>';
            echo '<td>' . $statusBadge . '</td>';
            echo '<td>';
            echo '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
            echo '<a href="' . $linkUrl . '" target="_blank" class="button button-light" style="padding:4px 8px;font-size:11px;color:#059669;border:1px solid #a7f3d0;font-weight:700;">📄 View Memo</a>';
            echo '<form method="post" action="/index.php?page=pharmacy_receipt" style="display:inline;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="reissue_voucher"><input type="hidden" name="voucher_id" value="' . $v['id'] . '"><input type="hidden" name="voucher_type" value="' . $v['voucher_type'] . '"><button class="button button-light" style="padding:4px 8px;font-size:11px;color:#0284c7;border:1px solid #bae6fd;font-weight:700;">🖨️ Re-Issue</button></form>';
            echo '<button type="button" class="button button-light" style="padding:4px 8px;font-size:11px;color:#475569;border:1px solid #cbd5e1;font-weight:700;" onclick="openEditVoucherModal(' . $v['id'] . ', \'' . e(addslashes($v['voucher_type'])) . '\', \'' . e(addslashes($v['patient_name'])) . '\', \'' . e(addslashes($v['patient_mobile'])) . '\', \'' . e(addslashes($v['payment_method'])) . '\', ' . (float)$v['discount_amount'] . ')">✏️ Edit</button>';
            echo '</div></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div></div>';

    // Edit Voucher Modal
    echo '<div id="editVoucherModal" style="display:none;position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(15,23,42,0.75);backdrop-filter:blur(4px);z-index:9999;align-items:center;justify-content:center;padding:20px;">';
    echo '<div style="background:white;border-radius:16px;max-width:500px;width:100%;padding:28px;box-shadow:0 20px 40px rgba(0,0,0,0.3);border:1px solid #e2e8f0;">';
    echo '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;"><h3 style="margin:0;font-size:18px;color:#0f172a;">✏️ Edit POS Voucher / Memo Details</h3><button onclick="closeEditVoucherModal()" style="border:0;background:none;font-size:20px;cursor:pointer;color:#64748b;">✕</button></div>';
    echo '<form method="post" action="/index.php?page=pharmacy_receipt" class="field-grid" style="gap:14px;"><input type="hidden" name="_csrf" value="' . e(csrf_token()) . '"><input type="hidden" name="action" value="edit_voucher"><input type="hidden" name="voucher_id" id="edit_modal_voucher_id"><input type="hidden" name="voucher_type" id="edit_modal_voucher_type">';
    echo '<label class="field span-2">Customer / Patient Name *<input type="text" name="patient_name" id="edit_modal_patient_name" required style="padding:10px;font-size:14px;border-radius:8px;"></label>';
    echo '<label class="field span-2">Mobile Number / UHID<input type="text" name="patient_mobile" id="edit_modal_patient_mobile" style="padding:10px;font-size:14px;border-radius:8px;"></label>';
    echo '<label class="field">Payment Method<select name="payment_method" id="edit_modal_payment_method" style="padding:10px;font-size:14px;border-radius:8px;"><option value="CASH">💵 CASH</option><option value="BKASH">📱 bKash</option><option value="NAGAD">📱 Nagad</option><option value="CARD">💳 CARD</option><option value="SPLIT">🔀 SPLIT</option></select></label>';
    echo '<label class="field">Discount Amount (৳)<input type="number" step="0.01" name="discount_amount" id="edit_modal_discount_amount" style="padding:10px;font-size:14px;border-radius:8px;"></label>';
    echo '<div class="form-actions span-2" style="margin-top:10px;"><button class="button button-primary full" style="background:#059669;border-color:#059669;font-weight:800;padding:12px;">✔ Save Voucher Changes</button></div>';
    echo '</form></div></div>';

    echo '<script>
    function openEditVoucherModal(id, type, name, mobile, pm, discount) {
        document.getElementById("edit_modal_voucher_id").value = id;
        document.getElementById("edit_modal_voucher_type").value = type;
        document.getElementById("edit_modal_patient_name").value = name;
        document.getElementById("edit_modal_patient_mobile").value = mobile;
        document.getElementById("edit_modal_payment_method").value = pm;
        document.getElementById("edit_modal_discount_amount").value = discount;
        document.getElementById("editVoucherModal").style.display = "flex";
    }
    function closeEditVoucherModal() {
        document.getElementById("editVoucherModal").style.display = "none";
    }
    </script>';

    page_end();
}

