    .cms-tab-btn { padding: 10px 18px; border: 1px solid transparent; background: #ffffff; font-weight: 700; font-size: 13px; color: #475569; cursor: pointer; border-radius: 10px; transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1); display: inline-flex; align-items: center; gap: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.02); white-space: nowrap; }
