    echo '<script>
    function switchCmsTab(tabId, btn) {
        var contents = document.querySelectorAll(".cms-tab-content");
        contents.forEach(function(c) { c.classList.remove("active"); });
        var btns = document.querySelectorAll(".cms-tab-btn");
        btns.forEach(function(b) { b.classList.remove("active"); });

        var target = document.getElementById(tabId);
        if (target) target.classList.add("active");
        if (btn) btn.classList.add("active");
    }

    function selectThemeSwatch(pri, sec, btnCol, element) {
        document.getElementById("primary_color_picker").value = pri;
        document.getElementById("primary_color_hex").value = pri;
        document.getElementById("secondary_color_picker").value = sec;
        document.getElementById("secondary_color_hex").value = sec;
        document.getElementById("button_color_picker").value = btnCol;
        document.getElementById("button_color_hex").value = btnCol;

        var swatches = document.querySelectorAll(".swatch-item");
        swatches.forEach(function(s) { s.classList.remove("selected"); s.textContent = ""; });
        element.classList.add("selected");
        element.textContent = "✓";
    }

    function handleDragOver(e, box) {
        e.preventDefault();
        e.stopPropagation();
        box.classList.add("dragover");
    }

    function handleDragLeave(e, box) {
        e.preventDefault();
        e.stopPropagation();
        box.classList.remove("dragover");
    }

    function handleFileDrop(e, inputId, previewId, b64InputId) {
        e.preventDefault();
        e.stopPropagation();
        e.currentTarget.classList.remove("dragover");
        var dt = e.dataTransfer;
        var files = dt.files;
        if (files && files.length > 0) {
            var file = files[0];
            var input = document.getElementById(inputId);
            if (input) {
                var container = new DataTransfer();
                container.items.add(file);
                input.files = container.files;
            }
            readAndPreviewFile(file, previewId, b64InputId);
        }
    }

    function previewSelectedFile(input, previewId, b64InputId) {
        if (input.files && input.files[0]) {
            readAndPreviewFile(input.files[0], previewId, b64InputId);
        }
    }

    function readAndPreviewFile(file, previewId, b64InputId) {
        var reader = new FileReader();
        reader.onload = function(e) {
            var img = document.getElementById(previewId);
            if (img) {
                img.src = e.target.result;
                img.style.display = "block";
            }
            var b64Input = document.getElementById(b64InputId);
            if (b64Input) {
                b64Input.value = e.target.result;
            }
        };
        reader.readAsDataURL(file);
    }
    </script>';

    page_end();
}
